window.GNN_LESSONS=window.GNN_LESSONS||{};window.GNN_LESSONS["L4"]={"deck":"L4","slides":[{"p":1,"title":"4주차: GNN의 확장성","terms":["Scalability","Full-batch","Mini-batch","GCN"],"pass1":[{"kind":"say","lines":["4주차 주제는 **확장성(Scalability)**이에요.","한 줄로 하면 '데이터가 커져도 감당할 수 있는 성질'이에요.","노드가 수억 개인 큰 그래프에서도 GNN을 돌리는 법을 배워요."]},{"kind":"analogy","head":"도서관 한 권과 도서관 전체","scene":"민수가 책 한 권을 읽고 줄거리를 정리하는 건 쉬워요. 그런데 도서관에 있는 책 300만 권을 한꺼번에 책상에 올려놓고 정리하라고 하면 책상이 무너지죠. 그래서 한 번에 몇 권씩만 꺼내 읽는 방법을 찾아야 해요. GNN도 똑같아요.","map":[["책상 크기","GPU 메모리"],["책 300만 권","노드가 수억 개인 큰 그래프"],["몇 권씩 꺼내 읽기","**미니 배치(Mini-batch)**로 쪼개 계산하기"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"오늘 하루의 뼈대","items":["지금까지 배운 GNN은 '모르면 이웃에게 묻고, 모으고, 나와 합친다'는 기계예요.","작은 그래프에서는 잘 돌아가요. 그런데 노드가 1억 개면 메모리가 먼저 터져요.","**풀배치(Full-batch)**, 즉 전체를 한 번에 계산하는 방식이 문제의 뿌리예요.","해결책은 전부 '한 번에 다 보지 말고 일부만 뽑아 보자'는 한 방향이에요."]},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 '이번 주 볼 것은 GNN의 확장성에 대한 내용'이라고 시작했어요.","문제가 왜 생기는지 먼저 보고, 그다음 해결 방법들을 보겠다고 했어요.","뿌리는 한 문장이에요. GNN은 크기가 고정되지 않은 이웃에서 정보를 끌어와요.","그래서 출발 노드에 따라 계산할 양이 제각각 달라진다는 거예요."]}],"pass3":[],"pass4":[],"walk":{"head":null,"parts":[{"b":[0.06,0.16,0.55,0.17],"c":[0.0325,0.144,0.605,0.202],"r":5.3245,"img":"img/L4/walk/p001_20_01.jpg","say":"제목이 'Scalability of Graph Neural Networks', 즉 GNN의 **확장성(Scalability)**이에요."},{"b":[0.22,0.49,0.2,0.05],"c":[0.208,0.46,0.224,0.11],"r":3.6202,"img":"img/L4/walk/p001_20_02.jpg","say":"이오준 교수님 이름이에요."},{"b":[0.16,0.58,0.28,0.05],"c":[0.146,0.55,0.308,0.11],"r":4.9778,"img":"img/L4/walk/p001_20_03.jpg","say":"가톨릭대학교 인공지능학과, 아래에 이메일 주소가 있어요."},{"b":[0.66,0.02,0.33,0.95],"c":[0.5936,0,0.4064,1],"r":0.7225,"img":"img/L4/walk/p001_20_04.jpg","say":"점과 선으로 그린 그래프 무늬예요. 점이 노드, 선이 엣지예요."}]}},{"p":2,"title":"목차: 오늘 배울 네 덩어리","terms":["Node-wise Sampling","Layer-wise Sampling","Graph-wise Sampling","GraphSAGE","FastGCN","ASGCN","Cluster-GCN","GraphSAINT"],"pass1":[{"kind":"say","lines":["오늘은 네 덩어리로 가요.","먼저 '왜 큰 그래프에서 GNN이 안 돌아가나'를 진단해요.","그다음 쪼개는 방법 세 가지를 배워요. 노드마다, 층마다, 그래프째예요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"compare","head":"네 덩어리와 대표 모델","cols":["덩어리","무엇을 하나","대표 모델"],"rows":[["1 문제 진단","왜 안 되는지 알아내기","GCN 자체"],["2 **노드 단위 샘플링(Node-wise Sampling)**","대상 노드마다 이웃 몇 개만","**GraphSAGE**, VR-GCN"],["3 **레이어 단위 샘플링(Layer-wise Sampling)**","층마다 볼 노드를 미리 정함","**FastGCN**, **ASGCN**"],["4 **그래프 단위 샘플링(Graph-wise Sampling)**","부분 그래프를 통째로","**Cluster-GCN**, **GraphSAINT**"]]},{"kind":"points","head":"이번 레슨이 다루는 범위","items":["p.1 부터 p.22 까지예요.","1번 덩어리 전체(복습 포함)와 2번 덩어리인 **GraphSAGE**의 앞부분이에요.","**FastGCN**과 **ASGCN**, **Cluster-GCN**과 **GraphSAINT**는 이름만 만나요."]},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 학습 안정성과 계산 부하를 줄이려면 어떻게든 쪼개야 한다고 했어요.","쪼개는 방법이 노드마다, 레이어마다, 그래프마다 세 가지라고 했어요.","그리고 이 중 **가장 많이 쓰이는 것은 첫 번째(노드 단위)**라고 못 박았어요.","그러니 **GraphSAGE** 쪽을 가장 단단히 알아 두면 돼요."]}],"pass3":[],"pass4":[],"walk":{"head":{"b":[0.0433,0.1025,0.0776,0.0415],"c":[0,0.0865,0.2,0.0735],"r":4.8375,"img":"img/L4/walk/p002_h.jpg"},"parts":[{"b":[0.278,0.146,0.653,0.141],"c":[0.2454,0.13,0.7183,0.173],"r":7.3814,"img":"img/L4/walk/p002_11_01.jpg","say":"01 대규모 GNN을 향한 문제들. 메모리 문제와 기울기 갱신 문제가 나와요."},{"b":[0.278,0.33,0.653,0.145],"c":[0.2454,0.314,0.7183,0.177],"r":7.2146,"img":"img/L4/walk/p002_11_02.jpg","say":"02 **노드 단위 샘플링(Node-wise Sampling)**. 대표 모델이 **GraphSAGE**예요."},{"b":[0.278,0.519,0.653,0.15],"c":[0.2454,0.503,0.7183,0.182],"r":7.0164,"img":"img/L4/walk/p002_11_03.jpg","say":"03 **레이어 단위 샘플링(Layer-wise Sampling)**. 대표가 **FastGCN**, **ASGCN**이에요."},{"b":[0.278,0.707,0.653,0.15],"c":[0.2454,0.691,0.7183,0.182],"r":7.0164,"img":"img/L4/walk/p002_11_04.jpg","say":"04 **그래프 단위 샘플링(Graph-wise Sampling)**. 대표가 **Cluster-GCN**, **GraphSAINT**예요."}]}},{"p":3,"title":"복습: 임베딩은 이웃에서 만든다","terms":["Computation Graph","Degree","Adjacency Matrix","Message Passing","Neighborhood Explosion"],"pass1":[{"kind":"say","lines":["GNN의 출발점은 한 문장이에요.","'노드 임베딩을 그 노드의 지역 이웃에서 만든다'예요.","노드 임베딩은 노드 하나를 나타내는 숫자 줄이에요."]},{"kind":"analogy","head":"전학 온 친구가 누구인지 알아내기","scene":"새로 전학 온 친구가 어떤 사람인지 궁금해요. 직접 물어보기는 쑥스러워서, 그 친구와 어울리는 세 명에게 먼저 물어봐요. 그 세 명의 대답을 모아 보면 새 친구가 어떤 사람인지 대충 그려지죠. GNN도 이렇게 노드 주변을 모아서 그 노드를 설명해요.","map":[["새로 온 친구","대상 노드"],["어울리는 세 명","이웃 노드"],["대답을 모으는 일","집계, 즉 **메시지 패싱(Message Passing)**"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.02,"y":0.025,"w":0.2,"h":0.055,"say":"제목은 '복습: 이웃 집계'예요. p.8 까지가 2주차, 3주차 복습이에요.","c":[0.008,0,0.224,0.11],"r":3.6202,"img":"img/L4/walk/p003_20_01.jpg"},{"x":0.12,"y":0.33,"w":0.23,"h":0.48,"say":"입력 그래프. 선은 A-B, A-C, A-D, B-C, C-E, C-F, E-F 일곱 개예요.","c":[0.108,0.306,0.254,0.528],"r":0.8552,"img":"img/L4/walk/p003_20_02.jpg"},{"x":0.43,"y":0.32,"w":0.39,"h":0.49,"say":"오른쪽이 A의 **계산 그래프(Computation Graph)**예요. 나무 모양이죠.","c":[0.4105,0.2955,0.429,0.539],"r":1.415,"img":"img/L4/walk/p003_20_03.jpg"},{"x":0.485,"y":0.53,"w":0.075,"h":0.13,"say":"회색 네모가 '모으는 상자', 즉 집계예요. 점선 화살표가 이웃이 보내는 메시지예요.","c":[0.4225,0.514,0.2,0.162],"r":2.1948,"img":"img/L4/walk/p003_20_04.jpg"}]},{"kind":"points","head":"표로 보는 **차수(Degree)**","items":["**차수(Degree)**는 그 노드에 붙은 선의 개수, 즉 이웃 수예요.","A는 B, C, D 세 명이라 차수 3이에요.","C는 A, B, E, F 네 명이라 차수 4, D는 A 한 명이라 차수 1이에요.","D와 C가 네 배 차이예요. 이 들쭉날쭉함이 오늘 이야기의 씨앗이에요."]},{"kind":"steps","head":"A 하나를 계산하는 데 몇 칸이 드나요","steps":["맨 위(층-2 결과)는 A 하나, 1칸이에요.","중간(층-1 결과)은 B, C, D 세 개, 3칸이에요.","맨 아래(층-0 입력)는 B의 이웃 2개, C의 이웃 4개, D의 이웃 1개예요.","$2 + 4 + 1 = 7$ 칸이에요.","모두 더하면 $1 + 3 + 7 = 11$ 칸이에요."],"answer":"노드가 6개뿐인데 A 하나를 얻으려고 11칸을 계산해요. 게다가 A라는 글자가 이 안에 네 번 나와요.","given":"2층 GNN, 대상 노드는 A 하나예요."},{"kind":"figure","head":"A의 2층 계산 그래프","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<line class=\"e2 b1\" x1=\"240\" y1=\"52\" x2=\"110\" y2=\"104\"/>\n<line class=\"e2 b1\" x1=\"240\" y1=\"52\" x2=\"240\" y2=\"104\"/>\n<line class=\"e2 b1\" x1=\"240\" y1=\"52\" x2=\"370\" y2=\"104\"/>\n<line class=\"e b2\" x1=\"110\" y1=\"136\" x2=\"60\" y2=\"188\"/>\n<line class=\"e b2\" x1=\"110\" y1=\"136\" x2=\"150\" y2=\"188\"/>\n<line class=\"e b2\" x1=\"240\" y1=\"136\" x2=\"190\" y2=\"188\"/>\n<line class=\"e b2\" x1=\"240\" y1=\"136\" x2=\"222\" y2=\"188\"/>\n<line class=\"e b2\" x1=\"240\" y1=\"136\" x2=\"258\" y2=\"188\"/>\n<line class=\"e b2\" x1=\"240\" y1=\"136\" x2=\"290\" y2=\"188\"/>\n<line class=\"e b2\" x1=\"370\" y1=\"136\" x2=\"370\" y2=\"188\"/>\n<circle class=\"n2\" cx=\"240\" cy=\"36\" r=\"16\"/>\n<circle class=\"n b1\" cx=\"110\" cy=\"120\" r=\"16\"/>\n<circle class=\"n b1\" cx=\"240\" cy=\"120\" r=\"16\"/>\n<circle class=\"n b1\" cx=\"370\" cy=\"120\" r=\"16\"/>\n<circle class=\"n b2\" cx=\"60\" cy=\"204\" r=\"13\"/>\n<circle class=\"n b2\" cx=\"150\" cy=\"204\" r=\"13\"/>\n<circle class=\"n b2\" cx=\"190\" cy=\"204\" r=\"13\"/>\n<circle class=\"n b2\" cx=\"222\" cy=\"204\" r=\"13\"/>\n<circle class=\"n b2\" cx=\"258\" cy=\"204\" r=\"13\"/>\n<circle class=\"n b2\" cx=\"290\" cy=\"204\" r=\"13\"/>\n<circle class=\"n b2\" cx=\"370\" cy=\"204\" r=\"13\"/>\n<text class=\"tl\" x=\"240\" y=\"41\" font-size=\"15\" text-anchor=\"middle\">A<\/text>\n<text class=\"tl b1\" x=\"110\" y=\"125\" font-size=\"15\" text-anchor=\"middle\">B<\/text>\n<text class=\"tl b1\" x=\"240\" y=\"125\" font-size=\"15\" text-anchor=\"middle\">C<\/text>\n<text class=\"tl b1\" x=\"370\" y=\"125\" font-size=\"15\" text-anchor=\"middle\">D<\/text>\n<text class=\"tl b2\" x=\"60\" y=\"209\" font-size=\"14\" text-anchor=\"middle\">A<\/text>\n<text class=\"tl b2\" x=\"150\" y=\"209\" font-size=\"14\" text-anchor=\"middle\">C<\/text>\n<text class=\"tl b2\" x=\"190\" y=\"209\" font-size=\"14\" text-anchor=\"middle\">A<\/text>\n<text class=\"tl b2\" x=\"222\" y=\"209\" font-size=\"14\" text-anchor=\"middle\">B<\/text>\n<text class=\"tl b2\" x=\"258\" y=\"209\" font-size=\"14\" text-anchor=\"middle\">E<\/text>\n<text class=\"tl b2\" x=\"290\" y=\"209\" font-size=\"14\" text-anchor=\"middle\">F<\/text>\n<text class=\"tl b2\" x=\"370\" y=\"209\" font-size=\"14\" text-anchor=\"middle\">A<\/text>\n<text class=\"tm\" x=\"438\" y=\"41\" font-size=\"14\" text-anchor=\"middle\">1칸<\/text>\n<text class=\"tm b1\" x=\"438\" y=\"125\" font-size=\"14\" text-anchor=\"middle\">3칸<\/text>\n<text class=\"tm b2\" x=\"438\" y=\"209\" font-size=\"14\" text-anchor=\"middle\">7칸<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"248\" font-size=\"16\" text-anchor=\"middle\">노드는 6개인데 A 하나에 1 + 3 + 7 = 11칸<\/text>\n<\/svg>","caption":"**계산 그래프(Computation Graph)**는 원래 그래프를 나무처럼 펼친 것이에요. 같은 노드가 여러 칸에 겹쳐 나와요.","builds":3},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 GNN을 '대상 노드를 뿌리로 하는 k층 부분 트리를 샘플링해 오는 것'이라고 복습했어요.","그 트리의 정보를 한 레벨씩 뿌리를 향해 집계한다는 거예요.","그러면서 '문제는 얘의 형태가 제각각이라는 것'이라고 했어요.","이웃의 범위와 수를 미리 예상할 수가 없다는 뜻이에요."]},{"kind":"mining","src":"마이닝 2강 Representation of Graphs and Storage","lines":["누가 누구의 이웃인지 적는 방법이 두 가지예요.","하나는 **인접행렬(Adjacency Matrix)**. 노드가 $n$ 개면 $n \\times n$ 표에 0과 1을 적어요.","다른 하나는 인접 리스트. 노드마다 이웃 이름만 줄줄이 적어요.","인접행렬은 칸이 $n^2$ 개라 큰 그래프에서 메모리를 먹어요."]},{"kind":"warn","head":"여기서 헷갈리기 쉬워요","items":["계산 그래프는 원래 그래프를 펼쳐 놓은 것이지, 새로 만든 그래프가 아니에요.","그래서 같은 노드가 여러 칸에 중복해서 나타나요. 위 그림에서 A가 네 번 나왔죠."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"In a GNN, every node induces its own computation graph.","ko":"GNN에서는 모든 노드가 자기만의 계산 그래프를 만든다.","tip":"computation graph 라는 표기를 그대로 외워 두세요."},{"kind":"check","q":"**차수(Degree)**가 뜻하는 것은 무엇인가요?","choices":["노드에 붙은 선의 개수","GNN의 층 수","임베딩 벡터의 길이","그래프의 노드 수"],"a":0,"why":"**차수(Degree)**는 이웃 수예요. 이 값이 계산 그래프의 폭을 정해요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.1933,0.0757],"c":[0.0011,0.0019,0.2173,0.1077],"r":3.5869,"img":"img/L4/walk/p003_h.jpg"},"parts":[{"b":[0.04,0.155,0.63,0.055],"c":[0.0085,0.1125,0.693,0.14],"r":8.8,"img":"img/L4/walk/p003_12_01.jpg","say":"굵은 한 줄이 핵심이에요. '지역 이웃을 바탕으로 노드 임베딩을 만든다'."},{"b":[0.12,0.33,0.23,0.48],"c":[0.108,0.306,0.254,0.528],"r":0.8552,"img":"img/L4/walk/p003_12_02.jpg","say":"왼쪽이 입력 그래프예요. 노드 여섯 개가 있고 화살표가 A를 가리켜요."}]}},{"p":4,"title":"복습: 집계 상자 안에는 신경망이 있다","terms":["Aggregator","GCN","Degree","Full-batch","Adjacency Matrix"],"pass1":[{"kind":"say","lines":["이웃에게서 온 정보를 모으는 상자는 그냥 평균이 아니에요.","안에 **학습되는 신경망**이 들어 있어요.","그래서 '무엇을 어떻게 모을지'도 데이터에서 배워요."]},{"kind":"analogy","head":"반 친구 의견을 요약하는 규칙","scene":"반장이 친구 세 명의 의견을 듣고 한 문장으로 요약해요. 처음에는 그냥 평균만 냈는데, 자꾸 하다 보니 '이런 의견은 이렇게 묶는 게 좋더라'는 요령이 생겨요. 그 요령이 바로 학습되는 가중치예요.","map":[["요약하는 요령","가중치 행렬 $W$"],["의견을 한 문장으로 묶기","**집계기(Aggregator)**"],["내 생각도 남기기","내 이전 임베딩에 곱하는 $B$"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"formula","head":"2주차에 배운 GNN 한 층의 식","tex":"h_v^{(l+1)} = \\sigma \\left( W^{(l)} \\cdot \\frac{1}{|N(v)|} \\sum_{u \\in N(v)} h_u^{(l)} + B^{(l)} h_v^{(l)} \\right)","parts":[{"sym":"h_v^{(l)}","say":"노드 $v$ 의 층 $l$ 임베딩. $l$ 번째 수업이 끝난 뒤 $v$ 의 생각이에요."},{"sym":"N(v)","say":"$v$ 의 이웃 집합. 짝꿍 명단이에요."},{"sym":"|N(v)|","say":"이웃의 개수, 즉 **차수(Degree)**예요."},{"sym":"\\sum_{u \\in N(v)}","say":"이웃들의 것을 모두 더하기. 쪽지를 전부 걷는 일이에요."},{"sym":"W^{(l)}","say":"이웃 정보를 다루는 학습 가중치. 이웃 말을 해석하는 규칙이에요."},{"sym":"B^{(l)}","say":"내 정보를 다루는 학습 가중치. 내 생각을 유지하는 규칙이에요."},{"sym":"\\sigma","say":"비선형 함수. 보통 ReLU 로 음수를 0으로 깎아요."}],"whole":"이웃들의 임베딩을 평균 내서 규칙 $W$ 로 바꾸고, 내 이전 임베딩을 규칙 $B$ 로 바꾼 뒤 더하고, 마지막에 비선형 함수를 통과시켜요."},{"kind":"steps","head":"숫자로 한 번","steps":["$N(A) = \\{B, C, D\\}$ 이고 값은 0.1, 0.3, 0.2 예요.","이웃 평균은 $(0.1 + 0.3 + 0.2)/3 = 0.2$ 예요.","내 값 0.4 를 더하면 0.6 이에요.","ReLU 는 양수를 그대로 두니까 $h_A^{(1)} = 0.6$ 이에요.","같은 방법으로 C는 $(0.4+0.1+0.1+0.5)/4 = 0.275$, 더하면 0.575 예요."],"answer":"계산은 쉬워요. 문제는 C는 이웃 값 4개, D는 1개를 들고 있어야 한다는 거예요.","given":"$W$ 와 $B$ 를 1로 두고, 입력을 A 0.4, B 0.1, C 0.3, D 0.2, E 0.1, F 0.5 로 둘게요."},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 이 대목을 구현 이야기로 설명했어요.","노드마다 계산 그래프를 따로 만들어야 하니 메모리를 미리 잡아 두기가 힘들대요.","그래서 실제로는 **인접행렬(Adjacency Matrix)** 곱하기 특징행렬 곱하기 가중치가 제일 편해져요.","편한 대신 언제나 **풀배치(Full-batch)**로만 돌아간다는 게 문제예요."]},{"kind":"mining","src":"마이닝 3강 Centrality Measures","lines":["**메시지 패싱(Message Passing)** 계산은 고유벡터 중심성에서 이미 봤어요.","식이 $x_i(t) = \\sum_j A_{ij} x_j(t-1)$ 이었죠. 내 점수는 이웃 점수의 합이에요.","차이는 두 가지예요. 중심성은 숫자 하나, GNN은 벡터를 갱신해요.","그리고 중심성에는 학습할 가중치가 없지만 GNN에는 $W$ 가 있어요."]},{"kind":"warn","head":"빠뜨리기 쉬운 항","items":["식에서 $B^{(l)} h_v^{(l)}$, 즉 '내 이전 값' 항을 빠뜨리기 쉬워요.","이 항이 없으면 자기 정보를 잃어버려요.","**GCN**은 자기 자신을 이웃에 포함시켜 처리하고, **GraphSAGE**는 이어 붙이기로 처리해요."]}],"pass3":[{"kind":"check","q":"집계 상자 안에 들어 있는 것은 무엇인가요?","choices":["고정된 평균 계산만","학습되는 가중치 $W$ 와 비선형 함수","인접행렬 그 자체","노드 이름표"],"a":1,"why":"**집계기(Aggregator)** 안에는 학습되는 신경망이 있어서 '어떻게 모을지'도 배워요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.1933,0.0757],"c":[0.0011,0.0019,0.2173,0.1077],"r":3.5869,"img":"img/L4/walk/p004_h.jpg"},"parts":[{"b":[0.04,0.15,0.58,0.05],"c":[0.011,0.1106,0.638,0.1289],"r":8.7992,"img":"img/L4/walk/p004_20_01.jpg","say":"굵은 한 줄이 '노드는 신경망을 써서 이웃의 정보를 집계한다'예요."},{"b":[0.715,0.345,0.04,0.05],"c":[0.635,0.315,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p004_20_02.jpg","say":"B의 집계 상자. 들어가는 점선 화살표가 2개예요."},{"b":[0.715,0.515,0.04,0.05],"c":[0.635,0.485,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p004_20_03.jpg","say":"C의 집계 상자. 화살표가 4개나 들어가요."},{"b":[0.705,0.685,0.04,0.05],"c":[0.625,0.655,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p004_20_04.jpg","say":"D의 집계 상자. 화살표가 1개뿐이에요. 상자마다 입력 개수가 달라요."}]}},{"p":5,"title":"노드마다 계산 그래프가 전부 다르다","terms":["Computation Graph","Degree","Receptive Field","Neighborhood Explosion"],"pass1":[{"kind":"say","lines":["이번 쪽 한 줄은 이거예요.","노드마다 **계산 그래프(Computation Graph)**의 모양과 크기가 전부 달라요.","이 한 가지 사실이 오늘 배울 모든 문제의 원인이에요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.09,"y":0.275,"w":0.23,"h":0.085,"say":"파란 글씨에서 화살표 여섯 개가 아래 나무 여섯 개를 각각 가리켜요.","c":[0.078,0.259,0.254,0.117],"r":3.8594,"img":"img/L4/walk/p005_20_01.jpg"},{"x":0.665,"y":0.25,"w":0.17,"h":0.27,"say":"오른쪽 위가 익숙한 입력 그래프예요. 노드 색과 아래 나무 색이 짝이에요.","c":[0.65,0.234,0.2,0.302],"r":1.1773,"img":"img/L4/walk/p005_20_02.jpg"},{"x":0.355,"y":0.54,"w":0.175,"h":0.28,"say":"초록색은 C의 나무예요. 아래가 아주 넓게 퍼져 있어요.","c":[0.3425,0.524,0.2,0.312],"r":1.1396,"img":"img/L4/walk/p005_20_03.jpg"},{"x":0.575,"y":0.54,"w":0.06,"h":0.28,"say":"파란색은 D의 나무예요. 가지가 한 줄로 가늘어요.","c":[0.505,0.524,0.2,0.312],"r":1.1396,"img":"img/L4/walk/p005_20_04.jpg"}]},{"kind":"steps","head":"여섯 노드의 칸 수를 전부 세어요","steps":["세는 법은 '1(나 자신) + 내 차수 + 이웃들의 차수 합'이에요.","A: $1 + 3 + (2+4+1) = 11$ 칸","B: $1 + 2 + (3+4) = 10$ 칸, C: $1 + 4 + (3+2+2+2) = 12$ 칸","D: $1 + 1 + 3 = 5$ 칸, E와 F: 각각 $1 + 2 + (4+2) = 9$ 칸","가장 작은 D가 5칸, 가장 큰 C가 14칸이에요."],"answer":"노드 6개짜리 장난감 그래프에서도 2.8배 차이가 나요. 페이스북이라면 이 비율이 얼마나 될까요.","given":"2층 GNN 이에요."},{"kind":"figure","head":"D의 나무와 C의 나무","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<line class=\"e\" x1=\"105\" y1=\"52\" x2=\"105\" y2=\"94\"/>\n<line class=\"e\" x1=\"105\" y1=\"126\" x2=\"70\" y2=\"170\"/>\n<line class=\"e\" x1=\"105\" y1=\"126\" x2=\"105\" y2=\"170\"/>\n<line class=\"e\" x1=\"105\" y1=\"126\" x2=\"140\" y2=\"170\"/>\n<circle class=\"n2\" cx=\"105\" cy=\"36\" r=\"16\"/>\n<circle class=\"n\" cx=\"105\" cy=\"110\" r=\"15\"/>\n<circle class=\"n\" cx=\"70\" cy=\"186\" r=\"13\"/>\n<circle class=\"n\" cx=\"105\" cy=\"186\" r=\"13\"/>\n<circle class=\"n\" cx=\"140\" cy=\"186\" r=\"13\"/>\n<text class=\"tl\" x=\"105\" y=\"41\" font-size=\"15\" text-anchor=\"middle\">D<\/text>\n<text class=\"tl\" x=\"105\" y=\"115\" font-size=\"14\" text-anchor=\"middle\">A<\/text>\n<text class=\"tb\" x=\"105\" y=\"226\" font-size=\"16\" text-anchor=\"middle\">D: 5칸<\/text>\n<text class=\"tm\" x=\"105\" y=\"250\" font-size=\"14\" text-anchor=\"middle\">차수 1, 가늘어요<\/text>\n<line class=\"e2 b1\" x1=\"345\" y1=\"52\" x2=\"270\" y2=\"94\"/>\n<line class=\"e2 b1\" x1=\"345\" y1=\"52\" x2=\"320\" y2=\"94\"/>\n<line class=\"e2 b1\" x1=\"345\" y1=\"52\" x2=\"370\" y2=\"94\"/>\n<line class=\"e2 b1\" x1=\"345\" y1=\"52\" x2=\"420\" y2=\"94\"/>\n<line class=\"e b2\" x1=\"270\" y1=\"126\" x2=\"252\" y2=\"170\"/>\n<line class=\"e b2\" x1=\"270\" y1=\"126\" x2=\"276\" y2=\"170\"/>\n<line class=\"e b2\" x1=\"320\" y1=\"126\" x2=\"300\" y2=\"170\"/>\n<line class=\"e b2\" x1=\"320\" y1=\"126\" x2=\"324\" y2=\"170\"/>\n<line class=\"e b2\" x1=\"370\" y1=\"126\" x2=\"348\" y2=\"170\"/>\n<line class=\"e b2\" x1=\"370\" y1=\"126\" x2=\"372\" y2=\"170\"/>\n<line class=\"e b2\" x1=\"420\" y1=\"126\" x2=\"400\" y2=\"170\"/>\n<line class=\"e b2\" x1=\"420\" y1=\"126\" x2=\"428\" y2=\"170\"/>\n<circle class=\"n2\" cx=\"345\" cy=\"36\" r=\"16\"/>\n<circle class=\"n b1\" cx=\"270\" cy=\"110\" r=\"14\"/>\n<circle class=\"n b1\" cx=\"320\" cy=\"110\" r=\"14\"/>\n<circle class=\"n b1\" cx=\"370\" cy=\"110\" r=\"14\"/>\n<circle class=\"n b1\" cx=\"420\" cy=\"110\" r=\"14\"/>\n<circle class=\"n b2\" cx=\"252\" cy=\"186\" r=\"11\"/>\n<circle class=\"n b2\" cx=\"276\" cy=\"186\" r=\"11\"/>\n<circle class=\"n b2\" cx=\"300\" cy=\"186\" r=\"11\"/>\n<circle class=\"n b2\" cx=\"324\" cy=\"186\" r=\"11\"/>\n<circle class=\"n b2\" cx=\"348\" cy=\"186\" r=\"11\"/>\n<circle class=\"n b2\" cx=\"372\" cy=\"186\" r=\"11\"/>\n<circle class=\"n b2\" cx=\"400\" cy=\"186\" r=\"11\"/>\n<circle class=\"n b2\" cx=\"428\" cy=\"186\" r=\"11\"/>\n<text class=\"tl\" x=\"345\" y=\"41\" font-size=\"15\" text-anchor=\"middle\">C<\/text>\n<text class=\"tb b2\" x=\"345\" y=\"226\" font-size=\"16\" text-anchor=\"middle\">C: 14칸<\/text>\n<text class=\"tm b2\" x=\"345\" y=\"250\" font-size=\"14\" text-anchor=\"middle\">차수 4, 넓어요<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"16\" font-size=\"16\" text-anchor=\"middle\">깊이는 둘 다 2. 다른 건 폭이에요<\/text>\n<\/svg>","caption":"깊이는 둘 다 2 로 같아요. 다른 건 **폭**이고, 폭을 정하는 건 **차수(Degree)**예요.","builds":3},{"kind":"points","head":"폭을 모르면 생기는 일 세 가지","items":["메모리를 미리 못 잡아요. 최악의 경우에 맞춰 비워 둬야 해서 낭비가 커요.","병렬 연산이 어려워요. GPU는 같은 모양의 계산을 많이 할 때 빨라요.","역전파가 무거워요. 넓고 깊으면 모든 경로에 대해 기울기를 계산해야 해요.","이 셋을 한마디로 하면 '**수용 영역(Receptive Field)**을 예상할 수 없다'예요."]},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 이 지점을 '문제의 핵심'으로 짚었어요.","깊이 $k$ 는 똑같은데 노드마다 **폭**을 미리 예상할 수 없다는 게 문제래요.","대상 노드에 따라 확보해야 할 이웃의 범위가 계속 달라진다고요.","그래프 구조와 깊이에 따라 '어디서부터 어디까지'가 달라진다는 말이에요."]},{"kind":"mining","src":"마이닝 3강 Centrality Measures","lines":["차수 중심성 $C_D(v_i) = d(v_i) = \\sum_j A_{ij}$ 를 배웠어요.","인접행렬의 한 행을 전부 더하면 그 노드의 **차수(Degree)**가 나와요.","차수가 얼마나 흩어져 있는지는 차수 분산과 프리먼 중심화로 쟀어요.","차수 분산이 큰 그래프일수록 GNN을 돌리기 어려워요."]},{"kind":"warn","head":"두 가지 오해","items":["'계산 그래프가 다르다'를 '층 수가 다르다'로 읽으면 안 돼요. 층 수는 모두 같아요.","나무의 잎 개수를 '그 노드가 아는 노드 수'로 세면 안 돼요. 같은 노드가 여러 번 나와요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"Its width is determined by the node degrees, which vary greatly across nodes.","ko":"계산 그래프의 폭은 노드 차수로 정해지는데, 차수는 노드마다 크게 다르다.","tip":"width 와 degree 두 단어가 핵심이에요."},{"kind":"check","q":"노드마다 계산 그래프에서 달라지는 것은 무엇인가요?","choices":["깊이","폭","층마다의 가중치","비선형 함수"],"a":1,"why":"깊이는 모델이 정하니 모두 같아요. 달라지는 건 **차수(Degree)**가 정하는 폭이에요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.5072,0.1946],"c":[0,0.0019,0.5579,0.2266],"r":4.377,"img":"img/L4/walk/p005_h.jpg"},"parts":[{"b":[0.09,0.275,0.23,0.085],"c":[0.078,0.259,0.254,0.117],"r":3.8594,"img":"img/L4/walk/p005_11_01.jpg","say":"'모든 노드가 저마다 다른 계산 그래프를 만든다!' 여기서 화살표 여섯 개가 뻗어요."},{"b":[0.02,0.54,0.93,0.28],"c":[0,0.524,1,0.312],"r":5.698,"img":"img/L4/walk/p005_11_02.jpg","say":"아래에 여섯 노드의 나무가 나란히 있어요. 폭이 제각각인 게 보이죠."}]}},{"p":6,"title":"층마다 임베딩이 하나씩 생긴다","terms":["Receptive Field","Computation Graph","Shallow Embedding","Degree","Neighborhood Explosion"],"pass1":[{"kind":"say","lines":["노드는 층마다 임베딩을 하나씩 가져요.","층-0 임베딩은 원래 입력 특징 $x_v$ 그 자체예요.","층을 깊게 할수록 계산 그래프는 더 넓어져요."]},{"kind":"analogy","head":"수업을 한 시간씩 들을 때마다 생각이 바뀐다","scene":"민수가 같은 주제로 수업을 세 번 들어요. 수업을 듣기 전 생각이 있고, 한 시간 뒤 생각이 있고, 두 시간 뒤 생각이 또 있어요. 처음 생각은 원래 알고 있던 것 그대로예요. 수업 횟수를 늘릴수록 더 많은 친구의 이야기가 민수 생각에 섞여 들어와요.","map":[["수업 듣기 전 생각","층-0 임베딩, 즉 입력 특징"],["한 시간 뒤 생각","층-1 임베딩"],["수업 횟수","층 수 $L$, 곧 **수용 영역(Receptive Field)**의 크기"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"층 수 $L$ 이 정하는 것","items":["층을 $L$ 개 쌓으면 대상 노드는 $L$ 홉 떨어진 노드까지 정보를 받아요.","2주차 용어로 **수용 영역(Receptive Field)**이 $L$ 홉이 되는 거예요.","홉은 선을 한 번 건너는 걸음이에요.","거리가 $L+1$ 인 노드는 아무리 중요해도 영향을 못 줘요."]},{"kind":"steps","head":"층을 하나 더 쌓으면 칸이 얼마나 느나요","steps":["1층이면 $1 + 3 = 4$ 칸이에요.","2층이면 $1 + 3 + 7 = 11$ 칸이에요.","3층의 맨 아래는 2층 맨 아래 7칸의 차수를 모두 더한 값이에요.","$3 + 4 + 3 + 2 + 2 + 2 + 3 = 19$ 예요.","그래서 3층이면 $1 + 3 + 7 + 19 = 30$ 칸이에요."],"answer":"4 에서 11 로, 11 에서 30 으로 거의 세 배씩 늘어요. 이게 **이웃 폭발(Neighborhood Explosion)**이에요.","given":"대상 노드는 A 하나예요."},{"kind":"viz","viz":"gnn.receptive","head":"움직여 보기: 층을 늘리면 보이는 범위가 어디까지 커지나요","caption":"층 수가 곧 **수용 영역(Receptive Field)**의 크기예요."},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 이 구조 때문에 역전파도 힘들어진다고 했어요.","결과에 따라 역전파를 하려면 계산 그래프를 통째로 들고 있어야 한대요. 그것도 노드마다요.","그래서 계산 복잡도도 높지만 특히 **메모리 점유가 지나치게 크다**고 했어요."]},{"kind":"warn","head":"여기서 주의","items":["층-0 임베딩 $h_v^{(0)} = x_v$ 는 학습되는 값이 아니라 원래 주어진 입력이에요.","1주차의 **얕은 임베딩(Shallow Embedding)**에서는 임베딩 자체가 학습 파라미터였죠. GNN은 달라요.","'깊이를 마음대로'를 '깊을수록 좋다'로 읽으면 안 돼요. 보통 2층이나 3층에서 멈춰요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"The computation graph of a node grows exponentially with the number of layers.","ko":"계산 그래프는 층 수에 따라 지수적으로 커진다.","tip":"이유까지 덧붙이면 좋아요. 층마다 평균 차수가 곱해지기 때문이에요."},{"kind":"check","q":"층을 $L$ 개 쌓으면 수용 영역은 어떻게 되나요?","choices":["$L$ 홉","$L$ 제곱 홉","항상 1홉","그래프 전체"],"a":0,"why":"**수용 영역(Receptive Field)**은 층 수와 같은 홉 수예요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.1933,0.0757],"c":[0.0011,0.0019,0.2173,0.1077],"r":3.5869,"img":"img/L4/walk/p006_h.jpg"},"parts":[{"b":[0.045,0.148,0.36,0.05],"c":[0.027,0.118,0.396,0.11],"r":6.4,"img":"img/L4/walk/p006_20_01.jpg","say":"'노드는 층마다 임베딩을 가진다.' A는 층-0, 층-1, 층-2 임베딩을 따로 가져요."},{"b":[0.045,0.225,0.37,0.048],"c":[0.0265,0.194,0.407,0.11],"r":6.5778,"img":"img/L4/walk/p006_20_02.jpg","say":"'모델 깊이는 마음대로 정할 수 있다.' 좋은 소식이자 나쁜 소식이에요."},{"b":[0.045,0.298,0.46,0.05],"c":[0.022,0.268,0.506,0.11],"r":8.1778,"img":"img/L4/walk/p006_20_03.jpg","say":"'노드 A의 층-0 임베딩은 입력 특징, 즉 $x_A$ 이다.'"},{"b":[0.755,0.435,0.055,0.042],"c":[0.6825,0.401,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p006_20_04.jpg","say":"오른쪽 끝 '층-0'. 그 아래로 $x_A$, $x_C$ 같은 입력 특징이 늘어서요."},{"b":[0.598,0.455,0.05,0.04],"c":[0.523,0.42,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p006_20_05.jpg","say":"가운데 '층-1'. 회색 상자 세 개를 지나 B, C, D 의 층-1 임베딩이 나와요."},{"b":[0.418,0.6,0.05,0.04],"c":[0.343,0.565,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p006_20_06.jpg","say":"왼쪽 '층-2'. 큰 상자를 지나 A의 최종 임베딩이 나와요."}]}},{"p":7,"title":"모델 설계 1: 집계 함수와 손실 함수","terms":["Aggregator","Embedding Utilization","Full-batch","Computation Graph"],"pass1":[{"kind":"say","lines":["GNN을 만들려면 개발자가 세 가지를 골라야 해요.","이 쪽은 앞의 둘, '이웃 집계 함수'와 '임베딩 위의 손실 함수'예요.","오늘 배울 샘플링은 전부 세 번째 칸을 건드려요."]},{"kind":"analogy","head":"요리를 만들 때 정해야 할 세 가지","scene":"민수가 급식을 만들어요. 먼저 재료를 어떻게 섞을지 정해요. 그다음 맛이 좋은지 나쁜지 채점하는 기준을 정해요. 마지막으로 한 번에 몇 인분씩 만들지 정해요. GNN 도 똑같이 세 가지를 정해야 하고, 이번 주 내용은 전부 마지막 하나에 대한 이야기예요.","map":[["재료를 섞는 방법","**집계기(Aggregator)**"],["맛을 채점하는 기준","손실 함수 $L(z_u)$"],["한 번에 몇 인분","배치 구성"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"formula","head":"손실 함수 표기","tex":"L_{total} = \\frac{1}{n} \\sum_{u=1}^{n} L(z_u)","parts":[{"sym":"L","say":"손실 함수. 값이 작을수록 잘한 것이에요."},{"sym":"z_u","say":"노드 $u$ 의 최종 임베딩 벡터예요."},{"sym":"n","say":"학습에 쓰는 노드 수예요."},{"sym":"\\frac{1}{n}\\sum_{u=1}^{n}","say":"대상 노드들의 손실을 평균 내요."}],"whole":"전체 손실은 대상 노드 하나하나의 손실을 평균 낸 값이에요. **풀배치(Full-batch)**란 $n$ 이 그래프의 모든 노드라는 뜻이에요."},{"kind":"compare","head":"GNN 설계 세 칸","cols":["단계","정하는 것","오늘과의 관계"],"rows":[["1 **집계기(Aggregator)**","평균, 합, 최댓값, 풀링, LSTM","**GraphSAGE**가 이 칸을 빈칸으로 바꿈"],["2 손실 함수","노드 분류, 링크 예측","**Cluster-GCN**에서 다시 나옴"],["3 배치 구성","풀배치, 노드 미니 배치, 부분 그래프","이번 주 내용 전체가 이 칸"]]},{"kind":"steps","head":"**임베딩 활용도(Embedding Utilization)**를 세어요","steps":["2층 GNN에서 A 하나의 손실 $L(z_A)$ 를 얻고 싶어요.","그러려면 p.3 에서 센 대로 임베딩 11칸을 계산해야 해요.","쓸모 있는 결과는 1개, 중간 계산은 11개예요.","비율이 1 대 11 이에요."],"answer":"이 비율을 **임베딩 활용도(Embedding Utilization)**라고 불러요. 낮다는 건 계산을 낭비한다는 뜻이에요.","given":"대상 노드 A 하나, 2층 GNN 이에요."},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 이 구조 때문에 노드마다 따로 병렬 연산하기가 힘들다고 했어요.","하나의 그래프에 한 번의 연산을 해야 하니 항상 **풀배치(Full-batch)**로 작동한대요.","PyTorch Geometric 없이 순수 PyTorch로 미니 배치를 짜려 하면 제일 골치가 아프대요.","노드마다 확보해야 할 이웃의 범위가 계속 달라지기 때문이에요."]},{"kind":"mining","src":"마이닝 10강 Random Walk-based GRL","lines":["'임베딩 위에 손실을 건다'는 설계는 랜덤워크 기반 표현 학습과 뼈대가 같아요.","거기서도 노드마다 벡터를 만들고 그 위에 손실을 걸어 학습했어요.","차이는 임베딩을 만드는 방법이에요. 거기는 표에서 꺼냈고, GNN은 이웃 집계로 계산해요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"A GNN is trained by defining an aggregation function, defining a loss, and updating the shared weights.","ko":"GNN은 집계 함수를 정하고, 손실을 정하고, 공유된 가중치를 갱신해서 학습한다.","tip":"aggregation, loss, weights 세 단어 순서로 외우세요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.2688,0.0757],"c":[0,0.0019,0.2957,0.1077],"r":4.881,"img":"img/L4/walk/p007_h.jpg"},"parts":[{"b":[0.455,0.21,0.24,0.075],"c":[0.443,0.1925,0.264,0.11],"r":4.2667,"img":"img/L4/walk/p007_20_01.jpg","say":"'1) 이웃 집계 함수를 정한다.' 굵은 파란 화살표가 회색 상자들을 가리켜요."},{"b":[0.595,0.295,0.12,0.28],"c":[0.555,0.279,0.2,0.312],"r":1.1396,"img":"img/L4/walk/p007_20_02.jpg","say":"화살표가 가리키는 곳이 집계 상자예요. 여기 내용물을 네가 정하라는 표시예요."},{"b":[0.435,0.478,0.06,0.045],"c":[0.365,0.4455,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p007_20_03.jpg","say":"$z_A$ 는 A의 **최종** 임베딩이에요. $h$ 는 중간, $z$ 는 다 끝난 결과예요."},{"b":[0.35,0.782,0.28,0.082],"c":[0.336,0.766,0.308,0.114],"r":4.8031,"img":"img/L4/walk/p007_20_04.jpg","say":"'2) 임베딩 위에 손실 함수를 정한다, $L(z_u)$.' 손실은 얼마나 틀렸는지 재는 자예요."}]}},{"p":8,"title":"모델 설계 3: 계산 그래프 묶음으로 학습","terms":["Mini-batch","Full-batch","Computation Graph","SGD"],"pass1":[{"kind":"say","lines":["세 번째 단계는 배치예요.","노드 여러 개를 묶어서 그 계산 그래프들을 한꺼번에 학습에 써요.","이 묶음을 어떻게 만드느냐가 오늘의 주제예요."]},{"kind":"analogy","head":"문제집을 몇 장씩 풀까","scene":"민수가 문제집 100장을 풀고 채점해요. 100장을 다 풀고 한꺼번에 채점하면 정확하지만 하루가 걸려요. 10장씩 풀고 바로 채점하면 훨씬 빨리 고쳐 나갈 수 있죠. 이 '10장씩'이 미니 배치예요.","map":[["100장 다 풀고 채점","**풀배치(Full-batch)**"],["10장씩 풀고 채점","**미니 배치(Mini-batch)**"],["채점해서 고치기","기울기로 가중치 갱신"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"배치 용어 세 개","items":["배치는 한 번에 같이 처리하는 학습 표본의 묶음이에요.","**미니 배치(Mini-batch)**는 전체 중 일부만 담은 작은 묶음이에요.","**풀배치(Full-batch)**는 전체를 다 담은 묶음이에요.","배치 크기는 대상 노드가 몇 개인지를 말해요."]},{"kind":"steps","head":"배치 {A, B, C} 는 몇 칸인가요","steps":["p.5 에서 센 값을 그대로 써요.","A는 11칸, B는 10칸, C는 14칸이에요.","합계는 $11 + 10 + 12 = 33$ 칸이에요.","여섯 노드를 모두 넣으면 $11+10+12+5+9+9 = 56$ 칸이에요."],"answer":"원래 그래프의 노드는 6개뿐인데 35칸이에요. 같은 노드를 평균 5.8번씩 다시 계산한다는 뜻이에요.","given":"2층 GNN, 배치는 {A, B, C} 예요."},{"kind":"points","head":"배치를 1로 줄이면 되지 않나요","items":["안 돼요. 이유가 두 가지예요.","첫째, 배치를 1로 줄여도 그 노드 하나의 계산 그래프는 그대로예요.","대상 노드가 허브면 배치 크기 1에서도 100만 칸이 필요해요.","둘째, 배치가 너무 작으면 **확률적 경사하강(SGD)**의 흔들림이 커져 학습이 불안정해져요."]},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 이 묶음 이야기를 확장성 문제로 곧장 이었어요.","인접행렬을 통으로 갖다 놓고 계산하려니 메모리가 터져 나간대요.","**풀배치(Full-batch)**로 작동하니 역전파에 부하가 걸리고 학습도 안정적이지 않대요.","그래서 결론은 어떻게든 쪼갤 방법을 고민해야 한다는 거예요."]},{"kind":"mining","src":"마이닝 노드 분류 주차","lines":["그래프의 모든 노드에 정답 레이블이 붙어 있지는 않아요.","그래서 배치에 넣을 수 있는 대상 노드는 레이블이 있는 노드뿐이에요.","다만 계산 그래프에는 레이블 없는 이웃도 다 들어가요. 정보는 날라 주니까요.","이렇게 일부만 정답이 있는 상황을 준지도 학습이라고 불러요."]},{"kind":"warn","head":"헷갈리기 쉬운 두 쌍","items":["'배치'와 '층'은 달라요. 층은 깊이, 배치는 한 번에 처리하는 대상 노드 수예요.","'배치 크기'와 '샘플링 이웃 수'도 달라요. `batch_size=32, sizes=[10,5]` 에서 32가 배치 크기예요."]}],"pass3":[{"kind":"check","q":"배치를 1로 줄이면 메모리 문제가 풀릴까요?","choices":["풀려요","안 풀려요. 대상 노드의 이웃은 그대로 따라오니까요","층을 늘리면 풀려요","차수가 커지면 풀려요"],"a":1,"why":"줄어드는 건 대상 노드 개수뿐이에요. 따라오는 이웃은 그대로예요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.2688,0.0757],"c":[0,0.0019,0.2957,0.1077],"r":4.881,"img":"img/L4/walk/p008_h.jpg"},"parts":[{"b":[0.415,0.29,0.24,0.072],"c":[0.403,0.271,0.264,0.11],"r":4.2667,"img":"img/L4/walk/p008_20_01.jpg","say":"'3) 노드 묶음, 즉 계산 그래프 묶음 위에서 학습한다.'"},{"b":[0.255,0.21,0.12,0.135],"c":[0.215,0.194,0.2,0.167],"r":2.1291,"img":"img/L4/walk/p008_20_02.jpg","say":"왼쪽 그래프에서 A, B, C 에만 빨간 점선이 있어요. 이번 배치의 대상 노드예요."},{"b":[0.26,0.52,0.44,0.25],"c":[0.238,0.504,0.484,0.282],"r":3.0512,"img":"img/L4/walk/p008_20_03.jpg","say":"파란 상자 안에 계산 그래프 세 개가 나란히 있어요. 이 묶음이 곧 배치예요."}]}},{"p":9,"title":"실세계 그래프는 매우 크다","terms":["Adjacency Matrix","Scalability","Degree"],"pass1":[{"kind":"say","lines":["실세계 그래프는 노드가 수억 개예요.","**인접행렬(Adjacency Matrix)**을 통째로 올리는 것만으로 메모리가 감당이 안 돼요.","그래서 **확장성(Scalability)**은 선택이 아니라 필수예요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.007,"y":0.265,"w":0.48,"h":0.63,"say":"페이스북 월간 활성 사용자 수 꺾은선이에요. 2023년에 약 30억 명에 닿아요.","c":[0,0.2335,0.528,0.693],"r":1.3545,"img":"img/L4/walk/p009_20_01.jpg"},{"x":0.5,"y":0.425,"w":0.49,"h":0.125,"say":"ZINC15 설명이에요. 구매 가능 화합물 7억 5천만 개 이상을 담고 있대요.","c":[0.461,0.409,0.539,0.157],"r":6.1033,"img":"img/L4/walk/p009_20_02.jpg"},{"x":0.02,"y":0.945,"w":0.5,"h":0.04,"say":"맨 아래는 참고문헌 주소예요.","c":[0,0.8889,0.55,0.1111],"r":8.8009,"img":"img/L4/walk/p009_20_03.jpg"}]},{"kind":"steps","head":"노드 30억 개면 인접행렬이 얼마나 큰가요","steps":["**인접행렬(Adjacency Matrix)**은 $n \\times n$ 크기예요.","$n = 3 \\times 10^9$ 이에요.","칸 수는 $(3 \\times 10^9)^2 = 9 \\times 10^{18}$, 즉 900경 칸이에요.","칸마다 1바이트만 써도 약 90억 GB 예요."],"answer":"GPU 한 장은 보통 24GB 에서 80GB 예요. 상상도 못 할 크기죠. 이걸 $n$ 제곱 메모리 문제라고 불러요.","given":"빽빽한 행렬로 메모리에 올린다고 할게요."},{"kind":"figure","head":"노드가 10배면 칸은 100배","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<rect class=\"box\" x=\"30\" y=\"60\" width=\"60\" height=\"60\" rx=\"6\"/>\n<text class=\"tb\" x=\"60\" y=\"46\" font-size=\"15\" text-anchor=\"middle\">노드 10개<\/text>\n<text class=\"t\" x=\"60\" y=\"96\" font-size=\"15\" text-anchor=\"middle\">칸 100<\/text>\n<rect class=\"box b1\" x=\"150\" y=\"40\" width=\"100\" height=\"100\" rx=\"6\"/>\n<text class=\"tb b1\" x=\"200\" y=\"26\" font-size=\"15\" text-anchor=\"middle\">노드 100개<\/text>\n<text class=\"t b1\" x=\"200\" y=\"96\" font-size=\"15\" text-anchor=\"middle\">칸 10,000<\/text>\n<rect class=\"box2 b2\" x=\"300\" y=\"20\" width=\"140\" height=\"140\" rx=\"6\"/>\n<text class=\"tb b2\" x=\"370\" y=\"14\" font-size=\"15\" text-anchor=\"middle\">노드 1,000개<\/text>\n<text class=\"t b2\" x=\"370\" y=\"96\" font-size=\"15\" text-anchor=\"middle\">칸 1,000,000<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"196\" font-size=\"16\" text-anchor=\"middle\">노드가 10배면 인접행렬 칸은 100배<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"224\" font-size=\"14\" text-anchor=\"middle\">노드 30억이면 칸이 900경, 약 90억 GB 예요<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"250\" font-size=\"14\" text-anchor=\"middle\">GPU 한 장은 보통 24GB 에서 80GB 예요<\/text>\n<\/svg>","caption":"$n$ 이 커지면 $n^2$ 은 절망적으로 커져요. 노드를 10배 늘리면 메모리는 100배가 돼요.","builds":3},{"kind":"compare","head":"큰 그래프에는 두 종류가 있어요","cols":["","그래프 한 장이 거대","작은 그래프가 아주 많음"],"rows":[["예","페이스북 소셜 그래프","ZINC 화합물, 단백질 구조"],["주된 과제","노드 분류, 링크 예측","그래프 분류"],["무엇이 문제","한 그래프가 메모리에 안 들어감","그래프 수가 많아 학습 시간이 김"],["해법의 방향","그래프를 쪼갠다 (이번 주)","그래프 단위로 배치를 만든다"]]},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 실세계 그래프의 크기를 이렇게 말했어요.","노드가 수백만에서 수천만 개, 수억 개에 달한대요.","인접행렬을 메모리에 올리는 것만 해도 $n$ 제곱만큼의 공간이 필요하다고 지적했어요.","소셜 미디어, 단백질, DNA 모두 마찬가지이고 갈수록 커진다고 했어요."]},{"kind":"mining","src":"마이닝 2강 Representation of Graphs and Storage","lines":["해결책이 하나 있어요. 희소 행렬 표현이에요.","실세계 그래프는 엣지가 적어서 인접행렬의 거의 모든 칸이 0 이에요.","0을 다 저장하지 말고 1인 자리만 목록으로 적자는 거예요.","그러면 메모리가 $n^2$ 이 아니라 엣지 수 $m$ 에 비례해요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"Storing the dense adjacency matrix requires O(n^2) memory, which does not fit into GPU memory.","ko":"빽빽한 인접행렬을 저장하려면 $n$ 제곱 메모리가 필요하고, 이는 GPU 메모리에 들어가지 않는다.","tip":"dense adjacency matrix 라는 표기를 그대로 쓰세요."},{"kind":"warn","head":"답안에서 조심할 점","items":["'그래프가 크다'에는 두 가지 뜻이 있어요. 이번 주는 그래프 한 장이 거대한 경우예요.","노드가 30억이라고 엣지도 30억인 건 아니에요. 엣지는 수천억 개예요.","희소 표현은 저장 문제만 풀어요. 계산 그래프 폭발은 그대로 남아요."]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.3843,0.0757],"c":[0,0.0019,0.4227,0.1077],"r":6.9774,"img":"img/L4/walk/p009_h.jpg"},"parts":[{"b":[0.19,0.198,0.1,0.042],"c":[0.14,0.164,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p009_11_01.jpg","say":"왼쪽은 '규모가 크다'. 그래프 한 장이 거대한 경우예요."},{"b":[0.665,0.198,0.1,0.042],"c":[0.615,0.164,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p009_11_02.jpg","say":"오른쪽은 '개수가 많다'. 작은 그래프가 아주 많은 경우예요."}]}},{"p":10,"title":"벤치마크 그래프도 이미 거대하다","terms":["Degree","Scalability","Full-batch","Neighborhood Explosion"],"pass1":[{"kind":"say","lines":["연구용 표준 데이터셋조차 노드 1억, 엣지 16억 규모예요.","'큰 그래프'는 예외가 아니라 기본이에요.","그래서 **확장성(Scalability)**은 연구실에서도 피할 수 없는 문제예요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.06,"y":0.25,"w":0.57,"h":0.07,"say":"맨 윗줄 ogbn-papers100M. 노드 111,059,956개, 엣지 1,615,685,872개예요.","c":[0.0315,0.2217,0.627,0.1267],"r":8.7977,"img":"img/L4/walk/p010_20_01.jpg"},{"x":0.06,"y":0.64,"w":0.57,"h":0.07,"say":"맨 아랫줄 ogbn-arxiv. 노드 169,343개, 엣지 1,166,243개예요.","c":[0.0315,0.6117,0.627,0.1267],"r":8.7977,"img":"img/L4/walk/p010_20_02.jpg"},{"x":0.063,"y":0.732,"w":0.33,"h":0.035,"say":"'막대는 로그 눈금'이라는 설명이에요. 길이가 값이 아니라 자릿수에 비례해요.","c":[0.0465,0.6945,0.363,0.11],"r":5.8667,"img":"img/L4/walk/p010_20_03.jpg"},{"x":0.02,"y":0.93,"w":0.52,"h":0.055,"say":"참고문헌은 Ma, Rong, Huang 의 Graph neural networks: Scalability (2022) 예요.","c":[0,0.8844,0.572,0.1156],"r":8.7966,"img":"img/L4/walk/p010_20_04.jpg"}]},{"kind":"compare","head":"OGB 노드 분류 데이터셋","cols":["데이터셋","노드 수","엣지 수"],"rows":[["ogbn-papers100M","111,059,956","1,615,685,872"],["ogbn-products","2,449,029","61,859,140"],["ogbn-proteins","132,534","39,561,252"],["ogbn-mag","1,939,743","21,111,007"],["ogbn-arxiv","169,343","1,166,243"]]},{"kind":"steps","head":"평균 **차수(Degree)**를 구해요","steps":["무방향 그래프에서 평균 차수는 $d = 2m/n$ 이에요.","엣지 하나가 양쪽 노드의 차수를 1씩 올리니까 2를 곱해요.","ogbn-arxiv: $2 \\times 1{,}166{,}243 / 169{,}343 \\approx 14$ 예요.","ogbn-papers100M: $\\approx 29$, ogbn-proteins: $\\approx 597$ 이에요.","2층 계산 그래프는 대략 $d^2$ 칸이에요. arxiv 는 196, proteins 는 356,409 예요."],"answer":"proteins 는 3층이면 노드 하나의 계산 그래프가 약 2억 칸이에요. 전체 노드가 13만 개인데도요.","given":"$n$ 은 노드 수, $m$ 은 엣지 수예요."},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 이런 규모에서 '인접행렬을 통으로 갖다 놓고 계산하려니 메모리가 터져 나간다'고 했어요.","그리고 **풀배치(Full-batch)**로 작동하다 보니 역전파에 부하가 걸린대요.","학습도 그다지 안정적이지 않다고 덧붙였어요.","즉 문제는 메모리만이 아니라 학습의 질까지 건드려요."]},{"kind":"mining","src":"마이닝 1강, 2강","lines":["밀도는 실제 엣지 수를 가능한 최대 엣지 수 $n(n-1)/2$ 로 나눈 값이에요.","ogbn-arxiv 의 밀도는 약 0.008퍼센트예요.","인접행렬의 칸 중 99.99퍼센트가 0 이라는 뜻이에요.","실세계 그래프는 이렇게 희소해요."]},{"kind":"warn","head":"숫자를 읽을 때 주의","items":["노드가 적다고 가벼운 게 아니에요. proteins 는 노드가 적은데 평균 차수가 597이에요.","막대는 로그 눈금이라 길이를 그대로 값 비교로 읽으면 안 돼요.","평균 차수는 평균일 뿐이에요. 평균이 29여도 차수 100만인 노드가 섞여 있을 수 있어요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"Even standard benchmarks contain about 111 million nodes and 1.6 billion edges, so full-batch training is impossible.","ko":"표준 벤치마크조차 노드 약 1억 1천만, 엣지 16억 개라서 풀배치 학습이 불가능하다.","tip":"full-batch training is impossible 이 결론 부분이에요."},{"kind":"check","q":"계산 그래프의 크기를 주로 정하는 것은 무엇인가요?","choices":["노드 수","**차수(Degree)**","엣지 이름","데이터셋 이름"],"a":1,"why":"노드가 13만 개뿐인 proteins 가 가장 무거웠죠. 차수가 597이기 때문이에요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.546,0.2742],"c":[0,0.0019,0.6006,0.3062],"r":3.487,"img":"img/L4/walk/p010_h.jpg"},"parts":[{"b":[0.7,0.3,0.23,0.28],"c":[0.688,0.284,0.254,0.312],"r":1.4473,"img":"img/L4/walk/p010_11_01.jpg","say":"큰 초록 글씨 '111M'. ogbn-papers100M 의 노드 수예요. 엣지는 16억 개가 넘어요."},{"b":[0.7,0.6,0.23,0.185],"c":[0.688,0.584,0.254,0.217],"r":2.0809,"img":"img/L4/walk/p010_11_02.jpg","say":"아래 상자는 '작은 ogbn-arxiv 조차 노드 16.9만, 엣지 117만'이에요."}]}},{"p":11,"title":"GCN의 한계: 이웃 폭발과 허브 노드","terms":["GCN","Neighborhood Explosion","Hub Node","Scale-free Graph","Degree","Community","Adjacency Matrix","Transductive Learning","GraphSAGE"],"pass1":[{"kind":"say","lines":["**GCN**의 한계는 두 가지예요.","하나는 K홉 계산 그래프가 지수적으로 커져 GPU 메모리에 안 들어간다는 것이에요.","다른 하나는 **허브 노드(Hub Node)** 하나가 전체를 망가뜨린다는 것이에요."]},{"kind":"analogy","head":"연예인 한 명이 낀 단톡방","scene":"민수가 친구들에게 소식을 물으려고 단톡방을 만들었어요. 친구 세 명이면 금방 끝나요. 그런데 그중 한 명이 팔로워 1,000만 명인 연예인이라, 그 사람의 친구 목록까지 다 물어보려니 끝이 없어요. 한 명 때문에 방 전체가 감당이 안 되는 거예요.","map":[["연예인 한 명","**허브 노드(Hub Node)**"],["친구의 친구까지 묻기","2홉 이웃까지 계산하기"],["방이 감당 안 됨","GPU 메모리 초과"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.08,"y":0.22,"w":0.77,"h":0.042,"say":"'K홉 이웃 전체의 계산 그래프를 만들어야 한다.' 층을 K개 쌓으면 K홉까지 봐야 해요.","c":[0.0415,0.1554,0.847,0.1711],"r":8.8006,"img":"img/L4/walk/p011_20_01.jpg"},{"x":0.08,"y":0.328,"w":0.53,"h":0.04,"say":"'이웃으로 깊이 들어갈수록 계산 그래프는 지수적으로 커진다.'","c":[0.0535,0.2891,0.583,0.1178],"r":8.7983,"img":"img/L4/walk/p011_20_02.jpg"},{"x":0.095,"y":0.393,"w":0.52,"h":0.042,"say":"'이 계산 그래프를 GPU 메모리에 올리는 것 자체가 문제가 된다.'","c":[0.069,0.3562,0.572,0.1156],"r":8.7966,"img":"img/L4/walk/p011_20_03.jpg"},{"x":0.08,"y":0.542,"w":0.47,"h":0.04,"say":"'허브 노드란 그래프에서 차수가 매우 높은 노드를 말한다.'","c":[0.0565,0.507,0.517,0.11],"r":8.3556,"img":"img/L4/walk/p011_20_04.jpg"},{"x":0.295,"y":0.64,"w":0.185,"h":0.27,"say":"왼쪽 그림은 보통 노드의 계산 그래프예요. 아담한 크기죠.","c":[0.283,0.624,0.209,0.302],"r":1.2303,"img":"img/L4/walk/p011_20_05.jpg"},{"x":0.505,"y":0.628,"w":0.22,"h":0.29,"say":"오른쪽은 허브가 낀 경우예요. 가지가 너무 많아 점 세 개로 생략돼 있어요.","c":[0.493,0.612,0.244,0.322],"r":1.3471,"img":"img/L4/walk/p011_20_06.jpg"}]},{"kind":"steps","head":"허브가 끼면 칸 수가 어떻게 되나요","steps":["2층 **GCN**의 칸 수는 $1 + d + d^2$ 예요.","평범한 노드 ($d = 3$): $1 + 3 + 9 = 13$ 칸이에요.","이웃 중 하나가 허브($d = 1{,}000$)면 층-0 이 약 1,004칸, 합계 약 1,008칸이에요.","대상 노드 자신이 허브면 층-1 이 1,000, 층-0 이 1,000,000 이에요.","합계 약 1,001,001칸이에요."],"answer":"평범한 노드 13칸, 허브 노드 100만 칸. 7만 배 넘게 차이 나요. 이게 허브 노드의 저주예요.","given":"$d$ 는 평균 **차수(Degree)**예요."},{"kind":"figure","head":"평범한 노드와 허브 노드","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"118\" y=\"24\" font-size=\"16\" text-anchor=\"middle\">평범한 노드 (차수 3)<\/text>\n<line class=\"e\" x1=\"118\" y1=\"54\" x2=\"76\" y2=\"98\"/>\n<line class=\"e\" x1=\"118\" y1=\"54\" x2=\"118\" y2=\"98\"/>\n<line class=\"e\" x1=\"118\" y1=\"54\" x2=\"160\" y2=\"98\"/>\n<line class=\"e b1\" x1=\"76\" y1=\"126\" x2=\"50\" y2=\"166\"/>\n<line class=\"e b1\" x1=\"76\" y1=\"126\" x2=\"76\" y2=\"166\"/>\n<line class=\"e b1\" x1=\"76\" y1=\"126\" x2=\"102\" y2=\"166\"/>\n<line class=\"e b1\" x1=\"118\" y1=\"126\" x2=\"118\" y2=\"166\"/>\n<line class=\"e b1\" x1=\"160\" y1=\"126\" x2=\"140\" y2=\"166\"/>\n<line class=\"e b1\" x1=\"160\" y1=\"126\" x2=\"180\" y2=\"166\"/>\n<circle class=\"n2\" cx=\"118\" cy=\"40\" r=\"14\"/>\n<circle class=\"n\" cx=\"76\" cy=\"112\" r=\"12\"/>\n<circle class=\"n\" cx=\"118\" cy=\"112\" r=\"12\"/>\n<circle class=\"n\" cx=\"160\" cy=\"112\" r=\"12\"/>\n<circle class=\"n b1\" cx=\"50\" cy=\"178\" r=\"10\"/>\n<circle class=\"n b1\" cx=\"76\" cy=\"178\" r=\"10\"/>\n<circle class=\"n b1\" cx=\"102\" cy=\"178\" r=\"10\"/>\n<circle class=\"n b1\" cx=\"118\" cy=\"178\" r=\"10\"/>\n<circle class=\"n b1\" cx=\"140\" cy=\"178\" r=\"10\"/>\n<circle class=\"n b1\" cx=\"180\" cy=\"178\" r=\"10\"/>\n<text class=\"tb b1\" x=\"118\" y=\"214\" font-size=\"16\" text-anchor=\"middle\">약 13칸<\/text>\n<text class=\"tb\" x=\"352\" y=\"24\" font-size=\"16\" text-anchor=\"middle\">허브 노드 (차수 1,000)<\/text>\n<line class=\"e2 b2\" x1=\"352\" y1=\"54\" x2=\"270\" y2=\"98\"/>\n<line class=\"e2 b2\" x1=\"352\" y1=\"54\" x2=\"310\" y2=\"98\"/>\n<line class=\"e2 b2\" x1=\"352\" y1=\"54\" x2=\"352\" y2=\"98\"/>\n<line class=\"e2 b2\" x1=\"352\" y1=\"54\" x2=\"394\" y2=\"98\"/>\n<line class=\"e2 b2\" x1=\"352\" y1=\"54\" x2=\"434\" y2=\"98\"/>\n<circle class=\"n2\" cx=\"352\" cy=\"40\" r=\"14\"/>\n<circle class=\"n3 b2\" cx=\"270\" cy=\"112\" r=\"12\"/>\n<circle class=\"n3 b2\" cx=\"310\" cy=\"112\" r=\"12\"/>\n<circle class=\"n3 b2\" cx=\"352\" cy=\"112\" r=\"12\"/>\n<circle class=\"n3 b2\" cx=\"394\" cy=\"112\" r=\"12\"/>\n<circle class=\"n3 b2\" cx=\"434\" cy=\"112\" r=\"12\"/>\n<text class=\"tm b2\" x=\"352\" y=\"144\" font-size=\"14\" text-anchor=\"middle\">이런 가지가 1,000개<\/text>\n<text class=\"tm b2\" x=\"352\" y=\"168\" font-size=\"14\" text-anchor=\"middle\">그 아래 또 1,000개씩<\/text>\n<text class=\"tb b2\" x=\"352\" y=\"214\" font-size=\"16\" text-anchor=\"middle\">약 1,001,001칸<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"248\" font-size=\"16\" text-anchor=\"middle\">같은 2층인데 7만 배 넘게 차이 나요<\/text>\n<\/svg>","caption":"배치를 만들 때 어느 노드가 뽑힐지 모르니, 메모리는 최악의 경우에 맞춰 잡아야 해요.","builds":3},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 이 부분을 시험 포인트로 길게 설명했어요.","실세계 그래프, 특히 소셜 미디어는 **스케일 프리 그래프(Scale-free Graph)**래요.","차수가 0이나 1인 노드가 대부분이고 차수 높은 노드는 거의 없는 모양이에요.","허브를 중심으로 주변부가 따닥따닥 붙어 **커뮤니티(Community)**를 이룬다고 했어요."]},{"kind":"mining","src":"마이닝 3강 Centrality Measures","lines":["완전히 무작위로 만든 그래프에서는 차수가 푸아송 분포를 따라요. 종 모양이죠.","그런데 실제 네트워크는 연결이 아주 많은 노드가 몇 개 있어요. 이걸 허브라고 불러요.","대부분의 노드는 차수가 낮고, 적지만 중요한 일부는 차수가 엄청나게 높아요.","그래서 긴 꼬리가 생기고, 이것을 거듭제곱 법칙 분포라고 해요."]}],"pass3":[{"kind":"exam","src":"2024 가을 기말 1번 (b)","q":"What are the limitations of the GCN model compared to GraphSage?","qko":"**GraphSAGE**와 비교했을 때 **GCN** 모델의 한계는 무엇인가요?","solve":["한계를 두 갈래로 나눠 쓰면 점수가 깔끔해요.","첫째는 **확장성(Scalability)**이에요. **GCN**은 학습 중 전체 **인접행렬(Adjacency Matrix)**과 특징행렬이 필요해요.","전체 그래프에 대한 행렬 곱 때문에 메모리 사용량이 크고 계산이 비효율적이에요.","둘째는 **변환적 학습(Transductive Learning)**이에요. **GCN**은 고정된 그래프 구조를 가정해요.","노드나 엣지를 추가하면 모델을 다시 학습하거나 임베딩을 다시 계산해야 해요."],"answer":"Scalability 와 Transductive learning 두 가지. 각각 '전체 행렬이 필요하다'와 '그래프가 바뀌면 재학습'으로 씁니다."},{"kind":"english","head":"답안에 그대로 쓸 문장","en":"GCNs require the entire graph adjacency matrix and feature matrix during training.","ko":"GCN은 학습 중에 전체 인접행렬과 특징행렬을 필요로 한다.","tip":"entire 와 during training 두 부분이 채점 포인트예요."},{"kind":"check","q":"**스케일 프리 그래프(Scale-free Graph)**의 차수 분포는 어떤 모양인가요?","choices":["모든 노드의 차수가 같다","차수 낮은 노드가 대부분이고 허브가 드물게 있다","차수가 평균 근처에 몰린 종 모양이다","차수가 무작위로 고르다"],"a":1,"why":"긴 꼬리가 생기는 거듭제곱 법칙 분포예요. 그래서 **허브 노드(Hub Node)**가 반드시 있어요."},{"kind":"warn","head":"표현에 주의","items":["'지수적으로 커진다'를 '층 수에 비례해서 커진다'로 읽으면 안 돼요.","비례는 층이 2배면 크기도 2배지만, 지수는 층이 1 늘 때마다 $d$ 배가 되는 거예요.","$d = 30$ 이면 층 하나에 30배씩 늘어요. 이게 **이웃 폭발(Neighborhood Explosion)**이에요."]}],"pass4":[{"kind":"pyterm","name":"모양(shape)","say":["텐서는 숫자를 네모나게 담아 둔 상자예요.","`.shape` 는 그 상자가 몇 줄 몇 칸인지 알려 줘요.","`torch.zeros(n, n)` 은 $n \\times n$ 짜리 0 상자를 새로 만들어요."],"example":"A = torch.zeros(3, 3)\nprint(A.shape)","out":"torch.Size([3, 3])"},{"kind":"code","head":"인접행렬을 노드 수 x 노드 수 로 통째로 만들어요","file":"PracticeCode_2.ipynb 셀 30","code":"def build_gcn_normalized_adjacency(edge_index, num_nodes):\n    '''\n    Return A_hat = D_tilde^{-1/2} A_tilde D_tilde^{-1/2}\n    where A_tilde = A + I.\n    '''\n    edge_index_with_loops, _ = add_self_loops(edge_index, num_nodes=num_nodes)\n    row, col = edge_index_with_loops\n\n    deg = degree(row, num_nodes=num_nodes)\n    deg_inv_sqrt = deg.pow(-0.5)\n    deg_inv_sqrt[deg_inv_sqrt == float(\"inf\")] = 0\n    norm_coeffs = deg_inv_sqrt[row] * deg_inv_sqrt[col]\n\n    A_hat = torch.zeros(num_nodes, num_nodes)\n    for i in range(edge_index_with_loops.shape[1]):\n        src, dst = int(row[i]), int(col[i])\n        A_hat[dst, src] = norm_coeffs[i]\n\n    return A_hat, edge_index_with_loops, deg\n\n\nA_hat, edge_index_with_loops, deg = build_gcn_normalized_adjacency(\n    data.edge_index, num_nodes\n)\n\nprint(\"Normalized adjacency (A_hat) statistics:\")\nprint(f\"  Shape: {tuple(A_hat.shape)}\")\nprint(f\"  Non-zero entries: {int((A_hat != 0).sum())}\")\nprint(f\"  Row sums (first 5): {A_hat.sum(dim=1)[:5].tolist()}\")","lines":[{"from":1,"to":5,"say":"함수 이름과 설명이에요. 따옴표 세 개 사이는 실행되지 않는 설명 글이에요. 자기 자신으로 가는 선(self loop)을 더한 뒤 정규화한 인접행렬을 돌려준대요."},{"from":6,"to":7,"say":"`add_self_loops` 로 모든 노드에 자기 자신으로 가는 선을 하나씩 붙여요. `row, col` 은 선의 출발점 번호 목록과 도착점 번호 목록이에요."},{"from":9,"to":12,"say":"`degree` 로 노드마다 **차수(Degree)**를 세고, 그 -0.5 제곱을 구해요. 무한대가 나오면 0으로 바꾸고, 선마다 양쪽 값을 곱해 정규화 계수를 만들어요."},{"from":14,"to":17,"say":"여기가 핵심이에요. `torch.zeros(num_nodes, num_nodes)` 로 **노드 수 x 노드 수** 짜리 빈 표를 통째로 만들어요. 그리고 선이 있는 칸에만 값을 채워요."},{"from":19,"to":19,"say":"`return` 은 결과를 돌려주는 말이에요. 만든 표와 선 목록과 차수를 함께 돌려줘요."},{"from":22,"to":24,"say":"실제로 함수를 불러 `A_hat` 을 만들어요. 가라테 동아리 그래프라 노드가 34개뿐이에요."},{"from":26,"to":29,"say":"만든 표의 모양과 0이 아닌 칸 수, 앞 다섯 줄의 합을 출력해요."}],"link":"슬라이드 p.9 의 '$n$ 제곱 메모리' 문제가 이 줄에 그대로 있어요. 노드가 1억이면 이 표는 만들 수 없어요."}],"walk":{"head":{"b":[0.0131,0.0179,0.3444,0.0757],"c":[0,0.0019,0.3789,0.1077],"r":6.2544,"img":"img/L4/walk/p011_h.jpg"},"parts":[{"b":[0.047,0.143,0.19,0.045],"c":[0.035,0.1105,0.214,0.11],"r":3.4586,"img":"img/L4/walk/p011_12_01.jpg","say":"첫째 굵은 항목: '계산 비용이 크다'."},{"b":[0.047,0.464,0.35,0.044],"c":[0.0295,0.431,0.385,0.11],"r":6.2222,"img":"img/L4/walk/p011_12_02.jpg","say":"둘째 굵은 항목: '허브 노드 또는 유명인 노드의 저주'."}]}},{"p":12,"title":"원래 GNN을 막는 두 가지 장벽","terms":["Adjacency Matrix","SGD","Full-batch","Mini-batch","Neighborhood Explosion","GCN"],"pass1":[{"kind":"say","lines":["장벽은 딱 둘이에요.","하나는 메모리. **인접행렬(Adjacency Matrix)**과 특징행렬 전체를 올려야 해요.","다른 하나는 기울기 갱신. 반복마다 모든 노드를 이웃 따라 재귀로 갱신해요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"상자 안 글자 하나씩","boxes":[{"x":0.08,"y":0.32,"w":0.4,"h":0.055,"say":"'대부분의 GNN 은 인접행렬 전체와 모든 노드의 특징, 임베딩 행렬을 메모리에 올린다.'","c":[0.06,0.2925,0.44,0.11],"r":7.1111,"img":"img/L4/walk/p012_20_01.jpg"},{"x":0.08,"y":0.41,"w":0.4,"h":0.055,"say":"'아주 큰 그래프에서는 이게 들어가지 않아서 GNN 을 그대로 쓸 수 없다.'","c":[0.06,0.3825,0.44,0.11],"r":7.1111,"img":"img/L4/walk/p012_20_02.jpg"},{"x":0.52,"y":0.32,"w":0.4,"h":0.055,"say":"'학습 반복마다 모든 노드의 기울기를 이웃을 따라 재귀로 갱신한다.'","c":[0.5,0.2925,0.44,0.11],"r":7.1111,"img":"img/L4/walk/p012_20_03.jpg"},{"x":0.52,"y":0.41,"w":0.4,"h":0.04,"say":"'거대한 데이터에 풀배치 경사하강을 하는 것만큼 느리다.'","c":[0.5,0.375,0.44,0.11],"r":7.1111,"img":"img/L4/walk/p012_20_04.jpg"}]},{"kind":"formula","head":"왼쪽 식: GD (풀배치 경사하강)","tex":"\\theta \\leftarrow \\theta - \\eta \\nabla_\\theta \\frac{1}{n} \\sum_{i=1}^{n} \\ell_i","parts":[{"sym":"\\theta","say":"모델의 모든 학습 파라미터 묶음. 지금까지 정리한 공부 노트예요."},{"sym":"\\leftarrow","say":"오른쪽 값으로 왼쪽을 새로 쓴다는 표시예요."},{"sym":"\\eta","say":"학습률. 한 걸음의 보폭이에요."},{"sym":"\\nabla_\\theta","say":"기울기. 어느 방향으로 고쳐야 덜 틀리는지 알려 줘요."},{"sym":"\\ell_i","say":"$i$ 번째 노드의 손실. 문제 $i$ 를 얼마나 틀렸는지예요."},{"sym":"\\frac{1}{n}\\sum_{i=1}^{n}","say":"노드 $n$ 개 전부의 평균이에요."}],"whole":"모든 노드의 손실을 평균 내서 기울기를 구하고, 그 반대 방향으로 보폭 $\\eta$ 만큼 가중치를 옮겨요. **풀배치(Full-batch)**예요."},{"kind":"formula","head":"오른쪽 식: SGD (확률적 경사하강)","tex":"\\theta \\leftarrow \\theta - \\eta \\nabla_\\theta \\frac{1}{|\\mathcal{B}|} \\sum_{i \\in \\mathcal{B}} \\ell_i","parts":[{"sym":"\\mathcal{B}","say":"이번 반복에 쓰는 작은 묶음, 즉 **미니 배치(Mini-batch)**예요."},{"sym":"|\\mathcal{B}|","say":"그 묶음에 든 표본 수, 배치 크기예요."},{"sym":"\\sum_{i \\in \\mathcal{B}}","say":"묶음 안의 손실만 더해요."}],"whole":"전부가 아니라 작은 묶음의 손실만 평균 내서 가중치를 옮겨요. 빠르지만 매 걸음이 들쭉날쭉해요. 이걸 분산이 크다고 말해요."},{"kind":"steps","head":"GD 와 SGD 의 한 걸음 비용","steps":["노드가 1억 개인 그래프예요. 미니 배치 크기는 1,000 으로 잡을게요.","GD 는 한 번 갱신에 100,000,000개를 봐요.","**확률적 경사하강(SGD)**은 1,000개만 봐요.","비용 비율이 10만 배 차이예요.","그런데 GNN 에서는 이게 안 돼요. 1,000개를 뽑아도 이웃이 따라오니까요."],"answer":"평균 차수 30 인 그래프에서 2층이면 $1{,}000 \\times 30^2 = 900{,}000$ 칸, 3층이면 2,700만 칸이에요.","given":"노드 1억, 배치 1,000 이에요."},{"kind":"figure","head":"배치를 줄여도 이웃이 따라온다","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"118\" y=\"26\" font-size=\"16\" text-anchor=\"middle\">보통 딥러닝<\/text>\n<rect class=\"box2\" x=\"46\" y=\"48\" width=\"144\" height=\"56\" rx=\"8\"/>\n<text class=\"t\" x=\"118\" y=\"82\" font-size=\"15\" text-anchor=\"middle\">배치: 사진 3장<\/text>\n<line class=\"e2 b1\" x1=\"118\" y1=\"104\" x2=\"118\" y2=\"134\"/>\n<rect class=\"box b1\" x=\"46\" y=\"136\" width=\"144\" height=\"56\" rx=\"8\"/>\n<text class=\"t b1\" x=\"118\" y=\"170\" font-size=\"15\" text-anchor=\"middle\">계산: 사진 3장<\/text>\n<text class=\"tb b1\" x=\"118\" y=\"222\" font-size=\"16\" text-anchor=\"middle\">딱 3장이면 끝<\/text>\n<text class=\"tb\" x=\"352\" y=\"26\" font-size=\"16\" text-anchor=\"middle\">GNN<\/text>\n<rect class=\"box2\" x=\"280\" y=\"48\" width=\"144\" height=\"56\" rx=\"8\"/>\n<text class=\"t\" x=\"352\" y=\"82\" font-size=\"15\" text-anchor=\"middle\">배치: 노드 3개<\/text>\n<line class=\"e2 b2\" x1=\"352\" y1=\"104\" x2=\"352\" y2=\"134\"/>\n<rect class=\"box b2\" x=\"262\" y=\"136\" width=\"180\" height=\"56\" rx=\"8\"/>\n<text class=\"t b2\" x=\"352\" y=\"162\" font-size=\"15\" text-anchor=\"middle\">계산: 노드 3개와<\/text>\n<text class=\"t b2\" x=\"352\" y=\"182\" font-size=\"15\" text-anchor=\"middle\">그 이웃의 이웃까지<\/text>\n<text class=\"tb b2\" x=\"352\" y=\"222\" font-size=\"16\" text-anchor=\"middle\">차수 30이면 2,700칸<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"252\" font-size=\"16\" text-anchor=\"middle\">배치를 줄여도 이웃이 따라와요<\/text>\n<\/svg>","caption":"바로 이것이 'GNN 에서는 **확률적 경사하강(SGD)**을 그냥 쓸 수 없다'는 말의 정확한 뜻이에요.","builds":3},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 두 장벽을 이렇게 요약했어요.","인접행렬을 통으로 갖다 놓으니 메모리가 터지고, 풀배치라 역전파에 부하가 걸린대요.","그리고 PyTorch Geometric 의 도움을 받으면 **GCN**도 미니 배치로 구현은 된다고 했어요.","다만 라이브러리가 뒤에서 처리해 줄 뿐 본질적으로는 풀배치라는 뜻이라고 덧붙였어요."]},{"kind":"warn","head":"SGD 를 오해하지 마세요","items":["'분산이 크다'를 '틀린 방향으로 간다'로 읽으면 안 돼요.","기댓값으로는 GD 와 같은 방향이에요. 매 걸음이 흔들릴 뿐이에요.","오히려 그 흔들림이 얕은 골짜기를 빠져나오는 데 도움이 되기도 해요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"In GNNs, plain SGD does not help because sampling a mini-batch of target nodes still pulls in their multi-hop neighborhoods.","ko":"GNN에서는 대상 노드의 미니 배치를 뽑아도 여러 홉의 이웃이 따라오기 때문에 단순한 SGD 가 도움이 되지 않는다.","tip":"still pulls in 이 이 문장의 핵심이에요."},{"kind":"check","q":"GNN 에서 단순한 **확률적 경사하강(SGD)**이 통하지 않는 이유는?","choices":["기울기가 0이 되어서","배치를 작게 잡아도 이웃이 따라와서","손실 함수를 못 정해서","층을 못 쌓아서"],"a":1,"why":"줄어드는 건 대상 노드 수뿐이에요. **이웃 폭발(Neighborhood Explosion)**은 그대로예요."}],"pass4":[{"kind":"code","head":"한 층이 인접행렬 전체를 받아요","file":"PracticeCode_2.ipynb 셀 48","code":"class MeanAggregationLayer(nn.Module):\n    '''Average neighbor messages, then combine with a linear map + ReLU.'''\n\n    def __init__(self, in_dim, out_dim):\n        super().__init__()\n        self.W_self = nn.Linear(in_dim, out_dim, bias=False)\n        self.W_neigh = nn.Linear(in_dim, out_dim, bias=False)\n\n    def forward(self, x, adj):\n        degree = adj.sum(dim=1, keepdim=True).clamp(min=1.0)\n        aggregated = (adj @ x) / degree\n        return torch.relu(self.W_self(x) + self.W_neigh(aggregated))\n\n\nclass BasicGNN(nn.Module):\n    '''Two-layer mean-aggregation GNN for node classification.'''\n\n    def __init__(self, in_dim, hidden_dim, num_classes):\n        super().__init__()\n        self.layer1 = MeanAggregationLayer(in_dim, hidden_dim)\n        self.layer2 = MeanAggregationLayer(hidden_dim, hidden_dim)\n        self.classifier = nn.Linear(hidden_dim, num_classes)\n\n    def forward(self, x, adj, return_embeddings=False):\n        h = self.layer1(x, adj)\n        h = self.layer2(h, adj)\n        if return_embeddings:\n            return h\n        return self.classifier(h)\n\n\nadj = to_dense_adj(data.edge_index, max_num_nodes=data.num_nodes)[0]\nprint(\"Mean-aggregation adjacency shape:\", tuple(adj.shape))","lines":[{"from":1,"to":2,"say":"`class` 는 부품 설계도를 만드는 말이에요. `nn.Module` 을 물려받으면 파이토치 부품이 돼요. 따옴표 세 개 사이는 설명 글이에요."},{"from":4,"to":7,"say":"`__init__` 은 부품을 처음 만들 때 딱 한 번 실행돼요. `super().__init__()` 은 물려받은 준비를 먼저 하라는 뜻이에요. 나에게 곱할 `W_self` 와 이웃에게 곱할 `W_neigh` 두 개를 만들어요."},{"from":9,"to":12,"say":"`forward` 가 실제 계산이에요. `adj` 가 바로 인접행렬 전체예요. 행마다 더해 **차수(Degree)**를 구하고, `adj @ x` 로 이웃 합을 구해 차수로 나눠 평균을 만들어요. `@` 는 행렬 곱이에요."},{"from":15,"to":22,"say":"`BasicGNN` 은 위 층을 두 개 쌓고 마지막에 분류용 선형 층을 붙인 모델이에요."},{"from":24,"to":29,"say":"`forward` 에서 층을 차례로 지나요. `return_embeddings` 가 참이면 임베딩을, 아니면 분류 점수를 돌려줘요."},{"from":32,"to":33,"say":"`to_dense_adj` 로 선 목록을 꽉 찬 인접행렬로 바꾸고 그 모양을 출력해요."}],"link":"슬라이드 왼쪽 상자 '1. 메모리' 가 이 줄이에요. `forward(x, adj)` 가 언제나 그래프 전체를 받아요."},{"kind":"code","head":"학습 루프가 매번 그래프 전체를 돌려요 (1/2)","file":"PracticeCode_2.ipynb 셀 49 (1/2)","code":"def accuracy_from_logits(logits, y, train_mask):\n    pred = logits.argmax(dim=1)\n    train_acc = (pred[train_mask] == y[train_mask]).float().mean().item()\n    full_acc = (pred == y).float().mean().item()\n    return pred, train_acc, full_acc\n\n\ndef train_dense_model(model, x, support, y, train_mask, epochs=300, lr=0.01, name=\"model\"):\n    optimizer = torch.optim.Adam(model.parameters(), lr=lr, weight_decay=5e-4)\n    history_loss, history_train, history_full = [], [], []\n\n    print(f\"Training {name}\")\n    print(\"=\" * 60)\n    for epoch in range(1, epochs + 1):\n        model.train()\n        optimizer.zero_grad()\n        logits = model(x, support)\n        loss = F.cross_entropy(logits[train_mask], y[train_mask])\n        loss.backward()\n        optimizer.step()\n","lines":[{"from":1,"to":5,"say":"`def` 는 함수를 만드는 말이에요. 예측이 정답과 얼마나 맞았는지 비율로 재는 함수예요. `argmax(dim=1)` 은 줄마다 가장 큰 칸의 번호를 고르는 것이에요."},{"from":8,"to":10,"say":"학습 함수의 시작이에요. `optimizer` 는 기울기를 보고 가중치를 고쳐 주는 도구예요. 아래 세 리스트에 기록을 쌓아요."},{"from":12,"to":13,"say":"무엇을 학습하는지 화면에 찍어요."},{"from":14,"to":20,"say":"여기가 한 번의 갱신이에요. `model(x, support)` 에서 `support` 가 인접행렬 전체라, 매 반복마다 **풀배치(Full-batch)**로 그래프 전부를 계산해요. `loss.backward()` 가 역전파예요."}],"link":"슬라이드 오른쪽 상자 '2. 기울기 갱신'이 이 루프예요. 노드가 1억이면 `model(x, support)` 한 줄에서 멈춰요."},{"kind":"code","head":"학습 루프가 매번 그래프 전체를 돌려요 (2/2)","file":"PracticeCode_2.ipynb 셀 49 (2/2)","code":"        model.eval()\n        with torch.no_grad():\n            logits_eval = model(x, support)\n            _, train_acc, full_acc = accuracy_from_logits(logits_eval, y, train_mask)\n\n        history_loss.append(loss.item())\n        history_train.append(train_acc)\n        history_full.append(full_acc)\n\n        if epoch % 20 == 0 or epoch == 1:\n            print(\n                f\"Epoch {epoch:03d}/{epochs} | loss={loss.item():.4f} \"\n                f\"| train acc={train_acc:.4f} | full-graph acc={full_acc:.4f}\"\n            )\n\n    print(\"=\" * 60)\n    return history_loss, history_train, history_full\n\n\ntorch.manual_seed(42)\nbasic_gnn = BasicGNN(data.x.size(1), hidden_dim=16, num_classes=num_classes)\nbasic_losses, basic_train_accs, basic_full_accs = train_dense_model(\n    basic_gnn, data.x, adj, data.y, data.train_mask, name=\"the basic mean-aggregation GNN\"\n)","lines":[{"from":1,"to":8,"say":"고친 뒤 다시 전체를 계산해 정확도를 재고 기록에 넣어요."},{"from":10,"to":17,"say":"20번마다 한 줄씩 진행 상황을 찍고, 끝나면 기록 세 개를 돌려줘요."},{"from":20,"to":24,"say":"실제로 모델을 만들고 300번 학습을 돌려요. 노드가 34개라서 이렇게 해도 돌아가요."}]}],"walk":{"head":{"b":[0.0131,0.0179,0.3712,0.0757],"c":[0,0.0019,0.4083,0.1077],"r":6.7397,"img":"img/L4/walk/p012_h.jpg"},"parts":[{"b":[0.067,0.216,0.42,0.42],"c":[0.046,0.195,0.462,0.462],"r":1.7778,"img":"img/L4/walk/p012_11_01.jpg","say":"왼쪽 위 '1. 메모리'. 인접행렬 전체와 특징, 임베딩 행렬을 다 올린대요."},{"b":[0.509,0.216,0.42,0.42],"c":[0.488,0.195,0.462,0.462],"r":1.7778,"img":"img/L4/walk/p012_11_02.jpg","say":"오른쪽 위 '2. 기울기 갱신'. 반복마다 모든 노드를 재귀로 갱신한대요."},{"b":[0.067,0.682,0.42,0.145],"c":[0.046,0.666,0.462,0.177],"r":4.6403,"img":"img/L4/walk/p012_11_03.jpg","say":"아래 왼쪽은 GD 식이에요. 정확하지만 계산 비용이 커요."},{"b":[0.509,0.682,0.42,0.145],"c":[0.488,0.666,0.462,0.177],"r":4.6403,"img":"img/L4/walk/p012_11_04.jpg","say":"아래 오른쪽은 SGD 식이에요. 빠르지만 분산이 커져요."}]}},{"p":13,"title":"쪼개는 방법 세 가지","terms":["Node-wise Sampling","Layer-wise Sampling","Graph-wise Sampling","GraphSAGE","FastGCN","ASGCN","Cluster-GCN","GraphSAINT","Community","Homophily"],"pass1":[{"kind":"say","lines":["쪼개는 방법은 셋이에요.","**노드 단위 샘플링(Node-wise Sampling)**은 대상 노드마다 그 주변을 뽑아요.","**레이어 단위 샘플링(Layer-wise Sampling)**은 층마다 고정된 노드 집합을 뽑아요.","**그래프 단위 샘플링(Graph-wise Sampling)**은 부분 그래프를 통째로 뽑아요."]},{"kind":"analogy","head":"도시 전체를 조사하는 세 가지 방법","scene":"민수가 도시의 분위기를 조사해요. 첫째, 사람마다 그 옆집 두 곳씩만 물어봐요. 둘째, 동네마다 '오늘은 이 집들만 본다'고 미리 정해 둬요. 셋째, 아예 한 구역을 통째로 떼어 그 안만 꼼꼼히 봐요. 세 방법 다 도시 전체를 한 번에 보지 않아요.","map":[["사람마다 옆집 둘","**노드 단위 샘플링(Node-wise Sampling)**"],["동네마다 볼 집 미리 정하기","**레이어 단위 샘플링(Layer-wise Sampling)**"],["한 구역을 통째로","**그래프 단위 샘플링(Graph-wise Sampling)**"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"상자 안 그림과 설명","boxes":[{"x":0.09,"y":0.26,"w":0.23,"h":0.24,"say":"왼쪽 그림: 가운데 빨간 노드가 대상 노드, 주변 주황 노드가 뽑힌 이웃이에요.","c":[0.078,0.244,0.254,0.272],"r":1.6601,"img":"img/L4/walk/p013_20_01.jpg"},{"x":0.067,"y":0.61,"w":0.27,"h":0.06,"say":"설명: '노드마다 이웃의 일부를 재귀로 뽑는다. **GraphSAGE**, VR-GCN'","c":[0.0535,0.585,0.297,0.11],"r":4.8,"img":"img/L4/walk/p013_20_02.jpg"},{"x":0.38,"y":0.26,"w":0.23,"h":0.24,"say":"가운데 그림: 판 세 장에 층마다 뽑힌 노드가 주황색, 빨간 선으로 이어져 있어요.","c":[0.368,0.244,0.254,0.272],"r":1.6601,"img":"img/L4/walk/p013_20_03.jpg"},{"x":0.362,"y":0.61,"w":0.27,"h":0.06,"say":"설명: '층마다 고정된 노드 집합을 뽑아 묶음이 공유. **FastGCN**, **ASGCN**'","c":[0.3485,0.585,0.297,0.11],"r":4.8,"img":"img/L4/walk/p013_20_04.jpg"},{"x":0.67,"y":0.26,"w":0.23,"h":0.24,"say":"오른쪽 그림: 왼쪽 절반만 주황색이에요. 한 덩어리를 통째로 떼어 냈다는 뜻이에요.","c":[0.658,0.244,0.254,0.272],"r":1.6601,"img":"img/L4/walk/p013_20_05.jpg"},{"x":0.656,"y":0.61,"w":0.28,"h":0.06,"say":"설명: '부분 그래프로 자르고 각각에 온전한 GNN. **Cluster-GCN**, **GraphSAINT**'","c":[0.642,0.585,0.308,0.11],"r":4.9778,"img":"img/L4/walk/p013_20_06.jpg"}]},{"kind":"compare","head":"세 방식 한눈에","cols":["항목","노드 단위","레이어 단위","그래프 단위"],"rows":[["뽑는 단위","대상 노드의 이웃","층마다의 노드 집합","부분 그래프"],["대표 모델","**GraphSAGE**","**FastGCN**, **ASGCN**","**Cluster-GCN**, **GraphSAINT**"],["장점","간단하고 구현이 쉬움","품질을 이론으로 보장","이웃 폭발이 없음"],["단점","품질 보장이 없음","복잡해서 잘 안 쓰임","잘린 엣지 정보가 사라짐"],["실제 사용","가장 많이 쓰임","거의 안 쓰임","현대 알고리즘의 주류"]]},{"kind":"points","head":"한 가지만 더 짚어요","items":["**노드 단위 샘플링(Node-wise Sampling)**은 대상 노드마다 다르게 뽑아요.","**레이어 단위 샘플링(Layer-wise Sampling)**은 한 층에서 뽑은 집합을 배치 전체가 함께 써요.","'묶음이 공유한다'가 이 둘을 가르는 지점이에요.","**그래프 단위 샘플링(Graph-wise Sampling)**은 아예 그래프를 잘라 버려요."]},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 세 방식의 특징을 시험 포인트로 정리해 줬어요.","노드 단위는 개수를 제약하는 방식인데 **샘플링 품질을 보장할 수 없다**고 했어요.","레이어 단위는 반대로 **품질이 이론적으로 뒷받침**되지만 복잡해서 잘 안 쓰인대요.","그래프 단위는 장점이 직관적이고 간단하다는 것이라고 했어요."]},{"kind":"mining","src":"마이닝 5강 Community Detection","lines":["**커뮤니티(Community)**는 무작위로 기대되는 것보다 안쪽 연결이 강한 노드들의 모음이에요.","노드 집합을 겹치지 않는 여러 부분집합으로 나누는 일이죠.","커뮤니티가 생기는 이유로 **동질성(Homophily)**을 들었어요.","비슷한 특징을 가진 노드들이 같은 군집 안에서 연결되는 경향이에요."]},{"kind":"warn","head":"고르는 것이지 합치는 것이 아니에요","items":["세 방식은 '같이 쓰는 것'이 아니라 '하나를 고르는 것'이에요.","모델 하나는 보통 한 방식만 써요."]}],"pass3":[{"kind":"exam","src":"2025 가을 중간 6번 (10점) (a)","q":"How is the sampling strategy of GraphSAINT different from node-wise or edge-wise methods such as GraphSage?","qko":"**GraphSAINT**의 샘플링 전략이 **GraphSAGE** 같은 노드 단위, 엣지 단위 방법과 어떻게 다른가요?","solve":["먼저 무엇을 뽑는지 대비시켜요.","**GraphSAGE** 같은 **노드 단위 샘플링(Node-wise Sampling)**은 개별 노드와 그 이웃을 뽑아요.","**GraphSAINT**는 미니 배치마다 부분 그래프를 통째로 뽑아요.","그래서 구조와 이웃 정보를 더 많이 보존하면서 학습은 효율적으로 유지돼요."],"answer":"GraphSAINT samples entire subgraphs for each mini-batch instead of individual nodes or edges, preserving more structural and neighborhood information while keeping training efficient."},{"kind":"english","head":"서술형에 쓸 한 줄","en":"Node-wise sampling picks a fixed number of neighbors around each target node; it is simple but gives no guarantee on sampling quality.","ko":"노드 단위는 대상 노드마다 고정된 수의 이웃을 뽑는다. 간단하지만 품질 보장이 없다.","tip":"no guarantee on sampling quality 가 단점 문장이에요."},{"kind":"check","q":"층마다 뽑은 노드 집합을 배치 전체가 함께 쓰는 방식은?","choices":["**노드 단위 샘플링(Node-wise Sampling)**","**레이어 단위 샘플링(Layer-wise Sampling)**","**그래프 단위 샘플링(Graph-wise Sampling)**","풀배치"],"a":1,"why":"'묶음이 공유한다'가 레이어 단위의 표시예요. 대표가 **FastGCN**과 **ASGCN**이에요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.2688,0.0757],"c":[0,0.0019,0.2957,0.1077],"r":4.881,"img":"img/L4/walk/p013_h.jpg"},"parts":[{"b":[0.067,0.535,0.2,0.045],"c":[0.055,0.5025,0.224,0.11],"r":3.6202,"img":"img/L4/walk/p013_12_01.jpg","say":"왼쪽 초록 글씨 '노드 단위'. 대상 노드마다 그 주변을 뽑아요."},{"b":[0.362,0.535,0.2,0.045],"c":[0.35,0.5025,0.224,0.11],"r":3.6202,"img":"img/L4/walk/p013_12_02.jpg","say":"가운데 주황 글씨 '레이어 단위'. 합성곱 층마다 뽑아요."},{"b":[0.656,0.535,0.2,0.045],"c":[0.644,0.5025,0.224,0.11],"r":3.6202,"img":"img/L4/walk/p013_12_03.jpg","say":"오른쪽 보라 글씨 '그래프 단위'. 부분 그래프를 통째로 뽑아요."}]}},{"p":14,"title":"샘플링을 채점하는 두 가지 질문","terms":["Node-wise Sampling","Layer-wise Sampling","Graph-wise Sampling","GraphSAGE","FastGCN","ASGCN","Cluster-GCN","GraphSAINT"],"pass1":[{"kind":"say","lines":["샘플링을 하기로 정했으면 두 가지를 고민해야 해요.","'샘플링 알고리즘을 얼마나 효율적으로 만들까'가 첫째예요.","'뽑은 표본의 품질을 어떻게 보장할까'가 둘째예요."]},{"kind":"analogy","head":"반 40명 중 5명만 설문하기","scene":"반 전체 40명의 의견을 알고 싶은데 시간이 없어 5명만 물어보기로 했어요. 아무나 5명을 부르면 1초면 되지만, 우연히 다 같은 동아리 친구일 수도 있죠. 반대로 '가장 의견이 다양한 5명'을 찾으려고 40명을 다 조사하면 차라리 40명한테 그냥 묻는 게 빨라요.","map":[["5명을 고르는 시간","샘플링의 효율성"],["5명이 40명을 대표하나","샘플링의 품질"],["다 같은 동아리라 생긴 치우침","편향"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"두 질문을 풀어 쓰면","items":["효율적이라는 말은 계산이 빠르고 메모리를 적게 쓴다는 뜻이에요.","샘플링 비용이 절약한 비용보다 크면 안 하느니만 못해요.","품질은 뽑은 일부가 전체를 얼마나 잘 대표하는가예요.","치우침이 생기면 그걸 편향이라고 불러요."]},{"kind":"compare","head":"앞으로 배울 모델의 채점표","cols":["모델","방식","효율성","품질 보장"],"rows":[["**GraphSAGE**","노드 단위","좋음","없음"],["**FastGCN**","레이어 단위","좋음","있음"],["**ASGCN**","레이어 단위","보통","있음"],["**Cluster-GCN**","그래프 단위","좋음","러프하지만 실전에서 잘 됨"],["**GraphSAINT**","그래프 단위","좋음","있음"]]},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 두 질문을 이렇게 풀어 줬어요.","첫째, 샘플링 기법 자체가 효율적이어야 하고 학습 효율도 올려 줘야 한대요.","둘째, 샘플에서 가져오는 데이터의 품질이 학습 결과에 영향을 준대요.","그러면서 **성능이 떨어질지 오히려 개선할지**를 샘플링 확률이 정한다고 했어요."]},{"kind":"warn","head":"두 질문은 서로 반대로 움직여요","items":["품질을 올리려고 좋은 이웃을 고르려 하면 계산이 늘어요.","계산을 줄이려고 마구 뽑으면 품질이 떨어져요.","이 상충 관계를 이해하는 게 이번 주의 핵심이에요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"The sampler itself must be computationally efficient, and the sampled subset must faithfully represent the full graph.","ko":"샘플러 자체가 계산적으로 효율적이어야 하고, 뽑은 부분집합이 전체 그래프를 충실히 대표해야 한다.","tip":"efficient 와 faithfully represent 두 축을 꼭 같이 쓰세요."},{"kind":"check","q":"**GraphSAGE**는 두 질문 중 어느 쪽으로 기울어 있나요?","choices":["효율성 쪽. 고르는 비용이 거의 0 이지만 품질 보장이 없어요","품질 쪽. 이론적 보장이 있어요","둘 다 완벽해요","둘 다 나빠요"],"a":0,"why":"무작위로 고정 개수만 뽑으니 비용은 거의 0 이에요. 대신 품질 보장이 없어요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.3964,0.0757],"c":[0,0.0019,0.4361,0.1077],"r":7.1986,"img":"img/L4/walk/p014_h.jpg"},"parts":[{"b":[0.06,0.143,0.47,0.042],"c":[0.0365,0.109,0.517,0.11],"r":8.3556,"img":"img/L4/walk/p014_20_01.jpg","say":"첫째 질문: '효율적인 샘플링 알고리즘을 어떻게 설계할까?'"},{"b":[0.06,0.21,0.32,0.04],"c":[0.044,0.175,0.352,0.11],"r":5.6889,"img":"img/L4/walk/p014_20_02.jpg","say":"둘째 질문: '샘플링 품질을 어떻게 보장할까?'"},{"b":[0.524,0.345,0.25,0.075],"c":[0.5115,0.3275,0.275,0.11],"r":4.4444,"img":"img/L4/walk/p014_20_03.jpg","say":"'노드 묶음, 즉 계산 그래프 묶음 위에서 학습한다'. p.8 과 같은 그림이에요."},{"b":[0.361,0.565,0.43,0.265],"c":[0.3395,0.549,0.473,0.297],"r":2.8313,"img":"img/L4/walk/p014_20_04.jpg","say":"이 묶음을 만드는 일이 곧 샘플링이고, 여기서 두 질문이 생겨요."}]}},{"p":15,"title":"구분 슬라이드: 노드 단위 샘플링","terms":["Node-wise Sampling","GraphSAGE","Mini-batch","Inductive Learning"],"pass1":[{"kind":"say","lines":["여기서부터는 세 방식 중 첫 번째예요.","**노드 단위 샘플링(Node-wise Sampling)**, 대표 모델은 **GraphSAGE**예요.","대상 노드마다 이웃을 전부 쓰지 않고 일부만 골라 써요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"한 줄 설명을 곱씹어요","items":["'이웃을 전부 쓰지 않고 일부만 골라 쓴다'가 전부예요.","차수가 100만인 허브라도 '너는 2명만 보여 줘'라고 정해 버려요.","그러면 계산 그래프의 폭이 고정되고 미리 메모리를 잡을 수 있어요.","p.16 부터 p.22 까지가 **GraphSAGE** 이야기예요."]},{"kind":"points","head":"읽기 전에 던지는 세 질문","items":["이웃을 몇 개로 제한하면 계산 그래프의 크기가 어떻게 바뀌나요? 답은 p.22 예요.","**GraphSAGE**가 GCN과 다른 점 두 가지는 무엇인가요? 답은 p.19 예요.","원논문이 가장 크게 내세운 장점이 확장성이었나요? 답은 p.18 이고, 아니에요.","원논문 제목이 '큰 그래프에서의 귀납적 표현 학습'이에요. 제목에 답이 있어요."]},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 세 방식 중 **이 첫 번째가 가장 많이 쓰이는 방식**이라고 못 박았어요.","나머지가 잘 안 쓰이는 이유는 수업을 쭉 보면 금방 와닿을 거라고도 했어요.","그러니 이 대목을 가장 꼼꼼히 봐야 해요."]}],"pass3":[],"pass4":[],"walk":{"head":null,"parts":[{"b":[0.048,0.348,0.27,0.062],"c":[0.0345,0.324,0.297,0.11],"r":4.8,"img":"img/L4/walk/p015_20_01.jpg","say":"진한 남색 큰 글씨 '노드 단위 샘플링'."},{"b":[0.045,0.45,0.41,0.036],"c":[0.0245,0.413,0.451,0.11],"r":7.2889,"img":"img/L4/walk/p015_20_02.jpg","say":"한 줄 설명: '대상 노드마다 이웃을 전부 쓰지 않고 일부만 골라 쓴다.'"},{"b":[0.048,0.606,0.19,0.036],"c":[0.036,0.569,0.214,0.11],"r":3.4586,"img":"img/L4/walk/p015_20_03.jpg","say":"'대표 모델: **GraphSAGE**'"}]}},{"p":16,"title":"GraphSAGE 아이디어: 몇 개만 뽑는다","terms":["GraphSAGE","Neighbor Sampling","Node-wise Sampling","Degree","Hub Node","Mini-batch","Scalability"],"pass1":[{"kind":"say","lines":["**GraphSAGE**의 아이디어는 딱 한 줄이에요.","K홉 이웃을 전부 쓰지 말고, 그중 몇 개만 무작위로 골라 계산 그래프를 만들어요.","이 과정을 **이웃 샘플링(Neighbor Sampling)**이라고 불러요."]},{"kind":"analogy","head":"반장이 의견을 걷는 새 규칙","scene":"반장이 친구 40명 전원에게 의견을 물으려니 하루가 다 가요. 그래서 규칙을 바꿔요. '누구든 두 명한테만 묻는다.' 친구가 세 명인 아이도 두 명, 친구가 100명인 아이도 두 명이에요. 그러면 걸리는 시간이 항상 똑같아져서 미리 계획을 세울 수 있어요.","map":[["두 명한테만 묻기","**이웃 샘플링(Neighbor Sampling)**"],["친구가 100명인 아이","**허브 노드(Hub Node)**"],["시간이 항상 똑같아짐","계산 그래프 크기가 고정됨"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.05,"y":0.136,"w":0.53,"h":0.04,"say":"'지금까지는 이웃 메시지를 가중 평균으로 집계했다. 더 잘할 수 있을까?'","c":[0.0235,0.0971,0.583,0.1178],"r":8.7983,"img":"img/L4/walk/p016_20_01.jpg"},{"x":0.05,"y":0.222,"w":0.79,"h":0.042,"say":"'K홉 이웃 중 몇 개를 무작위로 골라 계산 그래프를 만든다.' 무작위라는 말이 중요해요.","c":[0.0105,0.1552,0.869,0.1756],"r":8.7978,"img":"img/L4/walk/p016_20_02.jpg"},{"x":0.065,"y":0.364,"w":0.8,"h":0.04,"say":"'이 과정을 **이웃 샘플링(Neighbor Sampling)**이라 하며, 노드 수십억 개까지 확장되는 비결이다.'","c":[0.025,0.2951,0.88,0.1778],"r":8.7989,"img":"img/L4/walk/p016_20_03.jpg"},{"x":0.297,"y":0.64,"w":0.075,"h":0.04,"say":"왼쪽 글씨 'Sampling 1-Hop neighborhood'. 1홉에서 뽑는다는 뜻이에요.","c":[0.2345,0.605,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p016_20_04.jpg"},{"x":0.455,"y":0.64,"w":0.04,"h":0.045,"say":"노드 1 이 흐려요. 1홉 이웃 3명 중 2명만 뽑았다는 표시예요.","c":[0.375,0.6075,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p016_20_05.jpg"}]},{"kind":"steps","head":"이웃을 2개로 제한하면 칸 수가 어떻게 되나요","steps":["샘플링 안 하면 뿌리 1, 층-1 이 3, 층-0 이 $4 + 3 + 3 = 10$ 이라 합계 14칸이에요.","이웃을 2개로 제한하면 뿌리 1, 층-1 이 2, 층-0 이 $2 + 2 = 4$ 라 합계 7칸이에요.","이제 **차수(Degree)**를 바꿔 볼게요. $d = 3$ 이면 원래 13칸, 제한하면 7칸이에요.","$d = 30$ 이면 원래 931칸, 제한하면 7칸이에요.","$d = 1{,}000$ 이면 원래 약 1,001,001칸, 제한하면 7칸이에요."],"answer":"차수가 3이든 100만이든 무조건 7칸이에요. 계산 그래프 크기가 그래프 성질과 완전히 무관해져요.","given":"2층 GNN 이고, 층마다 이웃 $S = 2$ 개만 뽑아요."},{"kind":"figure","head":"차수가 얼마든 7칸","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"240\" y=\"24\" font-size=\"16\" text-anchor=\"middle\">이웃을 2개로 제한하면 언제나 7칸<\/text>\n<line class=\"e2 b1\" x1=\"240\" y1=\"66\" x2=\"170\" y2=\"112\"/>\n<line class=\"e2 b1\" x1=\"240\" y1=\"66\" x2=\"310\" y2=\"112\"/>\n<line class=\"e2 b2\" x1=\"170\" y1=\"144\" x2=\"130\" y2=\"188\"/>\n<line class=\"e2 b2\" x1=\"170\" y1=\"144\" x2=\"210\" y2=\"188\"/>\n<line class=\"e2 b2\" x1=\"310\" y1=\"144\" x2=\"270\" y2=\"188\"/>\n<line class=\"e2 b2\" x1=\"310\" y1=\"144\" x2=\"350\" y2=\"188\"/>\n<circle class=\"n2\" cx=\"240\" cy=\"50\" r=\"16\"/>\n<circle class=\"n b1\" cx=\"170\" cy=\"128\" r=\"15\"/>\n<circle class=\"n b1\" cx=\"310\" cy=\"128\" r=\"15\"/>\n<circle class=\"n b2\" cx=\"130\" cy=\"202\" r=\"13\"/>\n<circle class=\"n b2\" cx=\"210\" cy=\"202\" r=\"13\"/>\n<circle class=\"n b2\" cx=\"270\" cy=\"202\" r=\"13\"/>\n<circle class=\"n b2\" cx=\"350\" cy=\"202\" r=\"13\"/>\n<text class=\"tl\" x=\"240\" y=\"55\" font-size=\"15\" text-anchor=\"middle\">0<\/text>\n<text class=\"tm\" x=\"430\" y=\"55\" font-size=\"14\" text-anchor=\"middle\">1칸<\/text>\n<text class=\"tm b1\" x=\"430\" y=\"133\" font-size=\"14\" text-anchor=\"middle\">2칸<\/text>\n<text class=\"tm b2\" x=\"430\" y=\"207\" font-size=\"14\" text-anchor=\"middle\">4칸<\/text>\n<text class=\"tm b3\" x=\"60\" y=\"55\" font-size=\"14\" text-anchor=\"middle\">대상 노드<\/text>\n<text class=\"tm b3\" x=\"60\" y=\"133\" font-size=\"14\" text-anchor=\"middle\">1홉 2개<\/text>\n<text class=\"tm b3\" x=\"60\" y=\"207\" font-size=\"14\" text-anchor=\"middle\">2홉 2개씩<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"248\" font-size=\"16\" text-anchor=\"middle\">차수가 3이든 100만이든 1 + 2 + 4 = 7칸<\/text>\n<\/svg>","caption":"크기를 정하는 건 이제 그래프가 아니라 우리가 고른 숫자 $S$ 와 층 수 $L$ 이에요.","builds":3},{"kind":"viz","viz":"gnn.sample","head":"움직여 보기: 이웃을 몇 명만 뽑아 계산 그래프를 붙잡아요","caption":"숫자는 이 쪽 손계산 가정이에요."},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 '우리가 한 깊이에서 샘플링하는 개수를 그냥 한정 짓자'는 거라고 했어요.","0번 노드의 이웃 수가 10만이든 100만이든 두 개만, 세 개만 보겠다고 딱 정한대요.","그림으로 보면 직관적으로 무슨 말인지 알 거라고 했어요.","교수님이 말한 보통의 제한 개수는 **2나 3** 이에요. 생각보다 훨씬 작죠."]},{"kind":"mining","src":"마이닝 5강 Community Detection","lines":["'무작위로 몇 개만 뽑는다'는 발상은 마이닝에서도 나왔어요.","최대 클리크를 찾을 때 부분 네트워크를 표본으로 뽑아 거기서 찾았어요.","이유는 소셜 네트워크의 차수가 거듭제곱 법칙을 따르기 때문이었어요.","거듭제곱 법칙 때문에 문제가 생기고, 그래서 일부만 보는 방식으로 푸는 구조가 같아요."]},{"kind":"warn","head":"세 가지를 조심하세요","items":["'K홉 중 몇 개'를 'K홉 전체에서 몇 개'로 읽으면 안 돼요. **홉마다 따로** 고르는 거예요.","이웃이 $S$ 개보다 적으면 중복을 허용해 뽑거나 있는 것만 써요. 상한만 지키면 돼요.","흐린 노드는 그래프에 없는 게 아니라 이번 반복에서 안 뽑힌 노드예요."]}],"pass3":[{"kind":"exam","src":"2024 가을 기말 2번 (10점) (b)","q":"How does the GraphSage model address the scalability problem?","qko":"**GraphSAGE** 모델은 **확장성(Scalability)** 문제를 어떻게 해결하나요?","solve":["먼저 무엇을 뽑는지 씁니다. 층마다 노드별로 고정된 크기의 이웃 집합을 뽑아요.","그래서 계산 그래프의 크기가 노드 **차수(Degree)**에 더 이상 의존하지 않아요.","크기가 예측 가능해지니 메모리를 미리 잡을 수 있어요.","그 덕분에 **미니 배치(Mini-batch)** 학습이 가능해져요."],"answer":"GraphSAGE samples a fixed-size set of neighbors at every layer, so the computation graph size no longer depends on node degree and becomes predictable, which enables mini-batch training."},{"kind":"check","q":"**이웃 샘플링(Neighbor Sampling)**은 이웃을 어떻게 고르나요?","choices":["차수가 큰 이웃부터","중심성이 높은 이웃부터","그냥 무작위로 고정 개수만","레이블이 같은 이웃만"],"a":2,"why":"똑똑하게 고르는 게 아니라 무작위예요. 덕분에 뽑는 비용이 거의 0 이지만 품질 보장이 없어요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0177,0.5765,0.1663],"c":[0,0.0017,0.6341,0.1983],"r":5.6848,"img":"img/L4/walk/p016_h.jpg"},"parts":[{"b":[0.05,0.222,0.79,0.042],"c":[0.0105,0.1552,0.869,0.1756],"r":8.7978,"img":"img/L4/walk/p016_12_01.jpg","say":"'아이디어: K홉 이웃을 전부 쓰지 않고, 그중 몇 개를 무작위로 골라 계산 그래프를 만든다.'"},{"b":[0.295,0.487,0.345,0.352],"c":[0.2777,0.4694,0.3795,0.3872],"r":1.7424,"img":"img/L4/walk/p016_12_02.jpg","say":"아래 그림에서 흐린 노드는 이번에 안 뽑힌 이웃이에요."}]}},{"p":17,"title":"뽑고, 집계하고, 예측한다","terms":["GraphSAGE","Inductive Learning","Transductive Learning","Mini-batch","Neighbor Sampling","Aggregator","GCN"],"pass1":[{"kind":"say","lines":["**GraphSAGE**는 세 걸음이에요.","뽑기(Sample), 집계하기(Aggregate), 예측하기(Predict)예요.","그리고 이 구조 덕분에 학습 때 본 적 없는 노드에도 임베딩을 만들어 줄 수 있어요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.029,"y":0.125,"w":0.33,"h":0.04,"say":"굵은 부제: '**GraphSAGE**: 뽑고, 집계하고, 예측한다'.","c":[0.0125,0.09,0.363,0.11],"r":5.8667,"img":"img/L4/walk/p017_20_01.jpg"},{"x":0.064,"y":0.192,"w":0.83,"h":0.074,"say":"'이전 GNN 들은 고정된 그래프 위에서 변환적이었다. **GraphSAGE**는 귀납적으로 배운다.'","c":[0.0225,0.1368,0.913,0.1845],"r":8.7974,"img":"img/L4/walk/p017_20_02.jpg"},{"x":0.067,"y":0.325,"w":0.28,"h":0.35,"say":"1번 상자 그림: 점선 원 두 개가 동심원이에요. 안쪽이 1홉, 바깥이 2홉이에요.","c":[0.053,0.3075,0.308,0.385],"r":1.4222,"img":"img/L4/walk/p017_20_03.jpg"},{"x":0.362,"y":0.325,"w":0.28,"h":0.35,"say":"2번 상자 그림: 초록(2홉) 에서 파랑(1홉) 으로, 그다음 빨강(대상 노드) 으로 모여요.","c":[0.348,0.3075,0.308,0.385],"r":1.4222,"img":"img/L4/walk/p017_20_04.jpg"},{"x":0.656,"y":0.325,"w":0.28,"h":0.35,"say":"3번 상자 그림: 대상 노드에서 화살표가 나가 주황색 카드를 가리켜요. 예측 결과예요.","c":[0.642,0.3075,0.308,0.385],"r":1.4222,"img":"img/L4/walk/p017_20_05.jpg"}]},{"kind":"compare","head":"세 걸음","cols":["단계","하는 일","결과"],"rows":[["1 뽑기","1홉에서 $S_1$ 개, 2홉에서 $S_2$ 개 무작위 선택","크기가 고정된 계산 그래프"],["2 집계","바깥 홉부터 안쪽으로 모으며 변환","층마다의 임베딩"],["3 예측","최종 임베딩으로 레이블이나 문맥을 맞힘","손실 값, 그리고 역전파"]]},{"kind":"points","head":"새로운 것은 1번 하나뿐","items":["2번과 3번은 지금까지 배운 GNN과 똑같아요.","그런데 1번 하나가 바뀌는 것만으로 두 가지가 따라와요.","하나는 **확장성(Scalability)**, 다른 하나는 **귀납적 학습(Inductive Learning)**이에요.","좋은 아이디어가 대개 이래요. 손대는 곳은 한 군데인데 효과는 여러 방향으로 퍼져요."]},{"kind":"points","head":"두 단어를 미리 풀어 둘게요","items":["**변환적 학습(Transductive Learning)**은 학습 때 본 그 그래프에만 답을 낼 수 있는 방식이에요.","**귀납적 학습(Inductive Learning)**은 규칙을 배워서 처음 보는 대상에도 적용하는 방식이에요.","자세한 이야기는 다음 쪽 p.18 에서 해요."]},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 **GraphSAGE**로 얻는 가장 큰 장점을 '**미니 배치(Mini-batch)**가 가능해진다'고 했어요.","원래 GNN 층은 모든 1홉 이웃의 정보를 긁어다가 갱신하는 것이었죠.","이걸 '특정한 $k$ 개의 이웃으로부터 가져다 갱신한다'로 바꾸는 거예요.","그러면 어디서 정보를 가져올지, 메모리를 얼마나 잡을지 미리 예상할 수 있대요."]},{"kind":"warn","head":"순서를 헷갈리지 마세요","items":["집계는 **바깥 홉부터** 안쪽으로예요. 2홉 정보가 1홉에게 먼저 도착해야 하니까요.","반대로 뽑기는 안쪽부터 바깥으로예요. 대상 노드에서 1홉, 그다음 2홉이죠.","즉 뽑는 순서와 모으는 순서가 반대예요."]}],"pass3":[{"kind":"exam","src":"2025 가을 중간 4번 (10점) (a)","q":"What is the key idea of the GraphSage model and how is it different from traditional GCN?","qko":"**GraphSAGE** 모델의 핵심 아이디어는 무엇이고 전통적인 **GCN**과 어떻게 다른가요?","solve":["핵심 아이디어부터 써요. 이웃에서 특징을 뽑고 집계해서 노드 임베딩을 배워요.","그 결과 본 적 없는 노드에 대한 **귀납적 학습(Inductive Learning)**이 가능해져요.","전통적 **GCN**은 학습 중 전체 그래프가 필요해요.","이 대비를 한 문장에 담으면 4점짜리 답이 완성돼요."],"answer":"GraphSAGE learns node embeddings by sampling and aggregating features from a node's neighbors, enabling inductive learning for unseen nodes, unlike traditional GCNs that require the entire graph during training."},{"kind":"english","head":"이 한 문장만 외워도 여러 문제에 써요","en":"GraphSAGE learns node embeddings by sampling and aggregating features from a node's neighbors.","ko":"GraphSAGE 는 노드의 이웃에서 특징을 뽑고 집계해서 노드 임베딩을 배운다.","tip":"sampling, aggregating, inductive 세 단어가 다 들어 있어요."},{"kind":"check","q":"집계는 어느 방향으로 하나요?","choices":["안쪽에서 바깥으로","바깥 홉부터 안쪽으로","왼쪽에서 오른쪽으로","순서는 상관없어요"],"a":1,"why":"2홉 이웃의 정보가 1홉 이웃에게 먼저 도착해야 대상 노드로 전달할 수 있어요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0177,0.8933,0.2604],"c":[0,0.0017,0.9827,0.2924],"r":5.9748,"img":"img/L4/walk/p017_h.jpg"},"parts":[{"b":[0.067,0.6,0.13,0.045],"c":[0.032,0.5675,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p017_11_01.jpg","say":"1 뽑기. 대상 노드의 $k=1$ 과 $k=2$ 이웃을 뽑아요."},{"b":[0.362,0.6,0.13,0.045],"c":[0.327,0.5675,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p017_11_02.jpg","say":"2 집계. 바깥 홉부터 순서대로 모아요."},{"b":[0.656,0.6,0.13,0.045],"c":[0.621,0.5675,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p017_11_03.jpg","say":"3 예측. 모은 정보로 레이블을 맞혀요."}]}},{"p":18,"title":"GraphSAGE는 귀납적 학습을 연다","terms":["Inductive Learning","Transductive Learning","Shallow Embedding","GraphSAGE","GCN","Aggregator","Mini-batch","Adjacency Matrix"],"pass1":[{"kind":"say","lines":["**GraphSAGE**가 처음 나왔을 때 가장 크게 내세운 건 확장성이 아니었어요.","**귀납적 학습(Inductive Learning)**이었어요.","노드마다 임베딩을 외우는 게 아니라 **집계기(Aggregator)**를 배우기 때문이에요."]},{"kind":"analogy","head":"전화번호부를 외운 사람과 규칙을 아는 사람","scene":"민수는 친구 100명의 전화번호를 통째로 외웠어요. 그런데 새 친구가 전학 오면 민수는 그 번호를 몰라요. 반면 영희는 '이 학교 번호는 학년, 반, 번호를 붙이면 된다'는 규칙을 알아요. 새 친구가 와도 영희는 바로 번호를 만들어 낼 수 있죠.","map":[["번호를 통째로 외움","**변환적 학습(Transductive Learning)**"],["규칙을 앎","**귀납적 학습(Inductive Learning)**"],["새로 전학 온 친구","학습 때 본 적 없는 노드"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"compare","head":"두 학습 방식","cols":["항목","**변환적 학습(Transductive Learning)**","**귀납적 학습(Inductive Learning)**"],"rows":[["배우는 것","노드마다의 임베딩 벡터(표)","이웃을 모으는 함수(규칙)"],["파라미터 수","노드 수에 비례","노드 수와 무관, 층 수에만 비례"],["새 노드가 오면","못 다룸, 다시 학습해야 함","그대로 임베딩을 만들어 줌"],["예","DeepWalk, node2vec, 그냥 구현한 **GCN**","**GraphSAGE**"]]},{"kind":"points","head":"왜 표가 아니라 함수인가","items":["1주차의 **얕은 임베딩(Shallow Embedding)**은 노드마다 벡터를 표에 적어 두고 그 표를 학습했어요.","노드가 100만 개면 벡터 100만 개가 학습 파라미터였죠.","그래서 새 노드가 오면 표에 자리가 없어서 답을 못 냈어요.","**GraphSAGE**는 표가 아니라 함수를 배우니 이 문제가 사라져요."]},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 이 대목을 시험 포인트로 길게 설명했어요.","**GCN**은 풀배치라 노드가 추가되면 **인접행렬(Adjacency Matrix)** 크기와 모양이 바뀐대요.","그래서 **GCN** 또한 그냥 구현하면 **귀납적 학습(Inductive Learning)**이 불가능하다고 했어요.","**미니 배치(Mini-batch)**가 가능하다는 건 '내가 봐야 할 만큼만 관찰한다'는 뜻이에요."]},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님이 이유를 한 문장으로 정리했어요.","GNN 층은 '이웃들의 정보와 나의 관계를 추론하는 방법'을 배운다는 거예요.","그래서 노드가 추가되거나 인접행렬 크기가 변해도 모델 동작에 영향이 없어요.","1주차에서 얕은 임베딩이 룩업 테이블이라 변환적이라고 했던 것과 같은 맥락이에요."]},{"kind":"mining","src":"마이닝 10강 Random Walk-based GRL","lines":["DeepWalk, node2vec 는 랜덤워크로 경로를 만들고 word2vec 를 돌렸어요.","결과는 '노드 이름에서 벡터로' 가는 표 하나예요.","새 노드가 생기면 표에 자리가 없어서 전체를 다시 학습해야 했어요.","이게 **변환적 학습(Transductive Learning)**의 전형이에요."]},{"kind":"warn","head":"반만 맞는 설명","items":["'샘플링을 해서 귀납적이다'로만 외우면 반만 맞아요.","더 근본적인 이유는 학습 대상이 노드별 벡터가 아니라 **집계기(Aggregator)**의 가중치라는 점이에요.","그래서 파라미터 수가 노드 수와 무관해요."]}],"pass3":[{"kind":"english","head":"답안에 그대로 쓸 문장","en":"GraphSAGE is inductive because it learns aggregator functions rather than per-node embeddings.","ko":"GraphSAGE 는 노드별 임베딩이 아니라 집계 함수를 배우기 때문에 귀납적이다.","tip":"aggregator functions rather than per-node embeddings 가 채점 포인트예요."},{"kind":"english","head":"반대편에 쓸 문장","en":"GCNs assume a static, fixed graph structure during training.","ko":"GCN 은 학습 중 정적이고 고정된 그래프 구조를 가정한다.","tip":"static, fixed 두 형용사를 같이 쓰면 좋아요."},{"kind":"check","q":"**GraphSAGE**가 귀납적인 근본 이유는 무엇인가요?","choices":["샘플링을 해서","노드별 벡터가 아니라 집계 함수의 가중치를 배워서","층이 얕아서","GPU 를 써서"],"a":1,"why":"파라미터 수가 노드 수와 무관해지기 때문이에요. 그래서 새 노드도 그대로 처리해요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.5557,0.0757],"c":[0,0.0019,0.6113,0.1077],"r":10.0906,"img":"img/L4/walk/p018_h.jpg"},"parts":[{"b":[0.06,0.134,0.83,0.07],"c":[0.0185,0.0768,0.913,0.1845],"r":8.7974,"img":"img/L4/walk/p018_20_01.jpg","say":"'**GraphSAGE**는 **GCN**의 귀납적 판이다. 본 적 없는 노드에도 잘 일반화된다.'"},{"b":[0.06,0.241,0.34,0.04],"c":[0.043,0.206,0.374,0.11],"r":6.0444,"img":"img/L4/walk/p018_20_02.jpg","say":"'노드마다 임베딩을 따로 배울 필요가 없다.' 이 한 줄이 핵심이에요."},{"b":[0.06,0.31,0.89,0.084],"c":[0.0155,0.2531,0.979,0.1978],"r":8.799,"img":"img/L4/walk/p018_20_03.jpg","say":"'집계 함수(MEAN, POOLING, LSTM)를 배운다.' 학습은 확률적 경사하강으로 이뤄져요."},{"b":[0.257,0.492,0.38,0.034],"c":[0.238,0.454,0.418,0.11],"r":6.7556,"img":"img/L4/walk/p018_20_04.jpg","say":"범례예요. 노란 막대가 특징 벡터, 초록 0 이 대상 노드예요."},{"b":[0.292,0.578,0.17,0.33],"c":[0.277,0.5615,0.2,0.363],"r":0.9795,"img":"img/L4/walk/p018_20_05.jpg","say":"왼쪽 그림: 탐색 깊이 $K=1$ 에서의 이웃 샘플링이에요."},{"b":[0.514,0.555,0.2,0.355],"c":[0.502,0.5373,0.224,0.3905],"r":1.0198,"img":"img/L4/walk/p018_20_06.jpg","say":"오른쪽 그림: 뽑아 온 이웃의 특징을 학습 가능한 집계기로 합쳐요."}]}},{"p":19,"title":"GCN 층을 두 군데 고친다","terms":["GraphSAGE","GCN","Aggregator","Concatenation","Permutation Invariance"],"pass1":[{"kind":"say","lines":["**GraphSAGE**는 **GCN** 층을 두 군데 바꿔요.","확장 1은 평균 대신 아무 **집계기(Aggregator)**나 쓸 수 있게 한 것이에요.","확장 2는 더하지 말고 **이어 붙이기(Concatenation)** 하는 것이에요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.067,"y":0.292,"w":0.553,"h":0.13,"say":"확장 1 의 식이에요. AGGREGATE 라는 빈칸이 생겼어요.","c":[0.0393,0.276,0.6083,0.162],"r":6.6754,"img":"img/L4/walk/p019_20_01.jpg"},{"x":0.067,"y":0.497,"w":0.553,"h":0.17,"say":"확장 2 의 식이에요. CONCAT 이 들어 있어요.","c":[0.0393,0.481,0.6083,0.202],"r":5.3536,"img":"img/L4/walk/p019_20_02.jpg"},{"x":0.1,"y":0.607,"w":0.4,"h":0.03,"say":"작은 글씨: '자기 정보와 이웃 정보를 벡터의 서로 다른 절반에 따로 담는다.'","c":[0.08,0.567,0.44,0.11],"r":7.1111,"img":"img/L4/walk/p019_20_03.jpg"},{"x":0.641,"y":0.3,"w":0.292,"h":0.14,"say":"'평균 - GCN: 원래 GCN 방식의 이웃 벡터 평균.'","c":[0.6264,0.284,0.3212,0.172],"r":3.3199,"img":"img/L4/walk/p019_20_04.jpg"},{"x":0.641,"y":0.467,"w":0.292,"h":0.142,"say":"'LSTM: 무작위로 섞은 이웃 집합에 LSTM 을 돌린다. 표현력이 더 크다.'","c":[0.6264,0.451,0.3212,0.174],"r":3.2817,"img":"img/L4/walk/p019_20_05.jpg"},{"x":0.641,"y":0.637,"w":0.292,"h":0.142,"say":"'풀링: 이웃마다 층을 통과시킨 다음, 원소별로 풀링.'","c":[0.6264,0.621,0.3212,0.174],"r":3.2817,"img":"img/L4/walk/p019_20_06.jpg"}]},{"kind":"formula","head":"확장 1: 일반화된 집계기","tex":"\\mathbf{h}_{N(v)}^{(l+1)} = \\text{AGGREGATE}_l \\left( \\left\\{ \\mathbf{h}_u^{(l)}, \\forall u \\in N(v) \\right\\} \\right)","parts":[{"sym":"\\mathbf{h}_{N(v)}^{(l+1)}","say":"$v$ 의 이웃들을 모은 결과 벡터. 친구들 의견을 합친 한 문장이에요."},{"sym":"\\text{AGGREGATE}_l","say":"$l$ 번째 층의 **집계기(Aggregator)**. 의견을 합치는 방법이에요."},{"sym":"\\{ \\cdots \\}","say":"멀티셋, 즉 순서 없는 모음이에요. 걷어 온 쪽지 뭉치예요."},{"sym":"\\mathbf{h}_u^{(l)}","say":"이웃 $u$ 의 층 $l$ 임베딩이에요."},{"sym":"\\forall u \\in N(v)","say":"$v$ 의 모든 이웃에 대해라는 뜻이에요."}],"whole":"**GCN**에서는 이 자리에 평균이 고정돼 있었는데, 여기서는 빈칸이 됐어요. 실제 **GraphSAGE**에서는 $N(v)$ 전체가 아니라 샘플링된 부분집합을 써요."},{"kind":"formula","head":"확장 2: 더하지 말고 이어 붙이기","tex":"\\mathbf{h}_v^{(l+1)} = \\sigma \\left( W^{(l+1)} \\cdot \\text{CONCAT} \\left( \\mathbf{h}_v^{(l)}, \\mathbf{h}_{N(v)}^{(l+1)} \\right) \\right)","parts":[{"sym":"\\text{CONCAT}(a, b)","say":"벡터 $a$ 뒤에 $b$ 를 이어 붙이기. 종이 두 장을 위아래로 붙이는 일이에요."},{"sym":"\\mathbf{h}_v^{(l)}","say":"첫 번째 칸. 내 이전 임베딩이에요."},{"sym":"\\mathbf{h}_{N(v)}^{(l+1)}","say":"두 번째 칸. 방금 모은 이웃 결과예요."},{"sym":"W^{(l+1)}","say":"이어 붙인 긴 벡터를 바꾸는 가중치예요."},{"sym":"\\sigma","say":"비선형 함수. 보통 ReLU 예요."}],"whole":"내 벡터 $[0.4]$ 와 이웃 결과 $[0.2]$ 를 더하면 $[0.6]$ 한 칸이지만, 이어 붙이면 $[0.4, 0.2]$ 두 칸이에요. **이어 붙이기(Concatenation)**를 하면 내 정보가 그대로 남아요."},{"kind":"steps","head":"MEAN 집계와 concat 으로 손계산","steps":["1단계. 이웃 평균을 구해요. A는 0.3, 0.2, 0.1 이라 $0.6/3 = 0.2$ 예요.","B는 0.3, 0.1 이라 0.2. C는 0.4, 0.1 이라 0.25. D도 0.4, 0.1 이라 0.25 예요.","E는 0.4, 0.1, 0.2 라 $0.7/3 \\approx 0.2333$ 이에요.","2단계. 내 값과 이어 붙여요. A는 $[0.4, 0.2]$, B는 $[0.1, 0.2]$ 예요.","C는 $[0.3, 0.25]$, D는 $[0.2, 0.25]$, E는 $[0.1, 0.2333]$ 이에요.","ReLU 는 음수를 0으로 깎는데, 값이 전부 양수라 그대로 통과해요."],"answer":"입력이 1차원이었는데 출력이 2차원이 됐어요. **이어 붙이기(Concatenation)**를 하면 차원이 두 배가 돼요.","given":"노드 5개. 엣지는 A-C, A-D, A-E, B-C, B-E, D-E. 초기 값은 A 0.4, B 0.1, C 0.3, D 0.2, E 0.1 이에요."},{"kind":"compare","head":"집계기 세 가지","cols":["이름","하는 일","메모"],"rows":[["평균 (Mean)","이웃 벡터를 칸마다 평균","원래 **GCN** 방식이에요"],["풀링 (Pooling)","이웃마다 층을 지난 뒤 원소별 최댓값","표현력에 제약이 있어요"],["LSTM","섞은 이웃 집합에 LSTM 을 돌림","**순열 불변성(Permutation Invariance)**이 없어 요즘 안 써요"]]},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 원본 **GCN**과 다른 점을 이렇게 설명했어요.","이전에는 대상 노드 표현과 이웃 표현을 같이 평균 냈는데, **GraphSAGE**는 concat 후 변환한대요.","장점은 **대상 노드 자신의 정보를 조금 더 잘 보존한다**는 것이에요.","그리고 LSTM 집계기는 **순열 불변성(Permutation Invariance)**이 없어서 요즘은 안 쓴다고 했어요."]},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님이 **GraphSAGE**에서 기억할 것은 딱 두 가지라고 정리했어요.","첫째, 1홉 이웃을 전부 가져오지 않고 개수를 $k$ 개로 제한해요. 보통 2나 3이에요.","둘째, 집계한 이웃 정보와 내 정보를 concat 한 뒤 변환해요.","그리고 **두 번째는 마이너한 차이이고 가장 중요한 건 첫 번째**라고 했어요."]}],"pass3":[{"kind":"exam","src":"2025 가을 중간 4번 (10점) (b), (c)","q":"Compute the feature of each node at k=1, then compute the graph embedding h_G by mean global pooling.","qko":"$k=1$ 에서 각 노드의 특징을 계산하고, 평균 전역 풀링으로 그래프 임베딩 $h_G$ 를 구하세요.","solve":["쓸 식은 두 줄이에요. $h_{N(i)}^{(k)} = \\text{MEAN}(\\{h_u^{(k-1)}\\})$ 와 $h_i^{(k)} = \\text{ReLU}(h_i^{(k-1)} \\parallel h_{N(i)}^{(k)})$ 예요.","이웃 평균을 먼저 구해요. $h_{N(A)}^{(1)} = \\text{MEAN}(0.3, 0.2, 0.1) = 0.2$ 예요.","$h_{N(B)}^{(1)} = \\text{MEAN}(0.3, 0.1) = 0.2$, $h_{N(C)}^{(1)} = \\text{MEAN}(0.4, 0.1) = 0.25$ 예요.","내 값과 concat 하면 $h_A^{(1)} = [0.4, 0.2]$, $h_B^{(1)} = [0.1, 0.2]$, $h_C^{(1)} = [0.3, 0.25]$ 예요.","평균 전역 풀링은 차원마다 다섯 노드의 값을 평균 내요.","1번째 칸은 $(0.4+0.1+0.3+0.2+0.1)/5 = 0.22$ 예요."],"answer":"$h_G \\approx [0.22, 0.227]$. concat 순서는 언제나 (내 값, 이웃 값) 이고, 반올림은 소수 둘째 자리예요."},{"kind":"exam","src":"2024 가을 기말 2번 (10점) (a)","q":"Compute the output representation of each node at k=1, where AGGREGATE is MAX.","qko":"집계기가 MAX 일 때 $k=1$ 에서 각 노드의 출력 표현을 계산하세요. 노드는 A~D 네 개이고 $h_A^{(0)} = 0.1$ 이에요.","solve":["첫째 줄만 MEAN 에서 MAX 로 바뀌어요. 이웃 값 중 가장 큰 값 하나를 고르면 돼요.","둘째 줄은 똑같아요. $h_i^{(1)} = \\text{ReLU}(h_i^{(0)} \\parallel h_{N(i)}^{(1)})$ 예요.","노드마다 이웃 목록을 먼저 적고, 그 값들 중 최댓값을 적어요.","그다음 내 값과 이어 붙이면 2차원 벡터가 나와요."],"answer":"답은 노드마다 $[\\text{내 값}, \\text{이웃 중 최댓값}]$ 형태의 2차원 벡터예요. MEAN 이든 MAX 든 둘째 줄은 같아요."},{"kind":"english","head":"서술형에 쓸 한 줄","en":"GraphSAGE concatenates the self representation with the aggregated neighbor representation instead of averaging them together.","ko":"GraphSAGE 는 자기 표현과 집계된 이웃 표현을 같이 평균 내는 대신 이어 붙인다.","tip":"instead of averaging them together 가 GCN 과의 대비예요."},{"kind":"check","q":"**이어 붙이기(Concatenation)**를 하면 벡터 차원이 어떻게 되나요?","choices":["그대로예요","두 배가 돼요","절반이 돼요","1이 돼요"],"a":1,"why":"$[0.4]$ 와 $[0.2]$ 를 이어 붙이면 $[0.4, 0.2]$ 예요. 그래서 뒤에 곱하는 $W$ 가 차원을 다시 줄여 줘요."},{"kind":"warn","head":"해설지 오타와 답안 순서","items":["2025 가을 중간 해설지의 $h_G$ 첫 값이 0.022 로 인쇄돼 있는데 $1.1/5 = 0.22$ 의 오타예요.","같은 해설지에서 $h_{N(E)}$ 의 값 하나가 빠져 있어요. $\\text{MEAN}(0.4, 0.1, 0.2)$ 가 맞아요.","시험에서 concat 순서는 (내 값, 이웃 값) 이에요. 반대로 쓰면 틀려요."]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.459,0.0757],"c":[0,0.0019,0.5049,0.1077],"r":8.3343,"img":"img/L4/walk/p019_h.jpg"},"parts":[{"b":[0.064,0.242,0.13,0.03],"c":[0.029,0.202,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p019_11_01.jpg","say":"왼쪽 위 작은 제목: '확장 1: 일반화된 집계기'."},{"b":[0.064,0.448,0.13,0.03],"c":[0.029,0.408,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p019_11_02.jpg","say":"왼쪽 아래 작은 제목: '확장 2: 더하지 말고 이어 붙이기'."},{"b":[0.64,0.24,0.11,0.034],"c":[0.595,0.202,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p019_11_03.jpg","say":"오른쪽 제목: '집계기 선택지'. 아래 상자 세 개가 선택지예요."}]}},{"p":20,"title":"이름 SAGE 에 답이 들어 있다","terms":["GraphSAGE","Neighbor Sampling","Mini-batch","Inductive Learning","Robustness","Scalability","Aggregator"],"pass1":[{"kind":"say","lines":["**GraphSAGE**는 SAmple and aggreGatE 의 줄임말이에요.","즉 '뽑고 모은다'예요.","이름 자체가 이 모델의 두 동작이에요."]},{"kind":"analogy","head":"이름표에 사용법이 적힌 도구","scene":"민수가 새 도구를 받았는데 이름이 '뽑모'예요. 처음엔 이상한 이름이라고 생각했지만, 설명서를 보니 이 도구는 딱 두 가지 일만 해요. 재료를 몇 개 뽑고, 그걸 하나로 모으는 일이죠. 이름을 외우면 사용법도 외워지는 셈이에요.","map":[["'뽑'","SAmple, 즉 **이웃 샘플링(Neighbor Sampling)**"],["'모'","aggreGatE, 즉 **집계기(Aggregator)** 학습"],["이름이 곧 사용법","이름 네 글자가 두 문제의 해답"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"compare","head":"이름 조각과 그 결과","cols":["이름 조각","동작","얻는 것"],"rows":[["SAmple","이웃 중 고정 개수를 무작위로 뽑기","고정 크기 계산 그래프, **미니 배치(Mini-batch)**"],["aggreGatE","뽑은 이웃의 특징을 학습된 함수로 합치기","노드 임베딩, **귀납적 학습(Inductive Learning)**"]]},{"kind":"points","head":"샘플링의 효과 세 가지","items":["첫째, **확장성(Scalability)**. 계산량이 차수와 무관해지고 우리가 정한 $S$ 와 $L$ 로만 정해져요.","둘째, **강건성(Robustness)**. 매번 다른 이웃 2명만 보게 하면 '누가 와도 답을 맞히는 법'을 배워요.","이건 일반 딥러닝의 드롭아웃과 같은 원리예요. 일부러 가려서 더 튼튼하게 만드는 거죠.","셋째, **귀납적 학습(Inductive Learning)**. 전체 그래프를 안 보니 그래프가 바뀌어도 그대로 돌아가요."]},{"kind":"compare","head":"경량화는 아니에요","cols":["줄어드는 것","안 줄어드는 것"],"rows":[["계산 그래프의 칸 수","학습 파라미터 개수"],["한 번의 갱신 메모리","모델 파일 크기"],["한 번의 갱신 시간","추론할 때 필요한 층 수"]]},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 임의의 $k$ 개만 보여 주는 것의 효과를 하나 더 말했어요.","이웃 중에는 보탬이 되는 이웃도 있고 노이즈 같은 정보를 주는 이웃도 있대요.","임의의 $k$ 개만 보여 주면 노이즈가 낀 환경에서 과제 수행을 배우게 돼요.","결과적으로 모델 자체가 **강건성(Robustness)**을 갖게 된다고 했어요."]},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님이 한 가지 주의도 줬어요.","말하다가 스스로 고쳤는데, 샘플링을 한다고 모델이 경량화되는 건 아니래요.","**가중치의 개수 자체는 크게 변하지 않기 때문**이에요.","줄어드는 건 파라미터가 아니라 한 번의 계산에서 건드리는 데이터의 양이에요."]},{"kind":"warn","head":"철자 문제","items":["SAGE 는 '현자'라는 영어 단어와 같지만 뜻과는 무관한 말장난이에요.","시험에서 'SAGE 가 무엇의 약자인가'를 물으면 SAmple and aggreGatE 라고 답하세요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"Neighbor sampling brings three benefits: the model becomes scalable, robust to noisy neighbors, and inductive.","ko":"이웃 샘플링은 세 가지 이점을 준다. 확장 가능해지고, 잡음 이웃에 강건해지고, 귀납적이 된다.","tip":"scalable, robust, inductive 세 단어 순서로 외우세요."},{"kind":"english","head":"한 줄 덧붙이면 좋아요","en":"Note that the number of learnable parameters does not decrease.","ko":"학습 파라미터 수가 줄어드는 것은 아니다.","tip":"경량화가 아니라는 점을 짚으면 점수에 도움이 돼요."},{"kind":"check","q":"샘플링으로 줄어드는 것은 무엇인가요?","choices":["학습 파라미터 개수","한 번의 갱신에서 만지는 데이터 양","모델 파일 크기","층 수"],"a":1,"why":"머리 크기는 그대로인데 한 번에 펼치는 페이지 수만 줄인 거예요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0177,0.2424,0.0673],"c":[0.001,0.0017,0.2667,0.0993],"r":4.7748,"img":"img/L4/walk/p020_h.jpg"},"parts":[{"b":[0.064,0.143,0.43,0.043],"c":[0.0425,0.1095,0.473,0.11],"r":7.6444,"img":"img/L4/walk/p020_20_01.jpg","say":"맨 위 큰 항목: '**GraphSAGE** (SAmple and aggreGatE)'. SA, G, E 에 밑줄이 있어요."},{"b":[0.095,0.22,0.64,0.04],"c":[0.063,0.1689,0.704,0.1422],"r":8.8014,"img":"img/L4/walk/p020_20_02.jpg","say":"첫 불릿: '노드마다 임베딩을 따로 학습하지 않고, 이웃에서 특징을 뽑아 임베딩을 만든다.'"},{"b":[0.111,0.328,0.11,0.038],"c":[0.066,0.292,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p020_20_03.jpg","say":"화살표로 강조된 '**미니 배치(Mini-batch)**'. Sample 의 결과예요."},{"b":[0.095,0.464,0.75,0.04],"c":[0.0575,0.4007,0.825,0.1667],"r":8.7982,"img":"img/L4/walk/p020_20_04.jpg","say":"둘째 불릿: '집계 함수 묶음을 학습한다.'"},{"b":[0.111,0.572,0.1,0.04],"c":[0.061,0.537,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p020_20_05.jpg","say":"화살표로 강조된 '집계하기'. aggreGatE 의 결과예요."}]}},{"p":21,"title":"미니 배치 한 번이 도는 방법","terms":["Mini-batch","GraphSAGE","Aggregator","Neighbor Sampling","Community","Cluster-GCN","Homophily"],"pass1":[{"kind":"say","lines":["**미니 배치(Mini-batch)** 한 번은 세 단계로 돌아가요.","이웃을 뽑고, 특징을 집계하고, 예측해요.","그림에서 주목할 건 '대상 노드 2개가 각각 자기 영역만 본다'는 점이에요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.09,"y":0.208,"w":0.42,"h":0.17,"say":"불릿 셋: 이웃을 뽑는다, 특징 정보를 집계한다, 그래프 문맥과 레이블을 예측한다.","c":[0.069,0.192,0.462,0.202],"r":4.066,"img":"img/L4/walk/p021_20_01.jpg"},{"x":0.16,"y":0.56,"w":0.26,"h":0.23,"say":"왼쪽 두 덩어리. 안쪽 점선이 K=1, 바깥 점선이 K=2 범위예요.","c":[0.147,0.544,0.286,0.262],"r":1.9406,"img":"img/L4/walk/p021_20_02.jpg"},{"x":0.215,"y":0.83,"w":0.11,"h":0.1,"say":"두 덩어리가 모여 Model $f(X, A; W)$ 로 들어가요.","c":[0.17,0.814,0.2,0.132],"r":2.6936,"img":"img/L4/walk/p021_20_03.jpg"},{"x":0.54,"y":0.555,"w":0.25,"h":0.235,"say":"오른쪽은 같은 그림인데 화살표가 파란색과 초록색 두 종류예요.","c":[0.5275,0.539,0.275,0.267],"r":1.831,"img":"img/L4/walk/p021_20_04.jpg"},{"x":0.755,"y":0.85,"w":0.075,"h":0.08,"say":"범례: 파란 화살표가 Aggregator 1, 초록이 Aggregator 2 예요. 층마다 가중치가 달라요.","c":[0.6925,0.834,0.2,0.112],"r":3.1746,"img":"img/L4/walk/p021_20_05.jpg"}]},{"kind":"points","head":"식 $f(X, A; W)$ 를 읽어요","items":["$X$ 는 특징행렬이에요. 노드마다의 입력 특징을 세로로 쌓은 것이죠.","$A$ 는 인접행렬, 또는 샘플링된 부분이에요.","세미콜론 뒤 $W$ 는 학습 파라미터예요.","'입력 $X$, $A$ 를 받아 파라미터 $W$ 로 계산하는 모델'이라는 표기예요."]},{"kind":"steps","head":"$S = 2$ 로 미니 배치를 돌려 봐요","steps":["대상 노드 {A, E} 두 개를 뽑았다고 해요.","$S = 2$ 로 무작위 샘플링을 했더니 A 는 {C, D}, E 는 {A, B} 가 뽑혔어요.","A의 이웃 평균은 $0.5/2 = 0.25$ 라 concat 하면 $[0.4, 0.25]$ 예요.","E의 이웃 평균도 $0.5/2 = 0.25$ 라 $[0.1, 0.25]$ 예요.","p.19 에서 전체 이웃을 썼을 때는 $[0.4, 0.2]$, $[0.1, 0.2333]$ 이었죠."],"answer":"값이 조금 달라졌어요. 이게 샘플링의 대가예요. 대신 대상 노드 하나당 층-0 칸 수가 언제나 4 로 고정돼요.","given":"p.19 와 같은 5노드 그래프예요."},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 미니 배치가 왜 되는지를 다시 강조했어요.","이웃 개수를 제약하면 어디서 정보를 가져올지, 메모리를 얼마나 잡을지 예상할 수 있대요.","그래서 **미니 배치(Mini-batch)**가 가능해진다는 거예요.","실무에서는 PyTorch Geometric 의 `NeighborSampler` 로 같은 샘플링을 쓸 수 있다고 했어요."]},{"kind":"mining","src":"마이닝 5강 Community Detection","lines":["그림에서 두 대상 노드의 영역이 겹치는 부분을 보세요.","같은 **커뮤니티(Community)** 안에 있으면 영역이 많이 겹쳐요.","겹침이 많으면 같은 노드를 두 번 계산하는 낭비가 생기죠.","이 '겹침을 오히려 이용하자'는 생각이 뒤쪽 **Cluster-GCN**의 출발점이에요."]},{"kind":"warn","head":"숫자 두 개를 헷갈리지 마세요","items":["'미니 배치 2'는 대상 노드가 2개라는 뜻이지 샘플링 이웃이 2개라는 뜻이 아니에요.","층마다 집계기가 다르다는 건 층마다 가중치가 다르다는 뜻이에요. 집계 방식 자체는 보통 같아요.","매 반복마다 뽑히는 이웃이 달라지니 같은 노드의 임베딩도 조금씩 달라져요. 의도된 동작이에요."]}],"pass3":[{"kind":"exam","src":"2025 가을 중간 5번 (10점) (a)","q":"What is mini-batch training?","qko":"**미니 배치(Mini-batch)** 학습이란 무엇인가요?","solve":["정의부터 씁니다. 그래프 전체를 한 번에 처리하지 않아요.","반복마다 무작위로 고른 작은 대상 노드 부분집합으로 모델을 갱신해요.","**GraphSAGE**라면 그 대상 노드마다 고정 개수의 이웃만 따라와요.","그래서 메모리가 예측 가능해지고 학습이 안정돼요."],"answer":"Mini-batch training updates the model using a small randomly selected subset of target nodes at each iteration, instead of processing the entire graph at once."},{"kind":"check","q":"그림의 'search depth : 2' 가 뜻하는 것은?","choices":["대상 노드가 2개","층이 2개, 즉 2홉까지 본다","이웃을 2개 뽑는다","배치를 두 번 돌린다"],"a":1,"why":"탐색 깊이는 층 수예요. 대상 노드 개수는 'Mini batch : 2' 쪽이에요."}],"pass4":[{"kind":"points","head":"4주차 실습 노트북은 아직 없어요","items":["그래서 코드는 2주차 노트북 `PracticeCode_2.ipynb` 로 확인했어요.","p.11 에서 인접행렬을 노드 수 x 노드 수 로 통째로 만드는 줄을 봤어요.","p.12 에서 `forward(x, adj)` 와 `model(x, support)` 가 언제나 전체를 받는 걸 봤어요.","그 두 줄이 바로 이 쪽이 고치려는 지점이에요."]},{"kind":"warn","head":"코드로 다시 정리하면","items":["`adj` 자리에 들어가는 것이 그래프 전체면 **풀배치(Full-batch)**예요.","**GraphSAGE**는 이 자리에 '뽑힌 이웃만 담긴 작은 부분'을 넣어요.","PyTorch Geometric 의 `NeighborSampler` 예제 코드는 슬라이드 p.29 에 나와요."]}],"walk":{"head":{"b":[0.0131,0.0179,0.2964,0.0757],"c":[0,0.0019,0.3261,0.1077],"r":5.3829,"img":"img/L4/walk/p021_h.jpg"},"parts":[{"b":[0.061,0.136,0.3,0.042],"c":[0.046,0.102,0.33,0.11],"r":5.3333,"img":"img/L4/walk/p021_11_01.jpg","say":"'**미니 배치(Mini-batch)**: 세 단계로 이뤄진다' 아래에 불릿 셋이 있어요."},{"b":[0.149,0.489,0.23,0.035],"c":[0.137,0.4515,0.254,0.11],"r":4.1051,"img":"img/L4/walk/p021_11_02.jpg","say":"'Mini batch : 2, search depth : 2'. 대상 노드 2개, 탐색 깊이 2 라는 뜻이에요."}]}},{"p":22,"title":"고정 크기 샘플링이 바꾸는 복잡도","terms":["GraphSAGE","Neighbor Sampling","Mini-batch","Degree","Scalability","Node-wise Sampling","FastGCN","ASGCN"],"pass1":[{"kind":"say","lines":["이 쪽은 **GraphSAGE** 이야기의 결론이에요.","고정 크기 샘플링을 쓰면 입력층 노드 수가 $O(|V|^K)$ 에서 $O(\\prod_{i=1}^{K} S_i)$ 로 줄어요.","오른쪽 값에는 그래프 크기도 **차수(Degree)**도 들어 있지 않아요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.06,"y":0.205,"w":0.42,"h":0.038,"say":"불릿 1: '미니 배치 뽑기(대상 노드를 미니 배치로 뽑는다)'.","c":[0.039,0.169,0.462,0.11],"r":7.4667,"img":"img/L4/walk/p022_20_01.jpg"},{"x":0.06,"y":0.272,"w":0.29,"h":0.037,"say":"불릿 2: '대상 노드마다 고정 크기 집합 뽑기'.","c":[0.0455,0.2355,0.319,0.11],"r":5.1556,"img":"img/L4/walk/p022_20_02.jpg"},{"x":0.358,"y":0.455,"w":0.085,"h":0.036,"say":"왼쪽 상자의 'Sampled Nodes' 표. 위에서부터 1, 6, 9 예요.","c":[0.3005,0.418,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p022_20_03.jpg"},{"x":0.611,"y":0.72,"w":0.23,"h":0.028,"say":"오른쪽 아래 'Fix-size neighbor sampling S=2'.","c":[0.599,0.679,0.254,0.11],"r":4.1051,"img":"img/L4/walk/p022_20_04.jpg"},{"x":0.569,"y":0.862,"w":0.335,"h":0.07,"say":"핵심 식: '입력층의 노드 수: $O(|V|^K) \\rightarrow O(\\prod_{i=1}^{K} S_i)$'.","c":[0.5522,0.842,0.3685,0.11],"r":5.9556,"img":"img/L4/walk/p022_20_05.jpg"}]},{"kind":"formula","head":"이번 주에서 가장 중요한 식","tex":"O(|V|^K) \\rightarrow O\\left(\\prod_{i=1}^{K} S_i\\right)","parts":[{"sym":"O(\\cdot)","say":"대략 이 정도 규모라는 표기예요. '자릿수로 말하면' 정도의 뜻이에요."},{"sym":"|V|","say":"그래프의 노드 개수. 전교생 수예요."},{"sym":"K","say":"층 수, 곧 홉 수예요."},{"sym":"|V|^K","say":"최악의 경우 필요한 노드 수예요."},{"sym":"\\prod_{i=1}^{K}","say":"$i=1$ 부터 $K$ 까지 **곱한다**는 기호예요. 시그마는 더하기, 파이는 곱하기예요."},{"sym":"S_i","say":"층 $i$ 에서 뽑을 이웃 개수. 층마다 정한 정원이에요."}],"whole":"원래는 최악의 경우 노드 수의 $K$ 제곱만큼 필요했는데, 고정 크기 샘플링을 하면 층마다의 정원을 전부 곱한 값만 필요해요."},{"kind":"steps","head":"제한이 있을 때와 없을 때","steps":["층마다 정원을 같게 $S$ 로 두면 곱은 $S^L$ 이 돼요. 제한이 없으면 $d^L$ 이고요.","$d = 100$, $L = 2$ 면 제한 없이는 10,000, $S=2$ 면 4 예요. 2,500배 차이예요.","$L = 3$ 이면 1,000,000 대 8 이라 125,000배예요.","$L = 4$ 면 100,000,000 대 16 이라 625만배예요.","층마다 정원을 다르게 줄 수도 있어요. 자주 쓰는 설정이 $S_1 = 10$, $S_2 = 5$ 예요.","$10 \\times 5 = 50$ 이라, 배치 크기가 32면 $32 \\times 50 = 1{,}600$ 개만 만져요."],"answer":"노드가 1억 개인 그래프에서 한 번에 1,600개만 만지는 거예요. 가까운 층에 정원을 더 크게 주는 게 보통이에요.","given":"$d$ 는 평균 차수, $L$ 은 층 수, $S$ 는 층마다 뽑을 이웃 수예요."},{"kind":"figure","head":"층이 깊어질수록 격차가 폭발한다","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"240\" y=\"24\" font-size=\"16\" text-anchor=\"middle\">평균 차수 100 일 때 입력층 칸 수<\/text>\n<text class=\"tm\" x=\"66\" y=\"56\" font-size=\"14\" text-anchor=\"middle\">층 수<\/text>\n<text class=\"tm\" x=\"210\" y=\"56\" font-size=\"14\" text-anchor=\"middle\">제한 없음<\/text>\n<text class=\"tm\" x=\"360\" y=\"56\" font-size=\"14\" text-anchor=\"middle\">S = 2 제한<\/text>\n<rect class=\"box b1\" x=\"30\" y=\"66\" width=\"420\" height=\"38\" rx=\"6\"/>\n<text class=\"t b1\" x=\"66\" y=\"91\" font-size=\"15\" text-anchor=\"middle\">1층<\/text>\n<text class=\"t b1\" x=\"210\" y=\"91\" font-size=\"15\" text-anchor=\"middle\">100<\/text>\n<text class=\"tb b1\" x=\"360\" y=\"91\" font-size=\"15\" text-anchor=\"middle\">2<\/text>\n<rect class=\"box b2\" x=\"30\" y=\"110\" width=\"420\" height=\"38\" rx=\"6\"/>\n<text class=\"t b2\" x=\"66\" y=\"135\" font-size=\"15\" text-anchor=\"middle\">2층<\/text>\n<text class=\"t b2\" x=\"210\" y=\"135\" font-size=\"15\" text-anchor=\"middle\">10,000<\/text>\n<text class=\"tb b2\" x=\"360\" y=\"135\" font-size=\"15\" text-anchor=\"middle\">4<\/text>\n<rect class=\"box b3\" x=\"30\" y=\"154\" width=\"420\" height=\"38\" rx=\"6\"/>\n<text class=\"t b3\" x=\"66\" y=\"179\" font-size=\"15\" text-anchor=\"middle\">3층<\/text>\n<text class=\"t b3\" x=\"210\" y=\"179\" font-size=\"15\" text-anchor=\"middle\">1,000,000<\/text>\n<text class=\"tb b3\" x=\"360\" y=\"179\" font-size=\"15\" text-anchor=\"middle\">8<\/text>\n<rect class=\"box2 b4\" x=\"30\" y=\"198\" width=\"420\" height=\"38\" rx=\"6\"/>\n<text class=\"t b4\" x=\"66\" y=\"223\" font-size=\"15\" text-anchor=\"middle\">4층<\/text>\n<text class=\"t b4\" x=\"210\" y=\"223\" font-size=\"15\" text-anchor=\"middle\">100,000,000<\/text>\n<text class=\"tb b4\" x=\"360\" y=\"223\" font-size=\"15\" text-anchor=\"middle\">16<\/text>\n<text class=\"tb b4\" x=\"240\" y=\"258\" font-size=\"16\" text-anchor=\"middle\">왼쪽은 100배씩, 오른쪽은 2배씩 늘어요<\/text>\n<\/svg>","caption":"왼쪽 칸은 층마다 100배씩, 오른쪽 칸은 2배씩 늘어요. 이게 **이웃 샘플링(Neighbor Sampling)**의 힘이에요.","builds":4},{"kind":"compare","head":"두 상자의 숫자","cols":["층","미니 배치만","고정 크기 샘플링 $S=2$"],"rows":[["Layer 3 (맨 위)","1","1"],["Layer 2","6","3"],["Layer 1 (맨 아래)","9","5"]]},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 **GraphSAGE**를 이렇게 마무리했어요.","여기까지 보면 완벽해 보이지만 완벽하지는 않대요.","샘플링된 결과가 전체를 얼마나 충실히 반영하느냐 하는 문제가 남아요.","**GraphSAGE**는 전적으로 그냥 고정된 개수를 랜덤으로 뽑을 뿐이라는 게 한계예요."]},{"kind":"warn","head":"계산에서 자주 틀리는 곳","items":["$\\prod$ 는 곱하기예요. $\\sum$ (더하기)와 헷갈리면 답이 완전히 달라져요.","$S_1 = 10$, $S_2 = 5$ 일 때 답은 15가 아니라 50이에요.","왼쪽 상자의 9, 6, 1 은 '배치 계산에 실제로 쓰이는 노드만 세었다'는 뜻이에요."]}],"pass3":[{"kind":"english","head":"만점 답안에 쓸 한 줄","en":"The number of nodes at the input layer drops from O(|V|^K) to O(S_1 x S_2 x ... x S_K).","ko":"입력층의 노드 수가 $O(|V|^K)$ 에서 $S_i$ 들의 곱으로 줄어든다.","tip":"이어서 'which is independent of the graph size and node degrees' 를 붙이면 좋아요."},{"kind":"english","head":"한계도 한 줄 덧붙이세요","en":"However, GraphSAGE samples neighbors uniformly at random, so there is no theoretical guarantee on the sampling quality.","ko":"다만 GraphSAGE 는 이웃을 균등하게 무작위로 뽑기 때문에 샘플링 품질에 대한 이론적 보장이 없다.","tip":"이 한계를 공격하는 모델이 다음에 나오는 **FastGCN**과 **ASGCN**이에요."},{"kind":"check","q":"$S_1 = 10$, $S_2 = 5$ 일 때 대상 노드 하나당 층-0 노드 수는?","choices":["15","50","2","105"],"a":1,"why":"$\\prod$ 는 곱하기예요. $10 \\times 5 = 50$ 이에요."},{"kind":"warn","head":"마지막 정리","items":["**노드 단위 샘플링(Node-wise Sampling)**의 장점은 구현이 간편하다는 것이에요.","단점은 샘플링 품질을 이론으로 보장할 수 없다는 것이에요.","이 두 줄이 서술형에서 가장 자주 요구되는 짝이에요."]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4857,0.3019],"c":[0,0.0019,0.5343,0.3339],"r":2.8448,"img":"img/L4/walk/p022_h.jpg"},"parts":[{"b":[0.104,0.349,0.35,0.585],"c":[0.0865,0.3197,0.385,0.6435],"r":1.0636,"img":"img/L4/walk/p022_11_01.jpg","say":"왼쪽 상자 '미니 배치 학습'. 층마다 뽑힌 노드가 1, 6, 9 개예요."},{"b":[0.542,0.349,0.37,0.585],"c":[0.5235,0.3197,0.407,0.6435],"r":1.1244,"img":"img/L4/walk/p022_11_02.jpg","say":"오른쪽 상자 '고정 크기 이웃 샘플링'. 같은 층이 1, 3, 5 개로 줄었어요."}]}},{"p":23,"title":"집계기 자리는 갈아 끼울 수 있는 빈칸","terms":["GraphSAGE","Aggregator","Concatenation","Computation Graph","GCN"],"pass1":[{"kind":"say","lines":["**그래프세이지(GraphSAGE)**의 **집계기(Aggregator)**는 조건이 딱 두 개예요.","벡터 여러 개를 받아 벡터 하나를 내놓을 것,","그리고 미분이 될 것. 그러면 무엇이든 끼워 넣어도 돼요."]},{"kind":"analogy","head":"믹서기에 칼날을 바꿔 끼우기","scene":"민수네 집에 믹서기가 하나 있어요. 과일을 넣으면 주스 한 컵이 나와요. 그런데 안쪽 칼날은 통째로 바꿔 끼울 수 있어요. 칼날을 바꿔도 나오는 건 여전히 주스 한 컵이에요. 넣는 과일 개수가 몇 개든 컵은 언제나 하나예요.","map":[["과일 여러 개","이웃들이 보낸 벡터 여러 개"],["주스 한 컵","벡터 하나"],["바꿔 끼우는 칼날","**집계기(Aggregator)** 자리"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.02,"y":0.03,"w":0.12,"h":0.055,"say":"제목이 'GraphSAGE' 예요. 여기부터 **그래프세이지(GraphSAGE)** 본론이에요.","c":[0,0.0025,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p023_20_01.jpg"},{"x":0.21,"y":0.33,"w":0.17,"h":0.31,"say":"왼쪽이 입력 그래프. A 위에 'TARGET NODE' 화살표가 붙어 있어요.","c":[0.195,0.314,0.2,0.342],"r":1.0396,"img":"img/L4/walk/p023_20_02.jpg"},{"x":0.444,"y":0.284,"w":0.285,"h":0.358,"say":"오른쪽이 A 의 **계산 그래프(Computation Graph)**예요. 오른쪽에서 왼쪽으로 정보가 흘러요.","c":[0.4298,0.2661,0.3135,0.3938],"r":1.4153,"img":"img/L4/walk/p023_20_03.jpg"},{"x":0.482,"y":0.432,"w":0.054,"h":0.101,"say":"연한 회색 네모가 A 의 **집계기(Aggregator)**, 짙은 회색은 B, C, D 의 집계기예요.","c":[0.409,0.416,0.2,0.133],"r":2.6734,"img":"img/L4/walk/p023_20_04.jpg"},{"x":0.215,"y":0.741,"w":0.503,"h":0.064,"say":"맨 아래 식이에요. 파란 상자가 쳐진 곳이 갈아 끼울 수 있는 부품이에요.","c":[0.1899,0.7171,0.5533,0.1118],"r":8.7983,"img":"img/L4/walk/p023_20_05.jpg"}]},{"kind":"formula","head":"이 쪽의 식 한 글자씩","tex":"\\mathbf{h}_v^k = \\sigma\\left(\\left[\\mathbf{A}_k \\cdot \\mathrm{AGG}\\left(\\{\\mathbf{h}_u^{k-1}, \\forall u \\in N(v)\\}\\right),\\ \\mathbf{B}_k \\mathbf{h}_v^{k-1}\\right]\\right)","parts":[{"sym":"v","say":"브이. 임베딩을 새로 만들 대상 노드예요."},{"sym":"k","say":"케이. 층 번호예요. 몇 번째 소문 돌리기인지예요."},{"sym":"N(v)","say":"엔 오브 브이. $v$ 의 이웃 집합, 즉 친구 명단이에요."},{"sym":"\\forall u \\in N(v)","say":"이웃 전부에 대해라는 뜻이에요."},{"sym":"\\mathrm{AGG}(\\cdot)","say":"**집계기(Aggregator)**. 쪽지 봉투를 벡터 하나로 요약해요."},{"sym":"\\mathbf{A}_k","say":"이웃 요약본에 곱할 가중치. 친구 말을 읽는 뇌예요."},{"sym":"\\mathbf{B}_k","say":"내 정보에 곱할 가중치. 내 생각을 읽는 뇌예요."},{"sym":"[\\ \\cdot\\ ,\\ \\cdot\\ ]","say":"대괄호. 두 벡터를 옆으로 **이어 붙이기(Concatenation)** 해요."},{"sym":"\\sigma","say":"시그마. 비선형 함수, 보통 ReLU 예요."}],"whole":"친구 쪽지를 요약해 뇌 $\\mathbf{A}_k$ 로 읽은 것과, 내 어제 점수표를 뇌 $\\mathbf{B}_k$ 로 읽은 것을 나란히 붙인 뒤 다듬어요."},{"kind":"steps","head":"어떤 함수가 AGG 자리에 들어갈 수 있나요","steps":["합(sum): 첫 칸 $1+0+1=2$, 둘째 칸 $0+1+1=2$ 라 $(2, 2)$ 예요. 합격이에요.","평균(mean): 두 칸 모두 $2/3 \\approx 0.67$ 이라 $(0.67, 0.67)$ 이에요. 합격이에요.","최댓값(max): $\\max(1,0,1)=1$, $\\max(0,1,1)=1$ 이라 $(1, 1)$ 이에요. 합격이에요.","개수만 세기: 3 이라는 숫자 하나뿐이에요. 벡터가 아니라 탈락이에요.","앞의 셋은 모두 두 칸짜리 벡터 하나를 내놓았어요."],"answer":"들어가는 개수는 제각각이어도 나오는 모양이 항상 같아야 해요. 그게 유일한 조건이에요.","given":"이웃 쪽지 세 장이 $(1,0)$, $(0,1)$, $(1,1)$ 이라고 해요."},{"kind":"points","head":"'집합'이라고 적혀 있지만 실제로는","items":["슬라이드는 '벡터 집합(set of vectors)'이라고 써요.","그런데 실제로 다루는 건 3주차에 배운 멀티셋이에요.","같은 특징이 두 번 들어오면 두 번으로 세는 집계기도 쓰니까요.","합과 평균이 바로 그런 **집계기(Aggregator)**예요."]},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 **그래프세이지(GraphSAGE)**의 가장 큰 장점을 이렇게 말했어요.","**미니 배치(Mini-batch)**가 가능해진다는 점이라고요.","이웃 개수에 제한을 두면 어디서 정보를 가져올지 미리 알 수 있대요.","메모리를 얼마나 잡아야 할지도 미리 예상할 수 있게 된다고요."]},{"kind":"warn","head":"기호 때문에 헷갈리는 곳","items":["이 쪽은 가중치를 $\\mathbf{A}_k$, $\\mathbf{B}_k$ 로 쓰는데 p.24 와 p.25 는 $\\mathbf{W}_k$, $\\mathbf{B}_k$ 로 써요. 같은 것이에요.","가중치 $\\mathbf{A}_k$ 와 **인접행렬(Adjacency Matrix)** $A$ 를 헷갈리지 마세요.","'아무 함수나 된다'가 '아무거나 써도 성능이 같다'는 뜻은 아니에요. 표현력은 합, 평균, 최댓값 순이에요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"GraphSAGE replaces the fixed mean aggregator of GCN with any differentiable set function.","ko":"GraphSAGE 는 GCN 의 고정된 평균 집계기를 미분 가능한 아무 집합 함수로 바꾼다.","tip":"so the aggregator itself becomes a design choice 를 붙이면 더 좋아요."},{"kind":"exam","src":"2024 가을 기말 1번 (b)","q":"What is the limitation of GCNs compared to GraphSAGE?","qko":"**그래프세이지(GraphSAGE)**에 비해 **GCN**이 갖는 한계는 무엇인가요?","solve":["해설 첫 문장이 핵심이에요. 학습에 필요한 것을 먼저 말해요.","**GCN**은 학습하는 동안 그래프 전체의 **인접행렬(Adjacency Matrix)**이 필요해요.","특징행렬도 통째로 필요해요. 그래서 큰 그래프에서 메모리가 터져요.","**그래프세이지(GraphSAGE)**는 고정 개수의 이웃만 뽑아 쓰니 그 부담이 없어요."],"answer":"GCNs require the entire graph adjacency matrix and feature matrix during training."},{"kind":"check","q":"**집계기(Aggregator)** 자리에 들어갈 함수의 조건은 무엇인가요?","choices":["벡터 하나를 내놓고 미분이 될 것","항상 평균일 것","이웃 수를 세어 줄 것","반드시 선형일 것"],"a":0,"why":"벡터 여러 개를 벡터 하나로 보내고 미분이 되면 돼요. 이 둘이 전부예요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.1734,0.0757],"c":[0,0.0019,0.2,0.1077],"r":3.3014,"img":"img/L4/walk/p023_h.jpg"},"parts":[{"b":[0.038,0.146,0.556,0.049],"c":[0.0102,0.1087,0.6116,0.1236],"r":8.7968,"img":"img/L4/walk/p023_12_01.jpg","say":"맨 위 한 줄이 전부예요. '벡터 집합을 벡터 하나로 보내는 미분 가능한 아무 함수'."},{"b":[0.482,0.432,0.054,0.101],"c":[0.409,0.416,0.2,0.133],"r":2.6734,"img":"img/L4/walk/p023_12_02.jpg","say":"오른쪽 가운데 연한 회색 네모가 바로 그 빈칸이에요."}]}},{"p":24,"title":"더하지 말고 옆으로 이어 붙여요","terms":["GraphSAGE","GCN","Concatenation","Aggregator","Neighbor Sampling","Degree"],"pass1":[{"kind":"say","lines":["**GCN**은 이웃 요약과 내 정보를 **더해서** 한 덩어리로 만들었어요.","**그래프세이지(GraphSAGE)**는 둘을 옆으로 붙여 따로 남겨 둬요.","이걸 **이어 붙이기(Concatenation)**라고 해요."]},{"kind":"analogy","head":"물감 두 통을 섞을까, 나란히 둘까","scene":"미술 시간에 민수가 파란 물감과 노란 물감을 받았어요. 두 통을 한 통에 부어 섞으면 초록색 한 통이 되죠. 예쁘지만 다시 파란색과 노란색으로 나눌 수는 없어요. 대신 두 통을 그냥 나란히 놓아 두면 언제든 필요한 쪽을 골라 쓸 수 있어요.","map":[["섞어서 한 통","**GCN**의 더하기"],["나란히 놓은 두 통","**이어 붙이기(Concatenation)**"],["필요한 쪽을 골라 쓰기","다음 층이 두 칸에 다른 무게를 주기"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.299,"y":0.296,"w":0.34,"h":0.136,"say":"**GCN** 식이에요. 이웃을 더한 뒤 이웃 수로 나누니 평균이에요.","c":[0.282,0.28,0.374,0.168],"r":3.9577,"img":"img/L4/walk/p024_20_01.jpg"},{"x":0.215,"y":0.741,"w":0.507,"h":0.068,"say":"**그래프세이지(GraphSAGE)** 식이에요. 대괄호와 AGG 가 새로 생겼어요.","c":[0.1897,0.7187,0.5577,0.1127],"r":8.7974,"img":"img/L4/walk/p024_20_02.jpg"},{"x":0.42,"y":0.601,"w":0.222,"h":0.074,"say":"위 화살표 설명: '자기 임베딩과 이웃 임베딩을 이어 붙인다'. 대괄호를 가리켜요.","c":[0.408,0.583,0.246,0.11],"r":3.9758,"img":"img/L4/walk/p024_20_03.jpg"},{"x":0.198,"y":0.864,"w":0.108,"h":0.043,"say":"왼쪽 아래: '일반화된 집계'. AGG 글자를 가리켜요.","c":[0.152,0.8305,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p024_20_04.jpg"},{"x":0.526,"y":0.87,"w":0.087,"h":0.043,"say":"오른쪽 아래: '**이웃 샘플링(Neighbor Sampling)**'. 이웃이 전부가 아니라 뽑힌 이웃이라는 표시예요.","c":[0.4695,0.8365,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p024_20_05.jpg"}]},{"kind":"compare","head":"고친 곳이 딱 세 군데예요","cols":["자리","GCN","GraphSAGE"],"rows":[["이웃 모으기","평균으로 고정","아무 **집계기(Aggregator)**나"],["이웃 범위","1홉 이웃 전부","뽑은 고정 개수만"],["내 정보 합치기","더하기","**이어 붙이기(Concatenation)**"],["출력 길이","$d$ 차원","$2d$ 차원"]]},{"kind":"points","head":"세로 막대 두 개의 뜻","items":["$|N(v)|$ 는 '엔 브이의 크기'라고 읽어요.","세로 막대 두 개는 절댓값이 아니라 **개수**를 뜻해요.","즉 $v$ 의 이웃이 몇 명인지, 곧 **차수(Degree)**예요.","**GCN** 식에서 이걸로 나누니까 합이 아니라 평균이 되는 거예요."]},{"kind":"steps","head":"MEAN 집계로 한 층을 돌려 봐요","steps":["1단계. 이웃 평균을 구해요. A 의 이웃은 C, D, E 예요.","$h_{N(A)} = (0.3 + 0.2 + 0.1)/3 = 0.2$ 예요.","B 는 $(0.3+0.1)/2 = 0.2$, C 와 D 는 $(0.4+0.1)/2 = 0.25$ 예요.","E 의 이웃은 A, B, D 세 개라 $(0.4+0.1+0.2)/3 \\approx 0.2333$ 이에요.","2단계. 내 값과 이어 붙여요. A 는 $[0.4, 0.2]$, B 는 $[0.1, 0.2]$ 예요.","C 는 $[0.3, 0.25]$, D 는 $[0.2, 0.25]$, E 는 $[0.1, 0.2333]$ 이에요."],"answer":"값이 전부 양수라 ReLU 를 지나도 그대로예요. 숫자 하나였던 것이 두 칸짜리 벡터가 됐어요.","given":"노드 5개. 엣지는 A-C, A-D, A-E, B-C, B-E, D-E. 값은 A 0.4, B 0.1, C 0.3, D 0.2, E 0.1 이에요."},{"kind":"steps","head":"**GCN** 이었다면 어떻게 달랐을까요","steps":["**GCN**은 내 값과 이웃 평균을 더해요.","A 는 $0.4 + 0.2 = 0.6$, B 는 $0.1 + 0.2 = 0.3$ 이에요.","C 는 $0.3 + 0.25 = 0.55$, D 는 $0.2 + 0.25 = 0.45$ 예요.","A 의 0.6 만 보고 '내가 0.4, 친구가 0.2' 였음을 되찾을 수 있나요? 없어요.","$[0.4, 0.2]$ 는 두 값이 칸마다 그대로 남아 있어서 되찾을 수 있어요."],"answer":"더하기는 되돌릴 수 없고, **이어 붙이기(Concatenation)**는 되돌릴 수 있어요. 대신 길이가 두 배가 돼요.","given":"같은 그래프, 같은 값이에요."},{"kind":"figure","head":"섞기와 나란히 두기","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"118\" y=\"28\" font-size=\"16\" text-anchor=\"middle\">GCN: 더하기<\/text>\n<rect class=\"box\" x=\"60\" y=\"44\" width=\"52\" height=\"30\" rx=\"6\"/>\n<text class=\"t\" x=\"86\" y=\"65\" font-size=\"14\" text-anchor=\"middle\">0.4<\/text>\n<rect class=\"box2\" x=\"124\" y=\"44\" width=\"52\" height=\"30\" rx=\"6\"/>\n<text class=\"t\" x=\"150\" y=\"65\" font-size=\"14\" text-anchor=\"middle\">0.2<\/text>\n<text class=\"tm\" x=\"118\" y=\"96\" font-size=\"14\" text-anchor=\"middle\">내 값 + 이웃 값<\/text>\n<rect class=\"box b1\" x=\"86\" y=\"108\" width=\"64\" height=\"34\" rx=\"6\"/>\n<text class=\"tb b1\" x=\"118\" y=\"131\" font-size=\"16\" text-anchor=\"middle\">0.6<\/text>\n<text class=\"tm b1\" x=\"118\" y=\"166\" font-size=\"14\" text-anchor=\"middle\">한 칸으로 뭉쳐서<\/text>\n<text class=\"tm b1\" x=\"118\" y=\"188\" font-size=\"14\" text-anchor=\"middle\">되돌릴 수 없어요<\/text>\n<line class=\"e\" x1=\"240\" y1=\"34\" x2=\"240\" y2=\"198\"/>\n<text class=\"tb\" x=\"362\" y=\"28\" font-size=\"16\" text-anchor=\"middle\">GraphSAGE: 이어 붙이기<\/text>\n<rect class=\"box\" x=\"304\" y=\"44\" width=\"52\" height=\"30\" rx=\"6\"/>\n<text class=\"t\" x=\"330\" y=\"65\" font-size=\"14\" text-anchor=\"middle\">0.4<\/text>\n<rect class=\"box2\" x=\"368\" y=\"44\" width=\"52\" height=\"30\" rx=\"6\"/>\n<text class=\"t\" x=\"394\" y=\"65\" font-size=\"14\" text-anchor=\"middle\">0.2<\/text>\n<text class=\"tm\" x=\"362\" y=\"96\" font-size=\"14\" text-anchor=\"middle\">두 칸을 나란히<\/text>\n<rect class=\"box b2\" x=\"302\" y=\"108\" width=\"58\" height=\"34\" rx=\"6\"/>\n<text class=\"tb b2\" x=\"331\" y=\"131\" font-size=\"16\" text-anchor=\"middle\">0.4<\/text>\n<rect class=\"box2 b2\" x=\"364\" y=\"108\" width=\"58\" height=\"34\" rx=\"6\"/>\n<text class=\"tb b2\" x=\"393\" y=\"131\" font-size=\"16\" text-anchor=\"middle\">0.2<\/text>\n<text class=\"tm b2\" x=\"362\" y=\"166\" font-size=\"14\" text-anchor=\"middle\">칸이 나뉘어 있어서<\/text>\n<text class=\"tm b2\" x=\"362\" y=\"188\" font-size=\"14\" text-anchor=\"middle\">둘 다 그대로 남아요<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"228\" font-size=\"16\" text-anchor=\"middle\">대신 벡터 길이가 두 배가 돼요<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"252\" font-size=\"14\" text-anchor=\"middle\">다음 층 가중치의 입력 크기도 두 배예요<\/text>\n<\/svg>","caption":"**이어 붙이기(Concatenation)**를 하면 내 정보가 이웃 정보에 묻히지 않아요.","builds":3},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 이 대목을 이렇게 정리했어요.","이전 방식(**GCN**)은 대상 노드 표현과 이웃 표현을 같이 평균 냈대요.","**그래프세이지(GraphSAGE)**는 이웃을 먼저 집계하고 concat 한 뒤 변환한다고요.","장점은 대상 노드 자신의 정보를 조금 더 잘 보존한다는 것이에요."]},{"kind":"warn","head":"여기서 놓치기 쉬운 것","items":["concat 순서는 언제나 (내 값, 이웃 값) 이에요. 반대로 쓰면 틀려요.","$d$ 차원 두 개를 붙이면 $2d$ 차원이에요. 다음 층 가중치의 입력 크기도 $2d$ 가 돼야 해요.","ReLU 를 벡터에 씌운다는 건 칸마다 따로 $\\max(0, x)$ 를 한다는 뜻이에요."]}],"pass3":[{"kind":"exam","src":"2025 가을 중간 4번 (10점) (b)","q":"Compute the feature of each node at k=1.","qko":"$k=1$ 에서 각 노드의 특징을 계산하세요. 집계기는 MEAN 이에요.","solve":["쓸 식은 두 줄이에요. 먼저 이웃 평균, 그다음 concat 후 ReLU 예요.","$h_{N(A)}^{(1)} = \\mathrm{MEAN}(0.3, 0.2, 0.1) = 0.2$ 예요.","$h_{N(B)}^{(1)} = \\mathrm{MEAN}(0.3, 0.1) = 0.2$, $h_{N(C)}^{(1)} = \\mathrm{MEAN}(0.4, 0.1) = 0.25$ 예요.","$h_{N(D)}^{(1)} = 0.25$, $h_{N(E)}^{(1)} = \\mathrm{MEAN}(0.4, 0.1, 0.2) \\approx 0.23$ 이에요.","내 값과 이어 붙이면 두 칸짜리 벡터가 나와요."],"answer":"$h_A^{(1)} = [0.4, 0.2]$, $h_B^{(1)} = [0.1, 0.2]$, $h_C^{(1)} = [0.3, 0.25]$, $h_D^{(1)} = [0.2, 0.25]$, $h_E^{(1)} = [0.1, 0.23]$ 이에요."},{"kind":"exam","src":"2025 가을 중간 4번 (10점) (c)","q":"Compute the graph embedding h_G by mean global pooling.","qko":"평균 전역 풀링으로 그래프 임베딩 $h_G$ 를 구하세요.","solve":["전역 풀링은 다섯 노드의 벡터를 칸별로 평균 내는 거예요.","첫째 칸은 $(0.4+0.1+0.3+0.2+0.1)/5 = 1.1/5 = 0.22$ 예요.","둘째 칸은 $(0.2+0.2+0.25+0.25+0.2333)/5$ 예요.","더하면 $1.1333$ 이고 5 로 나누면 $\\approx 0.2267$ 이에요."],"answer":"$h_G \\approx [0.22, 0.23]$ 이에요. 반올림은 소수 둘째 자리예요."},{"kind":"warn","head":"공식 해설지에 오타가 있어요","items":["해설지의 $h_{N(E)}^{(1)}$ 줄이 $\\mathrm{MEAN}(0.4, 0.2) = 0.7$ 로 적혀 있어요.","E 의 이웃은 A, B, D 세 개라 $(0.4+0.1+0.2)/3 \\approx 0.2333$ 이 맞아요.","시험장에서는 이웃 명단을 직접 세어 확인하세요. **차수(Degree)**를 잘못 세면 다 틀려요."]},{"kind":"english","head":"한 문장 더","en":"GraphSAGE concatenates the self embedding with the aggregated neighbor embedding instead of averaging them together.","ko":"GraphSAGE 는 자기 임베딩과 집계된 이웃 임베딩을 같이 평균 내는 대신 이어 붙인다.","tip":"instead of averaging them together 가 GCN 과의 대비를 만들어요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.2817,0.0757],"c":[0,0.0019,0.3098,0.1077],"r":5.1138,"img":"img/L4/walk/p024_h.jpg"},"parts":[{"b":[0.04,0.15,0.2,0.048],"c":[0.028,0.119,0.224,0.11],"r":3.6202,"img":"img/L4/walk/p024_12_01.jpg","say":"위 불릿은 '단순한 이웃 집계', 즉 2주차에 배운 **GCN** 층이에요."},{"b":[0.04,0.515,0.16,0.05],"c":[0.02,0.485,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p024_12_02.jpg","say":"아래 불릿이 **그래프세이지(GraphSAGE)**예요. 같은 자리가 어떻게 바뀌었는지 봐요."}]}},{"p":25,"title":"집계 함수 세 가지: 평균, 풀링, LSTM","terms":["GraphSAGE","Aggregator","Pooling","LSTM","Permutation Invariance","Concatenation"],"pass1":[{"kind":"say","lines":["논문이 제안한 **집계기(Aggregator)** 후보는 세 가지예요.","평균, **풀링(Pooling)**, 그리고 **LSTM** 이에요.","요즘은 **LSTM** 집계기를 쓰지 않아요. 순서에 답이 흔들리거든요."]},{"kind":"analogy","head":"반 친구들의 의견을 모으는 세 가지 방법","scene":"민수가 반 친구 세 명의 의견을 한 줄로 요약해야 해요. 첫째는 세 의견의 평균을 내는 거예요. 둘째는 의견마다 다듬은 뒤 가장 센 말만 고르는 거예요. 셋째는 세 명을 한 줄로 세워 차례로 듣는 거예요. 그런데 셋째는 순서가 바뀌면 요약도 바뀌어요.","map":[["평균 내기","평균 집계기"],["다듬고 센 말만 고르기","**풀링(Pooling)** 집계기"],["줄 세워 차례로 듣기","**LSTM** 집계기"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.06,"y":0.135,"w":0.35,"h":0.05,"say":"맨 위 물음: '이웃에서 정보를 어떻게 집계할까?'","c":[0.0425,0.105,0.385,0.11],"r":6.2222,"img":"img/L4/walk/p025_20_01.jpg"},{"x":0.373,"y":0.422,"w":0.233,"h":0.056,"say":"주황 상자가 AGG 전체를 감싸며 '일반화된 집계'라고 알려 줘요.","c":[0.361,0.395,0.257,0.11],"r":4.1535,"img":"img/L4/walk/p025_20_02.jpg"},{"x":0.4375,"y":0.198,"w":0.306,"h":0.068,"say":"파란 설명은 '이웃 임베딩과 자기 임베딩을 **이어 붙이기(Concatenation)**'예요.","c":[0.4222,0.177,0.3366,0.11],"r":5.44,"img":"img/L4/walk/p025_20_03.jpg"},{"x":0.096,"y":0.756,"w":0.231,"h":0.059,"say":"'원소별 평균/최댓값' 상자가 감마 기호를 가리켜요.","c":[0.084,0.7305,0.255,0.11],"r":4.1212,"img":"img/L4/walk/p025_20_04.jpg"},{"x":0.3125,"y":0.907,"w":0.361,"h":0.055,"say":"맨 아래가 **LSTM** 식이에요. 파이 기호가 섞은 순서예요.","c":[0.2944,0.8795,0.3971,0.11],"r":6.4178,"img":"img/L4/walk/p025_20_05.jpg"}]},{"kind":"formula","head":"풀링 집계기","tex":"\\mathrm{AGG} = \\gamma\\left(\\{\\mathbf{Q}\\mathbf{h}_u^{k-1}, \\forall u \\in N(v)\\}\\right)","parts":[{"sym":"\\mathbf{Q}","say":"큐. 이웃 벡터를 먼저 바꿔 주는 학습 가능한 행렬이에요."},{"sym":"\\gamma","say":"감마. 대칭 벡터 함수, 즉 칸별 평균이나 칸별 최댓값이에요."},{"sym":"\\mathbf{h}_u^{k-1}","say":"이웃 $u$ 의 한 층 전 임베딩이에요."},{"sym":"\\forall u \\in N(v)","say":"뽑힌 이웃 전부에 대해라는 뜻이에요."}],"whole":"쪽지를 한 장씩 $\\mathbf{Q}$ 로 가공한 다음, 칸마다 평균이나 최댓값을 뽑아요. 3주차의 최대 풀링이 $\\gamma = \\max$ 인 경우예요."},{"kind":"formula","head":"LSTM 집계기","tex":"\\mathrm{AGG} = \\mathrm{LSTM}\\left(\\left[\\mathbf{h}_u^{k-1}, \\forall u \\in \\pi(N(v))\\right]\\right)","parts":[{"sym":"\\pi(N(v))","say":"파이 오브 엔 브이. 이웃 명단을 무작위로 섞은 순서예요."},{"sym":"[\\ \\cdot\\ ]","say":"대괄호. 여기서는 순서가 있는 줄 세우기를 뜻해요."},{"sym":"\\mathrm{LSTM}","say":"순서가 있는 입력을 앞에서 뒤로 읽는 순환 신경망이에요."}],"whole":"이웃을 한 줄로 세워 앞에서부터 읽어요. 줄 세우는 순서가 달라지면 결과도 달라진다는 게 문제예요."},{"kind":"steps","head":"같은 봉투를 세 방법으로 요약해 봐요","steps":["봉투 P 는 $(1,0)$ 과 $(0,1)$ 두 장이에요.","봉투 Q 는 거기에 $(1,1)$ 을 더한 세 장이에요.","평균: P 는 $(0.5, 0.5)$, Q 는 $(0.67, 0.67)$ 이라 두 봉투를 구별해요.","최댓값 **풀링(Pooling)**: P 는 $(1, 1)$, Q 도 $(1, 1)$ 이라 구별을 못 해요.","쪽지 $(1,1)$ 이 더 들어왔는데 이미 1 이 있어서 아무 변화가 없었어요."],"answer":"최댓값은 평균보다도 더 많이 뭉개요. 3주차 결론인 합, 평균, 최댓값 순서가 여기 그대로예요.","given":"**풀링(Pooling)**의 $\\mathbf{Q}$ 는 아무것도 안 바꾸는 단위행렬이라고 둘게요."},{"kind":"steps","head":"**LSTM** 이 왜 문제인지 숫자로","steps":["**LSTM** 을 '직전 값의 절반에 지금 값을 더한다'로 단순화해 볼게요.","$1 \\to 2 \\to 3$ 순서: $1$, $0.5+2=2.5$, $1.25+3=4.25$ 라 답은 $4.25$ 예요.","$3 \\to 2 \\to 1$ 순서: $3$, $1.5+2=3.5$, $1.75+1=2.75$ 라 답은 $2.75$ 예요.","$2 \\to 1 \\to 3$ 순서: $2$, $1+1=2$, $1+3=4$ 라 답은 $4$ 예요.","같은 봉투인데 답이 세 개나 나왔어요."],"answer":"이게 **순열 불변성(Permutation Invariance)**이 없다는 말의 뜻이에요. 평균과 최댓값은 어떤 순서든 같은 답을 내요.","given":"이웃 세 명의 값이 1, 2, 3 이라고 해요."},{"kind":"figure","head":"순서를 뒤집어 보기","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"70\" y=\"30\" font-size=\"15\" text-anchor=\"middle\">이웃 값 1, 2, 3<\/text>\n<circle class=\"n\" cx=\"30\" cy=\"62\" r=\"17\"/>\n<text class=\"tl\" x=\"30\" y=\"68\" font-size=\"15\" text-anchor=\"middle\">1<\/text>\n<circle class=\"n3\" cx=\"70\" cy=\"62\" r=\"17\"/>\n<text class=\"tl\" x=\"70\" y=\"68\" font-size=\"15\" text-anchor=\"middle\">2<\/text>\n<circle class=\"n4\" cx=\"110\" cy=\"62\" r=\"17\"/>\n<text class=\"tl\" x=\"110\" y=\"68\" font-size=\"15\" text-anchor=\"middle\">3<\/text>\n<text class=\"tm\" x=\"70\" y=\"112\" font-size=\"14\" text-anchor=\"middle\">순서만 뒤집어요<\/text>\n<circle class=\"n4\" cx=\"30\" cy=\"150\" r=\"17\"/>\n<text class=\"tl\" x=\"30\" y=\"156\" font-size=\"15\" text-anchor=\"middle\">3<\/text>\n<circle class=\"n3\" cx=\"70\" cy=\"150\" r=\"17\"/>\n<text class=\"tl\" x=\"70\" y=\"156\" font-size=\"15\" text-anchor=\"middle\">2<\/text>\n<circle class=\"n\" cx=\"110\" cy=\"150\" r=\"17\"/>\n<text class=\"tl\" x=\"110\" y=\"156\" font-size=\"15\" text-anchor=\"middle\">1<\/text>\n<line class=\"e2 b1\" x1=\"140\" y1=\"62\" x2=\"184\" y2=\"62\"/>\n<line class=\"e2 b1\" x1=\"140\" y1=\"150\" x2=\"184\" y2=\"150\"/>\n<rect class=\"box b1\" x=\"190\" y=\"44\" width=\"104\" height=\"36\" rx=\"8\"/>\n<text class=\"t b1\" x=\"242\" y=\"68\" font-size=\"15\" text-anchor=\"middle\">평균 = 2<\/text>\n<rect class=\"box b1\" x=\"190\" y=\"132\" width=\"104\" height=\"36\" rx=\"8\"/>\n<text class=\"t b1\" x=\"242\" y=\"156\" font-size=\"15\" text-anchor=\"middle\">평균 = 2<\/text>\n<text class=\"tb b1\" x=\"242\" y=\"196\" font-size=\"15\" text-anchor=\"middle\">같아요<\/text>\n<line class=\"e2 b2\" x1=\"300\" y1=\"62\" x2=\"326\" y2=\"62\"/>\n<line class=\"e2 b2\" x1=\"300\" y1=\"150\" x2=\"326\" y2=\"150\"/>\n<rect class=\"box2 b2\" x=\"330\" y=\"44\" width=\"130\" height=\"36\" rx=\"8\"/>\n<text class=\"t b2\" x=\"395\" y=\"68\" font-size=\"15\" text-anchor=\"middle\">LSTM = 4.25<\/text>\n<rect class=\"box2 b2\" x=\"330\" y=\"132\" width=\"130\" height=\"36\" rx=\"8\"/>\n<text class=\"t b2\" x=\"395\" y=\"156\" font-size=\"15\" text-anchor=\"middle\">LSTM = 2.75<\/text>\n<text class=\"tb b2\" x=\"395\" y=\"196\" font-size=\"15\" text-anchor=\"middle\">달라요<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"232\" font-size=\"16\" text-anchor=\"middle\">그래프에는 노드 순서가 없어요<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"256\" font-size=\"14\" text-anchor=\"middle\">순서에 따라 답이 바뀌면 안 되는 이유예요<\/text>\n<\/svg>","caption":"그래프에는 노드 번호에 자연스러운 순서가 없어요. 그래서 **순열 불변성(Permutation Invariance)**이 꼭 필요해요.","builds":3},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 **LSTM** 집계기를 이렇게 정리했어요.","**그래프세이지(GraphSAGE)**가 RNN 계열을 집계기로 쓴 거의 마지막 논문이래요.","지금 안 쓰는 이유는 **순열 불변성(Permutation Invariance)**이 없기 때문이고요.","무작위로 섞어 줘도 순열 불변이 되지는 않아서 요즘은 쓰이지 않는다고요."]},{"kind":"mining","src":"마이닝 3강 Centrality Measures","lines":["평균 집계기는 이웃 값을 **차수(Degree)**로 나누는 것과 같아요.","차수 중심성에서 $\\sum_j A_{ij}$ 로 이웃 수를 세던 것과 같은 계산이에요.","다만 중심성은 숫자 하나를, **집계기(Aggregator)**는 벡터를 만들어요."]},{"kind":"warn","head":"자주 헷갈리는 세 가지","items":["평균 식에 $\\sum$ 기호가 있지만 $|N(v)|$ 로 나누니 합이 아니라 평균이에요.","**풀링(Pooling)**의 $\\mathbf{Q}$ 는 학습되는 행렬이라 파라미터가 늘어요. 평균 집계기에는 그런 행렬이 없어요.","**LSTM** 에 무작위 섞기를 넣어도 순열 불변이 되지는 않아요. 덜 치우친다는 정도예요."]}],"pass3":[{"kind":"exam","src":"2024 가을 기말 2번 (10점) (a)","q":"Compute the output representation of each node at k=1, where AGGREGATE is MAX.","qko":"집계기가 MAX 일 때 $k=1$ 에서 각 노드의 출력 표현을 계산하세요.","solve":["식은 2025 가을 중간 4번과 똑같고 AGGREGATE 만 MEAN 에서 MAX 로 바뀌었어요.","노드마다 이웃 목록을 먼저 적고, 그 값들 중 가장 큰 것을 고르면 돼요.","MAX 는 나누기가 없어서 오히려 계산이 쉬워요.","그다음 내 값과 이어 붙이면 두 칸짜리 벡터가 나와요.","둘째 줄은 MEAN 일 때와 완전히 같아요."],"answer":"노드마다 [내 값, 이웃 중 최댓값] 형태의 2차원 벡터가 답이에요."},{"kind":"english","head":"서술형에 쓸 한 줄","en":"The LSTM aggregator is not permutation invariant, so the same neighborhood can produce different embeddings depending on the ordering.","ko":"LSTM 집계기는 순열 불변이 아니라서, 같은 이웃이라도 순서에 따라 다른 임베딩이 나올 수 있다.","tip":"permutation invariant 라는 표기를 그대로 외워 두세요."},{"kind":"check","q":"**풀링(Pooling)** 집계기에서 감마 자리에 들어가는 것은 무엇인가요?","choices":["칸별 평균이나 칸별 최댓값","LSTM","인접행렬","ReLU"],"a":0,"why":"감마는 대칭 벡터 함수예요. 논문이 주로 쓴 것은 칸별 최댓값 쪽이에요."},{"kind":"warn","head":"계산 문제에서 조심할 점","items":["계산 문제는 MEAN 이 나올 수도 MAX 가 나올 수도 있어요. 둘 다 손에 익혀 두세요.","문제에 주어진 식을 그대로 따르세요. 정규화 줄이 없으면 하지 않아요.","MAX 는 이웃 값 중 최댓값 하나만 고르는 것이지 내 값까지 포함하는 게 아니에요."]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.6536,0.4625],"c":[0,0,0.7189,0.5087],"r":2.5124,"img":"img/L4/walk/p025_h.jpg"},"parts":[{"b":[0.1,0.5,0.5,0.12],"c":[0.075,0.484,0.55,0.152],"r":6.4327,"img":"img/L4/walk/p025_12_01.jpg","say":"첫째 평균. 이웃을 다 더하고 이웃 수로 나눠요."},{"b":[0.1,0.655,0.55,0.045],"c":[0.0725,0.6164,0.605,0.1222],"r":8.8016,"img":"img/L4/walk/p025_12_02.jpg","say":"둘째 **풀링(Pooling)**. 이웃 벡터를 변환한 뒤 대칭 함수를 씌워요."},{"b":[0.1,0.845,0.35,0.045],"c":[0.0825,0.8125,0.385,0.11],"r":6.2222,"img":"img/L4/walk/p025_12_03.jpg","say":"셋째 **LSTM**. 이웃을 무작위로 섞어 한 줄로 넣어요."}]}},{"p":26,"title":"알고리즘 아홉 줄을 한 줄씩","terms":["GraphSAGE","Aggregator","Concatenation","Normalization","Neighbor Sampling","Mini-batch"],"pass1":[{"kind":"say","lines":["**그래프세이지(GraphSAGE)** 순전파는 아홉 줄짜리 의사코드예요.","바깥 반복은 층, 안쪽 반복은 노드예요.","핵심은 4번 줄 집계, 5번 줄 이어 붙여 변환, 7번 줄 길이 맞추기예요."]},{"kind":"analogy","head":"학급 일지에 적힌 하루 순서","scene":"선생님이 칠판에 하루 순서를 적어 두었어요. 1교시부터 4교시까지 같은 순서를 반복해요. 교시마다 아이들을 번호순으로 불러, 짝꿍 쪽지를 모아 요약하고 자기 쪽지와 나란히 붙이게 해요. 한 교시가 끝나면 모두의 쪽지 길이를 똑같이 맞춰요.","map":[["교시 반복","층 반복, 2번 줄"],["번호순으로 한 명씩","노드 반복, 3번 줄"],["쪽지 길이 맞추기","**정규화(Normalization)**, 7번 줄"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.128,"y":0.228,"w":0.66,"h":0.11,"say":"Input 줄. 그래프, 입력 특징, 깊이 K, 층마다의 가중치와 집계기, 이웃 함수가 들어가요.","c":[0.095,0.2097,0.726,0.1467],"r":8.798,"img":"img/L4/walk/p026_20_01.jpg"},{"x":0.128,"y":0.348,"w":0.42,"h":0.033,"say":"Output 줄. 모든 노드의 벡터 표현 z 가 나와요.","c":[0.107,0.3095,0.462,0.11],"r":7.4667,"img":"img/L4/walk/p026_20_02.jpg"},{"x":0.585,"y":0.367,"w":0.251,"h":0.158,"say":"주황 상자: '일반화된 집계기. 평균(GCN), **풀링(Pooling)**, **LSTM**'.","c":[0.5724,0.351,0.2761,0.19],"r":2.5834,"img":"img/L4/walk/p026_20_03.jpg"},{"x":0.401,"y":0.733,"w":0.248,"h":0.044,"say":"초록 상자: 'SUM 대신 이어 붙이기를 쓴다'. 5번 줄을 가리켜요.","c":[0.3886,0.7,0.2728,0.11],"r":4.4089,"img":"img/L4/walk/p026_20_04.jpg"},{"x":0.19,"y":0.685,"w":0.26,"h":0.04,"say":"7번 줄. 벡터를 자기 길이로 나눠 길이를 1 로 맞춰요.","c":[0.177,0.65,0.286,0.11],"r":4.6222,"img":"img/L4/walk/p026_20_05.jpg"},{"x":0.11,"y":0.775,"w":0.22,"h":0.04,"say":"9번 줄. 마지막 층 결과가 최종 임베딩 z 예요.","c":[0.098,0.74,0.244,0.11],"r":3.9434,"img":"img/L4/walk/p026_20_06.jpg"}]},{"kind":"compare","head":"아홉 줄을 표로","cols":["줄","하는 일"],"rows":[["1","0층 임베딩은 원래 입력 특징 그대로"],["2","층을 1번부터 $K$ 번까지 반복"],["3","그 층 안에서 노드를 하나씩"],["4","이웃 봉투를 **집계기(Aggregator)**로 요약"],["5","내 것과 **이어 붙이기(Concatenation)** 후 가중치와 비선형"],["7","층이 끝나면 벡터 길이를 1 로 맞추는 **정규화(Normalization)**"]]},{"kind":"formula","head":"7번 줄의 정규화","tex":"\\mathbf{h}_v^k \\leftarrow \\mathbf{h}_v^k / \\left\\|\\mathbf{h}_v^k\\right\\|_2","parts":[{"sym":"\\left\\|\\cdot\\right\\|_2","say":"L2 노름. 벡터의 길이예요."},{"sym":"\\leftarrow","say":"왼쪽 화살표. 오른쪽 값을 왼쪽에 새로 넣는다는 표시예요."},{"sym":"\\mathbf{h}_v^k","say":"노드 $v$ 의 $k$ 층 임베딩이에요."}],"whole":"두 칸짜리 벡터 $(a, b)$ 의 길이는 $\\sqrt{a^2 + b^2}$ 예요. 벡터를 자기 길이로 나누면 길이가 정확히 1 이 돼요."},{"kind":"steps","head":"노드 A 를 알고리즘대로 따라가요","steps":["1번 줄. $h_A^0 = 0.4$, $h_C^0 = 0.3$, $h_D^0 = 0.2$, $h_E^0 = 0.1$ 이에요.","4번 줄. A 의 이웃은 C, D, E 라 $\\mathrm{MEAN}(0.3, 0.2, 0.1) = 0.2$ 예요.","5번 줄. $\\mathrm{CONCAT}(0.4, 0.2) = [0.4, 0.2]$ 이고 ReLU 후에도 같아요.","7번 줄. 길이는 $\\sqrt{0.4^2 + 0.2^2} = \\sqrt{0.20} \\approx 0.4472$ 예요.","각 칸을 나누면 $0.4/0.4472 \\approx 0.894$, $0.2/0.4472 \\approx 0.447$ 이에요.","확인하면 $0.894^2 + 0.447^2 \\approx 0.999$ 로 거의 1 이에요."],"answer":"**정규화(Normalization)**는 방향은 그대로 두고 길이만 1 로 바꿔요. 2 대 1 비율이 그대로 남았죠.","given":"p.24 의 그래프, MEAN 집계, 가중치는 아무것도 안 바꾸는 단위행렬이라고 해요."},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 여기서 기억할 것이 딱 두 가지라고 못 박았어요.","첫째, 1홉 이웃 전부가 아니라 개수를 제한한다는 점이에요. 보통 2 나 3 이고요.","그렇게 해야 **미니 배치(Mini-batch)**가 가능해진다고요.","둘째는 concat 후 변환인데, 이건 마이너한 차이이고 첫째가 가장 중요하다고요."]},{"kind":"mining","src":"마이닝 10강 Random Walk GRL","lines":["7번 줄의 길이 맞추기는 마이닝에서도 자주 나왔어요.","DeepWalk 나 node2vec 에서 두 임베딩이 비슷한지 코사인 유사도로 쟀죠.","코사인 유사도는 길이를 무시하고 방향만 봐요.","미리 길이를 1 로 맞춰 두면 내적 한 번으로 계산돼요."]}],"pass3":[{"kind":"warn","head":"이 쪽 슬라이드에 오타가 있어요","items":["초록 상자의 영어 원문은 'Use Concentration instead of SUM' 인데 오타예요.","Concentration(집중)이 아니라 Concatenation(이어 붙이기)이 맞아요.","한국어 슬라이드는 'SUM 대신 이어 붙이기를 쓴다'로 제대로 적혀 있어요."]},{"kind":"warn","head":"읽을 때 조심할 곳","items":["4번 줄의 이웃 함수는 전체 이웃이 아니라 **이웃 샘플링(Neighbor Sampling)** 결과예요.","7번 줄은 노드 반복 바깥에 있어요. 한 층의 모든 노드를 계산한 뒤 한꺼번에 정규화해요.","2번 줄의 $k$ 는 층 번호이고, 교수님이 말한 'k 개로 제한'의 $k$ 는 이웃 개수예요. 다른 $k$ 예요."]},{"kind":"english","head":"서술형에 쓸 한 줄","en":"GraphSAGE keeps a separate weight matrix and aggregator for every layer, and normalizes the result to unit length.","ko":"GraphSAGE 는 층마다 가중치 행렬과 집계기를 따로 두고, 결과를 길이 1 로 정규화한다.","tip":"unit length 라는 표현이 정규화를 가리켜요."},{"kind":"check","q":"7번 줄의 **정규화(Normalization)**가 하는 일은 무엇인가요?","choices":["벡터 방향을 바꾼다","벡터 길이를 1 로 맞춘다","이웃 수를 센다","음수를 0 으로 만든다"],"a":1,"why":"방향은 그대로 두고 길이만 1 로 바꿔요. 층을 지날수록 값이 커지거나 작아지는 걸 막아 줘요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.2891,0.0757],"c":[0,0.0019,0.318,0.1077],"r":5.2491,"img":"img/L4/walk/p026_h.jpg"},"parts":[{"b":[0.128,0.179,0.7,0.033],"c":[0.093,0.1177,0.77,0.1556],"r":8.7975,"img":"img/L4/walk/p026_12_01.jpg","say":"제목은 'Algorithm 1: GraphSAGE 임베딩 생성 알고리즘' 이에요."},{"b":[0.266,0.523,0.306,0.042],"c":[0.2507,0.489,0.3366,0.11],"r":5.44,"img":"img/L4/walk/p026_12_02.jpg","say":"4번 줄. 주황 상자가 **집계기(Aggregator)**를 가리켜요."},{"b":[0.316,0.589,0.198,0.044],"c":[0.304,0.556,0.222,0.11],"r":3.5879,"img":"img/L4/walk/p026_12_03.jpg","say":"5번 줄. 초록 상자가 CONCAT 을 가리켜요."}]}},{"p":27,"title":"이웃은 모두 똑같이 중요해요","terms":["GraphSAGE","Degree","Neighbor Sampling","Aggregator","Node-wise Sampling"],"pass1":[{"kind":"say","lines":["**그래프세이지(GraphSAGE)**에서 이웃의 중요도는 학습하지 않아요.","그래프 모양만 보고 이웃 수분의 1 로 바로 정해져요.","즉 뽑힌 이웃은 전부 똑같이 중요해요."]},{"kind":"analogy","head":"반 회의에서 발언 시간을 나누는 법","scene":"민수네 모둠이 회의를 해요. 모둠원이 세 명이면 한 사람당 3분의 1씩 똑같이 시간을 나눠요. 누가 더 말을 잘하는지 따지지 않고 그냥 인원수로 나누는 거예요. 편하고 빠르지만, 중요한 말을 할 사람에게 시간을 더 줄 수는 없죠.","map":[["인원수로 똑같이 나누기","무게를 이웃 수분의 1 로 고정"],["누가 중요한지 안 따짐","무게를 학습하지 않음"],["중요한 사람에게 더 주기","나중에 배울 어텐션 방식"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.06,"y":0.145,"w":0.3,"h":0.045,"say":"큰 불릿 제목: '**그래프세이지(GraphSAGE)**의 가중치 계수'.","c":[0.045,0.1125,0.33,0.11],"r":5.3333,"img":"img/L4/walk/p027_20_01.jpg"},{"x":0.486,"y":0.356,"w":0.09,"h":0.03,"say":"주황 글씨 '가중치 계수'. 화살표가 식 안을 가리켜요.","c":[0.431,0.316,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p027_20_02.jpg"},{"x":0.372,"y":0.432,"w":0.061,"h":0.099,"say":"주황 상자가 이웃 값을 이웃 수로 나누는 부분을 감싸요.","c":[0.3025,0.416,0.2,0.131],"r":2.7142,"img":"img/L4/walk/p027_20_03.jpg"},{"x":0.618,"y":0.444,"w":0.125,"h":0.086,"say":"오른쪽에 그 값이 따로 적혀 있어요. 이웃 수분의 1 이에요.","c":[0.5805,0.428,0.2,0.118],"r":3.0132,"img":"img/L4/walk/p027_20_04.jpg"},{"x":0.229,"y":0.593,"w":0.156,"h":0.309,"say":"아래 그림 1. **이웃 샘플링(Neighbor Sampling)**. 점선 원 안쪽이 1홉, 바깥이 2홉이에요.","c":[0.207,0.577,0.2,0.341],"r":1.0427,"img":"img/L4/walk/p027_20_05.jpg"},{"x":0.399,"y":0.593,"w":0.174,"h":0.309,"say":"그림 2. 이웃에서 특징 정보를 집계해요. 층마다 집계기 색이 달라요.","c":[0.386,0.577,0.2,0.341],"r":1.0427,"img":"img/L4/walk/p027_20_06.jpg"},{"x":0.587,"y":0.593,"w":0.184,"h":0.309,"say":"그림 3. 집계한 정보로 그래프 맥락과 레이블을 예측해요.","c":[0.575,0.577,0.208,0.341],"r":1.0844,"img":"img/L4/walk/p027_20_07.jpg"}]},{"kind":"formula","head":"가중치 계수","tex":"\\boldsymbol{\\alpha}_{vu} = \\frac{1}{|N(v)|}","parts":[{"sym":"\\boldsymbol{\\alpha}_{vu}","say":"알파 브이 유. $v$ 가 이웃 $u$ 의 말을 들을 때 곱하는 무게예요."},{"sym":"|N(v)|","say":"엔 브이의 크기. 뽑힌 이웃의 수, 즉 **차수(Degree)**예요."},{"sym":"\\frac{1}{|N(v)|}","say":"이웃이 $m$ 명이면 한 명당 $m$ 분의 1 씩이에요."}],"whole":"무게를 다 더하면 1 이에요. 그러니 결국 평균이에요. 이 값은 학습되지 않고 그래프 모양에서 바로 정해져요."},{"kind":"steps","head":"무게를 다르게 주면 답이 달라질까요","steps":["**그래프세이지(GraphSAGE)** 방식은 셋 다 3분의 1 이에요.","기여는 $0.3/3 = 0.1$, $0.2/3 \\approx 0.0667$, $0.1/3 \\approx 0.0333$ 이에요.","다 더하면 $0.2$ 예요.","만약 **차수(Degree)**에 비례해 무게를 준다면 C 는 2, D 는 2, E 는 3 이에요.","무게는 $2/7$, $2/7$, $3/7$ 이 되고 기여는 $0.0857$, $0.0571$, $0.0429$ 예요.","다 더하면 $\\approx 0.186$ 이에요."],"answer":"$0.2$ 가 $0.186$ 으로 달라졌어요. 무게를 어떻게 주느냐가 답을 바꿔요.","given":"A 의 이웃은 C, D, E 이고 값은 0.3, 0.2, 0.1 이에요."},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 **노드 단위 샘플링(Node-wise Sampling)**에 대해 이렇게 말했어요.","샘플링의 방향을 조정해 줄 수는 있대요.","**차수(Degree)**나 중심성으로 어떤 이웃이 더 중요한지 판별해서요.","그런데 부담이 커지니 보통은 **그래프세이지(GraphSAGE)** 정도의 랜덤이 선호된다고요."]},{"kind":"mining","src":"마이닝 3강 Centrality","lines":["중심성은 '이 노드가 얼마나 중요한가'를 재는 점수 모음이에요.","차수 중심성, 근접 중심성, 매개 중심성, 고유벡터 중심성 네 가지를 배웠죠.","이 점수를 샘플링 확률로 쓸 수 있다는 것이 교수님 말이에요.","다만 매개 중심성은 최단 경로를 다 구해야 해서 큰 그래프에서 비싸요."]},{"kind":"warn","head":"표기와 뜻에서 조심할 곳","items":["슬라이드 불릿과 오른쪽 식의 아래첨자 순서가 서로 달라요. 무방향 그래프라 같은 것으로 읽으면 돼요.","이웃 수는 **이웃 샘플링(Neighbor Sampling)** 뒤의 수예요. 원래 1000 명이어도 10 명만 뽑았으면 10분의 1 이에요.","'모든 이웃이 똑같이 중요하다'는 설계 가정이지 사실이 아니에요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"In GraphSAGE the weighting factor is fixed to one over the neighborhood size, so all sampled neighbors contribute equally.","ko":"GraphSAGE 에서 가중치 계수는 이웃 수분의 1 로 고정되므로 뽑힌 이웃은 모두 똑같이 기여한다.","tip":"and no attention weights are learned 를 덧붙이면 더 좋아요."},{"kind":"check","q":"**그래프세이지(GraphSAGE)**의 가중치 계수는 어떻게 정해지나요?","choices":["학습으로 배운다","그래프 구조에서 바로 정해진다","사람이 매번 정한다","층마다 무작위로 정한다"],"a":1,"why":"구조에서 명시적으로 정해져요. 학습되는 어텐션 가중치는 없어요."},{"kind":"warn","head":"장단점을 쓰라고 하면","items":["장점은 계산이 싸고 추가 파라미터가 없다는 것이에요.","단점은 정말 중요한 이웃과 잡음을 주는 이웃을 구별하지 못한다는 것이에요.","이 단점이 바로 다음 쪽에서 볼 한계로 이어져요."]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.3349,0.1787],"c":[0,0.0019,0.3684,0.2107],"r":3.1084,"img":"img/L4/walk/p027_h.jpg"},"parts":[{"b":[0.075,0.215,0.55,0.045],"c":[0.0475,0.1764,0.605,0.1222],"r":8.8016,"img":"img/L4/walk/p027_12_01.jpg","say":"첫 줄: '중요도는 그래프의 구조적 성질로 명시적으로 정해진다'."},{"b":[0.075,0.28,0.5,0.045],"c":[0.05,0.2469,0.55,0.1111],"r":8.8009,"img":"img/L4/walk/p027_12_02.jpg","say":"둘째 줄: '모든 이웃은 노드 v 에게 똑같이 중요하다'."}]}},{"p":28,"title":"GraphSAGE 정리: 기여 셋과 한계 둘","terms":["GraphSAGE","Inductive Learning","Transductive Learning","Mini-batch","Neighbor Sampling","Aggregator","Robustness","Scalability","Variance"],"pass1":[{"kind":"say","lines":["기여는 셋이에요. **귀납적 학습(Inductive Learning)**을 처음 다뤘고,","**집계기(Aggregator)**를 일반화했고, **미니 배치(Mini-batch)**로 빠르게 했어요.","한계는 둘이에요. 증가율이 여전히 곱하기이고, 품질 보장이 없어요."]},{"kind":"analogy","head":"처음 보는 문제도 푸는 공부법","scene":"민수가 시험 공부를 두 가지로 해 봤어요. 하나는 기출 문제의 답만 통째로 외우는 방법이에요. 똑같은 문제는 맞히지만 처음 보는 문제는 손도 못 대요. 다른 하나는 푸는 규칙을 익히는 방법이에요. 규칙을 쓰면 처음 보는 문제도 풀 수 있어요.","map":[["답만 외우기","**변환적 학습(Transductive Learning)**"],["규칙을 익히기","**귀납적 학습(Inductive Learning)**"],["처음 보는 문제","학습 때 없던 새 노드"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.09,"y":0.3,"w":0.38,"h":0.04,"say":"기여 1: '큰 그래프에서 **귀납적 학습(Inductive Learning)** 표현 학습을 처음으로 다뤘다'.","c":[0.071,0.265,0.418,0.11],"r":6.7556,"img":"img/L4/walk/p028_20_01.jpg"},{"x":0.09,"y":0.395,"w":0.38,"h":0.04,"say":"기여 2: '일반화된 집계기. 평균, **LSTM**, **풀링(Pooling)**'.","c":[0.071,0.36,0.418,0.11],"r":6.7556,"img":"img/L4/walk/p028_20_02.jpg"},{"x":0.09,"y":0.455,"w":0.38,"h":0.04,"say":"기여 3: '**미니 배치(Mini-batch)** 학습과 고정 크기 이웃 샘플링이 학습을 빠르게 한다'.","c":[0.071,0.42,0.418,0.11],"r":6.7556,"img":"img/L4/walk/p028_20_03.jpg"},{"x":0.545,"y":0.3,"w":0.38,"h":0.06,"say":"한계 1: '고정 크기 샘플링도 이웃 확장을 완전히 막지는 못한다. 증가율은 여전히 $S^L$'.","c":[0.526,0.275,0.418,0.11],"r":6.7556,"img":"img/L4/walk/p028_20_04.jpg"},{"x":0.545,"y":0.39,"w":0.38,"h":0.06,"say":"한계 2: '샘플링 품질에 이론적 보장이 없다. 편향과 **분산(Variance)**을 분석하지 않았다'.","c":[0.526,0.365,0.418,0.11],"r":6.7556,"img":"img/L4/walk/p028_20_05.jpg"}]},{"kind":"points","head":"**귀납적 학습(Inductive Learning)**이 무엇인가요","items":["학습할 때 본 적 없는 노드에도 모델을 그대로 쓸 수 있는 학습이에요.","반대말이 **변환적 학습(Transductive Learning)**이에요.","**변환적 학습(Transductive Learning)**은 학습 때 본 그 노드에만 답을 낼 수 있어요.","그래프 전체를 안 보니까 노드가 늘어도 모델 동작이 그대로예요."]},{"kind":"formula","head":"한계 첫 줄의 증가율","tex":"S^L","parts":[{"sym":"S","say":"에스. 한 층에서 노드 하나당 뽑는 이웃 수예요."},{"sym":"L","say":"엘. 층 수, 즉 몇 홉까지 보는지예요."},{"sym":"S^L","say":"에스의 엘 제곱. 대상 노드 하나가 결국 끌어오는 노드 수예요."}],"whole":"1층에서 $S$ 명을 뽑고, 그 $S$ 명이 각각 또 $S$ 명을 뽑으니 2층이면 $S \\times S$ 예요. 곱하기가 층마다 쌓여요."},{"kind":"steps","head":"층을 늘리면 얼마나 늘어날까요","steps":["$S = 10$ 으로 두고 대상 노드 한 개 기준으로 세어 봐요.","1층이면 10 개예요.","2층이면 $10 \\times 10 = 100$ 개예요.","3층이면 1,000 개, 4층이면 10,000 개예요.","5층이면 100,000 개예요."],"answer":"고정 크기로 뽑아도 층마다 곱해져요. 폭발을 없앤 게 아니라 예측 가능하게 만든 것이에요.","given":"층마다 같은 개수 $S$ 를 뽑는다고 해요."},{"kind":"figure","head":"층마다 곱해지는 증가율","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"240\" y=\"26\" font-size=\"16\" text-anchor=\"middle\">S = 10 일 때 대상 노드 하나가 끌어오는 수<\/text>\n<line class=\"e\" x1=\"50\" y1=\"200\" x2=\"440\" y2=\"200\"/>\n<rect class=\"box\" x=\"70\" y=\"194\" width=\"42\" height=\"6\" rx=\"2\"/>\n<rect class=\"box b1\" x=\"160\" y=\"180\" width=\"42\" height=\"20\" rx=\"2\"/>\n<rect class=\"box2 b2\" x=\"250\" y=\"140\" width=\"42\" height=\"60\" rx=\"2\"/>\n<rect class=\"box2 b3\" x=\"340\" y=\"60\" width=\"42\" height=\"140\" rx=\"2\"/>\n<text class=\"t\" x=\"91\" y=\"188\" font-size=\"14\" text-anchor=\"middle\">10<\/text>\n<text class=\"t b1\" x=\"181\" y=\"174\" font-size=\"14\" text-anchor=\"middle\">100<\/text>\n<text class=\"t b2\" x=\"271\" y=\"134\" font-size=\"14\" text-anchor=\"middle\">1,000<\/text>\n<text class=\"t b3\" x=\"361\" y=\"54\" font-size=\"14\" text-anchor=\"middle\">10,000<\/text>\n<text class=\"tm\" x=\"91\" y=\"222\" font-size=\"14\" text-anchor=\"middle\">1층<\/text>\n<text class=\"tm\" x=\"181\" y=\"222\" font-size=\"14\" text-anchor=\"middle\">2층<\/text>\n<text class=\"tm\" x=\"271\" y=\"222\" font-size=\"14\" text-anchor=\"middle\">3층<\/text>\n<text class=\"tm\" x=\"361\" y=\"222\" font-size=\"14\" text-anchor=\"middle\">4층<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"252\" font-size=\"16\" text-anchor=\"middle\">뽑는 수를 고정해도 층마다 곱해져요<\/text>\n<\/svg>","caption":"허브 노드를 지나면 10만 개가 한꺼번에 들어오는 일은 막았지만, 층마다의 곱하기는 그대로 남아요.","builds":3},{"kind":"compare","head":"샘플링이 주는 효과 셋","cols":["효과","무슨 뜻인가요"],"rows":[["**확장성(Scalability)**","계산량이 차수와 무관하게 우리가 정한 값으로만 정해져요"],["**강건성(Robustness)**","매번 다른 이웃만 보니 잡음이 섞여도 잘 버텨요"],["**귀납적 학습(Inductive Learning)**","전체 그래프를 안 보니 그래프가 바뀌어도 그대로 돌아가요"]]},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 샘플링의 효과를 세 가지로 정리했어요.","첫째 확장 가능해진다. 다만 가중치 수는 그대로라 경량화는 아니래요.","둘째 노이즈에 **강건성(Robustness)**을 갖게 된다고요.","셋째 노드가 추가돼도 모델 동작에 영향이 없어 귀납적 학습이 된다고요."]},{"kind":"prof","when":"4주차 화요일 수업","lines":["한계에 대해서도 분명히 말했어요.","일부만 가져다 학습하면 그게 전체를 충실히 반영하느냐가 문제래요.","**그래프세이지(GraphSAGE)**는 전적으로 고정된 개수의 랜덤이라고요.","그래서 이론적으로 뒷받침이 안 된다는 것이 한계라고 했어요."]},{"kind":"warn","head":"오해하기 쉬운 곳","items":["'귀납적 학습이 가능해졌다'가 '**GCN**은 절대 미니 배치가 안 된다'는 뜻은 아니에요.","샘플링은 경량화가 아니에요. 파라미터 수는 그대로예요.","$S$ 는 층마다 다를 수 있어요. 10 과 5 라면 곱은 50 이에요."]}],"pass3":[{"kind":"exam","src":"2024 가을 기말 2번 (10점) (b)","q":"How does GraphSAGE solve the scalability problem?","qko":"**그래프세이지(GraphSAGE)**는 **확장성(Scalability)** 문제를 어떻게 푸나요?","solve":["먼저 무엇을 하지 않는지 말해요. 그래프 전체를 한 번에 처리하지 않아요.","대신 고정 크기의 이웃 집합을 뽑아 써요.","그래서 한 번에 만지는 노드 수가 미리 정해져요.","덧붙여 **귀납적 학습(Inductive Learning)** 표현을 배우도록 설계됐다고 쓰면 좋아요."],"answer":"GraphSAGE avoids processing the entire graph at once by sampling a fixed-size set of neighbors, and it is designed to learn inductive representations."},{"kind":"english","head":"한계 서술에 쓸 한 줄","en":"Even with fixed-size sampling the receptive field still grows as S to the power of L.","ko":"고정 크기 샘플링을 해도 수용 영역은 여전히 S 의 L 제곱으로 커진다.","tip":"and GraphSAGE gives no theoretical guarantee on sampling quality 를 이어 붙이세요."},{"kind":"check","q":"**그래프세이지(GraphSAGE)**의 한계 두 가지는 무엇인가요?","choices":["느리다와 부정확하다","증가율이 여전히 곱하기와 품질 보장 없음","메모리와 속도","편향과 과평활"],"a":1,"why":"증가율이 여전히 $S^L$ 이라는 것과 편향, **분산(Variance)**을 분석하지 않았다는 것이에요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.2313,0.0757],"c":[0.0011,0.0019,0.2553,0.1077],"r":4.2142,"img":"img/L4/walk/p028_h.jpg"},"parts":[{"b":[0.067,0.191,0.424,0.611],"c":[0.0458,0.1604,0.4664,0.6721],"r":1.2337,"img":"img/L4/walk/p028_12_01.jpg","say":"왼쪽 상자가 기여예요. 플러스 기호가 붙은 줄이 셋이에요."},{"b":[0.509,0.191,0.424,0.611],"c":[0.4878,0.1604,0.4664,0.6721],"r":1.2337,"img":"img/L4/walk/p028_12_02.jpg","say":"오른쪽 상자가 한계예요. 마이너스 기호가 붙은 줄이 둘이에요."}]}},{"p":29,"title":"예제 코드: NeighborSampler","terms":["GraphSAGE","Neighbor Sampling","Mini-batch","Adjacency Matrix","Scalability"],"pass1":[{"kind":"say","lines":["파이토치 지오메트릭에는 이 샘플링이 이미 들어 있어요.","`sizes=[10, 5]` 는 1층에서 10 개, 2층에서 5 개를 뽑는다는 뜻이에요.","`batch_size=32` 는 한 묶음에 대상 노드 32 개를 처리한다는 뜻이에요."]},{"kind":"analogy","head":"도시락 주문서 한 장","scene":"민수가 소풍 도시락을 주문해요. 주문서에 '큰 칸 10개, 작은 칸 5개, 32인분'이라고 적어요. 식당은 이 주문서만 보고 재료를 얼마나 준비할지 바로 알 수 있어요. 소풍 가는 학교가 몇 명이든 상관없이요.","map":[["주문서 숫자","sizes 와 batch_size"],["재료 준비량","미리 계산되는 메모리"],["학교 전체 인원","그래프 전체 노드 수"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.05,"y":0.205,"w":0.88,"h":0.075,"say":"둘째 불릿: '미니 배치마다 노드 번호와 그 둘레의 지역 그래프 정보가 담긴다'.","c":[0.006,0.1447,0.968,0.1956],"r":8.798,"img":"img/L4/walk/p029_20_01.jpg"},{"x":0.08,"y":0.37,"w":0.75,"h":0.042,"say":"'sizes=[10, 5] 는 층마다 10 개와 5 개의 이웃 노드를 뽑는다는 뜻이다'.","c":[0.0425,0.3077,0.825,0.1667],"r":8.7982,"img":"img/L4/walk/p029_20_02.jpg"},{"x":0.08,"y":0.47,"w":0.45,"h":0.042,"say":"'batch_size=32 로 묶음마다 노드 32개를 처리한다'.","c":[0.0575,0.436,0.495,0.11],"r":8.0,"img":"img/L4/walk/p029_20_03.jpg"},{"x":0.09,"y":0.815,"w":0.4,"h":0.045,"say":"맨 아래 파란 문장: '예제 코드 파일에서 코드를 몇 개 돌려 봅시다'.","c":[0.07,0.7825,0.44,0.11],"r":7.1111,"img":"img/L4/walk/p029_20_04.jpg"}]},{"kind":"points","head":"지역 그래프가 왜 필요한가요","items":["일반 딥러닝의 배치에는 이미지나 문장만 담으면 돼요.","그래프에서는 주변 연결 정보까지 같이 담아야 해요.","대상 노드 주변만 잘라낸 작은 그래프를 지역 그래프라고 해요.","**이웃 샘플링(Neighbor Sampling)**이 배치마다 이걸 새로 만들어 줘요."]},{"kind":"steps","head":"한 배치가 노드 몇 개를 만지나요","steps":["대상 노드는 배치 크기 그대로 32 개예요.","1홉 이웃은 $32 \\times 10 = 320$ 개예요.","2홉 이웃은 $320 \\times 5 = 1{,}600$ 개예요.","다 더하면 $32 + 320 + 1{,}600 = 1{,}952$ 개예요."],"answer":"전체 그래프가 노드 100 만 개여도 한 번에 만지는 건 약 2 천 개예요. 이게 미리 예상 가능한 메모리라는 말이에요.","given":"sizes 는 10 과 5, 배치 크기는 32 예요."},{"kind":"figure","head":"한 배치가 만지는 노드 수","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"240\" y=\"44\" font-size=\"16\" text-anchor=\"middle\">sizes=[10, 5], batch_size=32<\/text>\n<rect class=\"box\" x=\"24\" y=\"88\" width=\"120\" height=\"60\" rx=\"10\"/>\n<text class=\"t\" x=\"84\" y=\"112\" font-size=\"14\" text-anchor=\"middle\">대상 노드<\/text>\n<text class=\"tb\" x=\"84\" y=\"136\" font-size=\"16\" text-anchor=\"middle\">32<\/text>\n<line class=\"e2 b1\" x1=\"150\" y1=\"118\" x2=\"182\" y2=\"118\"/>\n<text class=\"tm b1\" x=\"166\" y=\"106\" font-size=\"13\" text-anchor=\"middle\">x10<\/text>\n<rect class=\"box2 b1\" x=\"190\" y=\"88\" width=\"120\" height=\"60\" rx=\"10\"/>\n<text class=\"t b1\" x=\"250\" y=\"112\" font-size=\"14\" text-anchor=\"middle\">1홉 이웃<\/text>\n<text class=\"tb b1\" x=\"250\" y=\"136\" font-size=\"16\" text-anchor=\"middle\">320<\/text>\n<line class=\"e2 b2\" x1=\"316\" y1=\"118\" x2=\"348\" y2=\"118\"/>\n<text class=\"tm b2\" x=\"332\" y=\"106\" font-size=\"13\" text-anchor=\"middle\">x5<\/text>\n<rect class=\"box2 b2\" x=\"356\" y=\"88\" width=\"118\" height=\"60\" rx=\"10\"/>\n<text class=\"t b2\" x=\"415\" y=\"112\" font-size=\"14\" text-anchor=\"middle\">2홉 이웃<\/text>\n<text class=\"tb b2\" x=\"415\" y=\"136\" font-size=\"16\" text-anchor=\"middle\">1,600<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"196\" font-size=\"15\" text-anchor=\"middle\">한 배치가 만지는 노드는 1,952 개<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"226\" font-size=\"14\" text-anchor=\"middle\">전체가 100만 개여도 이 숫자는 그대로예요<\/text>\n<\/svg>","caption":"리스트의 첫 번째 숫자가 대상 노드에서 가장 가까운 층이에요. 안쪽에서 바깥으로 갈수록 적게 뽑아요.","builds":3},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 파이토치 지오메트릭을 쓸 거라고 안내했어요.","**그래프세이지(GraphSAGE)**의 샘플링을 그대로 쓰려면 NeighborSampler 를 이용하면 된대요.","앞에서 **GCN**은 풀배치뿐이라고 했지만, 도움을 받으면 미니 배치 구현도 된다고요.","다만 본질적으로는 풀배치라는 뜻이라고 덧붙였어요."]},{"kind":"mining","src":"마이닝 2강 Representation and Storage","lines":["코드의 엣지 목록은 마이닝에서 배운 인접 리스트와 같은 생각이에요.","**인접행렬(Adjacency Matrix)**은 노드가 100 만 개면 칸이 1 조 개예요.","엣지가 500 만 개뿐이라면 목록은 정수 1000 만 개면 충분해요.","실세계 그래프는 대부분 아주 성겨서 이 차이가 어마어마해요."]}],"pass3":[{"kind":"check","q":"`sizes=[10, 5]` 에서 10 은 어느 층인가요?","choices":["가장 먼 2홉","대상 노드에 가장 가까운 1홉","층 수","배치 크기"],"a":1,"why":"첫 번째 숫자가 가장 가까운 층이에요. 먼 이웃일수록 적게 봐도 된다는 생각이에요."},{"kind":"warn","head":"코드와 관련해 조심할 점","items":["4주차 실습 노트북은 없어요. 4주차 코드는 이 슬라이드에 적힌 세 줄이 전부예요.","배치 안 노드 1,952 개는 최대치예요. 이웃이 10 명보다 적으면 그만큼만 뽑혀요.","설치한 버전에 따라 이름이나 위치가 다를 수 있어요. 시험에는 슬라이드에 적힌 대로 쓰세요."]}],"pass4":[{"kind":"code","head":"슬라이드에 인쇄된 코드 전부","file":"L4 슬라이드 p.29","code":"from torch_geometric.loader import NeighborSampler\nloader = NeighborSampler(data.edge_index, sizes=[10, 5], batch_size=32,\n                shuffle=True, num_nodes=data.num_nodes)","lines":[{"from":1,"to":1,"say":"파이토치 지오메트릭의 loader 묶음에서 NeighborSampler 를 가져와요. from A import B 는 'A 에서 B 만 꺼내 온다'는 뜻이에요."},{"from":2,"to":2,"say":"loader 라는 이름에 결과를 담아요. data.edge_index 는 엣지 목록, sizes 는 층마다 뽑을 이웃 수, batch_size 는 한 묶음의 대상 노드 수예요."},{"from":3,"to":3,"say":"shuffle=True 는 에폭마다 노드 순서를 섞으라는 뜻이고, num_nodes 는 전체 노드 수를 알려 주는 값이에요."}],"link":"2번 줄의 sizes 가 p.28 한계 식의 $S$ 이고, 리스트 길이가 층 수 $L$ 이에요."},{"kind":"pyterm","name":"리스트(list)","say":["대괄호 안에 값을 순서대로 담는 파이썬 상자예요.","`[10, 5]` 는 첫 칸이 10, 둘째 칸이 5 인 리스트예요.","칸 개수가 곧 층 수가 되는 게 이 코드의 약속이에요."],"example":"sizes = [10, 5]\nprint(len(sizes))","out":"2"},{"kind":"pyterm","name":"키워드 인자(keyword argument)","say":["함수에 값을 줄 때 이름표를 붙이는 방법이에요.","`batch_size=32` 처럼 이름과 값을 등호로 이어요.","이름표가 있으니 순서를 바꿔 써도 괜찮아요."],"example":"def order(kind, count=1):\n    return kind, count\n\nprint(order(\"apple\", count=3))","out":"('apple', 3)"},{"kind":"warn","head":"코드로 다시 정리하면","items":["NeighborSampler 가 **그래프세이지(GraphSAGE)**의 고정 크기 이웃 샘플링을 그대로 해 줘요.","미니 배치에는 노드 번호만이 아니라 그 둘레의 지역 그래프가 같이 담겨요.","한 배치가 만지는 노드 수가 미리 계산되니 메모리를 먼저 잡을 수 있어요."]}],"walk":{"head":{"b":[0.0131,0.0179,0.2964,0.0757],"c":[0,0.0019,0.3261,0.1077],"r":5.3829,"img":"img/L4/walk/p029_h.jpg"},"parts":[{"b":[0.05,0.14,0.45,0.045],"c":[0.0275,0.1075,0.495,0.11],"r":8.0,"img":"img/L4/walk/p029_12_01.jpg","say":"첫 불릿: 'DataLoader 는 NeighborSampler 로 **미니 배치(Mini-batch)**를 만든다'."},{"b":[0.083,0.556,0.833,0.191],"c":[0.0413,0.54,0.9163,0.223],"r":7.3048,"img":"img/L4/walk/p029_12_02.jpg","say":"가운데 검은 상자가 코드예요. 이 쪽의 핵심이에요."}]}},{"p":30,"title":"두 번째 방식: 레이어 단위 샘플링","terms":["Layer-wise Sampling","Node-wise Sampling","FastGCN","ASGCN","GraphSAGE","Mini-batch"],"pass1":[{"kind":"say","lines":["두 번째 방식은 **레이어 단위 샘플링(Layer-wise Sampling)**이에요.","노드마다 따로 뽑지 않고 층마다 한 번만 뽑아요.","그 층의 노드들을 묶음 전체가 함께 씁니다."]},{"kind":"analogy","head":"반별 간식과 학년 전체 간식","scene":"소풍날 간식을 준비하는 방법이 두 가지예요. 하나는 아이 한 명마다 두 개씩 따로 챙기는 방법이에요. 아이가 100명이면 200개가 필요하죠. 다른 하나는 학년 전체가 함께 쓰는 간식 통을 하나 놓는 방법이에요. 아이가 몇 명이든 통은 하나면 돼요.","map":[["한 명마다 따로 챙기기","**노드 단위 샘플링(Node-wise Sampling)**"],["학년 전체가 쓰는 통 하나","**레이어 단위 샘플링(Layer-wise Sampling)**"],["아이 수","묶음 안의 대상 노드 수"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"points","head":"한 문장에 담긴 두 가지 약속","items":["첫째, 층마다 뽑는 노드 수가 고정이에요.","둘째, 그 노드들을 묶음 전체가 공유해요.","묶음 안 대상 노드가 32 개든 320 개든 그 층의 집합은 하나예요.","그래서 비용이 깊이에 비례해서만 늘어요."]},{"kind":"steps","head":"곱하기가 더하기로 바뀌는 순간","steps":["**노드 단위 샘플링(Node-wise Sampling)**은 층마다 10 배가 돼요.","1층 10, 2층 100, 3층 1,000, 4층 10,000, 5층 100,000 이에요.","**레이어 단위 샘플링(Layer-wise Sampling)**은 층마다 100 이 더해져요.","1층 100, 2층 200, 3층 300, 4층 400, 5층 500 이에요.","3층부터 레이어 단위가 이기기 시작해요."],"answer":"5층에서는 100,000 대 500 으로 200 배 차이가 나요. 곱하기와 더하기의 차이예요.","given":"노드 단위는 한 노드당 10 개씩, 레이어 단위는 층마다 100 개씩이라고 해요."},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 두 방식의 차이를 이렇게 설명했어요.","**그래프세이지(GraphSAGE)**는 노드마다 샘플링을 달리한대요.","배치가 5 면 그 5 개 각각에서 2 개씩, 또 그 각각에서 2 개씩 뻗어 나간다고요.","레이어 단위는 레이어마다 관찰할 것을 미리 정해 놓는 것이라고 했어요."]},{"kind":"compare","head":"두 방식 한눈에","cols":["항목","노드 단위","레이어 단위"],"rows":[["누가 뽑나","대상 노드마다 따로","층마다 한 번"],["표본을 누가 쓰나","그 노드만","묶음 전체가 공유"],["비용 증가","층마다 곱하기","층마다 더하기"],["대표 모델","**그래프세이지(GraphSAGE)**","**FastGCN**, **ASGCN**"]]}],"pass3":[{"kind":"check","q":"**레이어 단위 샘플링(Layer-wise Sampling)**의 비용은 어떻게 늘어나나요?","choices":["깊이에 비례해서","깊이의 제곱으로","지수적으로","전혀 안 늘어난다"],"a":0,"why":"층마다 고정된 수를 뽑아 공유하니 깊이에 비례해서만 늘어요."},{"kind":"english","head":"서술형에 쓸 한 줄","en":"Layer-wise sampling draws a fixed number of nodes per layer that is shared by the whole batch, so the cost grows only linearly with depth.","ko":"레이어 단위 샘플링은 층마다 고정된 수의 노드를 뽑아 묶음 전체가 공유하므로, 비용이 깊이에 선형으로만 늘어난다.","tip":"shared by the whole batch 가 노드 단위와의 결정적 차이예요."}],"pass4":[],"walk":{"head":null,"parts":[{"b":[0.05,0.335,0.33,0.075],"c":[0.0335,0.3175,0.363,0.11],"r":5.8667,"img":"img/L4/walk/p030_12_01.jpg","say":"큰 제목이 '**레이어 단위 샘플링(Layer-wise Sampling)**' 이에요."},{"b":[0.05,0.45,0.52,0.075],"c":[0.024,0.4297,0.572,0.1156],"r":8.7966,"img":"img/L4/walk/p030_12_02.jpg","say":"'층마다 고정된 수의 노드를 뽑아 묶음 전체가 공유한다. 그래서 비용이 깊이에 비례해서만 늘어난다'."},{"b":[0.05,0.6,0.24,0.045],"c":[0.038,0.5675,0.264,0.11],"r":4.2667,"img":"img/L4/walk/p030_12_03.jpg","say":"'대표 모델: **FastGCN**, **ASGCN**' 이에요."}]}},{"p":31,"title":"FastGCN: SGD 가정이 깨지는 문제와 해법","terms":["FastGCN","SGD","Monte Carlo","Layer-wise Sampling","GraphSAGE","Node-wise Sampling"],"pass1":[{"kind":"say","lines":["**확률적 경사하강(SGD)**은 손실이 독립 표본들의 합이라고 믿어요.","그런데 GNN 손실은 한 노드가 이웃에 얽혀 있어서 그 믿음이 깨져요.","**FastGCN**은 노드를 확률에서 뽑힌 표본으로 보고 이 문제를 우회해요."]},{"kind":"analogy","head":"설문 조사가 되는 이유와 안 되는 이유","scene":"전교생 1000명의 키 평균을 알고 싶어요. 전부 재지 않고 30명만 재도 꽤 맞아요. 30명이 서로 상관없이 뽑혔기 때문이에요. 그런데 뽑은 30명이 모두 농구부라면 어떨까요. 서로 얽힌 사람만 뽑으면 평균이 엉뚱해져요.","map":[["상관없이 뽑힌 30명","독립인 표본"],["모두 농구부인 30명","이웃끼리 얽힌 노드들"],["다시 잘 뽑는 방법","확률분포에서 뽑는 **몬테카를로(Monte Carlo)**"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.03,"y":0.135,"w":0.1,"h":0.045,"say":"왼쪽 위 굵은 글씨가 '연속 관점' 이에요.","c":[0,0.1025,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p031_20_01.jpg"},{"x":0.11,"y":0.33,"w":0.16,"h":0.28,"say":"왼쪽 그림은 그래프 합성곱 관점. 채워진 동그라미가 뽑힌 노드예요.","c":[0.09,0.314,0.2,0.312],"r":1.1396,"img":"img/L4/walk/p031_20_02.jpg"},{"x":0.29,"y":0.32,"w":0.17,"h":0.29,"say":"오른쪽 그림은 적분 변환 관점. 동그라미가 곡선으로 바뀌었어요.","c":[0.275,0.304,0.2,0.322],"r":1.1042,"img":"img/L4/walk/p031_20_03.jpg"},{"x":0.029,"y":0.7,"w":0.483,"h":0.14,"say":"아래 상자에 다음 쪽부터 볼 식이 미리 나와 있어요.","c":[0.0049,0.684,0.5313,0.172],"r":5.4915,"img":"img/L4/walk/p031_20_04.jpg"},{"x":0.542,"y":0.212,"w":0.382,"h":0.296,"say":"'문제' 상자: GNN 손실은 독립성이 없다. 한 노드의 손실이 이웃에 달려 있다.","c":[0.5229,0.196,0.4202,0.328],"r":2.2775,"img":"img/L4/walk/p031_20_05.jpg"},{"x":0.542,"y":0.545,"w":0.382,"h":0.245,"say":"'해법' 상자: 층마다 기댓값이 되어 **몬테카를로(Monte Carlo)**로 추정할 수 있다.","c":[0.5229,0.529,0.4202,0.277],"r":2.6968,"img":"img/L4/walk/p031_20_06.jpg"}]},{"kind":"points","head":"먼저 용어 두 개를 풀어 둘게요","items":["i.i.d. 는 '서로 독립이고 같은 분포에서 나왔다'는 뜻이에요.","주사위를 여러 번 굴리는 것이 i.i.d. 예요. 앞 결과가 다음에 영향을 주지 않으니까요.","**몬테카를로(Monte Carlo)**는 어려운 값을 무작위 표본의 평균으로 추정하는 방법이에요.","이 두 단어가 이번 묶음 전체의 열쇠예요."]},{"kind":"points","head":"왜 그래프에서는 독립이 깨질까요","items":["노드 A 의 손실을 계산하려면 A 의 이웃이 필요해요.","그 이웃의 값을 계산하려면 또 그 이웃이 필요하고요.","그래서 A 의 손실과 B 의 손실이 같은 노드를 공유해요.","공유하는 순간 두 손실은 독립이 아니에요."]},{"kind":"steps","head":"기댓값을 표본 평균으로 추정해 봐요","steps":["진짜 평균은 $(0.6+1.2+0.9+0.3+1.5+0.6)/6 = 5.1/6 = 0.85$ 예요.","세 장만 뽑아 볼게요. $0.6, 1.2, 0.9$ 면 $2.7/3 = 0.9$ 예요.","$0.3, 1.5, 0.6$ 이면 $2.4/3 = 0.8$ 이에요.","$0.6, 0.3, 1.5$ 면 $0.8$, $1.2, 0.9, 0.6$ 이면 $0.9$ 예요.","네 번의 평균은 $(0.9+0.8+0.8+0.9)/4 = 0.85$ 예요."],"answer":"한 번은 틀려도 여러 번 하면 맞는 쪽으로 가요. 이게 **몬테카를로(Monte Carlo)**의 전부예요.","given":"주머니에 카드 여섯 장이 있고 숫자가 0.6, 1.2, 0.9, 0.3, 1.5, 0.6 이에요."},{"kind":"figure","head":"노드 단위와 레이어 단위의 모양 차이","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"118\" y=\"26\" font-size=\"15\" text-anchor=\"middle\">노드 단위<\/text>\n<text class=\"tb\" x=\"362\" y=\"26\" font-size=\"15\" text-anchor=\"middle\">레이어 단위<\/text>\n<circle class=\"n2\" cx=\"60\" cy=\"56\" r=\"13\"/>\n<circle class=\"n2\" cx=\"118\" cy=\"56\" r=\"13\"/>\n<circle class=\"n2\" cx=\"176\" cy=\"56\" r=\"13\"/>\n<line class=\"e b1\" x1=\"60\" y1=\"69\" x2=\"30\" y2=\"113\"/>\n<line class=\"e b1\" x1=\"60\" y1=\"69\" x2=\"78\" y2=\"113\"/>\n<line class=\"e b1\" x1=\"118\" y1=\"69\" x2=\"94\" y2=\"113\"/>\n<line class=\"e b1\" x1=\"118\" y1=\"69\" x2=\"142\" y2=\"113\"/>\n<line class=\"e b1\" x1=\"176\" y1=\"69\" x2=\"158\" y2=\"113\"/>\n<line class=\"e b1\" x1=\"176\" y1=\"69\" x2=\"206\" y2=\"113\"/>\n<circle class=\"n b1\" cx=\"30\" cy=\"124\" r=\"11\"/>\n<circle class=\"n b1\" cx=\"78\" cy=\"124\" r=\"11\"/>\n<circle class=\"n b1\" cx=\"94\" cy=\"124\" r=\"11\"/>\n<circle class=\"n b1\" cx=\"142\" cy=\"124\" r=\"11\"/>\n<circle class=\"n b1\" cx=\"158\" cy=\"124\" r=\"11\"/>\n<circle class=\"n b1\" cx=\"206\" cy=\"124\" r=\"11\"/>\n<text class=\"tb b1\" x=\"118\" y=\"172\" font-size=\"15\" text-anchor=\"middle\">부모마다 2개씩 모두 6개<\/text>\n<line class=\"e\" x1=\"240\" y1=\"36\" x2=\"240\" y2=\"186\"/>\n<circle class=\"n2\" cx=\"304\" cy=\"56\" r=\"13\"/>\n<circle class=\"n2\" cx=\"362\" cy=\"56\" r=\"13\"/>\n<circle class=\"n2\" cx=\"420\" cy=\"56\" r=\"13\"/>\n<line class=\"e b2\" x1=\"304\" y1=\"69\" x2=\"326\" y2=\"106\"/>\n<line class=\"e b2\" x1=\"362\" y1=\"69\" x2=\"334\" y2=\"106\"/>\n<line class=\"e b2\" x1=\"362\" y1=\"69\" x2=\"390\" y2=\"106\"/>\n<line class=\"e b2\" x1=\"420\" y1=\"69\" x2=\"398\" y2=\"106\"/>\n<rect class=\"box2 b2\" x=\"300\" y=\"106\" width=\"124\" height=\"36\" rx=\"18\"/>\n<circle class=\"n b2\" cx=\"330\" cy=\"124\" r=\"11\"/>\n<circle class=\"n b2\" cx=\"394\" cy=\"124\" r=\"11\"/>\n<text class=\"tb b2\" x=\"362\" y=\"172\" font-size=\"15\" text-anchor=\"middle\">층마다 2개를 같이 써요<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"214\" font-size=\"16\" text-anchor=\"middle\">곱하기가 더하기로 바뀌어요<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"242\" font-size=\"14\" text-anchor=\"middle\">한 층의 표본을 배치 전체가 나눠 써요<\/text>\n<\/svg>","caption":"**레이어 단위 샘플링(Layer-wise Sampling)**은 층 안의 표본 집합을 묶음 전체가 같이 써요.","builds":3},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 레이어 단위 샘플링을 아주 간단히 요약했어요.","그냥 **몬테카를로(Monte Carlo)**라고 생각하면 된대요.","이전 층 표현을 인접행렬에 따라 전파시켜 출력 표현으로 바꾸는데,","그 전파를 확률분포에 따라 잘 샘플링하면 여러 번 하다 보면 원래 결과에 가까워진다고요."]},{"kind":"warn","head":"관점이지 계산 방법이 아니에요","items":["'연속 관점'은 그래프를 진짜 연속으로 만든다는 게 아니에요. 수학적으로 그렇게 보자는 것이에요.","독립이 깨지는 문제는 GNN 전체의 문제예요. **그래프세이지(GraphSAGE)**는 그냥 넘어가고 **FastGCN**은 정면으로 다뤄요.","층마다 뽑는 개수는 층마다 다르게 정할 수 있어요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"FastGCN reinterprets graph vertices as i.i.d. samples from a probability measure.","ko":"FastGCN 은 그래프 꼭짓점을 확률 측도에서 뽑은 i.i.d. 표본으로 재해석한다.","tip":"which turns each layer into an expectation 을 이어 붙이세요."},{"kind":"check","q":"GNN 손실에서 **확률적 경사하강(SGD)**의 가정이 깨지는 이유는?","choices":["손실이 너무 크다","한 노드의 손실이 이웃에 달려 있다","층이 너무 깊다","가중치가 많다"],"a":1,"why":"이웃을 공유하니 서로 독립이 아니에요. i.i.d. 가정이 깨지는 거예요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4772,0.1741],"c":[0,0.0019,0.5249,0.2061],"r":4.5277,"img":"img/L4/walk/p031_h.jpg"},"parts":[{"b":[0.542,0.212,0.382,0.296],"c":[0.5229,0.196,0.4202,0.328],"r":2.2775,"img":"img/L4/walk/p031_12_01.jpg","say":"위 상자가 '문제'예요. **확률적 경사하강(SGD)**이 기대는 가정과 GNN 의 현실이 적혀 있어요."},{"b":[0.542,0.545,0.382,0.245],"c":[0.5229,0.529,0.4202,0.277],"r":2.6968,"img":"img/L4/walk/p031_12_02.jpg","say":"아래 상자가 '해법'이에요. 노드를 확률 측도에서 뽑은 표본으로 보자는 이야기예요."}]}},{"p":32,"title":"이웃 더하기를 적분으로 바꿔 쓰기","terms":["FastGCN","Monte Carlo","Adjacency Matrix","GCN","Normalization"],"pass1":[{"kind":"say","lines":["지금까지 GNN 층은 '이웃을 하나씩 더하기' 모양이었어요.","**FastGCN**은 이걸 '확률 무게를 매겨 더하기', 즉 적분으로 바꿔 써요.","값은 그대로예요. 바뀌는 건 표기뿐이에요."]},{"kind":"analogy","head":"같은 돈을 두 가지로 세기","scene":"저금통의 동전을 세는 방법이 두 가지예요. 하나는 한 개씩 집어 금액을 더하는 방법이에요. 다른 하나는 종류마다 전체에서 차지하는 비율만큼 무게를 매겨 평균을 낸 뒤 개수를 곱하는 방법이에요. 답은 같은데, 둘째는 몇 개만 보고도 어림할 수 있어요.","map":[["한 개씩 더하기","이웃 합"],["비율로 무게를 매겨 평균","확률 적분"],["몇 개만 집어 어림하기","**몬테카를로(Monte Carlo)**"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.07,"y":0.21,"w":0.87,"h":0.11,"say":"'**GCN**의 엄격한 위상 의존을 끊으려고' 로 시작해요. 위상은 누가 누구와 이어졌는가예요.","c":[0.0265,0.1683,0.957,0.1933],"r":8.8015,"img":"img/L4/walk/p032_20_01.jpg"},{"x":0.32,"y":0.455,"w":0.36,"h":0.075,"say":"식 안의 적분 기호와 마지막 $dP(u)$ 를 보세요. 확률 무게예요.","c":[0.302,0.4375,0.396,0.11],"r":6.4,"img":"img/L4/walk/p032_20_02.jpg"},{"x":0.07,"y":0.55,"w":0.4,"h":0.2,"say":"아래 정의 세 줄. $v$ 는 갱신 대상, $u$ 는 후보 이웃, $h$ 는 연속 임베딩 함수예요.","c":[0.05,0.534,0.44,0.232],"r":3.3716,"img":"img/L4/walk/p032_20_03.jpg"}]},{"kind":"formula","head":"적분 변환으로 쓴 층 갱신","tex":"h^{(l+1)}(v) = \\sigma\\left(\\int \\hat{A}(v, u)\\, h^{(l)}(u)\\, W^{(l)}\\, dP(u)\\right)","parts":[{"sym":"v","say":"브이. 갱신되는 대상 꼭짓점이에요."},{"sym":"u","say":"유. 연속 영역 안의 이웃 꼭짓점이에요."},{"sym":"\\hat{A}(v,u)","say":"에이햇 브이 유. 정규화된 **인접행렬(Adjacency Matrix)**의 값, 즉 연결 세기예요."},{"sym":"h^{(l)}(u)","say":"층 $l$ 에서의 연속 임베딩 함수예요."},{"sym":"W^{(l)}","say":"층 $l$ 의 가중치 행렬이에요."},{"sym":"dP(u)","say":"확률 측도 $P$ 에 따른 무게예요."},{"sym":"\\int \\dots dP(u)","say":"$u$ 전체에 확률 무게를 매겨 더하기예요."},{"sym":"\\sigma","say":"시그마. 비선형 함수예요."}],"whole":"모든 후보 이웃에 대해 연결 세기와 그 값과 가중치를 곱하고, 뽑힐 확률만큼 무게를 매겨 전부 합친 뒤 비선형을 씌워요."},{"kind":"compare","head":"표기만 바뀌었어요","cols":["원래 GCN (이산)","FastGCN (연속)"],"rows":[["이웃 하나씩 더하기","확률 무게를 매겨 더하기"],["행렬의 한 칸","함수 값"],["벡터 목록","함수"],["노드가 고정된 점","노드가 확률에서 뽑히는 표본"]]},{"kind":"steps","head":"두 표기가 같은 답을 내는지 확인","steps":["이산으로 계산해요. 곱이 $1.0$, $0.3$, $0.2$, $0$ 이에요.","다 더하면 $1.0 + 0.3 + 0.2 + 0 = 1.5$ 예요.","연속으로 계산해요. 네 노드에 확률을 $1/4$ 씩 준다고 해요.","$(1.0 + 0.3 + 0.2 + 0) \\times 0.25 = 0.375$ 예요.","$0.375 \\times 4 = 1.5$ 로 이산 계산과 같아요."],"answer":"확률로 무게를 매겨 평균을 낸 다음 개수를 곱하면 원래 합이에요. 다음 쪽의 평균 부분이 바로 이거예요.","given":"네 노드의 연결 세기는 0.5, 0.25, 0.25, 0 이고 값은 2.0, 1.2, 0.8, 3.0 이에요."},{"kind":"mining","src":"마이닝 2강 Representation and Storage","lines":["에이햇은 마이닝에서 배운 정규화된 **인접행렬(Adjacency Matrix)**이에요.","자기 자신으로 가는 고리를 더한 뒤 차수 행렬로 양옆을 눌러 준 것이에요.","차수가 큰 허브가 무조건 큰 값을 내보내는 걸 막는 **정규화(Normalization)**예요.","랜덤워크의 전이행렬과 사촌 관계인 행렬이에요."]},{"kind":"warn","head":"표기를 정확히 읽어야 해요","items":["이 식은 계산 방법이 아니라 관점이에요. 컴퓨터로 적분을 직접 풀지 않아요.","에이햇을 함수라고 썼지만 실제로는 정규화된 인접행렬의 한 칸이에요.","$dP(u)$ 를 빼먹고 $du$ 로 적으면 틀려요. 확률 무게가 핵심이에요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"By viewing vertices as i.i.d. draws from a measure P, FastGCN rewrites the discrete graph convolution as an integral transform.","ko":"꼭짓점을 측도 P 에서 뽑은 i.i.d. 표본으로 보면, FastGCN 은 이산 그래프 합성곱을 적분 변환으로 다시 쓴다.","tip":"so each layer becomes an expectation rather than a fixed matrix product 를 이어 붙이세요."},{"kind":"check","q":"이 쪽에서 표기를 바꿔서 얻는 것은 무엇인가요?","choices":["계산이 빨라진다","**몬테카를로(Monte Carlo)**를 쓸 자격을 얻는다","정확도가 올라간다","메모리가 준다"],"a":1,"why":"값은 그대로예요. 얻는 것은 적분을 표본 평균으로 근사한다는 통계학 도구예요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4772,0.1741],"c":[0,0.0019,0.5249,0.2061],"r":4.5277,"img":"img/L4/walk/p032_h.jpg"},"parts":[{"b":[0.07,0.21,0.87,0.11],"c":[0.0265,0.1683,0.957,0.1933],"r":8.8015,"img":"img/L4/walk/p032_12_01.jpg","say":"첫 문단: 꼭짓점을 확률분포에서 뽑은 i.i.d. 표본으로 해석하자는 제안이에요."},{"b":[0.32,0.455,0.36,0.075],"c":[0.302,0.4375,0.396,0.11],"r":6.4,"img":"img/L4/walk/p032_12_02.jpg","say":"가운데 식. 시그마 자리에 적분 기호가 들어왔어요."}]}},{"p":33,"title":"적분을 표본 평균으로 바꾸기","terms":["FastGCN","Monte Carlo","Variance","GraphSAGE","Layer-wise Sampling","Node-wise Sampling"],"pass1":[{"kind":"say","lines":["적분을 직접 풀 수 없으니 몇 개만 뽑아 평균을 내요.","층마다 뽑는 수를 못 박으니 이웃 폭발이 완전히 사라져요.","이것이 기본 **몬테카를로(Monte Carlo)** 근사예요."]},{"kind":"analogy","head":"국 맛을 보는 법","scene":"커다란 솥에 국을 끓였어요. 간이 맞는지 보려고 솥을 다 마실 필요는 없죠. 한 숟가락만 떠서 맛보면 돼요. 솥이 두 배로 커져도 맛보는 양은 한 숟가락이에요. 한 번은 짜게 느껴져도 여러 번 떠 보면 정확해져요.","map":[["솥 전체","층의 모든 노드"],["한 숟가락","층마다 뽑는 고정 개수"],["여러 번 떠 보기","학습을 여러 번 반복하기"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.03,"y":0.145,"w":0.28,"h":0.045,"say":"굵은 소제목: '**몬테카를로(Monte Carlo)** 적분과 중요도 샘플링'.","c":[0.016,0.1125,0.308,0.11],"r":4.9778,"img":"img/L4/walk/p033_20_01.jpg"},{"x":0.07,"y":0.22,"w":0.17,"h":0.045,"say":"그 아래: '기본 몬테카를로 근사'.","c":[0.055,0.1875,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p033_20_02.jpg"},{"x":0.11,"y":0.3,"w":0.85,"h":0.08,"say":"본문: 적분을 해석적으로 구할 수 없으니 몬테카를로 근사로 값을 매긴다는 이야기예요.","c":[0.065,0.2455,0.935,0.1889],"r":8.7995,"img":"img/L4/walk/p033_20_03.jpg"},{"x":0.28,"y":0.5,"w":0.37,"h":0.11,"say":"식. 앞 쪽의 적분 자리에 개수분의 1 과 시그마가 들어왔어요.","c":[0.2615,0.484,0.407,0.142],"r":5.0955,"img":"img/L4/walk/p033_20_04.jpg"},{"x":0.1,"y":0.65,"w":0.6,"h":0.045,"say":"'완전히'라는 단어가 중요해요. **그래프세이지(GraphSAGE)**에는 없던 표현이에요.","c":[0.07,0.6058,0.66,0.1333],"r":8.8022,"img":"img/L4/walk/p033_20_05.jpg"}]},{"kind":"formula","head":"기본 몬테카를로 근사","tex":"h^{(l+1)}(v) \\approx \\sigma\\left(\\frac{1}{t_l}\\sum_{j=1}^{t_l} \\hat{A}\\left(v, u_j\\right) h^{(l)}\\left(u_j\\right) W^{(l)}\\right)","parts":[{"sym":"\\approx","say":"근사 기호. '정확히 같다'가 아니라 '거의 같다'예요."},{"sym":"t_l","say":"티 엘. 층 $l$ 에서 뽑는 표본 노드 개수예요."},{"sym":"u_j","say":"유 제이. $j$ 번째로 뽑힌 노드예요."},{"sym":"\\sum_{j=1}^{t_l}","say":"뽑은 표본 전부에 대해 더하기예요."},{"sym":"\\frac{1}{t_l}","say":"뽑은 개수로 나누기, 즉 평균 내기예요."}],"whole":"분포에서 노드를 몇 개 뽑고, 각각 연결 세기와 값과 가중치를 곱해 더한 뒤 뽑은 개수로 나누고 비선형을 씌워요."},{"kind":"points","head":"**그래프세이지(GraphSAGE)**와의 결정적 차이","items":["**그래프세이지(GraphSAGE)**는 대상 노드의 이웃 중에서 뽑았어요.","그래서 대상이 달라지면 후보도 달라졌어요.","**FastGCN**은 분포에서 뽑아요. 대상이 무엇이든 후보 풀이 같아요.","그래서 한 번 뽑은 표본을 그 층의 모든 대상 노드가 나눠 써요.","**계산 그래프(Computation Graph)**의 폭이 층마다 고정되는 셈이에요."]},{"kind":"steps","head":"한 층을 실제로 계산해 봐요","steps":["전부 다 쓰면 평균은 $5.1/6 = 0.85$ 예요.","세 개만 뽑아요. $0.6, 1.2, 0.9$ 면 $2.7/3 = 0.9$ 예요.","$0.3, 1.5, 0.6$ 이면 $2.4/3 = 0.8$ 이에요.","$1.2, 0.3, 1.5$ 면 $3.0/3 = 1.0$ 이에요.","$0.6, 0.9, 0.6$ 이면 $2.1/3 = 0.7$ 이에요.","네 번의 평균은 $3.4/4 = 0.85$ 로 정답과 같아요."],"answer":"그런데 한 번씩 보면 0.7 에서 1.0 까지 널뛰어요. 이 널뛰는 정도가 **분산(Variance)**이에요.","given":"후보 노드 여섯 개의 값이 0.6, 1.2, 0.9, 0.3, 1.5, 0.6 이에요."},{"kind":"steps","head":"배치까지 넣어 계산량을 비교해요","steps":["**노드 단위 샘플링(Node-wise Sampling)**은 배치 크기에도 곱해져요.","2층이면 한 노드당 110, 배치 32 면 $32 \\times 110 = 3{,}520$ 이에요.","3층이면 한 노드당 1,110, 배치 32 면 $35{,}520$ 이에요.","**레이어 단위 샘플링(Layer-wise Sampling)**은 3층이어도 $100 \\times 3 = 300$ 이에요.","3층에서 벌써 35,520 대 300, 약 118 배 차이예요."],"answer":"노드 단위는 층마다 곱하고 배치에도 곱해요. 레이어 단위는 층마다 더하기만 하고 배치와 무관해요.","given":"배치 32, 층마다 노드 단위는 10 개씩, 레이어 단위는 100 개씩이에요."},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 레이어 단위 기법에서 기억할 부분을 이렇게 요약했어요.","전체 그래프를 레이어마다 관측하려니 계산 복잡도가 생기는 거래요.","그러니 일부 엣지들만 샘플링해서 전파시키면 되지 않겠느냐는 생각이라고요.","그걸 특정 확률분포에 따라 여러 번 반복하면 원본에 수렴할 거라고 보는 거예요."]},{"kind":"warn","head":"계산에서 자주 틀리는 곳","items":["근사 기호를 놓치지 마세요. 이 식은 추정값이라 매번 다른 답이 나와요.","나누는 수는 '뽑은 개수'예요. '전체 노드 수'가 아니에요.","뽑힌 노드 중에 $v$ 와 안 이어진 것이 섞일 수 있어요. 그건 0 을 더하는 헛수고예요."]}],"pass3":[{"kind":"exam","src":"계산 문제로 나온다면","q":"A layer samples three nodes and the products are 0.6, 1.2 and 0.9. Compute the layer output with ReLU.","qko":"한 층에서 노드 세 개를 뽑았고 곱한 값이 각각 $0.6$, $1.2$, $0.9$ 예요. 비선형이 ReLU 일 때 층 출력을 구하세요.","solve":["먼저 뽑힌 값을 전부 더해요. $0.6 + 1.2 + 0.9 = 2.7$ 이에요.","뽑은 개수 3 으로 나눠요. $2.7/3 = 0.9$ 예요.","ReLU 는 음수만 0 으로 바꾸는데 0.9 는 양수라 그대로예요.","개수로 나누는 것을 빼먹으면 답이 2.7 이 되어 틀려요."],"answer":"$\\mathrm{ReLU}(0.9) = 0.9$ 예요."},{"kind":"english","head":"서술형에 쓸 한 줄","en":"FastGCN fixes the number of sampled vertices per layer, so the receptive field grows linearly with depth instead of exponentially.","ko":"FastGCN 은 층마다 뽑는 꼭짓점 수를 고정하므로, 수용 영역이 지수적이 아니라 깊이에 선형으로 늘어난다.","tip":"linearly 와 exponentially 를 대비시키는 문장이에요."},{"kind":"check","q":"뽑은 값을 더한 뒤 무엇으로 나누나요?","choices":["전체 노드 수","뽑은 개수","층 수","배치 크기"],"a":1,"why":"뽑은 개수로 나눠요. 그래야 평균, 즉 기댓값의 추정값이 돼요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.9645,0.3723],"c":[0,0,1,0.4095],"r":4.3413,"img":"img/L4/walk/p033_h.jpg"},"parts":[{"b":[0.28,0.5,0.37,0.11],"c":[0.2615,0.484,0.407,0.142],"r":5.0955,"img":"img/L4/walk/p033_12_01.jpg","say":"가운데 식. 적분 기호가 사라지고 '뽑아서 평균 내기'가 들어왔어요."},{"b":[0.1,0.65,0.6,0.045],"c":[0.07,0.6058,0.66,0.1333],"r":8.8022,"img":"img/L4/walk/p033_12_02.jpg","say":"장점 줄: '층마다 뽑는 꼭짓점 수를 고정해, 재귀적 이웃 폭발을 완전히 피한다'."}]}},{"p":34,"title":"중요도 샘플링으로 널뜀을 줄여요","terms":["FastGCN","Importance Sampling","Proposal Distribution","Variance","Monte Carlo","GraphSAGE"],"pass1":[{"kind":"say","lines":["그냥 뽑으면 답이 널뛰어요. 널뛰는 정도가 **분산(Variance)**이에요.","**제안 분포(Proposal Distribution)**로 뽑고, 뽑힌 값을 그 확률로 나눠요.","이걸 **중요도 샘플링(Importance Sampling)**이라고 해요."]},{"kind":"analogy","head":"목소리 큰 학생과 조용한 학생","scene":"반 전체 의견을 알고 싶은데 시간이 없어 몇 명에게만 물어봐요. 목소리 큰 학생은 자주 불리고 조용한 학생은 어쩌다 불려요. 자주 불린 의견은 여러 번 들린 만큼 나눠서 반영해야 공정하죠. 조용한 학생 의견은 그만큼 크게 쳐 줘야 하고요.","map":[["자주 불리는 학생","뽑힐 확률이 큰 노드"],["나눠서 반영하기","뽑힐 확률로 나누기"],["크게 쳐 주기","작은 확률로 나눠 값이 커지기"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.07,"y":0.22,"w":0.24,"h":0.045,"say":"소제목: '**중요도 샘플링(Importance Sampling)**으로 분산 줄이기'.","c":[0.058,0.1875,0.264,0.11],"r":4.2667,"img":"img/L4/walk/p034_20_01.jpg"},{"x":0.11,"y":0.3,"w":0.85,"h":0.08,"say":"본문: 기본 몬테카를로 적분은 분산이 클 수 있어서 샘플링 측도를 바꾼다는 이야기예요.","c":[0.065,0.2455,0.935,0.1889],"r":8.7995,"img":"img/L4/walk/p034_20_02.jpg"},{"x":0.3,"y":0.48,"w":0.37,"h":0.12,"say":"식. 분모의 확률이 보정 장치예요.","c":[0.2815,0.464,0.407,0.152],"r":4.7602,"img":"img/L4/walk/p034_20_03.jpg"},{"x":0.1,"y":0.63,"w":0.83,"h":0.08,"say":"'통계적 일관성'은 표본을 많이 뽑을수록 참값에 수렴한다는 성질이에요.","c":[0.0585,0.5778,0.913,0.1845],"r":8.7974,"img":"img/L4/walk/p034_20_04.jpg"}]},{"kind":"formula","head":"중요도 샘플링을 넣은 추정량","tex":"h^{(l+1)}(v) \\approx \\sigma\\left(\\frac{1}{t_l}\\sum_{j=1}^{t_l} \\frac{\\hat{A}\\left(v, u_j\\right)}{Q\\left(u_j\\right)} h^{(l)}\\left(u_j\\right) W^{(l)}\\right)","parts":[{"sym":"Q(u_j)","say":"큐 오브 유 제이. 노드가 뽑힐 확률, 즉 **제안 분포(Proposal Distribution)**예요."},{"sym":"\\frac{\\hat{A}(v,u_j)}{Q(u_j)}","say":"뽑힐 확률로 나눈 보정된 연결 세기예요."},{"sym":"\\frac{1}{t_l}","say":"뽑은 개수로 나누기. 앞 쪽과 같아요."},{"sym":"\\approx","say":"추정값이라는 표시예요."}],"whole":"앞 쪽 식과 딱 한 군데가 달라요. 연결 세기 아래에 뽑힐 확률이 들어왔어요. 자주 뽑히는 노드는 그만큼 깎아 세요."},{"kind":"steps","head":"균등하게 뽑으면 얼마나 널뛰나요","steps":["확률이 모두 $0.25$ 라고 해요. 두 개씩 뽑아 볼게요.","$u_1, u_2$ 면 $\\frac{1}{2}(2.0/0.25 + 0.5/0.25) = \\frac{1}{2}(8+2) = 5.0$ 이에요.","$u_3, u_4$ 면 $\\frac{1}{2}(2+4) = 3.0$ 이에요.","$u_1, u_4$ 면 $\\frac{1}{2}(8+4) = 6.0$ 이에요.","$u_2, u_3$ 면 $\\frac{1}{2}(2+2) = 2.0$ 이에요.","네 경우의 평균은 $4.0$ 으로 정답이에요."],"answer":"평균은 맞지만 한 번씩 보면 2.0 에서 6.0 까지 널뛰어요. **분산(Variance)**이 커요.","given":"네 노드의 값이 2.0, 0.5, 0.5, 1.0 이고 참값은 전체 합 4.0 이에요."},{"kind":"steps","head":"크기에 비례해 뽑으면 어떻게 될까요","steps":["확률을 $0.5$, $0.125$, $0.125$, $0.25$ 로 잡아요.","$u_1$ 은 $2.0/0.5 = 4.0$ 이에요.","$u_2$ 는 $0.5/0.125 = 4.0$, $u_3$ 도 $4.0$ 이에요.","$u_4$ 는 $1.0/0.25 = 4.0$ 이에요.","네 칸이 전부 4.0 이라 어느 둘을 뽑아도 $\\frac{1}{2}(4.0+4.0) = 4.0$ 이에요."],"answer":"**분산(Variance)**이 0 이에요. 한 번만 뽑아도 정답이에요. 확률을 값의 크기에 비례하게 잡은 덕분이에요.","given":"같은 네 노드이고 값도 같아요."},{"kind":"figure","head":"널뛰는 정도가 달라져요","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"118\" y=\"26\" font-size=\"15\" text-anchor=\"middle\">균등하게 뽑을 때<\/text>\n<text class=\"tb\" x=\"362\" y=\"26\" font-size=\"15\" text-anchor=\"middle\">크기에 비례해 뽑을 때<\/text>\n<line class=\"e\" x1=\"26\" y1=\"190\" x2=\"214\" y2=\"190\"/>\n<line class=\"hl\" x1=\"26\" y1=\"120\" x2=\"214\" y2=\"120\"/>\n<text class=\"tm\" x=\"118\" y=\"112\" font-size=\"13\" text-anchor=\"middle\">참값 4.0<\/text>\n<rect class=\"box2 b1\" x=\"36\" y=\"85\" width=\"34\" height=\"105\" rx=\"3\"/>\n<rect class=\"box2 b1\" x=\"86\" y=\"155\" width=\"34\" height=\"35\" rx=\"3\"/>\n<rect class=\"box2 b1\" x=\"136\" y=\"50\" width=\"34\" height=\"140\" rx=\"3\"/>\n<rect class=\"box2 b1\" x=\"180\" y=\"173\" width=\"30\" height=\"17\" rx=\"3\"/>\n<text class=\"t b1\" x=\"53\" y=\"80\" font-size=\"13\" text-anchor=\"middle\">5.0<\/text>\n<text class=\"t b1\" x=\"103\" y=\"150\" font-size=\"13\" text-anchor=\"middle\">3.0<\/text>\n<text class=\"t b1\" x=\"153\" y=\"45\" font-size=\"13\" text-anchor=\"middle\">6.0<\/text>\n<text class=\"t b1\" x=\"195\" y=\"168\" font-size=\"13\" text-anchor=\"middle\">2.0<\/text>\n<text class=\"tb b1\" x=\"118\" y=\"212\" font-size=\"15\" text-anchor=\"middle\">2.0 에서 6.0 까지 널뛰어요<\/text>\n<line class=\"e\" x1=\"266\" y1=\"190\" x2=\"454\" y2=\"190\"/>\n<line class=\"hl\" x1=\"266\" y1=\"120\" x2=\"454\" y2=\"120\"/>\n<rect class=\"box b2\" x=\"276\" y=\"120\" width=\"34\" height=\"70\" rx=\"3\"/>\n<rect class=\"box b2\" x=\"326\" y=\"120\" width=\"34\" height=\"70\" rx=\"3\"/>\n<rect class=\"box b2\" x=\"376\" y=\"120\" width=\"34\" height=\"70\" rx=\"3\"/>\n<rect class=\"box b2\" x=\"420\" y=\"120\" width=\"30\" height=\"70\" rx=\"3\"/>\n<text class=\"t b2\" x=\"293\" y=\"114\" font-size=\"13\" text-anchor=\"middle\">4.0<\/text>\n<text class=\"t b2\" x=\"343\" y=\"114\" font-size=\"13\" text-anchor=\"middle\">4.0<\/text>\n<text class=\"t b2\" x=\"393\" y=\"114\" font-size=\"13\" text-anchor=\"middle\">4.0<\/text>\n<text class=\"t b2\" x=\"435\" y=\"114\" font-size=\"13\" text-anchor=\"middle\">4.0<\/text>\n<text class=\"tb b2\" x=\"362\" y=\"212\" font-size=\"15\" text-anchor=\"middle\">어떻게 뽑아도 4.0 이에요<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"244\" font-size=\"15\" text-anchor=\"middle\">둘 다 평균은 정답, 다른 건 널뛰는 정도예요<\/text>\n<\/svg>","caption":"어떤 확률로 뽑아도 평균은 항상 정답이에요. 달라지는 건 **분산(Variance)**뿐이에요.","builds":3},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 이 지점을 이렇게 짚었어요.","**몬테카를로(Monte Carlo)** 근사를 하니 최적의 확률분포를 계산할 수 있대요.","그런데 그걸 계산하는 건 복잡도가 높거나 아예 불가능하대요.","그리고 확률분포를 어떻게 정하느냐가 성능에 큰 영향을 준다고 강조했어요."]},{"kind":"warn","head":"여기서 자주 하는 실수","items":["어떤 확률을 골라도 평균은 항상 정답이에요. 달라지는 건 분산뿐이에요.","값이 0 이 아닌데 뽑힐 확률이 0 이면 안 돼요. 그 값은 영원히 빠져요.","분모의 확률을 빼먹고 계산하면 답이 완전히 달라져요. 시험에서 자주 나오는 실수예요."]}],"pass3":[{"kind":"exam","src":"계산 문제로 나온다면","q":"Given f values 2.0 and 0.5 with Q values 0.5 and 0.125, compute the importance sampling estimate for t=2.","qko":"값이 $2.0$, $0.5$ 이고 뽑힐 확률이 $0.5$, $0.125$ 일 때 두 개짜리 중요도 샘플링 추정값을 구하세요.","solve":["먼저 각 값을 그 확률로 나눠요.","$2.0 / 0.5 = 4.0$ 이에요.","$0.5 / 0.125 = 4.0$ 이에요.","두 값을 더해 뽑은 개수 2 로 나눠요."],"answer":"$\\frac{1}{2}(4.0 + 4.0) = 4.0$ 이에요."},{"kind":"english","head":"서술형에 쓸 한 줄","en":"Importance sampling draws vertices from a proposal distribution and divides each term by that probability.","ko":"중요도 샘플링은 제안 분포에서 꼭짓점을 뽑고 각 항을 그 확률로 나눈다.","tip":"which keeps the estimator unbiased while reducing its variance 를 붙이세요."},{"kind":"check","q":"**중요도 샘플링(Importance Sampling)**에서 각 항을 무엇으로 나누나요?","choices":["이웃 수","뽑힐 확률","층 수","인접행렬 값"],"a":1,"why":"뽑힐 확률로 나눠요. 자주 뽑히는 노드를 깎고 드물게 뽑히는 노드를 키워요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.9633,0.3714],"c":[0,0,1,0.4085],"r":4.352,"img":"img/L4/walk/p034_h.jpg"},"parts":[{"b":[0.3,0.48,0.37,0.12],"c":[0.2815,0.464,0.407,0.152],"r":4.7602,"img":"img/L4/walk/p034_12_01.jpg","say":"가운데 식. 연결 세기 아래에 분모가 새로 생겼어요."},{"b":[0.1,0.63,0.83,0.08],"c":[0.0585,0.5778,0.913,0.1845],"r":8.7974,"img":"img/L4/walk/p034_12_02.jpg","say":"아래 문단: **그래프세이지(GraphSAGE)**처럼 재귀로 뽑지 않고 제안 분포에서 바로 뽑는다는 이야기예요."}]}},{"p":35,"title":"이론상 가장 좋은 뽑기 확률","terms":["FastGCN","Proposal Distribution","Variance","Importance Sampling","Normalization"],"pass1":[{"kind":"say","lines":["**분산(Variance)**을 가장 작게 만드는 뽑기 확률이 있어요.","적분되는 항의 크기에 비례하면 돼요.","그 크기는 연결 세기와 그 노드 값의 크기를 곱한 것이에요."]},{"kind":"analogy","head":"어디를 먼저 청소할까","scene":"민수가 시간이 모자라 방의 일부만 청소할 수 있어요. 어디를 고를까요. 먼지가 가장 많이 쌓인 곳부터 고르는 게 이득이죠. 깨끗한 구석은 닦아 봐야 거의 안 달라지니까요. 먼지 양에 비례해 시간을 나누면 방이 가장 깨끗해져요.","map":[["먼지가 많은 곳","항의 크기가 큰 노드"],["시간을 비례해서 나누기","크기에 비례한 **제안 분포(Proposal Distribution)**"],["가장 깨끗해진 방","가장 작은 **분산(Variance)**"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.03,"y":0.145,"w":0.22,"h":0.045,"say":"소제목: '분산 줄이기와 실제 구현'.","c":[0.018,0.1125,0.244,0.11],"r":3.9434,"img":"img/L4/walk/p035_20_01.jpg"},{"x":0.07,"y":0.22,"w":0.14,"h":0.045,"say":"그 아래: '최적 샘플링 분포'.","c":[0.04,0.1875,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p035_20_02.jpg"},{"x":0.11,"y":0.3,"w":0.63,"h":0.14,"say":"'항들의 크기'가 핵심 표현이에요. 적분 기호 안에 든 것이 얼마나 큰가예요.","c":[0.0785,0.284,0.693,0.172],"r":7.1628,"img":"img/L4/walk/p035_20_03.jpg"},{"x":0.32,"y":0.545,"w":0.29,"h":0.065,"say":"식. 왼쪽 별표가 '최적'을 뜻해요.","c":[0.3055,0.5225,0.319,0.11],"r":5.1556,"img":"img/L4/walk/p035_20_04.jpg"}]},{"kind":"formula","head":"최적 제안 분포","tex":"Q^*(u) \\propto \\sum_v \\left|\\hat{A}(v,u)\\right| \\left\\|h^{(l)}(u) W^{(l)}\\right\\|","parts":[{"sym":"Q^*(u)","say":"큐 스타. 최적 **제안 분포(Proposal Distribution)**예요. 별표가 최적을 뜻해요."},{"sym":"\\propto","say":"비례 기호. 등호가 아니라 상수배만큼 차이 난다는 뜻이에요."},{"sym":"\\sum_v","say":"시그마 브이. 위층의 모든 대상 노드에 대해 더하기예요."},{"sym":"\\left|\\hat{A}(v,u)\\right|","say":"절댓값. 연결 세기의 크기이고 부호는 무시해요."},{"sym":"\\left\\|\\cdot\\right\\|","say":"노름. 벡터의 길이예요."},{"sym":"h^{(l)}(u) W^{(l)}","say":"노드의 임베딩을 가중치로 변환한 것이에요."}],"whole":"노드를 뽑을 확률은 위층과 얼마나 강하게 이어져 있는지와 그 노드 값이 얼마나 큰지의 곱에 비례해야 해요."},{"kind":"points","head":"비례 기호를 어떻게 확률로 바꾸나요","items":["비례한다는 말은 오른쪽 값을 다 구한 뒤 전체 합으로 나눈다는 뜻이에요.","확률이니까 다 더하면 1 이 되어야 하니까요.","이 나누기가 바로 **정규화(Normalization)**예요.","그래서 비례 기호만 보고 답을 적으면 틀려요."]},{"kind":"points","head":"왜 두 요소를 곱하나요","items":["첫째, 많은 대상 노드와 강하게 이어진 노드는 자주 봐야 해요.","안 그러면 여러 노드의 계산이 한꺼번에 어긋나요.","둘째, 값이 큰 노드는 결과에 큰 영향을 주니 역시 자주 봐야 해요.","값이 거의 0 인 노드는 봐 봐야 별 차이가 없어요."]},{"kind":"steps","head":"최적 확률을 직접 만들어 봐요","steps":["1단계. 연결 세기 합이 $1.0$, $0.25$, $0.25$, $0.5$ 라고 해요.","2단계. 값의 길이를 구해요. $(3,4)$ 는 $\\sqrt{25} = 5.0$ 이에요.","$(1,0)$ 은 $1.0$, $(0,2)$ 는 $2.0$, $(1,1)$ 은 $\\approx 1.414$ 예요.","3단계. 곱해요. $5.0$, $0.25$, $0.5$, $\\approx 0.707$ 이에요.","4단계. 전체 합 $6.457$ 로 나눠요.","$\\approx 0.774$, $0.039$, $0.077$, $0.110$ 이고 다 더하면 1 이에요."],"answer":"첫 노드가 77 퍼센트로 압도적이에요. 둘 다 크기 때문이에요. 넷째는 4 퍼센트지만 뽑히면 25 배로 커져 제 몫을 해요.","given":"위층에 대상 노드가 두 개인 네 노드짜리 층이에요."},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 여기서 근사가 필요한 이유를 말했어요.","**몬테카를로(Monte Carlo)**를 하면 최적 확률분포를 계산할 수 있대요.","그런데 그 자체를 계산하는 건 복잡도가 높거나 아예 불가능하대요.","그 근사를 어떻게 하느냐가 **FastGCN**과 **ASGCN**을 가르는 지점이라고요."]},{"kind":"warn","head":"여기서 드러나는 문제","items":["2단계에 쓴 값들은 학습이 한 걸음 갈 때마다 바뀌어요.","그러면 3단계와 4단계도 매번 다시 해야 해요.","샘플링으로 아끼려던 계산이 통째로 돌아와요. 그래서 이 최적 분포는 실전에서 못 써요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"The variance-minimizing proposal distribution is proportional to the magnitude of the integrand.","ko":"분산을 최소로 하는 제안 분포는 피적분 항의 크기에 비례한다.","tip":"that is, to the product of the connection strength and the norm of the transformed embedding 을 붙이세요."},{"kind":"check","q":"비례 기호로 적힌 값을 확률로 만들려면 무엇을 해야 하나요?","choices":["아무것도 안 해도 된다","전체 합으로 나눈다","제곱한다","루트를 씌운다"],"a":1,"why":"전체 합으로 나누는 **정규화(Normalization)**를 해야 다 더해 1 이 돼요."},{"kind":"warn","head":"아래첨자와 기호를 정확히","items":["시그마 브이는 위층의 대상 노드들에 대한 합이에요. 후보 노드에 대한 합이 아니에요.","절댓값을 쓰는 이유는 정규화된 인접행렬에 음수가 섞일 수 있어서예요.","여기는 노름이고 다음 쪽은 노름 제곱이에요. 루트 유무가 달라요."]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4772,0.2491],"c":[0,0.0019,0.5249,0.2811],"r":3.3197,"img":"img/L4/walk/p035_h.jpg"},"parts":[{"b":[0.11,0.3,0.63,0.14],"c":[0.0785,0.284,0.693,0.172],"r":7.1628,"img":"img/L4/walk/p035_12_01.jpg","say":"본문: 분산을 최소로 하는 최적 제안 분포는 적분되는 항들의 크기에 비례해야 한다."},{"b":[0.32,0.545,0.29,0.065],"c":[0.3055,0.5225,0.319,0.11],"r":5.1556,"img":"img/L4/walk/p035_12_02.jpg","say":"가운데 식. 비례 기호가 등호가 아니라는 점을 꼭 보세요."}]}},{"p":36,"title":"실제로 쓰는 확률은 그냥 정규화예요","terms":["FastGCN","Adjacency Matrix","Proposal Distribution","Normalization","ASGCN"],"pass1":[{"kind":"say","lines":["최적 확률은 노드 값이 필요해서 너무 비싸요.","**FastGCN**은 값에 대한 의존을 통째로 버려요.","남는 건 **인접행렬(Adjacency Matrix)** 한 줄을 제곱해 더한 값뿐이에요."]},{"kind":"analogy","head":"매번 재는 저울과 한 번 적어 둔 표","scene":"가게에서 물건을 고를 때 손님이 올 때마다 무게를 다시 재야 한다면 아주 번거롭죠. 그런데 물건 무게가 바뀌지 않는다면, 처음에 한 번 재어 표로 적어 두고 그 표만 보면 돼요. 재는 일이 딱 한 번으로 끝나요.","map":[["매번 재는 저울","학습마다 바뀌는 노드 값"],["한 번 적어 둔 표","학습해도 안 바뀌는 인접행렬"],["표만 보고 고르기","미리 계산해 둔 뽑기 확률"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.07,"y":0.22,"w":0.13,"h":0.045,"say":"소제목: '현실적인 근사'.","c":[0.035,0.1875,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p036_20_01.jpg"},{"x":0.11,"y":0.3,"w":0.6,"h":0.15,"say":"본문: 최적 확률은 중간 층 임베딩이 필요해서 비싸고, 학습 내내 바뀐다는 이야기예요.","c":[0.08,0.284,0.66,0.182],"r":6.4469,"img":"img/L4/walk/p036_20_02.jpg"},{"x":0.11,"y":0.51,"w":0.48,"h":0.045,"say":"'은닉 특징 의존을 통째로 없앤다'가 이 쪽의 선언이에요.","c":[0.086,0.4775,0.528,0.11],"r":8.5333,"img":"img/L4/walk/p036_20_03.jpg"},{"x":0.36,"y":0.66,"w":0.2,"h":0.085,"say":"식. 위가 열 노름 제곱, 아래가 전체 합이에요.","c":[0.348,0.644,0.224,0.117],"r":3.4036,"img":"img/L4/walk/p036_20_04.jpg"}]},{"kind":"formula","head":"실제로 쓰는 뽑기 확률","tex":"Q(u) = \\frac{\\left\\|\\hat{A}(:, u)\\right\\|^2}{\\sum_{u'} \\left\\|\\hat{A}(:, u')\\right\\|^2}","parts":[{"sym":"\\hat{A}(:, u)","say":"에이햇 콜론 유. 정규화된 인접행렬의 $u$ 번째 열 전체예요."},{"sym":":","say":"콜론. '모든 행'이라는 뜻이에요. 파이썬 슬라이싱과 같은 표기예요."},{"sym":"\\left\\|\\cdot\\right\\|^2","say":"노름 제곱. 열의 각 칸을 제곱해 전부 더한 값이에요."},{"sym":"\\sum_{u'}","say":"모든 노드에 대해 더하기. **정규화(Normalization)**용이에요."},{"sym":"u'","say":"유 프라임. $u$ 와 구별하려고 쓰는 다른 이름이에요."}],"whole":"노드를 뽑을 확률은 인접행렬에서 그 노드의 열이 가진 힘에 비례해요. 분모는 전부 더해 1 로 만드는 정규화예요."},{"kind":"steps","head":"확률을 직접 만들어 봐요","steps":["1단계. 열마다 제곱해서 더해요. 열은 세로줄이에요.","첫째 열은 $0.25 + 0.25 + 0 + 0 = 0.5$ 예요.","둘째 열은 $0.25 + 0.25 + 0 + 0.25 = 0.75$ 예요.","셋째 열은 $0.5$, 넷째 열은 $0.75$ 예요.","2단계. 전체 합은 $0.5 + 0.75 + 0.5 + 0.75 = 2.5$ 예요.","3단계. 나누면 $0.2$, $0.3$, $0.2$, $0.3$ 이고 다 더하면 1 이에요."],"answer":"균등이면 전부 0.25 인데, 이웃이 많은 쪽이 0.3 으로 더 자주 뽑히게 됐어요.","given":"네 노드짜리 정규화된 인접행렬의 값이 0.5 와 0 으로 이루어져 있다고 해요."},{"kind":"figure","head":"열 하나로 확률을 만드는 순서","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"240\" y=\"44\" font-size=\"16\" text-anchor=\"middle\">FastGCN 이 실제로 쓰는 뽑기 확률<\/text>\n<rect class=\"box\" x=\"20\" y=\"100\" width=\"120\" height=\"64\" rx=\"10\"/>\n<text class=\"t\" x=\"80\" y=\"126\" font-size=\"14\" text-anchor=\"middle\">인접행렬의<\/text>\n<text class=\"t\" x=\"80\" y=\"148\" font-size=\"14\" text-anchor=\"middle\">u 번째 열<\/text>\n<line class=\"e2 b1\" x1=\"146\" y1=\"132\" x2=\"174\" y2=\"132\"/>\n<rect class=\"box2 b1\" x=\"180\" y=\"100\" width=\"120\" height=\"64\" rx=\"10\"/>\n<text class=\"t b1\" x=\"240\" y=\"126\" font-size=\"14\" text-anchor=\"middle\">제곱해서 더하기<\/text>\n<text class=\"tb b1\" x=\"240\" y=\"148\" font-size=\"15\" text-anchor=\"middle\">.5 .75 .5 .75<\/text>\n<line class=\"e2 b2\" x1=\"306\" y1=\"132\" x2=\"334\" y2=\"132\"/>\n<rect class=\"box2 b2\" x=\"340\" y=\"100\" width=\"120\" height=\"64\" rx=\"10\"/>\n<text class=\"t b2\" x=\"400\" y=\"126\" font-size=\"14\" text-anchor=\"middle\">합 2.5 로 나누기<\/text>\n<text class=\"tb b2\" x=\"400\" y=\"148\" font-size=\"15\" text-anchor=\"middle\">.2 .3 .2 .3<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"208\" font-size=\"15\" text-anchor=\"middle\">인접행렬은 학습해도 바뀌지 않아요<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"234\" font-size=\"14\" text-anchor=\"middle\">그래서 딱 한 번만 계산하면 끝이에요<\/text>\n<\/svg>","caption":"최적 분포에 있던 값 의존이 사라졌어요. 남은 건 **인접행렬(Adjacency Matrix)**뿐이에요.","builds":3},{"kind":"points","head":"근사는 근사일 뿐이에요","items":["이 확률이 항상 균등보다 나은 건 아니에요.","값의 크기가 열 노름을 따르지 않으면 오히려 더 널뛸 수도 있어요.","그래도 계산 이점이 압도적이라 실전에서는 이 쪽을 택해요.","학습 전에 한 번 구해 두면 끝이니까요."]},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 두 모델의 차이를 여기서 갈랐어요.","**FastGCN**은 그냥 최적 분포를 근사하는데, 그 결과가 보다시피 그냥 정규화래요.","복잡한 이론을 폈지만 남는 건 간단한 식 하나라는 뜻이에요.","반면 **ASGCN**은 근사를 위해 학습 가능한 접근을 취한다고 했어요."]},{"kind":"warn","head":"표기를 정확히 읽으세요","items":["열이에요. 행이 아니에요. 콜론이 앞에 있으면 '모든 행, u 번째 열'이에요.","노름 제곱이에요. 루트를 씌우지 않아요. 앞 쪽의 최적 분포는 루트가 있었어요.","이 확률은 층과 무관하게 하나예요. 층마다 다시 계산하지 않아요."]}],"pass3":[{"kind":"exam","src":"계산 문제로 나온다면","q":"If the squared column norms are 0.5, 0.75, 0.5 and 0.75, compute the FastGCN sampling probabilities.","qko":"열 노름 제곱이 각각 $0.5$, $0.75$, $0.5$, $0.75$ 일 때 **FastGCN**의 샘플링 확률을 구하세요.","solve":["먼저 전체 합을 구해요. $0.5 + 0.75 + 0.5 + 0.75 = 2.5$ 예요.","각 값을 그 합으로 나눠요.","$0.5 / 2.5 = 0.2$ 이고 $0.75 / 2.5 = 0.3$ 이에요.","다 더해서 1 이 되는지 꼭 확인하세요."],"answer":"$Q = (0.2,\\ 0.3,\\ 0.2,\\ 0.3)$ 이에요."},{"kind":"english","head":"서술형에 쓸 한 줄","en":"FastGCN drops the hidden-feature term, so the sampling probability depends only on the graph topology.","ko":"FastGCN 은 은닉 특징 항을 버려서, 샘플링 확률이 그래프 위상에만 의존한다.","tip":"the normalized squared column norm 이라는 표현을 덧붙이면 좋아요."},{"kind":"check","q":"**FastGCN**이 실제로 쓰는 확률은 무엇에만 기대나요?","choices":["노드 임베딩","**인접행렬(Adjacency Matrix)**","층 수","배치 크기"],"a":1,"why":"임베딩 의존을 통째로 버려서 인접행렬만 남아요. 그래서 한 번만 계산하면 끝이에요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.6956,0.4554],"c":[0,0,0.7651,0.501],"r":2.7149,"img":"img/L4/walk/p036_h.jpg"},"parts":[{"b":[0.11,0.51,0.48,0.045],"c":[0.086,0.4775,0.528,0.11],"r":8.5333,"img":"img/L4/walk/p036_12_01.jpg","say":"'실제 샘플링 분포는 그래프의 구조적 위상에만 기댄다'."},{"b":[0.36,0.66,0.2,0.085],"c":[0.348,0.644,0.224,0.117],"r":3.4036,"img":"img/L4/walk/p036_12_02.jpg","say":"그 아래 식이 실제로 쓰는 확률이에요. 열 하나를 제곱해 더한 값이에요."}]}},{"p":37,"title":"FastGCN 정리: 기여 셋과 한계 하나","terms":["FastGCN","Importance Sampling","Variance","Layer-wise Sampling","Node-wise Sampling","GraphSAGE","Cluster-GCN","Degree"],"pass1":[{"kind":"say","lines":["기여는 셋이에요. 층마다 고정 크기로 뽑아 비용이 깊이에 비례하고,","**중요도 샘플링(Importance Sampling)**이 품질 보장을 주고, 층마다 병렬로 뽑을 수 있어요.","한계는 하나예요. 층이 독립이라 뽑힌 노드끼리 안 이어질 수 있어요."]},{"kind":"analogy","head":"두 층에서 따로 뽑은 짝꿍","scene":"1반에서 세 명, 2반에서 세 명을 따로 뽑아 짝을 지으라고 했어요. 그런데 두 반은 서로 상의하지 않고 뽑았죠. 운이 좋으면 서로 아는 아이들끼리 만나 이야기가 잘 통해요. 운이 나쁘면 서로 전혀 모르는 여섯 명이 모여 아무 말도 오가지 않아요.","map":[["서로 상의하지 않고 뽑기","층마다 독립으로 뽑기"],["서로 아는 사이","두 노드가 이어져 있음"],["말이 안 오감","연결 세기가 0 이라 헛수고"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.09,"y":0.295,"w":0.38,"h":0.06,"say":"기여 1: '이웃 폭발을 층마다 고정 크기 샘플링으로 푼다. 비용이 깊이에 비례'.","c":[0.071,0.27,0.418,0.11],"r":6.7556,"img":"img/L4/walk/p037_20_01.jpg"},{"x":0.09,"y":0.39,"w":0.38,"h":0.04,"say":"기여 2: '**중요도 샘플링(Importance Sampling)**이 품질 보장, 즉 분산 감소를 준다'.","c":[0.071,0.355,0.418,0.11],"r":6.7556,"img":"img/L4/walk/p037_20_02.jpg"},{"x":0.09,"y":0.49,"w":0.38,"h":0.04,"say":"기여 3: '층마다 따로 뽑으니 샘플링을 병렬로 돌릴 수 있다'.","c":[0.071,0.455,0.418,0.11],"r":6.7556,"img":"img/L4/walk/p037_20_03.jpg"},{"x":0.545,"y":0.295,"w":0.38,"h":0.06,"say":"한계 1: '층이 독립이라 층 사이 상관을 무시한다'.","c":[0.526,0.27,0.418,0.11],"r":6.7556,"img":"img/L4/walk/p037_20_04.jpg"},{"x":0.545,"y":0.43,"w":0.38,"h":0.04,"say":"한계 2: '표본 사이 연결이 성기면 성능이 떨어진다'. 성기다는 듬성듬성하다는 뜻이에요.","c":[0.526,0.395,0.418,0.11],"r":6.7556,"img":"img/L4/walk/p037_20_05.jpg"}]},{"kind":"points","head":"왜 이런 한계가 생길까요","items":["**FastGCN**은 1층에서 뽑을 때 확률만 보고 뽑아요.","2층에서 뽑을 때도 똑같은 확률만 보고 뽑아요. 둘이 상의하지 않아요.","그런데 계산할 때는 두 노드 사이의 연결 세기가 곱해져요.","안 이어져 있으면 0 이라 그 표본은 헛수고예요."]},{"kind":"steps","head":"얼마나 자주 헛수고가 될까요","steps":["평균 **차수(Degree)**가 5 이니 아무 노드나 집었을 때 이어질 확률은 $5/100 = 0.05$ 예요.","1층에서 10 개를 독립으로 뽑으면 이어진 것은 평균 $10 \\times 0.05 = 0.5$ 개예요.","하나도 못 만날 확률은 $0.95^{10} \\approx 0.60$ 이에요.","50 개를 뽑으면 기대 개수 2.5, 못 만날 확률 $\\approx 0.08$ 이에요.","100 개면 기대 5.0, 못 만날 확률 $\\approx 0.006$ 이에요."],"answer":"많이 뽑으면 해결되지만 그러면 계산량이 다시 늘어요. 성긴 그래프일수록 이 문제가 심해요.","given":"노드 100 개, 평균 차수 5 인 그래프예요. 2층에서 노드 하나를 뽑았다고 해요."},{"kind":"compare","head":"**그래프세이지(GraphSAGE)**와 맞바꾼 것","cols":["항목","GraphSAGE","FastGCN"],"rows":[["뽑는 곳","대상 노드의 실제 이웃","층 전체 확률분포"],["헛수고 표본","없음","생길 수 있음"],["비용 증가","층마다 곱하기","층마다 더하기"],["품질 보장","없음","있음"]]},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 레이어 단위 방식의 장단점을 분명히 말했어요.","가장 큰 장점은 샘플링 품질이 이론적으로 뒷받침된다는 것이래요.","전체를 전파할 때와 샘플링을 반복할 때의 층 출력이 거의 비슷할 것이 보장된다고요.","단점은 그냥 복잡하다는 것이고, 그래서 잘 안 쓰인다고 두 번이나 말했어요."]}],"pass3":[{"kind":"warn","head":"이 쪽 슬라이드의 참고문헌이 잘못됐어요","items":["맨 아래 참고문헌 줄이 **Cluster-GCN** 논문(Chiang et al., KDD 2019)을 가리켜요.","**FastGCN** 정리 쪽이니 Chen, Ma, Xiao 의 FastGCN 논문(ICLR 2018)이 맞아요.","슬라이드 오타로 보여요. 논문 이름을 묻는 문제가 나오면 FastGCN 논문으로 답하세요."]},{"kind":"english","head":"세 방식을 비교하라고 하면","en":"Node-wise sampling such as GraphSAGE is simple to implement but gives no theoretical guarantee on sampling quality.","ko":"GraphSAGE 같은 노드 단위 샘플링은 구현이 간단하지만 샘플링 품질에 이론적 보장이 없다.","tip":"이어서 레이어 단위 문장을 붙이면 한 세트가 완성돼요."},{"kind":"english","head":"이어서 붙일 한 줄","en":"Layer-wise sampling such as FastGCN guarantees that the layer outputs stay close to the full-graph propagation.","ko":"FastGCN 같은 레이어 단위 샘플링은 층 출력이 전체 전파 결과와 가깝게 유지됨을 보장한다.","tip":"but it is complex and rarely used in practice 로 마무리하면 한 세트가 완성돼요."},{"kind":"check","q":"**FastGCN**의 한계는 무엇 때문에 생기나요?","choices":["층마다 따로 독립으로 뽑아서","이웃을 너무 많이 뽑아서","가중치가 많아서","인접행렬이 커서"],"a":0,"why":"층끼리 상의하지 않고 뽑으니 뽑힌 노드끼리 안 이어져 있을 수 있어요."},{"kind":"warn","head":"말뜻을 정확히","items":["'품질 보장'은 **분산(Variance)**이 줄어든다는 뜻이지 항상 정확하다는 뜻이 아니에요.","'병렬로 돌릴 수 있다'는 샘플링 단계 이야기예요. 순전파는 여전히 아래층부터 차례로 해요.","**노드 단위 샘플링(Node-wise Sampling)**과 **레이어 단위 샘플링(Layer-wise Sampling)**의 장단점은 항상 짝으로 외우세요."]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.1958,0.0757],"c":[0.0011,0.0019,0.2198,0.1077],"r":3.6282,"img":"img/L4/walk/p037_h.jpg"},"parts":[{"b":[0.067,0.191,0.424,0.611],"c":[0.0458,0.1604,0.4664,0.6721],"r":1.2337,"img":"img/L4/walk/p037_12_01.jpg","say":"왼쪽 상자가 기여예요. 플러스가 붙은 줄이 셋이에요."},{"b":[0.509,0.191,0.424,0.611],"c":[0.4878,0.1604,0.4664,0.6721],"r":1.2337,"img":"img/L4/walk/p037_12_02.jpg","say":"오른쪽 상자가 한계예요. 마이너스가 붙은 줄이 둘인데 사실 한 가지 이야기예요."}]}},{"p":38,"title":"ASGCN: GCN 을 기댓값으로 다시 쓰기","terms":["ASGCN","GCN","Monte Carlo","Node-wise Sampling","Adjacency Matrix","Normalization"],"pass1":[{"kind":"say","lines":["**에이에스GCN(ASGCN)**은 **FastGCN**과 달리 버리지 않고 배우게 해요.","그 첫 단계로 우리가 아는 **GCN**을 기댓값 언어로 번역해요.","기댓값으로 써야 뽑아서 평균 내는 방법을 쓸 수 있거든요."]},{"kind":"analogy","head":"합계로 말하기와 평균으로 말하기","scene":"반 아이 네 명이 사탕을 0.4, 0.2, 0.2, 0 만큼 받았어요. '다 합쳐 0.8개'라고 말할 수도 있고, '0.8개를 네 명이 이 비율로 나눴다'고 말할 수도 있어요. 둘째 방식에는 '몇 명만 뽑아 평균을 내자'를 붙일 수 있어요.","map":[["다 합친 값","이웃 합"],["전체 크기와 나눈 비율","정규화 계수와 확률"],["몇 명만 뽑아 평균","**몬테카를로(Monte Carlo)** 추정"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.03,"y":0.145,"w":0.3,"h":0.045,"say":"큰 소제목: '노드 단위에서 레이어 단위로 넘어가기'.","c":[0.015,0.1125,0.33,0.11],"r":5.3333,"img":"img/L4/walk/p038_20_01.jpg"},{"x":0.3,"y":0.365,"w":0.36,"h":0.06,"say":"1번의 식. 정규화 계수 곱하기 기댓값 모양이에요.","c":[0.282,0.34,0.396,0.11],"r":6.4,"img":"img/L4/walk/p038_20_02.jpg"},{"x":0.1,"y":0.44,"w":0.3,"h":0.04,"say":"정규화 계수의 정의. **인접행렬(Adjacency Matrix)** 한 행을 다 더한 값이에요.","c":[0.085,0.405,0.33,0.11],"r":5.3333,"img":"img/L4/walk/p038_20_03.jpg"},{"x":0.1,"y":0.51,"w":0.5,"h":0.06,"say":"뽑을 확률의 정의. 행의 값을 그 합으로 나눈 것이에요.","c":[0.075,0.4844,0.55,0.1111],"r":8.8009,"img":"img/L4/walk/p038_20_04.jpg"},{"x":0.32,"y":0.755,"w":0.33,"h":0.075,"say":"2번의 식. 기댓값을 표본 몇 개의 평균으로 바꿨어요.","c":[0.3035,0.7375,0.363,0.11],"r":5.8667,"img":"img/L4/walk/p038_20_05.jpg"}]},{"kind":"formula","head":"기댓값으로 다시 쓴 GCN","tex":"h^{(l+1)}(v_i) = \\sigma_{W^{(l)}}\\left(N(v_i)\\ \\mathbb{E}_{p(u_j|v_i)}\\left[h^{(l)}(u_j)\\right]\\right)","parts":[{"sym":"v_i","say":"브이 아이. 위층의 대상 노드. 부모라고 불러요."},{"sym":"u_j","say":"유 제이. 아래층의 후보 이웃 노드. 자식이에요."},{"sym":"N(v_i)","say":"엔 오브 브이 아이. 인접행렬 한 행을 전부 더한 값, 즉 정규화 계수예요."},{"sym":"p(u_j|v_i)","say":"부모가 정해졌을 때 그 자식을 뽑을 확률이에요."},{"sym":"\\mathbb{E}_{p}[\\cdot]","say":"기댓값. 확률에 따른 평균값이에요."},{"sym":"\\sigma_{W^{(l)}}","say":"가중치 곱하기와 비선형을 한 기호로 줄여 쓴 것이에요."}],"whole":"이웃 합을 (정규화 계수) 곱하기 (확률에 따른 평균)으로 갈라 쓴 것이에요. 나누고 다시 곱했으니 값은 그대로예요."},{"kind":"formula","head":"뽑을 확률의 정의","tex":"p(u_j | v_i) = \\frac{\\hat{A}_{i,j}}{N(v_i)}, \\qquad N(v_i) = \\sum_{j=1}^{N} \\hat{A}_{i,j}","parts":[{"sym":"\\hat{A}_{i,j}","say":"에이햇 아이 제이. 정규화된 인접행렬의 $i$ 행 $j$ 열 값이에요."},{"sym":"\\sum_{j=1}^{N}","say":"그 행의 값을 모두 더하기예요."},{"sym":"N(v_i)","say":"그 합. 확률을 만들기 위한 **정규화(Normalization)** 계수예요."}],"whole":"행의 값을 그 행의 합으로 나누면 다 더해 1 이 되는 확률이 돼요. 그래야 기댓값이라고 부를 수 있어요."},{"kind":"steps","head":"표기만 바뀌었는지 검산해 봐요","steps":["1단계. 정규화 계수는 $0.4 + 0.2 + 0.2 + 0 = 0.8$ 이에요.","2단계. 확률은 $0.4/0.8 = 0.5$, $0.2/0.8 = 0.25$, $0.25$, $0$ 이에요.","3단계. 기댓값은 $0.5(2.0) + 0.25(1.0) + 0.25(3.0) = 2.0$ 이에요.","4단계. 정규화 계수를 곱하면 $0.8 \\times 2.0 = 1.6$ 이에요.","검산. 원래 식으로 하면 $0.4(2.0)+0.2(1.0)+0.2(3.0) = 1.6$ 이에요."],"answer":"같은 값이 나왔어요. 표기만 바꿨을 뿐 계산은 그대로라는 뜻이에요.","given":"부모의 인접행렬 행이 0.4, 0.2, 0.2, 0 이고 자식들의 값이 2.0, 1.0, 3.0, 5.0 이에요."},{"kind":"steps","head":"기댓값을 표본으로 바꾸면","steps":["확률 $0.5$, $0.25$, $0.25$, $0$ 에서 두 개를 뽑아요.","첫째와 첫째가 뽑히면 $(2.0 + 2.0)/2 = 2.0$ 이에요.","첫째와 둘째면 $(2.0 + 1.0)/2 = 1.5$ 예요.","첫째와 셋째면 $(2.0 + 3.0)/2 = 2.5$ 예요.","둘째와 셋째면 $(1.0 + 3.0)/2 = 2.0$ 이에요."],"answer":"참값 2.0 주위에서 널뛰어요. 그리고 이 확률표는 부모마다 다르다는 게 문제예요.","given":"같은 부모, 같은 값이고 표본은 두 개씩이에요."},{"kind":"points","head":"부모마다 다른 확률표가 문제예요","items":["다른 부모는 인접행렬의 다른 행을 쓰니 확률표도 달라요.","그래서 부모마다 따로 뽑아야 해요.","이것이 바로 **노드 단위 샘플링(Node-wise Sampling)**이에요.","부모가 많아지면 샘플링 횟수도 그만큼 늘고, 층이 깊어지면 또 곱해져요."]},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 **에이에스GCN(ASGCN)**이 왜 학습으로 가는지 설명했어요.","결국 노드 표현이 개입되니까 어려움이 생기는 것이래요.","노드 표현이 개입되면 그 값을 계속 다시 계산해야 하기 때문이고요.","그래서 학습 가능한 접근을 취하게 된다고요."]},{"kind":"warn","head":"같은 기호, 다른 뜻","items":["여기서 $N(v_i)$ 는 이웃 집합이 아니라 숫자예요. 앞쪽에서 쓰던 이웃 집합과 이름만 같아요.","모자 기호가 둘이에요. 인접행렬 위의 모자는 정규화, 뮤 위의 모자는 추정을 뜻해요.","부모와 자식은 계산 그래프에서 위와 아래를 가리키는 말이에요."]}],"pass3":[{"kind":"exam","src":"계산 문제로 나온다면","q":"Given a normalized adjacency row of 0.4, 0.2, 0.2 and 0, compute the normalization factor and the sampling probabilities.","qko":"정규화된 인접행렬의 한 행이 $0.4$, $0.2$, $0.2$, $0$ 일 때 정규화 계수와 뽑을 확률을 구하세요.","solve":["정규화 계수는 그 행을 전부 더한 값이에요.","$0.4 + 0.2 + 0.2 + 0 = 0.8$ 이에요.","확률은 각 값을 그 합으로 나눈 것이에요.","$0.4/0.8 = 0.5$, $0.2/0.8 = 0.25$ 예요."],"answer":"정규화 계수는 $0.8$, 확률은 $(0.5,\\ 0.25,\\ 0.25,\\ 0)$ 이에요."},{"kind":"english","head":"서술형에 쓸 한 줄","en":"Factoring out the row sum as a normalization factor turns the GCN update into an expectation of the child embedding.","ko":"행 합을 정규화 계수로 빼내면 GCN 갱신은 자식 임베딩의 기댓값이 된다.","tip":"and approximating it with Monte-Carlo samples recovers node-wise sampling 을 이어 붙이세요."},{"kind":"check","q":"이 쪽에서 확률표가 부모마다 다른 이유는?","choices":["층이 달라서","인접행렬의 행이 부모마다 달라서","가중치가 달라서","표본 수가 달라서"],"a":1,"why":"부모마다 자기 행을 쓰니 확률표도 달라요. 그래서 부모마다 따로 뽑아야 해요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.5528,0.1741],"c":[0,0.0019,0.6081,0.2061],"r":5.2454,"img":"img/L4/walk/p038_h.jpg"},"parts":[{"b":[0.07,0.21,0.16,0.04],"c":[0.05,0.175,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p038_12_01.jpg","say":"1번: '기댓값으로 본 **GCN**'. 가중치를 떼어 내고 다시 쓰는 이야기예요."},{"b":[0.07,0.6,0.22,0.04],"c":[0.058,0.565,0.244,0.11],"r":3.9434,"img":"img/L4/walk/p038_12_02.jpg","say":"2번: '**몬테카를로(Monte Carlo)** 추정, 노드 단위'. 표본으로 바꾸면 노드 단위가 나와요."}]}},{"p":39,"title":"전역 분포 하나로 층 전체가 공유해요","terms":["ASGCN","Importance Sampling","Layer-wise Sampling","Node-wise Sampling","FastGCN","Variance"],"pass1":[{"kind":"say","lines":["부모마다 따로 뽑던 것을 층 전체가 쓰는 분포 하나로 바꿔요.","그냥 바꾸면 틀리니까 원래 확률과의 비율을 곱해 보정해요.","이것이 노드 단위를 레이어 단위로 바꾸는 열쇠예요."]},{"kind":"analogy","head":"공용 간식 통에서 각자 다르게 덜어 먹기","scene":"학년 전체가 쓰는 간식 통을 하나 놓았어요. 그런데 아이마다 좋아하는 간식이 달라요. 그래서 통에서 꺼낸 간식마다 '이 아이가 원래 이걸 얼마나 좋아했는지'를 곱해 점수를 매겨요. 통은 하나인데 아이마다 다른 점수가 나오죠.","map":[["공용 간식 통","층 전체가 쓰는 전역 분포"],["원래 얼마나 좋아했는지","부모별 진짜 확률"],["아이마다 다른 점수","부모마다 다른 추정값"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.07,"y":0.21,"w":0.27,"h":0.04,"say":"소제목: '3. **중요도 샘플링(Importance Sampling)**으로 레이어 단위 만들기'.","c":[0.0565,0.175,0.297,0.11],"r":4.8,"img":"img/L4/walk/p039_20_01.jpg"},{"x":0.11,"y":0.275,"w":0.85,"h":0.1,"say":"본문: 부모마다 따로 뽑지 않고 층 전체에 대한 전역 샘플링 분포를 정의한다는 이야기예요.","c":[0.065,0.2305,0.935,0.1889],"r":8.7995,"img":"img/L4/walk/p039_20_02.jpg"},{"x":0.26,"y":0.415,"w":0.45,"h":0.075,"say":"식. 분자에 부모별 확률, 분모에 전역 분포가 있어요.","c":[0.2375,0.3975,0.495,0.11],"r":8.0,"img":"img/L4/walk/p039_20_03.jpg"},{"x":0.29,"y":0.565,"w":0.16,"h":0.27,"say":"그림의 층 이름 세 줄. 위에서부터 l+1, l, l-1 층이에요.","c":[0.27,0.549,0.2,0.302],"r":1.1773,"img":"img/L4/walk/p039_20_04.jpg"},{"x":0.56,"y":0.555,"w":0.14,"h":0.28,"say":"화살표가 위층 여러 노드에서 아래층의 같은 빨간 노드로 모여요.","c":[0.53,0.539,0.2,0.312],"r":1.1396,"img":"img/L4/walk/p039_20_05.jpg"}]},{"kind":"formula","head":"전역 분포로 바꾼 추정량","tex":"\\hat{\\mu}_q(v_i) = \\frac{1}{n}\\sum_{j=1}^{n} \\frac{p\\left(\\hat{u}_j \\mid v_i\\right)}{q\\left(\\hat{u}_j \\mid V_{upper}\\right)} h^{(l)}\\left(\\hat{u}_j\\right)","parts":[{"sym":"V_{upper}","say":"브이 어퍼. 위층에 있는 노드들 전체예요."},{"sym":"q(\\hat{u}_j \\mid V_{upper})","say":"큐. 층 전체가 공유하는 전역 제안 분포예요."},{"sym":"p(\\hat{u}_j \\mid v_i)","say":"피. 앞 쪽의 부모별 진짜 확률이에요."},{"sym":"\\frac{p}{q}","say":"중요도 가중치. 전역으로 뽑은 것을 부모별로 보정해요."},{"sym":"\\hat{\\mu}_q(v_i)","say":"뮤 햇 큐. 전역 분포로 뽑아 만든 추정값이에요."},{"sym":"n","say":"엔. 층에서 뽑는 표본 수예요."}],"whole":"층 전체가 같은 표본을 쓰지만, 분자에 부모별 확률이 살아 있어서 부모마다 다른 값이 나와요."},{"kind":"compare","head":"**FastGCN**과 구조를 비교하면","cols":["항목","FastGCN","ASGCN"],"rows":[["무엇으로 뽑나","노드별 고정 확률","위층 전체를 조건으로 한 전역 분포"],["무엇으로 나누나","그 뽑을 확률","그 전역 분포"],["분자에 무엇이 있나","연결 세기","부모별 진짜 확률"],["부모별로 값이 다른가","연결 세기로만","부모별 확률이 곱해져 다름"]]},{"kind":"steps","head":"두 부모가 표본 두 개를 함께 써 봐요","steps":["참값부터 구해요. 첫 부모는 $0.5(2.0)+0.25(1.0)+0.25(3.0) = 2.0$ 이에요.","둘째 부모는 $0.2(2.0)+0.2(1.0)+0.6(3.0) = 2.4$ 예요.","전역 분포를 두 확률의 평균 $0.35$, $0.225$, $0.425$, $0$ 으로 잡아요.","첫째와 셋째 노드가 뽑혔다고 해요.","첫 부모는 $\\frac{1}{2}(\\frac{0.5}{0.35}(2.0) + \\frac{0.25}{0.425}(3.0)) \\approx 2.31$ 이에요.","둘째 부모는 같은 표본으로 $\\frac{1}{2}(\\frac{0.2}{0.35}(2.0) + \\frac{0.6}{0.425}(3.0)) \\approx 2.69$ 예요."],"answer":"노드 두 개만 뽑아 함께 썼는데 부모마다 다른 값이 나왔어요. 분자의 부모별 확률 덕분이에요.","given":"부모 둘, 후보 자식 넷이고 자식 값은 2.0, 1.0, 3.0, 5.0 이에요."},{"kind":"points","head":"표본 수가 부모 수와 무관해져요","items":["**노드 단위 샘플링(Node-wise Sampling)**이면 부모마다 2 개씩 모두 4 개가 필요해요.","부모가 100 명이면 200 개예요.","**레이어 단위 샘플링(Layer-wise Sampling)**은 부모가 100 명이어도 2 개예요.","여기서 지수적 증가가 사라져요."]},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 레이어 단위 샘플링을 이렇게 정리했어요.","레이어마다 전체 엣지를 다 쓰지 않고 일부를 샘플링해서 쓴대요.","어떤 엣지를 뽑을지는 특정 확률분포를 따라 정하겠다는 생각이고요.","그 확률분포를 어떻게 정하느냐가 학습 결과와 성능에 큰 영향을 준다고요."]},{"kind":"warn","head":"분자와 분모의 조건이 달라요","items":["분자의 확률은 부모 하나가 조건이고, 분모의 확률은 위층 전체가 조건이에요.","이 차이가 부모마다 다른 값이 나오는 이유예요.","전역 분포를 써도 답이 틀리지 않아요. 달라지는 건 **분산(Variance)**이에요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"ASGCN replaces the per-parent conditional distribution with a single global distribution shared by the whole layer.","ko":"ASGCN 은 부모별 조건부 분포를 층 전체가 공유하는 하나의 전역 분포로 바꾼다.","tip":"and compensates with the importance weight 를 이어 붙이세요."},{"kind":"check","q":"전역 분포로 뽑은 뒤 무엇을 곱해 보정하나요?","choices":["층 수","부모별 확률과 전역 확률의 비율","인접행렬","배치 크기"],"a":1,"why":"부모별 확률을 전역 확률로 나눈 중요도 가중치를 곱해요. 그래서 답이 틀리지 않아요."},{"kind":"warn","head":"기호에서 헷갈리기 쉬운 곳","items":["그림의 빨간 테두리는 '선택됨'이라는 표시이지 특별한 종류의 노드가 아니에요.","모자가 붙은 유는 실제로 뽑힌 노드예요. 후보 전체를 뜻하는 유와 구별하세요.","이 쪽의 $n$ 은 표본 수이고, 앞 쪽의 정규화 계수와는 아무 상관이 없어요."]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.9251,0.3847],"c":[0,0,1,0.4232],"r":4.2008,"img":"img/L4/walk/p039_h.jpg"},"parts":[{"b":[0.56,0.555,0.14,0.28],"c":[0.53,0.539,0.2,0.312],"r":1.1396,"img":"img/L4/walk/p039_12_01.jpg","say":"가운데 층과 아래 층에 빨간 테두리가 그려진 동그라미가 뽑힌 노드예요."},{"b":[0.465,0.655,0.11,0.1],"c":[0.42,0.639,0.2,0.132],"r":2.6936,"img":"img/L4/walk/p039_12_02.jpg","say":"화살표 옆 조건에 위층 노드가 여러 개 나열돼 있어요. 위층 전체를 보고 정한다는 뜻이에요."}]}},{"p":40,"title":"분산을 최소로 만드는 샘플러 유도","terms":["ASGCN","Variance","Cauchy-Schwarz","Proposal Distribution","Importance Sampling","FastGCN"],"pass1":[{"kind":"say","lines":["전역 분포를 아무렇게나 고르면 **분산(Variance)**이 폭발해요.","위층 노드 전체의 총 분산을 가장 작게 만드는 분포를 구해요.","**코시-슈바르츠(Cauchy-Schwarz)** 부등식을 쓰면 제곱근에 비례하는 답이 나와요."]},{"kind":"analogy","head":"용돈을 어떻게 나눠야 손해가 적을까","scene":"민수가 용돈 1만원을 세 가지 준비물에 나눠 써야 해요. 한 곳에 다 몰아주면 나머지 둘을 못 사서 크게 손해예요. 똑같이 나누면 가장 중요한 준비물이 모자라요. 중요한 쪽에 조금 더 주되 나머지도 버리지 않는 지점이 가장 나아요.","map":[["용돈 1만원","다 더해 1 이 되는 확률"],["한 곳에 몰아주기","중요한 노드만 뽑기"],["가장 손해 적은 지점","제곱근에 비례하는 분포"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.07,"y":0.21,"w":0.2,"h":0.04,"say":"1번: '중요도 샘플링의 분산 문제'.","c":[0.058,0.175,0.224,0.11],"r":3.6202,"img":"img/L4/walk/p040_20_01.jpg"},{"x":0.11,"y":0.275,"w":0.85,"h":0.07,"say":"본문: 분포를 아무렇게나 고르면 추정량의 분산이 극단적으로 커져 학습이 흔들린다는 이야기예요.","c":[0.065,0.2155,0.935,0.1889],"r":8.7995,"img":"img/L4/walk/p040_20_02.jpg"},{"x":0.07,"y":0.37,"w":0.2,"h":0.04,"say":"2번: '최적 샘플러 유도'. 안정성을 얻으려면 총 분산을 최소로 해야 한대요.","c":[0.058,0.335,0.224,0.11],"r":3.6202,"img":"img/L4/walk/p040_20_03.jpg"},{"x":0.11,"y":0.635,"w":0.76,"h":0.04,"say":"'**코시-슈바르츠(Cauchy-Schwarz)** 부등식을 쓰면 분자의 제곱근에 비례한다'.","c":[0.072,0.5706,0.836,0.1689],"r":8.7994,"img":"img/L4/walk/p040_20_04.jpg"},{"x":0.29,"y":0.72,"w":0.36,"h":0.15,"say":"최적 샘플러 식. 위는 루트, 아래는 전체 합이에요.","c":[0.272,0.704,0.396,0.182],"r":3.8681,"img":"img/L4/walk/p040_20_05.jpg"}]},{"kind":"formula","head":"최적 레이어 단위 샘플러","tex":"q^*\\left(u_j\\right) = \\frac{\\sqrt{\\sum_{i=1}^{n} p\\left(u_j \\mid v_i\\right)^2 \\left\\|h^{(l)}\\left(u_j\\right)\\right\\|^2}}{\\sum_{k=1}^{N}\\sqrt{\\sum_{i=1}^{n} p\\left(u_k \\mid v_i\\right)^2 \\left\\|h^{(l)}(u_k)\\right\\|^2}}","parts":[{"sym":"\\sum_{i=1}^{n}","say":"시그마 아이. 위층 부모 노드 전체에 대해 더하기예요."},{"sym":"p(u_j \\mid v_i)^2","say":"부모가 그 자식을 볼 확률의 제곱이에요."},{"sym":"\\left\\|h^{(l)}(u_j)\\right\\|^2","say":"그 노드 값의 길이의 제곱이에요."},{"sym":"\\sqrt{\\ \\cdot\\ }","say":"루트. 제곱근이에요."},{"sym":"\\sum_{k=1}^{N}","say":"시그마 케이. 분모의 정규화 합이에요."},{"sym":"q^*","say":"큐 스타. 분산을 가장 작게 만드는 분포예요."}],"whole":"부모들이 그 자식을 볼 확률의 제곱과 값 크기의 제곱을 곱해 더한 뒤 루트를 씌우고, 전체 합으로 나눠 확률로 만들어요."},{"kind":"points","head":"분산 식을 읽는 법","items":["대괄호 안의 값을 그 노드의 중요도라고 불러 볼게요.","총 분산은 그 중요도를 뽑힐 확률로 나눈 것들의 합이에요.","확률이 분모에 있으니, 중요한 노드에 확률을 작게 주면 분산이 폭발해요.","중요한 노드를 안 뽑으면 크게 손해라는 직관과 딱 맞아요."]},{"kind":"points","head":"왜 하필 제곱근일까요","items":["다 더해 1 이라는 조건 아래에서 그 합을 최소로 만드는 문제예요.","**코시-슈바르츠(Cauchy-Schwarz)** 부등식을 쓰면 답이 나와요.","중요도의 제곱근에 비례할 때 최소가 돼요.","부등식 증명은 외우지 않아도 돼요. 제곱근이라는 결론만 기억하세요."]},{"kind":"steps","head":"최적 샘플러를 직접 만들어 봐요","steps":["1단계. 중요도를 구해요. 첫 노드는 $(0.6^2 + 0.2^2) \\times 2^2 = 0.40 \\times 4 = 1.60$ 이에요.","둘째는 $(0.4^2 + 0.2^2) \\times 1 = 0.20$ 이에요.","셋째는 $(0 + 0.6^2) \\times 1 = 0.36$ 이에요.","2단계. 루트를 씌워요. $\\sqrt{1.60} \\approx 1.265$, $\\sqrt{0.20} \\approx 0.447$, $\\sqrt{0.36} = 0.600$ 이에요.","3단계. 합 $2.312$ 로 나눠요.","$\\approx 0.547$, $0.193$, $0.260$ 이고 다 더하면 1 이에요."],"answer":"중요도는 1.60 대 0.20 으로 8 배 차이였는데, 루트를 씌우니 2.8 배로 완만해졌어요.","given":"부모 둘, 자식 셋. 확률은 위 행이 0.6, 0.4, 0 이고 아래 행이 0.2, 0.2, 0.6, 값 길이는 2, 1, 1 이에요."},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 최적 분포에 대해 이렇게 말했어요.","**몬테카를로(Monte Carlo)**를 쓰니 최적 확률분포를 계산할 수 있대요.","그런데 그 자체를 구하는 건 복잡도가 높거나 불가능해서 근사를 하게 된다고요.","그 근사에도 수학적으로 최적의 지점이 있다고 했어요."]},{"kind":"warn","head":"두 모델의 결론 모양이 달라요","items":["**FastGCN**의 최적 분포는 크기에 비례해요.","**에이에스GCN(ASGCN)**의 최적 분포는 제곱합의 제곱근에 비례해요.","상수 항은 뽑기 확률과 상관없는 항이라 최소화할 때 무시해요. 빼는 부호에 당황하지 마세요."]}],"pass3":[{"kind":"exam","src":"계산 문제로 나온다면","q":"If the numerators inside the square root are 1.60, 0.20 and 0.36, compute the optimal sampler.","qko":"루트 안의 값이 $1.60$, $0.20$, $0.36$ 일 때 최적 샘플러를 구하세요.","solve":["먼저 각 값에 루트를 씌워요.","$\\sqrt{1.60} \\approx 1.265$, $\\sqrt{0.20} \\approx 0.447$, $\\sqrt{0.36} = 0.600$ 이에요.","세 값을 더하면 $2.312$ 예요.","각각을 그 합으로 나눠요."],"answer":"$q^* \\approx (0.547,\\ 0.193,\\ 0.260)$ 이에요."},{"kind":"english","head":"서술형에 쓸 한 줄","en":"Applying the Cauchy-Schwarz inequality, the variance-minimizing layer-wise sampler is proportional to the square root of the numerator.","ko":"코시-슈바르츠 부등식을 적용하면, 분산을 최소로 하는 레이어 단위 샘플러는 분자의 제곱근에 비례한다.","tip":"Cauchy-Schwarz 철자를 그대로 외워 두세요."},{"kind":"check","q":"제곱근을 씌우면 어떤 효과가 있나요?","choices":["큰 값이 더 커진다","큰 값과 작은 값의 격차가 완만해진다","확률이 0 이 된다","합이 1 이 된다"],"a":1,"why":"8 배 차이가 2.8 배로 줄어요. 중요한 노드를 더 뽑되 나머지도 버리지 않는 균형점이에요."},{"kind":"warn","head":"아래첨자를 반드시 확인하세요","items":["시그마 아이는 부모에 대한 합이고, 시그마 제이와 시그마 케이는 후보 자식에 대한 합이에요.","식 안에 노드 값의 길이가 들어 있어요. 이것 때문에 다음 쪽의 문제가 생겨요.","**제안 분포(Proposal Distribution)**는 확률이니 언제나 다 더해 1 이 되어야 해요."]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.8923,0.4651],"c":[0,0,0.9815,0.5116],"r":3.4107,"img":"img/L4/walk/p040_h.jpg"},"parts":[{"b":[0.19,0.485,0.55,0.09],"c":[0.1625,0.4689,0.605,0.1222],"r":8.8016,"img":"img/L4/walk/p040_12_01.jpg","say":"위 식이 총 **분산(Variance)**이에요. 대괄호 안의 값이 클수록 분산이 커져요."},{"b":[0.29,0.72,0.36,0.15],"c":[0.272,0.704,0.396,0.182],"r":3.8681,"img":"img/L4/walk/p040_12_02.jpg","say":"아래 식이 최적 샘플러예요. 분자에 루트가 씌워져 있어요."}]}},{"p":41,"title":"구할 수 없으니 배우게 해요","terms":["ASGCN","FastGCN","Variance","Proposal Distribution","Layer-wise Sampling"],"pass1":[{"kind":"say","lines":["최적 분포를 구하려면 중간 층의 값이 필요해요.","그런데 뽑기는 위에서 아래로 가고 값은 아래에서 위로 만들어져요.","순서가 안 맞아요. 그래서 **에이에스GCN(ASGCN)**은 뽑기 확률을 학습으로 배워요."]},{"kind":"analogy","head":"장 보러 가기 전에 요리 맛을 알고 싶다면","scene":"민수가 장을 보기 전에 '어떤 재료가 맛에 가장 큰 영향을 줄까'를 알고 싶어요. 그런데 맛은 요리를 다 만든 뒤에야 알 수 있죠. 재료를 고르는 순간에는 아직 맛이 없어요. 그래서 요리할 때마다 맛을 기록해 두고 조금씩 배워 가기로 해요.","map":[["재료 고르기","위에서 아래로 뽑기"],["요리 뒤에야 아는 맛","아래에서 위로 만들어지는 값"],["기록하며 배우기","학습 가능한 뽑기 확률"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.11,"y":0.275,"w":0.85,"h":0.11,"say":"본문: 샘플링은 출력층에서 입력층으로 가고, 활성값은 순전파로 만들어진다는 이야기예요.","c":[0.065,0.2355,0.935,0.1889],"r":8.7995,"img":"img/L4/walk/p041_20_01.jpg"},{"x":0.11,"y":0.485,"w":0.85,"h":0.08,"say":"해법: 뽑기 확률을 가벼운 학습 가능 자기 의존 함수로 모형화한대요.","c":[0.065,0.4305,0.935,0.1889],"r":8.7995,"img":"img/L4/walk/p041_20_02.jpg"},{"x":0.36,"y":0.635,"w":0.25,"h":0.085,"say":"손실 식. 원래 손실에 분산 벌점을 더했어요.","c":[0.3475,0.619,0.275,0.117],"r":4.1785,"img":"img/L4/walk/p041_20_03.jpg"},{"x":0.11,"y":0.745,"w":0.52,"h":0.075,"say":"마지막: 이 합친 손실로 역전파하면 최적 분포를 학습 중에 흉내 낸다고요.","c":[0.084,0.7247,0.572,0.1156],"r":8.7966,"img":"img/L4/walk/p041_20_04.jpg"}]},{"kind":"steps","head":"순서를 따라가 보면 왜 막히는지 보여요","steps":["1. 먼저 맨 위 출력층에서 대상 노드들을 정해요.","2. 그 노드들을 보고 바로 아래층에서 무엇을 뽑을지 정해요. 여기서 확률이 필요해요.","3. 또 그 아래층에서 뽑고, 맨 아래 입력층까지 내려가요.","4. 이제 아래에서 위로 실제 값을 계산해요. 여기서 값이 만들어져요.","2 번에서 확률이 필요한데 최적 분포는 4 번에서야 나오는 값을 요구해요."],"answer":"닭이 먼저냐 달걀이 먼저냐예요. 영어 제목의 'Inconsistency' 가 이 앞뒤 순서 불일치를 가리켜요.","given":"층이 세 개인 네트워크라고 해요."},{"kind":"figure","head":"샘플링과 활성값의 방향","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"240\" y=\"26\" font-size=\"16\" text-anchor=\"middle\">순서가 서로 어긋나요<\/text>\n<rect class=\"box\" x=\"140\" y=\"46\" width=\"200\" height=\"34\" rx=\"10\"/>\n<text class=\"t\" x=\"240\" y=\"68\" font-size=\"14\" text-anchor=\"middle\">출력층 (l+1)<\/text>\n<rect class=\"box\" x=\"140\" y=\"110\" width=\"200\" height=\"34\" rx=\"10\"/>\n<text class=\"t\" x=\"240\" y=\"132\" font-size=\"14\" text-anchor=\"middle\">중간층 (l)<\/text>\n<rect class=\"box\" x=\"140\" y=\"174\" width=\"200\" height=\"34\" rx=\"10\"/>\n<text class=\"t\" x=\"240\" y=\"196\" font-size=\"14\" text-anchor=\"middle\">입력층 (l-1)<\/text>\n<line class=\"e2 b1\" x1=\"112\" y1=\"56\" x2=\"112\" y2=\"196\"/>\n<polygon class=\"arrow b1\" points=\"106,196 118,196 112,210\"/>\n<text class=\"tm b1\" x=\"58\" y=\"120\" font-size=\"13\" text-anchor=\"middle\">샘플링은<\/text>\n<text class=\"tm b1\" x=\"58\" y=\"140\" font-size=\"13\" text-anchor=\"middle\">위에서 아래로<\/text>\n<line class=\"e2 b2\" x1=\"368\" y1=\"198\" x2=\"368\" y2=\"58\"/>\n<polygon class=\"arrow b2\" points=\"362,58 374,58 368,44\"/>\n<text class=\"tm b2\" x=\"424\" y=\"120\" font-size=\"13\" text-anchor=\"middle\">활성값은<\/text>\n<text class=\"tm b2\" x=\"424\" y=\"140\" font-size=\"13\" text-anchor=\"middle\">아래에서 위로<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"238\" font-size=\"15\" text-anchor=\"middle\">최적 분포는 활성값이 필요한데 늦게 생겨요<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"262\" font-size=\"14\" text-anchor=\"middle\">그래서 뽑기 확률을 학습으로 배우게 해요<\/text>\n<\/svg>","caption":"이 순서 문제 때문에 최적 분포를 샘플링 단계에서 계산할 수 없어요.","builds":3},{"kind":"formula","head":"분산을 벌점으로 더한 손실","tex":"\\mathcal{L}_{total} = \\mathcal{L}_{task} + \\lambda \\sum_{l=1}^{L} \\mathrm{Var}_{q_\\theta}^{(l)}","parts":[{"sym":"\\mathcal{L}_{total}","say":"엘 토털. 최종 손실이에요."},{"sym":"\\mathcal{L}_{task}","say":"엘 태스크. 원래 하려던 일의 손실, 예를 들어 노드 분류 오차예요."},{"sym":"\\lambda","say":"람다. 벌점의 세기를 정하는 값이에요. 사람이 정해요."},{"sym":"\\sum_{l=1}^{L}","say":"모든 층에 대해 더하기예요."},{"sym":"\\mathrm{Var}_{q_\\theta}^{(l)}","say":"층 $l$ 에서 샘플러가 실제로 만든 **분산(Variance)**이에요."},{"sym":"q_\\theta","say":"큐 세타. 파라미터로 만들어지는 학습되는 뽑기 확률이에요."}],"whole":"모델에게 두 가지 목표를 동시에 줘요. 분류도 잘하고, 네가 뽑는 방식이 널뛰지도 않게 하라는 거예요."},{"kind":"points","head":"자기 의존이 무슨 뜻인가요","items":["뽑기 확률을 만들 때 위층 임베딩을 보지 않는다는 뜻이에요.","노드 자기 자신의 입력 특징만 보고 만들어요.","그러면 위에서 아래로 내려가는 도중에도 바로 계산할 수 있어요.","순서 문제를 정면으로 푸는 게 아니라 우회하는 방법이에요."]},{"kind":"steps","head":"벌점 세기가 학습을 어떻게 끌고 가나요","steps":["균등한 샘플러는 과제 손실 0.40, 분산 1.20 이라 합이 $0.40 + 0.60 = 1.00$ 이에요.","조금 치우친 샘플러는 0.38 과 0.60 이라 합이 $0.68$ 이에요.","최적에 가까운 샘플러는 0.37 과 0.20 이라 합이 $0.47$ 이에요.","극단적으로 치우친 샘플러는 0.52 와 0.10 이라 합이 $0.57$ 이에요.","가장 작은 것은 0.47 이라 학습은 그쪽으로 가요."],"answer":"극단 샘플러는 분산이 가장 작은데도 과제 손실이 커져서 졌어요. 균형이 손실 식에 들어 있는 거예요.","given":"벌점 세기를 0.5 로 두었어요."},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 두 모델의 차이를 여기서 확실히 갈랐어요.","**FastGCN**은 최적 분포를 근사하는 방법이래요.","**에이에스GCN(ASGCN)**은 그 근사조차 힘드니 학습 가능한 접근을 취한다고요.","왜 힘드냐면 노드 표현이 개입되면 계속 다시 계산해야 하기 때문이라고 했어요."]},{"kind":"warn","head":"말뜻을 정확히","items":["'Inconsistency' 를 '값이 틀리다'로 읽지 마세요. 계산 순서가 안 맞는다는 뜻이에요.","벌점 세기는 학습되지 않아요. 사람이 정하는 하이퍼파라미터예요.","벌점을 더한다고 정확히 최적 분포가 되지는 않아요. 닮아 간다는 정도예요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"The optimal sampler cannot be computed during sampling, because sampling runs top-down while activations are produced bottom-up.","ko":"최적 샘플러는 샘플링이 위에서 아래로 가는 반면 활성값은 아래에서 위로 만들어져서 계산할 수 없다.","tip":"top-down 과 bottom-up 을 대비시키는 문장이에요."},{"kind":"english","head":"해법까지 한 줄 더","en":"ASGCN models the sampler as a lightweight learnable self-dependent function and adds its empirical variance as a penalty to the task loss.","ko":"ASGCN 은 샘플러를 가벼운 학습 가능 자기 의존 함수로 모형화하고, 경험적 분산을 과제 손실에 벌점으로 더한다.","tip":"so backpropagation tunes it to mimic the optimal sampler 로 마무리하면 만점이에요."},{"kind":"exam","src":"두 모델의 차이를 쓰라고 하면","q":"What is the difference between FastGCN and ASGCN?","qko":"**FastGCN**과 **에이에스GCN(ASGCN)**의 차이는 무엇인가요?","solve":["먼저 무엇을 최적화하려는지는 같다고 말해요. 둘 다 분산을 줄이려는 거예요.","**FastGCN**은 최적 분포를 고정된 값으로 근사해요. 정규화된 열 노름이죠.","**에이에스GCN(ASGCN)**은 그것을 학습으로 배워요.","그리고 ASGCN 의 분포는 위층 전체를 조건으로 삼아요."],"answer":"FastGCN approximates the optimal distribution by a fixed normalized column norm, while ASGCN learns it."},{"kind":"check","q":"벌점 세기를 너무 크게 잡으면 어떻게 되나요?","choices":["분산만 중시해 과제 성능이 나빠진다","학습이 빨라진다","분산이 0 이 된다","아무 변화 없다"],"a":0,"why":"분산만 보고 극단적인 샘플러를 고르게 돼요. 적당한 값을 실험으로 정해야 해요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.5528,0.1741],"c":[0,0.0019,0.6081,0.2061],"r":5.2454,"img":"img/L4/walk/p041_h.jpg"},"parts":[{"b":[0.07,0.21,0.18,0.04],"c":[0.058,0.175,0.204,0.11],"r":3.297,"img":"img/L4/walk/p041_12_01.jpg","say":"3번: '계산 불가라는 딜레마'. 왜 최적 분포를 못 쓰는지예요."},{"b":[0.07,0.425,0.12,0.04],"c":[0.03,0.39,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p041_12_02.jpg","say":"4번: '적응적 해법'. 그래서 무엇을 하는지예요."}]}},{"p":42,"title":"건너뛰기 연결로 멀리까지 보내요","terms":["ASGCN","Skip Connection","Over-smoothing","Receptive Field","GCN","Variance"],"pass1":[{"kind":"say","lines":["멀리 있는 노드끼리 메시지를 보내려면 층을 많이 쌓아야 해요.","그런데 깊게 쌓으면 **분산(Variance)**이 커지고 **과평활(Over-smoothing)**이 와요.","**에이에스GCN(ASGCN)**은 두 층 아래를 바로 잇는 지름길을 넣어요."]},{"kind":"analogy","head":"계단과 엘리베이터","scene":"5층 교실에 가려면 계단을 한 층씩 다섯 번 올라야 해요. 오래 걸리고 다리도 아프죠. 그런데 두 층씩 서는 엘리베이터가 생기면 같은 시간에 두 배 높이 갈 수 있어요. 더 좋은 건 이미 있는 통로를 쓴다는 점이에요.","map":[["계단 한 칸","GNN 한 층이 보는 1홉"],["두 층씩 서는 엘리베이터","**건너뛰기 연결(Skip Connection)**"],["이미 있는 통로","이미 뽑아 둔 노드들"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.11,"y":0.275,"w":0.85,"h":0.11,"say":"본문: 깊게 쌓으면 분산이 커지고 **과평활(Over-smoothing)**로 성능이 나빠진다는 이야기예요.","c":[0.065,0.2355,0.935,0.1889],"r":8.7995,"img":"img/L4/walk/p042_20_01.jpg"},{"x":0.11,"y":0.52,"w":0.55,"h":0.07,"say":"해법: 두 층 사이를 바로 잇는 지름길을 넣어 순전파를 바꾼다고요.","c":[0.0825,0.4939,0.605,0.1222],"r":8.8016,"img":"img/L4/walk/p042_20_02.jpg"},{"x":0.24,"y":0.615,"w":0.45,"h":0.055,"say":"식. 두 집계 결과를 더한 뒤 비선형을 씌워요.","c":[0.2175,0.5875,0.495,0.11],"r":8.0,"img":"img/L4/walk/p042_20_03.jpg"}]},{"kind":"points","head":"먼저 용어 세 개를 정리해요","items":["**건너뛰기 연결(Skip Connection)**은 한 층을 건너뛰어 앞뒤를 직접 잇는 지름길이에요.","잔차 연결도 비슷한 아이디어예요.","**과평활(Over-smoothing)**은 층이 깊어질수록 모든 노드 임베딩이 비슷해지는 현상이에요.","이 세 가지는 5주차에 자세히 배워요."]},{"kind":"formula","head":"건너뛰기 연결이 들어간 순전파","tex":"h^{(l+1)}(v_i) = \\sigma\\left(\\mathrm{Aggregate}\\left(h^{(l)}\\right) + \\mathrm{Aggregate}\\left(h^{(l-1)}\\right)\\right)","parts":[{"sym":"h^{(l)}","say":"에이치 엘. 바로 아래층 임베딩, 즉 1홉 정보예요."},{"sym":"h^{(l-1)}","say":"에이치 엘 마이너스 원. 두 층 아래 임베딩, 즉 2홉 정보예요."},{"sym":"\\mathrm{Aggregate}(\\cdot)","say":"애그리게이트. 이웃 집계예요."},{"sym":"+","say":"두 경로의 정보를 더해 합치기예요."},{"sym":"\\sigma","say":"비선형 함수예요."}],"whole":"원래 **GCN**은 바로 아래층만 봤어요. 여기에 두 층 아래에서 바로 모은 것을 하나 더 더해요."},{"kind":"steps","head":"수용 영역이 어떻게 바뀌나요","steps":["건너뛰기가 없으면 한 층이 1홉이에요. 2층이면 2홉, 3층이면 3홉이에요.","건너뛰기가 있으면 한 층에서 최대 2홉을 건널 수 있어요.","2층이면 최대 4홉, 3층이면 최대 6홉, 4층이면 최대 8홉이에요.","같은 층 수로 두 배 멀리 볼 수 있어요.","바꿔 말하면 같은 거리를 보는 데 층을 절반만 쌓아도 돼요."],"answer":"층이 얕으면 **과평활(Over-smoothing)**도 덜 일어나요. 이게 이 장치를 넣는 이유예요.","given":"**수용 영역(Receptive Field)**은 한 노드에 영향을 주는 노드들의 범위였죠."},{"kind":"figure","head":"지름길이 생기면","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"240\" y=\"26\" font-size=\"16\" text-anchor=\"middle\">건너뛰기 연결이 하는 일<\/text>\n<rect class=\"box\" x=\"150\" y=\"44\" width=\"180\" height=\"32\" rx=\"10\"/>\n<text class=\"t\" x=\"240\" y=\"65\" font-size=\"14\" text-anchor=\"middle\">(l+1) 번째 층<\/text>\n<rect class=\"box\" x=\"150\" y=\"112\" width=\"180\" height=\"32\" rx=\"10\"/>\n<text class=\"t\" x=\"240\" y=\"133\" font-size=\"14\" text-anchor=\"middle\">l 번째 층<\/text>\n<rect class=\"box\" x=\"150\" y=\"180\" width=\"180\" height=\"32\" rx=\"10\"/>\n<text class=\"t\" x=\"240\" y=\"201\" font-size=\"14\" text-anchor=\"middle\">(l-1) 번째 층<\/text>\n<line class=\"e2 b1\" x1=\"250\" y1=\"112\" x2=\"250\" y2=\"84\"/>\n<polygon class=\"arrow b1\" points=\"244,84 256,84 250,72\"/>\n<text class=\"tm b1\" x=\"300\" y=\"100\" font-size=\"13\">1홉<\/text>\n<line class=\"e2 b1\" x1=\"200\" y1=\"180\" x2=\"200\" y2=\"152\"/>\n<polygon class=\"arrow b1\" points=\"194,152 206,152 200,140\"/>\n<text class=\"tm b1\" x=\"118\" y=\"168\" font-size=\"13\">1홉<\/text>\n<path class=\"e2 b2\" d=\"M150,198 C78,182 78,80 218,74\" fill=\"none\"/>\n<polygon class=\"arrow b2\" points=\"218,68 218,80 230,74\"/>\n<text class=\"tb b2\" x=\"56\" y=\"118\" font-size=\"14\">건너뛰기<\/text>\n<text class=\"tb b2\" x=\"56\" y=\"138\" font-size=\"14\">2홉<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"240\" font-size=\"15\" text-anchor=\"middle\">한 층에서 1홉과 2홉을 함께 받아요<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"262\" font-size=\"14\" text-anchor=\"middle\">이미 뽑아 둔 노드라 뽑는 비용은 0 이에요<\/text>\n<\/svg>","caption":"한 층에서 1홉 정보와 2홉 정보를 함께 받아요. 이것이 고차 구조를 잡는다는 말의 뜻이에요.","builds":3},{"kind":"steps","head":"한 층을 숫자로 계산해 봐요","steps":["건너뛰기가 없으면 바로 아래층 집계 결과만 써요.","$\\mathrm{ReLU}(0.6) = 0.6$ 이에요.","건너뛰기가 있으면 두 층 아래 집계 결과도 더해요.","$\\mathrm{ReLU}(0.6 + 0.3) = \\mathrm{ReLU}(0.9) = 0.9$ 예요."],"answer":"값이 커졌을 뿐 아니라 그 안에 2홉 이웃의 정보가 섞여 들어왔어요.","given":"바로 아래층 집계가 0.6, 두 층 아래 집계가 0.3 이고 비선형은 ReLU 예요."},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 이 부분을 가볍게 짚고 넘어갔어요.","**에이에스GCN(ASGCN)**이 한 가지 더 넣은 것이 스킵 커넥션이래요.","스킵 커넥션과 잔차 연결은 다음 시간(5주차)에 자세히 배운다고요.","GNN 에서 비중 있게 다뤄지는 이유는 **과평활(Over-smoothing)**이 심각하기 때문이라고요."]},{"kind":"mining","src":"마이닝 11강 High-order Proximity GRL","lines":["슬라이드가 말한 '다중 홉 랜덤워크를 미리 계산하는 다른 방법'이 마이닝 내용이에요.","몇 다리 건너 얼마나 가까운지를 재는 Katz 지수나 Adamic-Adar 를 배웠죠.","문제는 인접행렬의 거듭제곱을 계산해야 하고 그 결과가 빽빽해진다는 점이에요.","0 이 사라지면서 메모리가 폭발해요. 그게 전처리 부담이라는 말이에요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"Standard GCNs need many layers to reach distant nodes, but stacking deeper increases variance and causes over-smoothing.","ko":"표준 GCN 은 멀리 있는 노드에 닿으려면 층을 많이 쌓아야 하는데, 깊게 쌓으면 분산이 커지고 과평활이 생긴다.","tip":"over-smoothing 철자를 그대로 외워 두세요."},{"kind":"english","head":"해법까지 한 줄 더","en":"ASGCN adds a skip connection from the layer two steps below, so a single layer receives both one-hop and two-hop information.","ko":"ASGCN 은 두 층 아래에서 오는 건너뛰기 연결을 넣어, 한 층이 1홉 정보와 2홉 정보를 함께 받게 한다.","tip":"one-hop 과 two-hop 을 함께 쓰는 게 핵심이에요."},{"kind":"check","q":"**건너뛰기 연결(Skip Connection)**은 **에이에스GCN(ASGCN)**의 무엇인가요?","choices":["핵심 샘플링 기법","부가 장치","손실 함수","정규화 방법"],"a":1,"why":"부가 장치예요. ASGCN 의 핵심은 여전히 학습 가능한 적응적 레이어 단위 샘플러예요."},{"kind":"warn","head":"여기서 헷갈리기 쉬운 곳","items":["두 층 사이를 잇는다는 것은 한 층이 아니라 두 층을 건너뛴다는 뜻이에요.","두 집계는 같은 함수가 아니에요. 각각 그 층에 맞는 인접행렬 부분을 써요.","과평활과 잔차 연결은 5주차 주제예요. 여기서는 왜 필요한지만 알면 충분해요."]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.5528,0.1741],"c":[0,0.0019,0.6081,0.2061],"r":5.2454,"img":"img/L4/walk/p042_h.jpg"},"parts":[{"b":[0.07,0.21,0.24,0.04],"c":[0.058,0.175,0.264,0.11],"r":4.2667,"img":"img/L4/walk/p042_12_01.jpg","say":"1번: '먼 곳까지 메시지를 보내야 하는 이유'."},{"b":[0.07,0.455,0.22,0.045],"c":[0.058,0.4225,0.244,0.11],"r":3.9434,"img":"img/L4/walk/p042_12_02.jpg","say":"2번: '레이어 단위 건너뛰기 연결'. 바로 아래에 식이 있어요."}]}},{"p":43,"title":"2차 근접성을 공짜로 얻어요","terms":["ASGCN","Skip Connection","Second-order Proximity","Layer-wise Sampling","Node-wise Sampling","GraphSAGE","Cluster-GCN","GraphSAINT"],"pass1":[{"kind":"say","lines":["두 층 아래 노드는 위층 노드에게 정확히 2홉 이웃이에요.","그 노드들은 이미 뽑아서 계산해 둔 것이라 다시 뽑을 필요가 없어요.","그래서 **건너뛰기 연결(Skip Connection)**의 샘플링 비용이 0 이에요."]},{"kind":"analogy","head":"이미 사 둔 재료로 한 그릇 더","scene":"민수가 저녁 준비를 하면서 재료를 이미 다 사 왔어요. 그런데 한 그릇을 더 만들기로 했어요. 재료는 이미 부엌에 있으니 장을 다시 보러 갈 필요가 없죠. 늘어나는 건 그릇을 하나 더 꺼내는 수고뿐이에요.","map":[["이미 사 둔 재료","이미 뽑아 둔 두 층 아래 노드"],["장을 다시 안 봐도 됨","샘플링 비용이 0"],["그릇 하나 더 꺼내기","덧셈 한 번 늘어남"]]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.29,"y":0.615,"w":0.16,"h":0.25,"say":"아래 그림의 층 이름 세 줄이에요. 위에서부터 l+1, l, l-1 층이에요.","c":[0.27,0.599,0.2,0.282],"r":1.2608,"img":"img/L4/walk/p043_20_01.jpg"},{"x":0.47,"y":0.695,"w":0.11,"h":0.075,"say":"'Skip Connection' 이라는 글자와 그 아래 두 연결 세기의 곱이 적혀 있어요.","c":[0.425,0.6775,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p043_20_02.jpg"},{"x":0.57,"y":0.605,"w":0.13,"h":0.26,"say":"오른쪽 노드 상자들. 맨 아래에서 맨 위로 크게 휘어 올라가는 굵은 화살표가 지름길이에요.","c":[0.535,0.589,0.2,0.292],"r":1.2177,"img":"img/L4/walk/p043_20_03.jpg"}]},{"kind":"formula","head":"2홉 경로의 세기","tex":"\\hat{A}(v, u)\\,\\hat{A}(u, s)","parts":[{"sym":"\\hat{A}(v,u)","say":"위층 노드와 가운데 층 노드 사이의 연결 세기예요."},{"sym":"\\hat{A}(u,s)","say":"가운데 층 노드와 아래층 노드 사이의 연결 세기예요."},{"sym":"\\hat{A}(v, u)\\,\\hat{A}(u, s)","say":"두 개의 곱. 가운데를 거쳐 가는 2홉 경로 하나의 세기예요."}],"whole":"행렬 곱의 정의가 '가운데를 거치는 모든 경로를 곱해서 더하기'였죠. 그래서 이건 정규화된 인접행렬을 제곱한 것의 한 칸이에요."},{"kind":"steps","head":"2홉 세기를 직접 계산해 봐요","steps":["$v$ 에서 $s_1$ 로 가는 경로가 둘이에요.","$v \\to u_1 \\to s_1$ 은 $0.5 \\times 0.6 = 0.30$ 이에요.","$v \\to u_2 \\to s_1$ 은 $0.4 \\times 0.3 = 0.12$ 예요.","더하면 $0.42$ 예요.","$v$ 에서 $s_2$ 로 가는 경로는 하나뿐이에요. $0.4 \\times 0.5 = 0.20$ 이에요."],"answer":"$s_1$ 이 $s_2$ 보다 두 배 이상 중요한 2홉 이웃이에요. 경로가 두 개라서 그래요.","given":"연결 세기가 $0.5$, $0.4$, $0.6$, $0.3$, $0.5$ 로 주어졌어요."},{"kind":"figure","head":"경로마다 곱하고 모두 더하기","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"240\" y=\"26\" font-size=\"16\" text-anchor=\"middle\">2홉 경로의 세기 구하기<\/text>\n<line class=\"e\" x1=\"56\" y1=\"124\" x2=\"100\" y2=\"78\"/>\n<line class=\"e\" x1=\"164\" y1=\"124\" x2=\"122\" y2=\"78\"/>\n<line class=\"e\" x1=\"76\" y1=\"198\" x2=\"60\" y2=\"158\"/>\n<line class=\"e\" x1=\"94\" y1=\"202\" x2=\"152\" y2=\"154\"/>\n<line class=\"e\" x1=\"192\" y1=\"198\" x2=\"170\" y2=\"154\"/>\n<circle class=\"n2\" cx=\"110\" cy=\"62\" r=\"18\"/>\n<text class=\"tl\" x=\"110\" y=\"68\" font-size=\"14\" text-anchor=\"middle\">v<\/text>\n<circle class=\"n\" cx=\"56\" cy=\"140\" r=\"16\"/>\n<text class=\"tl\" x=\"56\" y=\"146\" font-size=\"13\" text-anchor=\"middle\">u1<\/text>\n<circle class=\"n\" cx=\"164\" cy=\"140\" r=\"16\"/>\n<text class=\"tl\" x=\"164\" y=\"146\" font-size=\"13\" text-anchor=\"middle\">u2<\/text>\n<circle class=\"n3\" cx=\"80\" cy=\"214\" r=\"16\"/>\n<text class=\"tl\" x=\"80\" y=\"220\" font-size=\"13\" text-anchor=\"middle\">s1<\/text>\n<circle class=\"n3\" cx=\"196\" cy=\"214\" r=\"16\"/>\n<text class=\"tl\" x=\"196\" y=\"220\" font-size=\"13\" text-anchor=\"middle\">s2<\/text>\n<text class=\"tm\" x=\"44\" y=\"104\" font-size=\"13\">0.5<\/text>\n<text class=\"tm\" x=\"150\" y=\"104\" font-size=\"13\">0.4<\/text>\n<text class=\"tm\" x=\"26\" y=\"182\" font-size=\"13\">0.6<\/text>\n<text class=\"tm\" x=\"112\" y=\"190\" font-size=\"13\">0.3<\/text>\n<text class=\"tm\" x=\"198\" y=\"182\" font-size=\"13\">0.5<\/text>\n<rect class=\"box b1\" x=\"266\" y=\"70\" width=\"196\" height=\"56\" rx=\"8\"/>\n<text class=\"t b1\" x=\"364\" y=\"94\" font-size=\"14\" text-anchor=\"middle\">s1: 0.5 x 0.6 + 0.4 x 0.3<\/text>\n<text class=\"tb b1\" x=\"364\" y=\"116\" font-size=\"15\" text-anchor=\"middle\">= 0.42<\/text>\n<rect class=\"box2 b2\" x=\"266\" y=\"140\" width=\"196\" height=\"56\" rx=\"8\"/>\n<text class=\"t b2\" x=\"364\" y=\"164\" font-size=\"14\" text-anchor=\"middle\">s2: 0.4 x 0.5<\/text>\n<text class=\"tb b2\" x=\"364\" y=\"186\" font-size=\"15\" text-anchor=\"middle\">= 0.20<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"252\" font-size=\"14\" text-anchor=\"middle\">두 연결 세기를 곱해 모두 더한 값이에요<\/text>\n<\/svg>","caption":"**2차 근접성(Second-order Proximity)**은 공유하는 중간 노드가 많을수록 커져요.","builds":3},{"kind":"compare","head":"정말 공짜인지 세어 봐요","cols":["항목","건너뛰기 없음","건너뛰기 있음"],"rows":[["층마다 뽑는 노드 수","$t$","$t$ 로 같음"],["3층에서 뽑은 총 노드 수","$3t$","$3t$ 로 같음"],["추가 샘플링","없음","없음"],["볼 수 있는 최대 거리","3홉","6홉"]]},{"kind":"points","head":"왜 레이어 단위에서만 공짜일까요","items":["두 층 아래 노드는 위에서 아래로 뽑는 단계에서 이미 뽑혔어요.","그리고 순전파에서 이미 계산돼 있어요.","**건너뛰기 연결(Skip Connection)**은 그걸 한 번 더 쓰는 것뿐이에요.","**노드 단위 샘플링(Node-wise Sampling)**이라면 2홉 이웃을 새로 뽑아야 해서 공짜가 아니에요."]},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 마지막 정리에서 세 방식을 한 줄씩 비교했어요.","레이어 단위는 인접행렬의 일부만 보기로 정하는 것, 즉 엣지 샘플링이래요.","장점은 샘플링 품질을 이론적으로 보장할 수 있다는 것이고요.","단점은 그냥 복잡하고, 확률분포 만드는 것도 복잡해서 잘 안 쓰인다는 것이에요."]},{"kind":"mining","src":"마이닝 11강, 12강 High-order Proximity GRL","lines":["**2차 근접성(Second-order Proximity)**은 마이닝에서 이 이름 그대로 배웠어요.","직접 이어져 있지 않아도 이웃 집합이 비슷하면 가깝다고 보는 개념이었죠.","LINE 이라는 모델이 1차 근접성과 2차 근접성을 따로 학습했어요.","인접행렬을 제곱하면 공유 중간 노드가 많을수록 값이 커져요. 정의와 정확히 같아요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"The layer two steps below acts exactly as the two-hop neighborhood, because the skip connection multiplies the two connection strengths.","ko":"두 층 아래는 정확히 2홉 이웃 역할을 하는데, 건너뛰기 연결이 두 연결 세기를 곱하기 때문이다.","tip":"two-hop neighborhood 라는 표기를 그대로 외워 두세요."},{"kind":"english","head":"공짜라는 점까지 한 줄 더","en":"Since layer-wise sampling has already drawn and computed those nodes top-down, reusing them adds strictly zero sampling cost.","ko":"레이어 단위 샘플링이 위에서 아래로 그 노드들을 이미 뽑아 계산해 두었으므로, 다시 쓰는 데 드는 샘플링 비용은 정확히 0 이다.","tip":"zero sampling cost 가 Zero-Overhead 의 뜻이에요."},{"kind":"exam","src":"두 레이어 단위 모델을 비교하라고 하면","q":"Compare FastGCN and ASGCN in three points.","qko":"**FastGCN**과 **에이에스GCN(ASGCN)**을 세 가지로 비교하세요.","solve":["첫째, 층끼리의 관계예요. FastGCN 은 층이 독립이에요.","ASGCN 은 위층 전체를 조건으로 하는 전역 분포를 써요.","둘째, 분포를 얻는 방법이에요. FastGCN 은 고정된 근사예요.","ASGCN 은 학습 가능한 확률과 분산 벌점을 써요.","셋째, ASGCN 은 **건너뛰기 연결(Skip Connection)**로 2차 근접성까지 공짜로 얻어요."],"answer":"층 독립과 전역 분포, 고정 근사와 학습, 그리고 건너뛰기 연결 유무. 이 세 줄이면 충분해요."},{"kind":"check","q":"**건너뛰기 연결(Skip Connection)**의 샘플링 비용이 0 인 이유는?","choices":["노드를 안 쓰기 때문","이미 뽑아 계산해 둔 노드를 다시 쓰기 때문","층이 얕기 때문","인접행렬이 작기 때문"],"a":1,"why":"레이어 단위 샘플링이 이미 뽑아 둔 노드예요. 늘어나는 건 덧셈 한 번뿐이에요."},{"kind":"warn","head":"이 묶음을 한 줄로 정리하면","items":["Zero-Overhead 는 샘플링 비용이 0 이라는 뜻이에요. 덧셈과 약간의 메모리는 당연히 늘어요.","**레이어 단위 샘플링(Layer-wise Sampling)**은 이론적 보장이 가장 강하지만 복잡해서 잘 안 쓰여요.","다음 묶음(p.44 부터)은 가장 널리 쓰이는 그래프 단위 샘플링, 즉 **Cluster-GCN**과 **GraphSAINT** 예요."]},{"kind":"warn","head":"다음 묶음 시험 문제를 미리 한 줄","items":["**Cluster-GCN**과 **GraphSAINT** 계산 문제는 **그래프세이지(GraphSAGE)**와 식이 똑같아요.","딱 하나, 같은 군집이나 같은 부분 그래프 안의 이웃만 평균한다는 조건이 붙어요.","군집 밖 이웃은 분모에서도 빼야 해요. 가장 흔한 실수 지점이에요."]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.5528,0.2365],"c":[0,0.0019,0.6081,0.2685],"r":4.0263,"img":"img/L4/walk/p043_h.jpg"},"parts":[{"b":[0.12,0.275,0.85,0.045],"c":[0.065,0.203,0.935,0.1889],"r":8.7995,"img":"img/L4/walk/p043_12_01.jpg","say":"첫째, **2차 근접성(Second-order Proximity)**. 두 층 아래가 정확히 2홉 이웃이래요."},{"b":[0.12,0.38,0.85,0.075],"c":[0.065,0.323,0.935,0.1889],"r":8.7995,"img":"img/L4/walk/p043_12_02.jpg","say":"둘째, 추가 비용 없는 통합. 이미 뽑혀 계산돼 있으니 비용이 안 늘어요."},{"b":[0.12,0.515,0.85,0.045],"c":[0.065,0.443,0.935,0.1889],"r":8.7995,"img":"img/L4/walk/p043_12_03.jpg","say":"셋째, 결과. 빠른 수렴을 지키면서 고차 그래프 구조를 보존해요."}]}},{"p":44,"title":"그래프 단위 샘플링: 크면 자른다","terms":["Graph-wise Sampling","Node-wise Sampling","Layer-wise Sampling","Subgraph","Cluster-GCN","GraphSAINT","Mini-batch","Scalability"],"pass1":[{"kind":"say","lines":["세 번째 쪼개는 방법이에요.","노드마다도 아니고 층마다도 아니에요.","그래프에서 작은 조각을 통째로 하나 뽑아서 그것만 공부해요.","이것을 **그래프 단위 샘플링(Graph-wise Sampling)**이라고 해요."]},{"kind":"analogy","head":"세계 지도와 동네 지도","scene":"지수가 세계 지도를 책상에 펼치려는데 너무 커서 밖으로 삐져나가요. 지수는 자기 동네만 알면 돼요. 그래서 동네 부분만 가위로 오려 냈어요. 오려 낸 종이는 책상에 딱 맞고, 길을 찾는 방법은 원래 지도와 똑같아요.","map":[["너무 큰 세계 지도","노드가 수억 개인 큰 그래프"],["오려 낸 동네 지도","**부분 그래프(Subgraph)** 하나"],["책상 위에서 길 찾기","그 조각을 **미니 배치(Mini-batch)**로 쓰는 학습"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"compare","head":"쪼개는 세 방식을 한 문장으로","cols":["방식","무엇마다 정하나","한 문장"],"rows":[["**노드 단위 샘플링(Node-wise Sampling)**","대상 노드마다","이 노드의 이웃 중 2명만 볼래"],["**레이어 단위 샘플링(Layer-wise Sampling)**","층마다","이번 층에서는 이 엣지들만 쓸래"],["**그래프 단위 샘플링(Graph-wise Sampling)**","반복마다","이번에는 그래프의 이만큼만 볼래"]]},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 그래프 단위 샘플링의 장점이 직관적이고 간단한 것이라고 했어요.","아무리 성능이 좋고 이론이 받쳐 줘도 이해가 안 되면 실제로 잘 안 쓰인다고요.","이 방식은 접근법 자체가 아주 단순하다고 했어요.","전체 그래프가 커서 문제면 전체 그래프를 그냥 잘라 버리겠다는 거예요."]}],"pass3":[],"pass4":[],"walk":{"head":null,"parts":[{"b":[0.045,0.33,0.34,0.085],"c":[0.028,0.314,0.374,0.117],"r":5.6828,"img":"img/L4/walk/p044_20_01.jpg","say":"제목이 **그래프 단위 샘플링(Graph-wise Sampling)**이에요."},{"b":[0.045,0.44,0.47,0.09],"c":[0.0215,0.424,0.517,0.122],"r":7.5337,"img":"img/L4/walk/p044_20_02.jpg","say":"부분 그래프를 통째로 뽑고, 각각을 미니 배치로 삼아 보통 GNN을 그대로 돌려요."},{"b":[0.045,0.6,0.33,0.05],"c":[0.0285,0.57,0.363,0.11],"r":5.8667,"img":"img/L4/walk/p044_20_03.jpg","say":"대표 모델 두 개가 **Cluster-GCN**과 **GraphSAINT**예요."},{"b":[0.66,0.02,0.34,0.96],"c":[0.5893,0.0,0.4107,1],"r":0.7301,"img":"img/L4/walk/p044_20_04.jpg","say":"오른쪽 무늬는 점과 선으로 그린 그래프예요."}]}},{"p":45,"title":"GCN은 손실이 낱개로 쪼개지지 않는다","terms":["GCN","SGD","Mini-batch","Full-batch","Message Passing","Cluster-GCN","Hub Node"],"pass1":[{"kind":"say","lines":["보통 신경망은 사진 한 장의 점수를 따로따로 매길 수 있어요.","그런데 **그래프 합성곱 신경망(GCN)**은 그게 안 돼요.","한 노드가 얼마나 틀렸는지 재려면 그 노드의 이웃이 전부 필요하거든요."]},{"kind":"analogy","head":"사진 채점과 모둠 채점","scene":"선생님이 사진 100장을 채점해요. 한 장만 보면 끝이라 오늘은 세 장만 골라도 돼요. 그런데 옆 반은 모둠 과제를 채점해요. 한 사람 점수를 매기려면 같은 모둠 친구 전부를 봐야 해요. 한 사람만 고른다는 말이 성립하지 않아요.","map":[["사진 한 장 채점","보통 신경망의 손실 하나"],["모둠 친구 전부 보기","**GCN**에서 이웃 전부가 필요한 일"],["세 장만 골라 채점","**확률적 경사하강(SGD)**으로 몇 개만 뽑기"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"formula","head":"보통 신경망의 손실","tex":"\\mathcal{L} = \\sum_{i=0}^{N} loss(x_i, y_i)","parts":[{"sym":"\\mathcal{L}","say":"엘이라고 읽어요. 전체 손실, 즉 모델이 얼마나 틀렸는지의 총합이에요."},{"sym":"\\sum_{i=0}^{N}","say":"시그마예요. $i$ 를 0 부터 $N$ 까지 바꿔 가며 전부 더하라는 뜻이에요."},{"sym":"x_i","say":"$i$ 번째 데이터의 입력이에요."},{"sym":"y_i","say":"$i$ 번째 데이터의 정답이에요."},{"sym":"loss(x_i, y_i)","say":"그 하나만 보고 계산한 틀린 정도예요."}],"whole":"전체 손실은 데이터 하나하나의 손실을 그냥 더한 것이에요. 이렇게 쪼개져야 몇 개만 뽑는 **확률적 경사하강(SGD)**을 쓸 수 있어요."},{"kind":"steps","head":"하나만 뽑을 수 있나 확인해요","steps":["사진 100장을 다루는 보통 신경망이면 사진 1장만 있으면 손실 하나가 나와요.","1층 **GCN**이면 그 노드와 1홉 이웃 전부가 있어야 손실 하나가 나와요.","2층 **GCN**이면 1홉과 2홉 이웃까지 전부 있어야 해요.","사진 100장에서 32장을 뽑으면 딱 32장만 메모리에 올리면 돼요.","노드 100개에서 32개를 뽑으면 그 32개의 2홉 이웃까지 전부 올려야 해요."],"answer":"**허브 노드(Hub Node)**가 하나라도 끼면 이 숫자가 수천, 수만으로 불어나요.","given":"같은 크기의 묶음을 만든다고 할 때 무엇이 딸려 오는지 비교해요."},{"kind":"mining","src":"마이닝 10강 Random Walk-based GRL","lines":["DeepWalk 를 배울 때도 **확률적 경사하강(SGD)**이 나왔어요.","거기서는 노드 하나를 뽑아 그 노드의 손실만으로 임베딩을 고칠 수 있었어요.","얕은 임베딩은 노드마다 벡터가 표에 따로 들어 있었기 때문이에요.","GNN은 임베딩을 표에서 꺼내지 않고 이웃에서 계산해 만들어서 그 트릭이 안 통해요."]},{"kind":"points","head":"그래서 무슨 일이 생기나요","items":["손실을 더할 수는 있어요. 다만 항들이 서로 독립이 아니에요.","독립이 아니면 몇 개만 뽑아도 된다는 **확률적 경사하강(SGD)**의 전제가 깨져요.","그래서 노드 몇 개만 뽑아 **미니 배치(Mini-batch)**를 만든다가 자동으로 안 돼요.","이 문제를 푸는 첫 모델이 **Cluster-GCN**이에요."]}],"pass3":[{"kind":"english","head":"서술형에 그대로 쓸 문장","en":"In standard neural networks the loss decomposes into independent samples, but in a GCN the loss of one node depends on all of its neighbors.","ko":"보통 신경망은 손실이 독립인 표본들의 합으로 쪼개지지만, GCN은 한 노드의 손실이 이웃 전부에 달려 있다.","tip":"Why is mini-batch training difficult in GCN 이라는 문제의 답이에요."},{"kind":"warn","head":"여기서 헷갈리기 쉬워요","items":["손실이 쪼개지지 않는다는 말은 더할 수 없다는 뜻이 아니에요.","각 항이 서로 독립이 아니라서 일부만 뽑아도 되는 전제가 깨진다는 뜻이에요.","슬라이드 식은 시그마가 $i=0$ 에서 시작해요. 보통은 $i=1$ 인데 뜻은 같아요."]},{"kind":"check","q":"**GCN**에서 **미니 배치(Mini-batch)** 학습이 어려운 이유는 무엇인가요?","choices":["노드 수가 많아서","한 노드의 손실이 이웃 전부에 달려 있어서","가중치가 너무 많아서","레이블이 없어서"],"a":1,"why":"손실 항들이 서로 독립이 아니라서 몇 개만 뽑는 전제가 깨져요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4061,0.0757],"c":[0,0.0019,0.4467,0.1077],"r":7.3736,"img":"img/L4/walk/p045_h.jpg"},"parts":[{"b":[0.055,0.145,0.18,0.05],"c":[0.043,0.115,0.204,0.11],"r":3.297,"img":"img/L4/walk/p045_20_01.jpg","say":"굵은 줄이 GCN은 간단하지 않다예요. 그냥 보통 신경망처럼 학습하면 되는 게 아니라는 선언이에요."},{"b":[0.025,0.2,0.52,0.05],"c":[0,0.1672,0.572,0.1156],"r":8.7966,"img":"img/L4/walk/p045_20_02.jpg","say":"보통 신경망은 손실 함수를 데이터 하나하나의 합으로 쪼갤 수 있다고 적혀 있어요."},{"b":[0.09,0.255,0.55,0.05],"c":[0.0625,0.2189,0.605,0.1222],"r":8.8016,"img":"img/L4/walk/p045_20_03.jpg","say":"빨간 글씨가 핵심이에요. GCN에서는 한 노드의 손실이 이웃 전부에 달려 있어요."},{"b":[0.09,0.32,0.45,0.05],"c":[0.0675,0.29,0.495,0.11],"r":8.0,"img":"img/L4/walk/p045_20_04.jpg","say":"그 의존성 때문에 GCN에서 **확률적 경사하강(SGD)**을 할 때 어려움이 생겨요."},{"b":[0.07,0.5,0.57,0.36],"c":[0.0415,0.482,0.627,0.396],"r":2.8148,"img":"img/L4/walk/p045_20_05.jpg","say":"왼쪽 그림과 파란 상자는 우리가 기대한 것이에요. 한 덩이 넣으면 손실 하나가 나오는 그림이에요."},{"b":[0.68,0.4,0.24,0.53],"c":[0.668,0.3735,0.264,0.583],"r":0.805,"img":"img/L4/walk/p045_20_06.jpg","say":"오른쪽 나무와 파란 상자는 실제로 벌어지는 일이에요. 맨 위 손실 하나에 아래 전부가 매달려 있어요."}]}},{"p":46,"title":"임베딩 9개를 만들어 손실 1개를 얻는다","terms":["Embedding Utilization","GCN","Full-batch","Mini-batch","Cluster-GCN","Degree"],"pass1":[{"kind":"say","lines":["2층 **그래프 합성곱 신경망(GCN)**으로 노드 하나의 손실을 구해 볼게요.","슬라이드 예시에서는 노드 9개의 임베딩을 계산해야 해요.","그런데 얻는 손실은 딱 1개예요. 8개는 한 번 쓰이고 버려져요.","이것을 **임베딩 활용도(Embedding Utilization)**가 낮다고 해요."]},{"kind":"analogy","head":"감자 아홉 개로 1인분","scene":"민수가 요리를 하려고 감자 아홉 개를 깎았어요. 그런데 만든 음식은 1인분뿐이에요. 남은 감자 여덟 개는 그냥 버려요. 옆집 아주머니는 같은 감자 아홉 개로 아홉 사람 몫을 만들었어요. 깎은 수고는 같은데 얻은 것이 아홉 배죠.","map":[["깎은 감자 한 개","노드 임베딩 하나"],["만든 음식 1인분","얻은 손실 하나"],["버려진 감자 여덟 개","낮은 **임베딩 활용도(Embedding Utilization)**"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"formula","head":"**임베딩 활용도(Embedding Utilization)** 의 정의","tex":"\\text{활용도} = \\frac{\\text{얻은 손실의 개수}}{\\text{계산한 임베딩의 개수}}","parts":[{"sym":"\\text{얻은 손실의 개수}","say":"배치 안에서 정답과 비교해 본 노드의 수예요."},{"sym":"\\text{계산한 임베딩의 개수}","say":"그 손실을 얻으려고 만들어야 했던 임베딩 전부의 수예요."},{"sym":"\\frac{1}{9}","say":"노드 하나만 배치에 넣었을 때의 값, 약 0.11 이에요."},{"sym":"\\frac{9}{9}","say":"9개를 전부 배치에 넣었을 때의 값, 1 이에요."}],"whole":"재료를 얼마나 알뜰하게 썼는가를 재는 값이에요. 클수록 좋아요."},{"kind":"steps","head":"두 가지 경우를 직접 세어요","steps":["경우 1은 노드 하나만 **미니 배치(Mini-batch)**로 쓸 때예요.","계산한 임베딩은 대상 1 더하기 1홉 2 더하기 2홉 6 으로 9개예요.","얻은 손실은 대상 노드 하나뿐이라 1개예요. 활용도는 $1/9$ 로 약 0.11 이에요.","경우 2는 9개 노드를 전부 배치에 넣는 **풀배치(Full-batch)**예요.","계산한 임베딩은 똑같이 9개인데 손실은 9개라 활용도가 $9/9 = 1$ 이에요."],"answer":"같은 9개를 계산했는데 얻는 것이 9배 차이 나요. 이 다시 쓰기가 **Cluster-GCN**의 열쇠예요.","given":"슬라이드 그림의 노드 9개짜리 계산 그래프를 씁니다."},{"kind":"figure","head":"만든 임베딩을 몇 개의 손실이 나눠 쓰는가","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"118\" y=\"24\" font-size=\"16\" text-anchor=\"middle\">대상 노드 1개만 배치에<\/text>\n<line class=\"e\" x1=\"118\" y1=\"66\" x2=\"88\" y2=\"92\"/>\n<line class=\"e\" x1=\"118\" y1=\"66\" x2=\"148\" y2=\"92\"/>\n<line class=\"e\" x1=\"88\" y1=\"118\" x2=\"46\" y2=\"144\"/>\n<line class=\"e\" x1=\"88\" y1=\"118\" x2=\"76\" y2=\"144\"/>\n<line class=\"e\" x1=\"88\" y1=\"118\" x2=\"106\" y2=\"144\"/>\n<line class=\"e\" x1=\"148\" y1=\"118\" x2=\"130\" y2=\"144\"/>\n<line class=\"e\" x1=\"148\" y1=\"118\" x2=\"160\" y2=\"144\"/>\n<line class=\"e\" x1=\"148\" y1=\"118\" x2=\"190\" y2=\"144\"/>\n<circle class=\"n2\" cx=\"118\" cy=\"52\" r=\"14\"/>\n<circle class=\"n\" cx=\"88\" cy=\"104\" r=\"13\"/>\n<circle class=\"n\" cx=\"148\" cy=\"104\" r=\"13\"/>\n<circle class=\"n\" cx=\"46\" cy=\"156\" r=\"11\"/>\n<circle class=\"n\" cx=\"76\" cy=\"156\" r=\"11\"/>\n<circle class=\"n\" cx=\"106\" cy=\"156\" r=\"11\"/>\n<circle class=\"n\" cx=\"130\" cy=\"156\" r=\"11\"/>\n<circle class=\"n\" cx=\"160\" cy=\"156\" r=\"11\"/>\n<circle class=\"n\" cx=\"190\" cy=\"156\" r=\"11\"/>\n<text class=\"tm b1\" x=\"118\" y=\"192\" font-size=\"14\" text-anchor=\"middle\">임베딩 9개, 손실 1개<\/text>\n<text class=\"tb b1\" x=\"118\" y=\"218\" font-size=\"16\" text-anchor=\"middle\">활용도 1/9 은 약 0.11<\/text>\n<line class=\"e\" x1=\"240\" y1=\"36\" x2=\"240\" y2=\"228\"/>\n<text class=\"tb\" x=\"362\" y=\"24\" font-size=\"16\" text-anchor=\"middle\">9개 모두 배치에<\/text>\n<line class=\"e2 b2\" x1=\"362\" y1=\"66\" x2=\"332\" y2=\"92\"/>\n<line class=\"e2 b2\" x1=\"362\" y1=\"66\" x2=\"392\" y2=\"92\"/>\n<line class=\"e2 b2\" x1=\"332\" y1=\"118\" x2=\"290\" y2=\"144\"/>\n<line class=\"e2 b2\" x1=\"332\" y1=\"118\" x2=\"320\" y2=\"144\"/>\n<line class=\"e2 b2\" x1=\"332\" y1=\"118\" x2=\"350\" y2=\"144\"/>\n<line class=\"e2 b2\" x1=\"392\" y1=\"118\" x2=\"374\" y2=\"144\"/>\n<line class=\"e2 b2\" x1=\"392\" y1=\"118\" x2=\"404\" y2=\"144\"/>\n<line class=\"e2 b2\" x1=\"392\" y1=\"118\" x2=\"434\" y2=\"144\"/>\n<circle class=\"n3 b2\" cx=\"362\" cy=\"52\" r=\"14\"/>\n<circle class=\"n3 b2\" cx=\"332\" cy=\"104\" r=\"13\"/>\n<circle class=\"n3 b2\" cx=\"392\" cy=\"104\" r=\"13\"/>\n<circle class=\"n3 b2\" cx=\"290\" cy=\"156\" r=\"11\"/>\n<circle class=\"n3 b2\" cx=\"320\" cy=\"156\" r=\"11\"/>\n<circle class=\"n3 b2\" cx=\"350\" cy=\"156\" r=\"11\"/>\n<circle class=\"n3 b2\" cx=\"374\" cy=\"156\" r=\"11\"/>\n<circle class=\"n3 b2\" cx=\"404\" cy=\"156\" r=\"11\"/>\n<circle class=\"n3 b2\" cx=\"434\" cy=\"156\" r=\"11\"/>\n<text class=\"tm b2\" x=\"362\" y=\"192\" font-size=\"14\" text-anchor=\"middle\">임베딩 9개, 손실 9개<\/text>\n<text class=\"tb b2\" x=\"362\" y=\"218\" font-size=\"16\" text-anchor=\"middle\">활용도 9/9 는 1<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"252\" font-size=\"16\" text-anchor=\"middle\">같은 9개를 계산했는데 얻는 것이 9배 달라요<\/text>\n<\/svg>","caption":"왼쪽은 파란 대상 하나만 손실을 내요. 오른쪽은 9개가 모두 손실을 내요. 계산량은 같아요.","builds":3},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 계산 그래프가 넓고 깊어지면 순전파도 복잡하지만 역전파가 더 문제라고 했어요.","기울기를 계산 그래프의 처음부터 끝까지 전부 계산해야 하기 때문이에요.","그리고 이것이 GNN의 파라미터 수가 아주 적은데도 과적합에 취약한 원인이 되기도 한다고요."]}],"pass3":[{"kind":"english","head":"서술형에 쓸 한 줄","en":"Embedding utilization is the ratio of the number of losses obtained to the number of embeddings computed.","ko":"임베딩 활용도는 계산한 임베딩 수 대비 얻은 손실 수의 비율이다.","tip":"뒤에 Cluster-GCN improves it by putting a node and its neighbors into the same mini batch 를 붙이면 좋아요."},{"kind":"check","q":"노드 9개의 임베딩을 계산해 손실 1개를 얻었어요. **임베딩 활용도(Embedding Utilization)**는?","choices":["9","1","약 0.11","0"],"a":2,"why":"$1/9$ 는 약 0.11 이에요. **풀배치(Full-batch)**면 $9/9 = 1$ 이 돼요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4061,0.0757],"c":[0,0.0019,0.4467,0.1077],"r":7.3736,"img":"img/L4/walk/p046_h.jpg"},"parts":[{"b":[0.04,0.135,0.4,0.055],"c":[0.02,0.1075,0.44,0.11],"r":7.1111,"img":"img/L4/walk/p046_20_01.jpg","say":"문제는 계산 비용이 크다는 데서 온다예요."},{"b":[0.04,0.21,0.53,0.055],"c":[0.0135,0.1786,0.583,0.1178],"r":8.7983,"img":"img/L4/walk/p046_20_02.jpg","say":"2층 **GCN**으로 대상 노드의 손실을 구한다고 해 보자예요. 파란 글씨가 조건이에요."},{"b":[0.04,0.29,0.92,0.1],"c":[0.0,0.2378,1,0.2045],"r":8.6933,"img":"img/L4/walk/p046_20_03.jpg","say":"최종 표현을 얻으려면 그 노드의 2홉 이웃 안에 있는 노드 임베딩이 전부 필요해요."},{"b":[0.04,0.42,0.78,0.055],"c":[0.001,0.3608,0.858,0.1733],"r":8.8017,"img":"img/L4/walk/p046_20_04.jpg","say":"예를 들어 노드 9개의 임베딩이 필요한데 손실은 1개만 얻어요."},{"b":[0.4,0.5,0.2,0.42],"c":[0.388,0.479,0.224,0.462],"r":0.862,"img":"img/L4/walk/p046_20_05.jpg","say":"그림의 파란 네모를 세어 보세요. 아래 6개, 가운데 2개, 맨 위 1개로 모두 9개예요."}]}},{"p":47,"title":"이웃을 적게 뽑아도 확장은 남는다","terms":["GraphSAGE","Recursive Neighborhood Expansion","Receptive Field","Cluster-GCN","Node-wise Sampling","Embedding Utilization"],"pass1":[{"kind":"say","lines":["이웃을 다 보지 말고 조금만 보면 되지 않을까요?","그게 바로 앞에서 배운 **GraphSAGE**였어요.","그런데 층마다 곱해지는 구조는 그대로 남아요.","이것을 **재귀적 이웃 확장(Recursive Neighborhood Expansion)**이라고 해요."]},{"kind":"analogy","head":"친구 두 명에게만 물어보기","scene":"준호가 친구 두 명에게 물어봤어요. 그 두 친구도 몰라서 각자 친구 두 명에게 물었어요. 벌써 네 명이 움직였죠. 그 네 명이 또 두 명씩 물으면 여덟 명이에요. 두 명만 묻기로 했는데 모두 열네 명이 움직였어요.","map":[["두 명에게만 묻기","**GraphSAGE**의 이웃 개수 제한"],["또 묻고 또 묻기","**재귀적 이웃 확장(Recursive Neighborhood Expansion)**"],["움직인 열네 명","계산 그래프에 들어오는 노드 전부"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"재귀적이라는 말의 뜻","items":["재귀적이라는 말은 같은 일이 자기 안에서 또 일어난다는 뜻이에요.","이웃을 2명 뽑고 끝이 아니라 그 2명이 각자 또 2명을 뽑아요.","덧셈이 아니라 곱셈이라서 층을 하나 늘리면 전체가 2배가 돼요.","층이 10개면 $2^{10} = 1024$ 개예요. **수용 영역(Receptive Field)**이 지수로 커져요."]},{"kind":"steps","head":"층마다 $S$ 명씩 뽑을 때 몇 개가 딸려 오나요","steps":["$K$ 층이면 계산 그래프에 들어오는 노드 수는 대략 $S^K$ 개예요.","$S = 2$ 면 층 1개에 2, 2개에 4, 3개에 8, 4개에 16 이에요.","$S = 10$ 이면 층 1개에 10, 2개에 100, 3개에 1000 이에요.","배치에 노드 32개를 넣으면 $32 \\times 1000 = 32000$ 개예요.","**GraphSAGE** 예제 코드는 1층 10명, 2층 5명이라 $10 \\times 5 = 50$ 개였어요."],"answer":"배치 크기 32 에 50 을 곱하면 1600 개예요. **임베딩 활용도(Embedding Utilization)**로 재면 $32/1600 = 0.02$ 예요.","given":"한 층에서 이웃을 $S$ 명씩만 뽑고 층은 $K$ 개라고 해요."},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 **GraphSAGE**의 아이디어를 한 깊이에서 뽑는 이웃 개수를 한정하는 것이라 했어요.","보통 2나 3 이라고요.","그리고 한계로 샘플링 품질이 이론적으로 뒷받침되지 않는다는 점을 들었어요.","Cluster-GCN 슬라이드는 여기에 곱셈 구조 자체가 남는다는 점을 더 얹어요."]},{"kind":"warn","head":"이 슬라이드를 오해하지 마세요","items":["**GraphSAGE**를 깎아내리는 게 아니라 완전한 해법은 아니라는 뜻이에요.","$S^K$ 는 어림값이에요. 뽑은 이웃끼리 겹치면 실제로는 조금 적어요.","그림의 $k=1$, $k=2$ 점선 원은 몇 홉까지 보는가를 뜻해요."]}],"pass3":[{"kind":"english","head":"반대 방향 질문에 쓸 문장","en":"Even with a fixed number of sampled neighbors per layer, the computation graph still grows as S to the power K, so recursive neighborhood expansion remains.","ko":"층마다 뽑는 이웃 수를 고정해도 계산 그래프 안 노드 수는 여전히 $S^K$ 로 늘어나므로 재귀적 이웃 확장은 남는다.","tip":"2024 가을 기말 2번은 GraphSAGE가 확장성 문제를 어떻게 푸는지를 물었어요. 그 반대가 이 문장이에요."},{"kind":"check","q":"$S = 10$, $K = 3$ 일 때 대상 노드 하나에 딸려 오는 노드 수는 대략 몇 개인가요?","choices":["30","13","1000","100"],"a":2,"why":"$S^K = 10^3 = 1000$ 이에요. 덧셈이 아니라 곱셈이에요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4061,0.0757],"c":[0,0.0019,0.4467,0.1077],"r":7.3736,"img":"img/L4/walk/p047_h.jpg"},"parts":[{"b":[0.03,0.155,0.42,0.055],"c":[0.009,0.1275,0.462,0.11],"r":7.4667,"img":"img/L4/walk/p047_20_01.jpg","say":"아이디어는 이웃을 더 적은 수로 뽑아 쓰는 것이에요. 주황 글씨가 핵심이에요."},{"b":[0.08,0.225,0.6,0.055],"c":[0.05,0.1858,0.66,0.1333],"r":8.8022,"img":"img/L4/walk/p047_20_02.jpg","say":"예를 들어 **GraphSAGE**는 노드마다 이웃의 일부만 봐요."},{"b":[0.08,0.29,0.4,0.055],"c":[0.06,0.2625,0.44,0.11],"r":7.1111,"img":"img/L4/walk/p047_20_03.jpg","say":"하지만 여전히 **재귀적 이웃 확장(Recursive Neighborhood Expansion)**을 겪어요."},{"b":[0.15,0.4,0.23,0.44],"c":[0.138,0.378,0.254,0.484],"r":0.933,"img":"img/L4/walk/p047_20_04.jpg","say":"그림 1은 이웃 샘플링이에요. 점선 원 안쪽이 1홉, 바깥이 2홉이에요."},{"b":[0.38,0.4,0.24,0.44],"c":[0.368,0.378,0.264,0.484],"r":0.9697,"img":"img/L4/walk/p047_20_05.jpg","say":"그림 2는 이웃에서 특징을 집계하는 단계예요. 화살표 색이 두 가지인 건 층마다 집계기가 따로라서예요."},{"b":[0.62,0.4,0.25,0.44],"c":[0.6075,0.378,0.275,0.484],"r":1.0101,"img":"img/L4/walk/p047_20_06.jpg","say":"그림 3은 모은 정보로 그래프 맥락과 레이블을 예측하는 단계예요."}]}},{"p":48,"title":"자르면 그룹 사이 연결이 지워진다","terms":["Induced Subgraph","Subgraph","Message Passing","Cluster-GCN","Community","CiteSeer"],"pass1":[{"kind":"say","lines":["그래프를 조각내면 좋은 일만 생기는 게 아니에요.","그룹과 그룹을 잇던 선이 전부 끊겨요.","그 선으로 오던 메시지는 영영 사라져요. 슬라이드는 이것을 잃어버린 메시지라고 불러요."]},{"kind":"analogy","head":"반을 나누면 끊기는 친구 사이","scene":"친구 서른 명의 친한 사이를 선으로 그려 놓았어요. 학교가 서른 명을 세 반으로 나눴어요. 같은 반 친구와는 매일 이야기하지만 다른 반 친구와는 이야기할 기회가 사라져요. 그 친구가 알던 소식은 이제 안 와요.","map":[["같은 반 친구끼리의 선","**유도 부분 그래프(Induced Subgraph)** 안에 남는 엣지"],["다른 반으로 간 친구와의 선","지워지는 그룹 사이 엣지"],["듣지 못하게 된 소식","**메시지 패싱(Message Passing)** 중에 사라지는 메시지"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"**유도 부분 그래프(Induced Subgraph)**가 무엇인가요","items":["노드 집합을 먼저 고르고, 고른 노드끼리 원래 이어져 있던 엣지만 전부 가져와요.","한쪽 끝이 밖에 있는 엣지는 자동으로 버려져요. 고를 여지가 없어요.","반 친구 30명 중 5명만 골라 관계도를 다시 그리는 것과 같아요.","그 5명끼리의 선만 남고 나머지 25명으로 가던 선은 전부 지워져요."]},{"kind":"steps","head":"엣지가 몇 퍼센트나 사라지는지 세어요","steps":["노드 9개짜리 그래프를 군집 3개로 나눴다고 해요.","군집마다 안쪽 엣지가 있고, 군집을 이어 주는 엣지가 세 군데에 하나씩 있어요.","전체 엣지를 21개, 군집을 넘나드는 엣지를 3개라고 해요.","지워지는 비율은 $3 / 21$ 로 약 14% 예요.","남는 비율은 $18 / 21$ 로 약 86% 예요."],"answer":"21개 중 3개만 잘려 나가요. 생각보다 적게 잘린다는 것이 이 방법이 통하는 이유예요.","given":"군집 사이 엣지만 끊긴다고 할 때의 손해를 재 봐요."},{"kind":"mining","src":"마이닝 5강 Community Detection","lines":["왜 하필 그룹 사이 연결만 골라 끊는지는 그래프 분할의 기본 원칙이 답해 줘요.","그룹 사이 연결은 최소화하고 그룹 안 연결은 최대화한다는 원칙이에요.","Min-cut 과 Normalized-cut 이 바로 이 원칙을 쓰는 방법이에요.","군집화를 잘하면 애초에 끊기는 엣지가 적도록 자를 수 있어요."]},{"kind":"warn","head":"놓치기 쉬운 점","items":["엣지가 사라진다고 노드가 사라지는 건 아니에요. 연결만 끊겨요.","**커뮤니티(Community)** 경계에 있는 다리 같은 노드가 가장 많이 끊겨요.","21개 중 3개라는 숫자는 감을 잡기 위한 예시예요. 조각을 잘게 낼수록 비율이 올라가요."]}],"pass3":[{"kind":"english","head":"한계를 묻는 서술형에 쓸 문장","en":"Because Cluster-GCN trains on induced subgraphs, all between-cluster edges are dropped, so messages from other clusters are lost.","ko":"Cluster-GCN은 유도 부분 그래프 위에서 학습하므로 군집 사이 엣지가 전부 버려지고, 메시지 패싱 중에 다른 군집의 메시지가 영영 사라진다.","tip":"induced subgraph 와 between-cluster edges 두 표현을 꼭 넣으세요."},{"kind":"check","q":"**유도 부분 그래프(Induced Subgraph)**의 특징은 무엇인가요?","choices":["엣지를 먼저 고른다","노드를 고르면 그 사이 엣지가 자동으로 정해진다","엣지를 마음대로 고를 수 있다","노드가 사라진다"],"a":1,"why":"노드 집합을 고르면 엣지는 따라와요. 고를 여지가 없어요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4061,0.0757],"c":[0,0.0019,0.4467,0.1077],"r":7.3736,"img":"img/L4/walk/p048_h.jpg"},"parts":[{"b":[0.05,0.15,0.1,0.055],"c":[0.0,0.1225,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p048_20_01.jpg","say":"맨 위 굵은 글씨가 문제예요. 좋은 점보다 대가를 먼저 보여 주는 슬라이드예요."},{"b":[0.09,0.22,0.4,0.055],"c":[0.07,0.1925,0.44,0.11],"r":7.1111,"img":"img/L4/walk/p048_20_02.jpg","say":"**유도 부분 그래프(Induced Subgraph)**는 그룹 사이 연결을 지운다예요."},{"b":[0.09,0.29,0.78,0.055],"c":[0.051,0.2308,0.858,0.1733],"r":8.8017,"img":"img/L4/walk/p048_20_03.jpg","say":"그래서 다른 그룹에서 오는 메시지가 사라지고 GNN 성능이 나빠질 수 있어요."},{"b":[0.18,0.55,0.32,0.33],"c":[0.164,0.5335,0.352,0.363],"r":1.7239,"img":"img/L4/walk/p048_20_04.jpg","say":"왼쪽 세 덩어리예요. 덩어리 안은 검은 실선, 덩어리 사이는 연한 회색 굵은 선이에요."},{"b":[0.56,0.46,0.19,0.42],"c":[0.548,0.439,0.214,0.462],"r":0.8235,"img":"img/L4/walk/p048_20_05.jpg","say":"오른쪽이 떼어 낸 유도 부분 그래프예요. 분홍 점선 화살표가 잃어버린 메시지예요."}]}},{"p":49,"title":"빽빽한 곳에 집중하면 활용도가 올라간다","terms":["Embedding Utilization","Full-batch","Adjacency Matrix","GCN","Community","Cluster-GCN","Mini-batch"],"pass1":[{"kind":"say","lines":["**임베딩 활용도(Embedding Utilization)**를 최고로 만드는 방법은 이미 알고 있어요.","**풀배치(Full-batch)**예요. 임베딩 9개로 손실 9개를 얻으니까요.","문제는 풀배치가 메모리에 안 들어간다는 것이죠.","그러면 그래프의 빽빽한 부분만 떼어 내 그 안에서 풀배치를 하면 돼요."]},{"kind":"analogy","head":"같은 재료로 여러 그릇을 만들기","scene":"국을 한 솥 끓이면 여러 명이 나눠 먹을 수 있어요. 한 명 몫만 끓이면 냄비를 데우고 씻는 수고가 그대로 드는데 얻는 건 한 그릇이죠. 그래서 한 번 끓일 때 여러 명이 같이 먹을 수 있도록 서로 가까이 사는 사람들을 모아요.","map":[["한 솥 끓이기","**풀배치(Full-batch)** 계산"],["여러 그릇으로 나눠 먹기","만든 임베딩을 여러 손실이 다시 쓰기"],["가까이 사는 사람 모으기","서로 이웃인 노드를 같은 배치에 넣기"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"formula","head":"2층 **GCN**을 행렬 하나로","tex":"GCN_{2\\text{-}layer}(A, X) = A\\,\\sigma\\!\\left(A X W^{(0)}\\right) W^{(1)}","parts":[{"sym":"A","say":"**인접행렬(Adjacency Matrix)**이에요. 누가 누구와 이어졌는지 적은 표예요."},{"sym":"X","say":"특징행렬이에요. 한 줄이 노드 하나의 입력 특징이에요."},{"sym":"W^{(0)}","say":"1층 가중치 행렬이에요."},{"sym":"W^{(1)}","say":"2층 가중치 행렬이에요."},{"sym":"\\sigma","say":"시그마라고 읽어요. 비선형 활성화 함수예요."}],"whole":"특징을 변환하고 이웃과 섞기를 두 번 한다는 뜻이에요. 노드 하나를 가리키는 첨자가 없으니 모든 노드가 한꺼번에 나와요."},{"kind":"points","head":"다시 쓰기가 자동으로 일어나는 자리","items":["$A$ 를 곱하면 노드 $u$ 의 임베딩이 $u$ 와 이어진 모든 이웃의 줄에 더해져요.","이웃이 5명이면 그 임베딩 하나가 5군데에서 쓰여요. 한 번 만들어 다섯 번 쓰는 거예요.","배치에 대상 노드 하나만 있으면 이웃 임베딩은 딱 한 줄에만 더해지고 버려져요.","그래서 배치 안에 그 임베딩을 필요로 하는 노드가 여럿 있어야 해요."]},{"kind":"steps","head":"배치 크기를 키우면 활용도가 올라갈까요","steps":["노드 1개 배치면 계산한 임베딩 9개에 손실 1개, 활용도 $1/9$ 로 약 0.11 이에요.","노드 3개 배치인데 이웃이 겹치지 않으면 임베딩 27개에 손실 3개예요.","$3/27$ 도 약 0.11 이에요. 배치를 키웠는데 활용도가 그대로예요.","**풀배치(Full-batch)**로 9개를 전부 넣으면 임베딩 9개에 손실 9개예요.","$9/9 = 1.00$ 이에요."],"answer":"활용도는 크기 때문이 아니라 같은 이웃을 여러 대상이 공유할 때 올라가요.","given":"같은 9개짜리 계산 그래프를 세 가지 방식으로 비교해요."},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 실세계 그래프가 몇 개의 **커뮤니티(Community)**로 이루어져 있다고 반복해 말했어요.","커뮤니티 안 노드들은 서로 강하게 연결되어 있고요.","커뮤니티는 소수의 허브와 대다수의 리프로 구성된다고 했어요.","그리고 커뮤니티 사이 연결은 거의 존재하지 않는다고요."]}],"pass3":[{"kind":"english","head":"핵심 아이디어를 한 문장으로","en":"The key idea of Cluster-GCN is to maximize embedding utilization by placing nodes that share neighbors into the same mini batch.","ko":"Cluster-GCN의 핵심은 이웃을 공유하는 노드들, 즉 그래프의 빽빽한 부분을 같은 미니 배치에 넣어 임베딩 활용도를 최대로 만드는 것이다.","tip":"maximize embedding utilization 과 dense part 두 조각을 꼭 넣으세요."},{"kind":"warn","head":"여기서 틀리기 쉬워요","items":["풀배치가 최적이라는 말은 활용도 기준에서만이에요. 메모리로는 최악이에요.","**Cluster-GCN**은 전체가 아니라 작은 덩어리 안에서의 풀배치예요.","빽빽한 부분은 엣지가 많은 곳이지 노드가 많은 곳이 아니에요."]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4061,0.0757],"c":[0,0.0019,0.4467,0.1077],"r":7.3736,"img":"img/L4/walk/p049_h.jpg"},"parts":[{"b":[0.05,0.15,0.3,0.055],"c":[0.035,0.1225,0.33,0.11],"r":5.3333,"img":"img/L4/walk/p049_20_01.jpg","say":"맨 위 굵은 줄이 임베딩 활용도를 올리는 길이에요."},{"b":[0.09,0.22,0.68,0.055],"c":[0.056,0.1719,0.748,0.1511],"r":8.8006,"img":"img/L4/walk/p049_20_02.jpg","say":"손실을 한 번에 전부 고려하면 노드 9개 임베딩을 쓰고 손실 9개를 얻어요."},{"b":[0.3,0.285,0.36,0.055],"c":[0.282,0.2575,0.396,0.11],"r":6.4,"img":"img/L4/walk/p049_20_03.jpg","say":"가운데 식이 2층 **GCN**을 행렬 하나로 적은 것이에요."},{"b":[0.09,0.355,0.2,0.05],"c":[0.078,0.325,0.224,0.11],"r":3.6202,"img":"img/L4/walk/p049_20_04.jpg","say":"임베딩 활용도는 최적이라고 적혀 있어요."},{"b":[0.09,0.425,0.45,0.05],"c":[0.0675,0.395,0.495,0.11],"r":8.0,"img":"img/L4/walk/p049_20_05.jpg","say":"핵심은 노드 임베딩을 최대한 많이 다시 쓰는 것이에요."},{"b":[0.09,0.49,0.3,0.05],"c":[0.075,0.46,0.33,0.11],"r":5.3333,"img":"img/L4/walk/p049_20_06.jpg","say":"그래프의 빽빽한 부분에 집중한다가 빨간 글씨예요."}]}},{"p":50,"title":"METIS로 빽빽한 부분 그래프를 찾는다","terms":["METIS","Subgraph","Induced Subgraph","Community","Cluster-GCN","Embedding Utilization"],"pass1":[{"kind":"say","lines":["빽빽한 부분을 손으로 고를 수는 없어요.","그래서 그래프 군집화 알고리즘에게 맡겨요. 대표가 **메티스(METIS)**예요.","같은 4개 노드를 골라도 어떻게 고르느냐에 따라 결과가 완전히 달라져요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자와 위쪽 그림","boxes":[{"x":0.03,"y":0.14,"w":0.76,"h":0.1,"say":"아이디어는 그래프 군집화 알고리즘, 예를 들어 **메티스(METIS)**로 빽빽한 부분 그래프를 찾는 것이에요.","c":[0,0.1056,0.836,0.1689],"r":8.7994,"img":"img/L4/walk/p050_20_01.jpg"},{"x":0.21,"y":0.27,"w":0.18,"h":0.3,"say":"큰 그래프예요. 구름 모양 테두리 밖으로 선이 삐져나가요. GPU에 다 안 들어간다는 표현이에요.","c":[0.198,0.254,0.204,0.332],"r":1.0924,"img":"img/L4/walk/p050_20_02.jpg"},{"x":0.39,"y":0.27,"w":0.17,"h":0.3,"say":"뽑은 부분 그래프예요. GPU에 올릴 만큼 작아요.","c":[0.375,0.254,0.2,0.332],"r":1.071,"img":"img/L4/walk/p050_20_03.jpg"},{"x":0.57,"y":0.27,"w":0.18,"h":0.3,"say":"그 조각 안에서만 빨간 화살표가 오가요. 메시지가 조각 밖으로 안 나가요.","c":[0.558,0.254,0.204,0.332],"r":1.0924,"img":"img/L4/walk/p050_20_04.jpg"}]},{"kind":"points","head":"위쪽 세 그림은 학습 한 번의 순서예요","items":["자르고, 올리고, 그 안에서만 돌린다 세 단계예요.","이 세 단계가 배치마다 반복돼요.","왼쪽 구름은 GPU에 다 안 들어가는 원래 그래프예요.","오른쪽 빨간 화살표는 조각 안에서만 일어나는 메시지 주고받기예요."]},{"kind":"steps","head":"빽빽함을 숫자로 재요","steps":["노드가 $n$ 개인 부분 그래프에서 가능한 최대 엣지 수는 $\\frac{n(n-1)}{2}$ 예요.","$n = 4$ 면 최대 엣지가 $\\frac{4 \\times 3}{2} = 6$ 개예요.","슬라이드의 왼쪽은 엣지가 6개라 밀도가 $6/6 = 1.0$ 이에요.","오른쪽은 엣지가 1개뿐이라 밀도가 $1/6$ 으로 약 0.17 이에요.","오른쪽처럼 고르면 나머지 3개 노드는 이웃 없이 자기 자신만 보고 갱신돼요."],"answer":"같은 4개인데 남는 엣지 수가 6개와 1개로 갈려요. 어떻게 고르느냐가 전부예요.","given":"노드 4개를 고르는 두 방식을 비교해요."},{"kind":"mining","src":"마이닝 5강 Community Detection","lines":["**메티스(METIS)**는 그래프를 비슷한 크기 조각으로 빠르게 나누는 고전 알고리즘이에요.","그룹 사이 연결은 최소화, 그룹 안 연결은 최대화라는 원칙을 그대로 따라가요.","5강에서 Min-cut, Normalized-cut 으로 배운 원칙이고 Louvain, Leiden 도 같은 목표예요.","**Cluster-GCN**은 이 중 무엇을 써도 되고 논문이 쓴 것이 메티스예요."]},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 군집화에 스펙트럼 군집화 계열이 많이 쓰이고 대표가 **메티스(METIS)**라고 했어요.","그리고 쪼갠 조각을 뭐라고 부르냐고 물으며 **부분 그래프(Subgraph)**라고 다시 짚어 줬어요.","전체 그래프의 노드 집합과 엣지 집합을 부분집합으로 하는 그래프라는 정의예요."]}],"pass3":[{"kind":"english","head":"왜 군집화를 쓰는지 쓰는 문장","en":"Cluster-GCN applies a clustering algorithm such as METIS to partition the graph into dense subgraphs that keep most neighbors inside the batch.","ko":"Cluster-GCN은 메티스 같은 그래프 군집화 알고리즘으로 그래프를 빽빽한 부분 그래프로 나누는데, 빽빽한 부분 그래프는 이웃 대부분을 배치 안에 남기기 때문이다.","tip":"therefore maximizes embedding utilization 을 뒤에 붙이면 완성이에요."},{"kind":"warn","head":"자주 나오는 오해","items":["**메티스(METIS)**는 GNN의 일부가 아니에요. 학습 전에 한 번 돌리는 전처리예요.","그래서 학습 속도에는 거의 영향이 없어요.","슬라이드의 Left 와 Right 는 그냥 왼쪽 그림, 오른쪽 그림이라는 뜻이에요."]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.7557,0.2311],"c":[0,0.0019,0.8313,0.2631],"r":5.6171,"img":"img/L4/walk/p050_h.jpg"},"parts":[{"b":[0.13,0.63,0.22,0.27],"c":[0.118,0.614,0.244,0.302],"r":1.4364,"img":"img/L4/walk/p050_11_01.jpg","say":"왼쪽이 원래 그래프예요. 왼쪽은 성기고 오른쪽은 노드 4개가 서로 다 이어진 빽빽한 부분이에요."},{"b":[0.35,0.63,0.49,0.3],"c":[0.3255,0.614,0.539,0.332],"r":2.8862,"img":"img/L4/walk/p050_11_02.jpg","say":"주황 상자 안이 노드 4개짜리 부분 그래프 두 개예요. 왼쪽은 뭉쳐 골랐고 오른쪽은 흩어 골랐어요."}]}},{"p":51,"title":"인접행렬이 블록 대각 모양이 된다","terms":["Adjacency Matrix","Block-diagonal Matrix","Subgraph","Cluster-GCN","Mini-batch","METIS"],"pass1":[{"kind":"say","lines":["군집으로 나눈 것을 행렬의 말로 다시 적어 볼게요.","노드 번호를 군집 순서대로 매기면 **인접행렬(Adjacency Matrix)**이 예쁘게 갈려요.","대각선 자리에만 덩어리가 있는 **블록 대각 행렬(Block-diagonal Matrix)**과 그 바깥이에요.","**Cluster-GCN**은 앞엣것만 쓰고 뒤엣것을 버려요."]},{"kind":"analogy","head":"반별로 자리를 다시 배치한 좌석표","scene":"친한 사이를 표로 적었더니 뒤죽박죽이에요. 1반을 앞 번호, 2반을 뒤 번호로 다시 매기고 표를 그리면 표시가 대각선을 따라 두 덩어리로 모여요. 반을 넘는 사이만 덩어리 바깥에 찍혀요.","map":[["번호를 반 순서로 다시 매기기","노드를 군집 순서로 정렬하기"],["대각선의 두 덩어리","**블록 대각 행렬(Block-diagonal Matrix)**"],["덩어리 바깥의 표시","버려질 군집 사이 연결"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"formula","head":"군집으로 나눈 결과","tex":"\\bar{G} = [G_1, \\cdots, G_c] = [\\{\\mathcal{V}_1, \\mathcal{E}_1\\}, \\cdots, \\{\\mathcal{V}_c, \\mathcal{E}_c\\}]","parts":[{"sym":"\\bar{G}","say":"지 바라고 읽어요. 원래 그래프를 조각낸 결과 전체예요."},{"sym":"c","say":"씨라고 읽어요. 군집 개수예요."},{"sym":"G_t","say":"$t$ 번째 군집이 만드는 **부분 그래프(Subgraph)**예요."},{"sym":"\\mathcal{V}_t","say":"브이 티라고 읽어요. $t$ 번째 군집의 노드 집합이에요."},{"sym":"\\mathcal{E}_t","say":"이 티라고 읽어요. $t$ 번째 군집 안쪽 엣지 집합이에요."}],"whole":"전체 그래프를 $c$ 조각으로 나눴고 각 조각은 노드 집합과 그 안쪽 엣지 집합으로 이루어진다는 뜻이에요."},{"kind":"formula","head":"남기는 것과 버리는 것","tex":"A = \\bar{A} + \\Delta","parts":[{"sym":"\\bar{A}","say":"에이 바라고 읽어요. 군집 안쪽 연결만 남긴 인접행렬이에요."},{"sym":"A_{tt}","say":"에이 티 티라고 읽어요. $t$ 번째 군집 안의 연결 블록이에요."},{"sym":"\\Delta","say":"델타라고 읽어요. 군집 사이 연결만 모은 행렬이에요."},{"sym":"A_{st}","say":"에이 에스 티라고 읽어요. 군집 $s$ 와 $t$ 사이 연결 블록이에요."}],"whole":"원래 **인접행렬(Adjacency Matrix)**은 둘을 합한 것이에요. 군집 사이 엣지를 지운다는 말은 델타를 0 으로 만든다는 뜻이에요."},{"kind":"steps","head":"노드 6개로 직접 써 봐요","steps":["노드는 A, B, C, D, E, F 이고 군집은 $G_1 = \\{A, B, C\\}$, $G_2 = \\{D, E, F\\}$ 예요.","엣지는 군집 안에 A-B, A-C, B-C, D-E, D-F, E-F 여섯 개예요.","군집 사이 엣지는 C-D 와 B-E 두 개예요. 전체 엣지는 8개예요.","왼쪽 위 3 곱하기 3 과 오른쪽 아래 3 곱하기 3 만 남기면 대각선 블록만 남아요.","지워지는 자리는 (3,4), (4,3), (2,5), (5,2) 네 곳이에요."],"answer":"엣지로는 C-D 와 B-E 두 개, 전체 8개 중 $2/8 = 25\\%$ 가 날아가요. 무방향이라 엣지 하나가 두 자리를 차지해요.","given":"노드 6개, 군집 2개짜리 작은 그래프를 씁니다."},{"kind":"figure","head":"인접행렬이 남길 블록과 버릴 블록으로 갈린다","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"98\" y=\"26\" font-size=\"16\" text-anchor=\"middle\">원래 인접행렬 A<\/text>\n<rect class=\"box2\" x=\"38\" y=\"42\" width=\"60\" height=\"60\" rx=\"4\"/>\n<rect class=\"box\" x=\"98\" y=\"42\" width=\"60\" height=\"60\" rx=\"4\"/>\n<rect class=\"box\" x=\"38\" y=\"102\" width=\"60\" height=\"60\" rx=\"4\"/>\n<rect class=\"box2\" x=\"98\" y=\"102\" width=\"60\" height=\"60\" rx=\"4\"/>\n<text class=\"t\" x=\"68\" y=\"78\" font-size=\"15\" text-anchor=\"middle\">G1 안<\/text>\n<text class=\"tm\" x=\"128\" y=\"78\" font-size=\"14\" text-anchor=\"middle\">사이<\/text>\n<text class=\"tm\" x=\"68\" y=\"138\" font-size=\"14\" text-anchor=\"middle\">사이<\/text>\n<text class=\"t\" x=\"128\" y=\"138\" font-size=\"15\" text-anchor=\"middle\">G2 안<\/text>\n<text class=\"tm\" x=\"98\" y=\"188\" font-size=\"14\" text-anchor=\"middle\">네 덩어리가 섞여 있어요<\/text>\n<text class=\"tb b1\" x=\"272\" y=\"26\" font-size=\"16\" text-anchor=\"middle\">군집 순서로 번호를 매기면<\/text>\n<rect class=\"box2 b1\" x=\"212\" y=\"42\" width=\"60\" height=\"60\" rx=\"4\"/>\n<rect class=\"box b1\" x=\"272\" y=\"42\" width=\"60\" height=\"60\" rx=\"4\"/>\n<rect class=\"box b1\" x=\"212\" y=\"102\" width=\"60\" height=\"60\" rx=\"4\"/>\n<rect class=\"box2 b1\" x=\"272\" y=\"102\" width=\"60\" height=\"60\" rx=\"4\"/>\n<text class=\"tb b1\" x=\"242\" y=\"78\" font-size=\"15\" text-anchor=\"middle\">남김<\/text>\n<text class=\"tm b1\" x=\"302\" y=\"78\" font-size=\"14\" text-anchor=\"middle\">0<\/text>\n<text class=\"tm b1\" x=\"242\" y=\"138\" font-size=\"14\" text-anchor=\"middle\">0<\/text>\n<text class=\"tb b1\" x=\"302\" y=\"138\" font-size=\"15\" text-anchor=\"middle\">남김<\/text>\n<text class=\"tb b1\" x=\"272\" y=\"188\" font-size=\"16\" text-anchor=\"middle\">대각선 블록만 남긴 것<\/text>\n<rect class=\"box b2\" x=\"378\" y=\"52\" width=\"40\" height=\"40\" rx=\"4\"/>\n<rect class=\"box2 b2\" x=\"418\" y=\"52\" width=\"40\" height=\"40\" rx=\"4\"/>\n<rect class=\"box2 b2\" x=\"378\" y=\"92\" width=\"40\" height=\"40\" rx=\"4\"/>\n<rect class=\"box b2\" x=\"418\" y=\"92\" width=\"40\" height=\"40\" rx=\"4\"/>\n<text class=\"tm b2\" x=\"418\" y=\"156\" font-size=\"14\" text-anchor=\"middle\">버리는 쪽<\/text>\n<text class=\"tm b2\" x=\"418\" y=\"176\" font-size=\"14\" text-anchor=\"middle\">델타<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"228\" font-size=\"16\" text-anchor=\"middle\">A 는 대각선 블록과 바깥 블록의 합이에요<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"252\" font-size=\"14\" text-anchor=\"middle\">Cluster-GCN 은 앞엣것만 쓰고 뒤엣것을 버려요<\/text>\n<\/svg>","caption":"번호를 군집 순서로 매기면 대각선 블록만 남기고 나머지를 버릴 수 있어요.","builds":3},{"kind":"points","head":"블록 대각 모양이 왜 좋은가요","items":["**블록 대각 행렬(Block-diagonal Matrix)**은 블록마다 따로 계산해도 결과가 같아요.","그래서 큰 행렬 곱 하나를 작은 행렬 곱 $c$ 개로 쪼갤 수 있어요.","그 $c$ 개는 서로 독립이라 한 번에 하나씩만 올려도 돼요.","노드가 $n$ 개면 인접행렬은 $n^2$ 칸인데 $c$ 조각이면 한 조각이 $n^2/c^2$ 칸이에요."]}],"pass3":[{"kind":"check","q":"**블록 대각 행렬(Block-diagonal Matrix)**이 되려면 무엇을 해야 하나요?","choices":["엣지를 더 그린다","노드 번호를 군집 순서로 다시 매긴다","가중치를 0으로 둔다","층을 늘린다"],"a":1,"why":"번호를 섞어 두면 같은 그래프라도 블록으로 안 보여요. 계산 결과는 같아요."},{"kind":"warn","head":"기호 때문에 헷갈리는 점","items":["델타는 그리스 문자 이름일 뿐 차이나 변화량이라는 뜻이 아니에요.","격자 그림의 Epoch T 에서 대각선 밖에 색칠된 칸은 p.57 의 여러 군집 묶기 이야기예요.","기본 **Cluster-GCN**은 대각선 블록 하나씩만 **미니 배치(Mini-batch)**로 써요."]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4061,0.0757],"c":[0,0.0019,0.4467,0.1077],"r":7.3736,"img":"img/L4/walk/p051_h.jpg"},"parts":[{"b":[0.05,0.145,0.53,0.05],"c":[0.0235,0.1111,0.583,0.1178],"r":8.7983,"img":"img/L4/walk/p051_20_01.jpg","say":"효율적인 군집화 알고리즘으로 작은 군집을 뽑아낸다예요."},{"b":[0.13,0.23,0.44,0.055],"c":[0.108,0.2025,0.484,0.11],"r":7.8222,"img":"img/L4/walk/p051_20_02.jpg","say":"첫째 식이에요. 전체 그래프를 $c$ 조각으로 나눈 결과를 적은 것이에요."},{"b":[0.13,0.31,0.45,0.14],"c":[0.1075,0.294,0.495,0.172],"r":5.1163,"img":"img/L4/walk/p051_20_03.jpg","say":"둘째와 셋째 식이에요. 왼쪽이 대각선 블록만 남긴 행렬, 오른쪽이 바깥만 모은 행렬이에요."},{"b":[0.05,0.52,0.44,0.055],"c":[0.028,0.4925,0.484,0.11],"r":7.8222,"img":"img/L4/walk/p051_20_04.jpg","say":"부분 그래프 수준에서 무작위 묶음 만들기예요."},{"b":[0.11,0.64,0.49,0.26],"c":[0.0855,0.624,0.539,0.292],"r":3.2816,"img":"img/L4/walk/p051_20_05.jpg","say":"아래 격자가 인접행렬이에요. 대각선 블록 하나가 군집 하나, 한 색이 한 배치예요."},{"b":[0.63,0.29,0.36,0.41],"c":[0.604,0.2695,0.396,0.451],"r":1.561,"img":"img/L4/walk/p051_20_06.jpg","say":"오른쪽 흐름도는 군집화, 배치 만들기, GNN 순서예요."}]}},{"p":52,"title":"Cluster-GCN 한 장 요약: 나누고 지우고 쓴다","terms":["Cluster-GCN","Mini-batch","SGD","Embedding Utilization","Homophily","GraphSAGE","Induced Subgraph","METIS"],"pass1":[{"kind":"say","lines":["**Cluster-GCN**을 세 줄로 요약해요.","하나, 그래프를 군집으로 나누고 군집 사이 엣지를 지워요.","둘, 부분 그래프 하나를 **미니 배치(Mini-batch)**로 써요.","셋, 이웃이 군집 안에 머무르니 **임베딩 활용도(Embedding Utilization)**가 최적이에요."]},{"kind":"analogy","head":"한 동네만 놓고 공부하기","scene":"전국 지도를 다 외우기는 어려워요. 그래서 오늘은 우리 동네만 놓고 공부하기로 했어요. 동네 안의 길은 전부 외울 수 있고, 동네 밖으로 나가는 큰 길 몇 개는 오늘은 없는 셈 쳐요. 내일은 옆 동네를 같은 방법으로 공부해요.","map":[["우리 동네 지도","군집 하나의 **유도 부분 그래프(Induced Subgraph)**"],["동네 밖으로 나가는 큰 길","지워지는 군집 사이 엣지"],["오늘 공부할 분량","하나의 **미니 배치(Mini-batch)**"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"그림 속 색이 알려 주는 것","items":["노드 색은 레이블, 즉 정답 분류예요.","주황 무리 안에 빨간 노드 하나가 섞여 있고 파랑 무리에도 빨강과 주황이 섞여 있어요.","즉 군집이 레이블과 완전히 일치하지는 않아요.","이 점이 p.56 의 치우친 레이블 분포 문제로 이어져요."]},{"kind":"points","head":"왜 잘라도 괜찮다고 믿을 수 있나요","items":["근거는 **동질성(Homophily)** 가정이에요. 인접한 노드는 서로 비슷하다는 말이에요.","같은 커뮤니티 안 이웃의 정보는 나와 비슷하니 유의미해요.","다른 커뮤니티에서 오는 정보는 나와 다르니 오히려 노이즈가 되기 쉬워요.","그러니 군집 사이 엣지를 지우는 것은 잡음 제거일 수도 있어요."]},{"kind":"steps","head":"이웃이 군집 안에 머무르는지 확인해요","steps":["군집 $G_1 = \\{A, B, C\\}$ 만 배치로 쓴다고 해요.","A 의 이웃은 B, C 이고 둘 다 배치 안에 있어요. 밖으로 나간 이웃이 없어요.","B 의 이웃은 A, C, E 인데 E 만 군집 밖이라 빠져요.","C 의 이웃은 A, B, D 인데 D 만 군집 밖이라 빠져요.","결국 배치에 추가로 가져와야 할 노드가 하나도 없어요."],"answer":"**GraphSAGE**로 A, B, C 를 학습하면 2층 기준 6개가 딸려 와 활용도가 $3/6 = 0.5$ 인데, **Cluster-GCN**은 $3/3 = 1$ 이에요.","given":"p.51 의 노드 6개 그래프를 그대로 씁니다."},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 **Cluster-GCN**의 해답을 아주 짧게 정리했어요.","나는 미니 배치를 할 건데 미니 배치를 커뮤니티 단위로 하겠다는 것이라고요.","그래프를 커뮤니티 단위로 쪼개고 쪼갠 조각을 배치로 보고 모델을 돌린다는 것이 전부라고 했어요."]}],"pass3":[{"kind":"exam","src":"2025 가을 중간 5번 (a) (3점)","q":"What is mini-batch training?","qko":"미니 배치 학습이 무엇인지 서술하세요. ClusterGCN 문제의 (a) 예요.","solve":["먼저 일반적인 정의를 써요. 데이터 전체가 아니라 작은 부분 집합으로 한 번씩 모델을 갱신하는 것이에요.","그다음 **Cluster-GCN**에서의 뜻을 붙여요. 그래프를 먼저 군집으로 나눠요.","각 **유도 부분 그래프(Induced Subgraph)**를 하나의 미니 배치로 써요.","그래서 메시지 패싱이 배치 안에서 끝나고 지역 연결이 보존돼요."],"answer":"Mini-batch training means training on graph clusters instead of the full graph, while preserving local connectivity within each batch."},{"kind":"english","head":"모범답안 문장 그대로","en":"Mini-batch training means training on graph clusters instead of the full graph, allowing efficient learning on large graphs while preserving local connectivity within each batch.","ko":"미니 배치 학습은 전체 그래프 대신 그래프 군집 위에서 학습하는 것으로, 배치 안의 지역 연결을 지키면서 큰 그래프를 효율적으로 학습하게 해 준다.","tip":"preserving local connectivity within each batch 가 점수를 주는 조각이에요."},{"kind":"warn","head":"배치 크기를 오해하지 마세요","items":["미니 배치는 노드 32개 같은 고정 크기가 아니에요.","**Cluster-GCN**의 배치 크기는 군집 크기이고 군집마다 다를 수 있어요.","활용도가 최적이라는 말은 군집 안에서 최적이라는 뜻이에요. 버린 엣지는 분모에 안 들어가요."]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4061,0.0757],"c":[0,0.0019,0.4467,0.1077],"r":7.3736,"img":"img/L4/walk/p052_h.jpg"},"parts":[{"b":[0.05,0.135,0.92,0.1],"c":[0,0.0828,1,0.2045],"r":8.6933,"img":"img/L4/walk/p052_20_01.jpg","say":"첫 줄은 p.50 과 같아요. **메티스(METIS)** 같은 알고리즘으로 빽빽한 부분 그래프를 찾아요."},{"b":[0.05,0.27,0.17,0.05],"c":[0.035,0.24,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p052_20_02.jpg","say":"여기서 **Cluster-GCN**이라는 이름이 처음 굵게 등장해요."},{"b":[0.08,0.34,0.55,0.055],"c":[0.0525,0.3064,0.605,0.1222],"r":8.8016,"img":"img/L4/walk/p052_20_03.jpg","say":"그래프를 여러 군집으로 나누고 군집 사이 엣지를 지운다예요."},{"b":[0.08,0.41,0.45,0.055],"c":[0.0575,0.3825,0.495,0.11],"r":8.0,"img":"img/L4/walk/p052_20_04.jpg","say":"부분 그래프 하나를 **확률적 경사하강(SGD)**의 미니 배치로 쓴다예요."},{"b":[0.08,0.48,0.58,0.055],"c":[0.051,0.4431,0.638,0.1289],"r":8.7992,"img":"img/L4/walk/p052_20_05.jpg","say":"노드의 이웃이 군집 안에 머무르므로 임베딩 활용도가 최적이다예요."},{"b":[0.33,0.55,0.25,0.38],"c":[0.3175,0.531,0.275,0.418],"r":1.1696,"img":"img/L4/walk/p052_20_06.jpg","say":"아래 그림에서 굵은 곡선이 군집 경계이고 곡선을 가로지르는 점선이 지워질 엣지예요."}]}},{"p":53,"title":"같은 군집 안 노드만 평균에 넣는다","terms":["Cluster-GCN","GraphSAGE","Receptive Field","Concatenation","ReLU","Recursive Neighborhood Expansion","GraphSAINT"],"pass1":[{"kind":"say","lines":["**GraphSAGE**는 층마다 이웃을 몇 명씩 뽑아도 옆 군집으로 계속 번져 나갔어요.","**Cluster-GCN**은 층을 아무리 쌓아도 군집 경계를 넘지 않아요.","그래서 **수용 영역(Receptive Field)**이 군집 크기에서 멈춰요."]},{"kind":"look","walked":1},{"kind":"analogy","head":"한 명만 빼고 세는 평균","scene":"모둠 점수를 낼 때 우리 모둠 사람만 세기로 했어요. 지수와 자주 이야기하는 친구가 세 명인데 그중 한 명은 다른 모둠이에요. 그러면 그 친구 점수는 더하지도 않고, 나누는 인원수에서도 빼요. 세 명으로 나누는 게 아니라 두 명으로 나눠요.","map":[["우리 모둠 사람만 세기","같은 군집 이웃만 평균하기"],["나누는 인원수에서도 빼기","분모에서도 빼는 것"],["다른 모둠 친구","군집 밖 이웃"]]}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.05,"y":0.14,"w":0.18,"h":0.05,"say":"맨 위가 이웃 확장 억제예요.","c":[0.038,0.11,0.204,0.11],"r":3.297,"img":"img/L4/walk/p053_20_01.jpg"},{"x":0.07,"y":0.21,"w":0.28,"h":0.05,"say":"그 아래가 같은 군집 안 노드만 고려한다예요.","c":[0.056,0.18,0.308,0.11],"r":4.9778,"img":"img/L4/walk/p053_20_02.jpg"},{"x":0.11,"y":0.845,"w":0.29,"h":0.06,"say":"왼쪽 캡션은 고정 크기 이웃 샘플링, $S = 2$ 예요. **GraphSAGE** 쪽이에요.","c":[0.0955,0.82,0.319,0.11],"r":5.1556,"img":"img/L4/walk/p053_20_03.jpg"},{"x":0.58,"y":0.83,"w":0.2,"h":0.06,"say":"오른쪽 캡션은 군집 안 노드만 뽑는다예요. 파란 화살표가 끊어진 자리를 가리켜요.","c":[0.568,0.805,0.224,0.11],"r":3.6202,"img":"img/L4/walk/p053_20_04.jpg"}]},{"kind":"formula","head":"시험에 주어지는 갱신식","tex":"h_{N(i)}^{(k)} = \\mathrm{MEAN}\\left(\\{\\, h_u^{(k-1)} : u \\in N(i),\\ G_u = G_i \\,\\}\\right)","parts":[{"sym":"N(i)","say":"엔 오브 아이라고 읽어요. 노드 $i$ 의 이웃 전체예요."},{"sym":"G_i","say":"지 아이라고 읽어요. 노드 $i$ 가 속한 군집 이름이에요."},{"sym":"G_u = G_i","say":"$u$ 가 $i$ 와 같은 군집일 때만 센다는 조건이에요."},{"sym":"\\mathrm{MEAN}","say":"민이라고 읽어요. 평균이에요."}],"whole":"같은 군집 이웃의 값만 모아 평균낸다는 뜻이에요. 이 조건 하나가 **GraphSAGE** 문제와 가르는 지점이에요."},{"kind":"formula","head":"나와 이웃을 이어 붙이고 렐루","tex":"h_i^{(k)} = \\mathrm{ReLU}\\left(h_i^{(k-1)} \\,\\|\\, h_{N(i)}^{(k)}\\right)","parts":[{"sym":"h_i^{(k-1)}","say":"이전 층에서의 내 값이에요. 앞자리에 들어가요."},{"sym":"\\|","say":"세로 막대 두 개는 **이어 붙이기(Concatenation)**예요. 두 값을 나란히 붙여요."},{"sym":"h_{N(i)}^{(k)}","say":"방금 구한 이웃 평균이에요. 뒷자리에 들어가요."},{"sym":"\\mathrm{ReLU}","say":"렐루라고 읽어요. $\\max(0, x)$ 로 음수를 0 으로 바꿔요."}],"whole":"내 값과 이웃 평균을 두 칸짜리 벡터로 붙인 다음 음수만 0 으로 바꾼다는 뜻이에요."},{"kind":"steps","head":"강의안 예제로 손계산을 해요","steps":["노드 6개, $G_1 = \\{A, B, C\\}$, $G_2 = \\{D, E, F\\}$, 군집을 넘는 엣지는 C-D 와 B-E 예요.","처음 값은 A 가 0.4, B 가 0.1, C 가 0.3, D 가 0.2, E 가 0.5, F 가 0.2 예요.","1단계, 같은 군집 이웃만 남겨요. B 는 E 를, C 는 D 를, D 는 C 를, E 는 B 를 빼요.","2단계, 남은 이웃의 평균이에요. A 는 0.20, B 는 0.35, C 는 0.25 예요.","D 는 0.35, E 는 0.20, F 는 0.35 예요. B 의 분모가 3 이 아니라 2 인 점을 보세요."],"answer":"3단계로 자기 값과 이어 붙이면 A 는 $[0.4,\\ 0.20]$, B 는 $[0.1,\\ 0.35]$, C 는 $[0.3,\\ 0.25]$ 예요.","given":"$k = 1$ 에서 모든 노드의 출력 표현을 구해요."},{"kind":"steps","head":"같은 문제를 GraphSAGE 로 풀면","steps":["군집 조건만 빼면 **GraphSAGE** 문제가 돼요. 이웃을 전부 쓰니 분모가 달라져요.","B 는 0.4, 0.3, 0.5 를 써서 $1.2/3 = 0.40$ 이에요. 아까는 0.35 였어요.","C 는 0.4, 0.1, 0.2 를 써서 $0.7/3$ 으로 약 0.23 이에요. 아까는 0.25 였어요.","D 는 약 0.33, E 는 약 0.17 이에요.","A 와 F 만 두 모델에서 값이 같아요."],"answer":"A 와 F 는 군집 밖 이웃이 하나도 없어서 지울 것이 없었거든요. 나머지 네 노드는 값도 분모도 달라져요.","given":"같은 그래프, 같은 초기값에 조건 $G_u = G_i$ 만 뺍니다."},{"kind":"figure","head":"군집 경계에서 이웃 확장이 멈춘다","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"118\" y=\"24\" font-size=\"16\" text-anchor=\"middle\">GraphSAGE<\/text>\n<line class=\"e\" x1=\"60\" y1=\"70\" x2=\"100\" y2=\"70\"/>\n<line class=\"e\" x1=\"100\" y1=\"70\" x2=\"100\" y2=\"110\"/>\n<line class=\"e2\" x1=\"100\" y1=\"70\" x2=\"170\" y2=\"70\"/>\n<line class=\"e\" x1=\"170\" y1=\"70\" x2=\"170\" y2=\"110\"/>\n<line class=\"e\" x1=\"60\" y1=\"110\" x2=\"100\" y2=\"110\"/>\n<line class=\"e\" x1=\"170\" y1=\"110\" x2=\"205\" y2=\"110\"/>\n<circle class=\"n2\" cx=\"60\" cy=\"70\" r=\"13\"/>\n<circle class=\"n\" cx=\"100\" cy=\"70\" r=\"12\"/>\n<circle class=\"n3 b1\" cx=\"170\" cy=\"70\" r=\"12\"/>\n<circle class=\"n\" cx=\"100\" cy=\"110\" r=\"12\"/>\n<circle class=\"n\" cx=\"60\" cy=\"110\" r=\"12\"/>\n<circle class=\"n3 b1\" cx=\"170\" cy=\"110\" r=\"12\"/>\n<circle class=\"n3 b1\" cx=\"205\" cy=\"110\" r=\"12\"/>\n<text class=\"tm\" x=\"80\" y=\"150\" font-size=\"14\" text-anchor=\"middle\">왼쪽 군집<\/text>\n<text class=\"tm b1\" x=\"186\" y=\"150\" font-size=\"14\" text-anchor=\"middle\">오른쪽 군집<\/text>\n<text class=\"tb b1\" x=\"118\" y=\"180\" font-size=\"16\" text-anchor=\"middle\">층이 쌓이면 옆 군집까지 번져요<\/text>\n<line class=\"e\" x1=\"240\" y1=\"36\" x2=\"240\" y2=\"200\"/>\n<text class=\"tb\" x=\"362\" y=\"24\" font-size=\"16\" text-anchor=\"middle\">Cluster-GCN<\/text>\n<line class=\"e\" x1=\"300\" y1=\"70\" x2=\"340\" y2=\"70\"/>\n<line class=\"e\" x1=\"340\" y1=\"70\" x2=\"340\" y2=\"110\"/>\n<line class=\"e\" x1=\"410\" y1=\"70\" x2=\"410\" y2=\"110\"/>\n<line class=\"e\" x1=\"300\" y1=\"110\" x2=\"340\" y2=\"110\"/>\n<line class=\"e\" x1=\"410\" y1=\"110\" x2=\"445\" y2=\"110\"/>\n<circle class=\"n2\" cx=\"300\" cy=\"70\" r=\"13\"/>\n<circle class=\"n\" cx=\"340\" cy=\"70\" r=\"12\"/>\n<circle class=\"n4 b2\" cx=\"410\" cy=\"70\" r=\"12\"/>\n<circle class=\"n\" cx=\"340\" cy=\"110\" r=\"12\"/>\n<circle class=\"n\" cx=\"300\" cy=\"110\" r=\"12\"/>\n<circle class=\"n4 b2\" cx=\"410\" cy=\"110\" r=\"12\"/>\n<circle class=\"n4 b2\" cx=\"445\" cy=\"110\" r=\"12\"/>\n<text class=\"tb b2\" x=\"374\" y=\"64\" font-size=\"16\" text-anchor=\"middle\">끊김<\/text>\n<text class=\"tm\" x=\"320\" y=\"150\" font-size=\"14\" text-anchor=\"middle\">왼쪽 군집<\/text>\n<text class=\"tm b2\" x=\"426\" y=\"150\" font-size=\"14\" text-anchor=\"middle\">건너가지 않아요<\/text>\n<text class=\"tb b2\" x=\"362\" y=\"180\" font-size=\"16\" text-anchor=\"middle\">수용 영역이 군집에서 멈춰요<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"232\" font-size=\"16\" text-anchor=\"middle\">차이는 조건 하나예요<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"256\" font-size=\"14\" text-anchor=\"middle\">같은 군집 이웃만 평균에 넣어요<\/text>\n<\/svg>","caption":"왼쪽은 옆 군집까지 번지고 오른쪽은 경계에서 멈춰요. **재귀적 이웃 확장(Recursive Neighborhood Expansion)**이 사라져요.","builds":3}],"pass3":[{"kind":"exam","src":"2025 가을 중간 5번 (b) (7점)","q":"Calculate the output representations of all nodes at layer k = 1, where h_N(i) = MEAN of neighbours u with G_u = G_i, and h_i = ReLU(h_i concat h_N(i)).","qko":"노드 6개 A 부터 F 까지가 있고 군집은 $G_1$ 과 $G_2$ 예요. 처음 값은 차례로 0.1, 0.3, 0.2, 0.4, 0.1, 0.2 예요. $k = 1$ 에서 모든 노드의 출력 표현을 구하세요.","solve":["같은 군집 이웃만 모아요. $G_1$ 안에서 A 의 이웃은 B, C 예요.","$h_{N(A)} = \\mathrm{MEAN}(0.3, 0.2) = 0.25$, $h_{N(B)} = \\mathrm{MEAN}(0.1, 0.2) = 0.15$ 예요.","$h_{N(C)} = \\mathrm{MEAN}(0.1, 0.3) = 0.2$ 예요. $G_2$ 도 같은 방식이에요.","$h_{N(D)} = \\mathrm{MEAN}(0.1, 0.2) = 0.15$, $h_{N(E)} = \\mathrm{MEAN}(0.4, 0.2) = 0.3$ 이에요.","$h_{N(F)} = \\mathrm{MEAN}(0.4, 0.1) = 0.25$ 예요.","자기 값을 앞에 이어 붙이고 렐루를 씌워요. 전부 양수라 값이 그대로예요."],"answer":"$h_A = [0.1, 0.25]$, $h_B = [0.3, 0.15]$, $h_C = [0.2, 0.2]$, $h_D = [0.4, 0.15]$, $h_E = [0.1, 0.3]$, $h_F = [0.2, 0.25]$"},{"kind":"warn","head":"가장 흔한 실수 다섯 가지","items":["분모를 안 고치는 실수. 군집 밖 이웃은 값만 빼는 게 아니라 개수에서도 빼요.","자기 자신을 이웃에 넣는 실수. $N(i)$ 에 $i$ 자신은 안 들어가요.","**이어 붙이기(Concatenation)** 순서를 바꾸는 실수. 내 값이 앞, 이웃 평균이 뒤예요."]},{"kind":"warn","head":"남은 두 가지 실수","items":["이웃이 하나도 안 남으면 이웃 칸을 0 으로 두고 $[h_i^{(0)},\\ 0]$ 으로 써요.","**렐루(ReLU)**를 건너뛰는 실수. 음수 특징이 있으면 반드시 0 으로 바꿔요.","반올림은 기출 해설을 따라 소수 둘째 자리로 해요."]},{"kind":"check","q":"**Cluster-GCN** 문제에서 노드 B 의 이웃이 A, C, E 이고 E 만 다른 군집이면 분모는?","choices":["3","2","1","4"],"a":1,"why":"군집 밖 이웃은 분자에서도 분모에서도 빠져요. 그래서 2 예요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4061,0.2458],"c":[0,0.0019,0.4467,0.2778],"r":2.8587,"img":"img/L4/walk/p053_h.jpg"},"parts":[{"b":[0.12,0.33,0.32,0.47],"c":[0.104,0.3065,0.352,0.517],"r":1.2104,"img":"img/L4/walk/p053_11_01.jpg","say":"왼쪽 세 층은 **GraphSAGE**예요. 빨간 노드가 양쪽 덩어리에 계속 남아 있어요."},{"b":[0.51,0.33,0.36,0.47],"c":[0.492,0.3065,0.396,0.517],"r":1.3617,"img":"img/L4/walk/p053_11_02.jpg","say":"오른쪽 세 층은 **Cluster-GCN**이에요. 왼쪽 덩어리에서만 일이 벌어져요."},{"b":[0.51,0.68,0.24,0.07],"c":[0.498,0.66,0.264,0.11],"r":4.2667,"img":"img/L4/walk/p053_11_03.jpg","say":"두 덩어리를 잇던 선이 검은 점선으로 바뀌었어요. 없는 셈 친다는 표시예요."}]}},{"p":54,"title":"Cluster-GCN 정리: 기여와 한계","terms":["Cluster-GCN","GraphSAGE","GCN","METIS","Recursive Neighborhood Expansion","Bias","Variance","Layer-wise Sampling"],"pass1":[{"kind":"say","lines":["**Cluster-GCN**의 기여는 셋이에요.","이웃 확장이 아예 없고, 메모리가 알뜰하고, 손대지 않은 GNN을 그대로 써요.","한계는 둘이에요.","샘플링 품질에 대한 분석이 없고, 군집화 알고리즘에 성능이 크게 좌우돼요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"기여 세 줄을 하나씩","boxes":[{"x":0.08,"y":0.225,"w":0.08,"h":0.05,"say":"상자 제목이 기여예요.","c":[0.02,0.195,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p054_20_01.jpg"},{"x":0.09,"y":0.29,"w":0.39,"h":0.08,"say":"묶음의 부분 그래프 바깥 노드는 아예 뽑지 않아서 이웃 확장이 없다예요.","c":[0.0705,0.274,0.429,0.112],"r":6.8095,"img":"img/L4/walk/p054_20_02.jpg"},{"x":0.09,"y":0.39,"w":0.37,"h":0.05,"say":"실용적이다, 성능이 좋고 메모리도 알뜰하다예요.","c":[0.0715,0.36,0.407,0.11],"r":6.5778,"img":"img/L4/walk/p054_20_03.jpg"},{"x":0.09,"y":0.49,"w":0.33,"h":0.05,"say":"부분 그래프마다 손대지 않은 GNN을 그대로 쓴다예요.","c":[0.0735,0.46,0.363,0.11],"r":5.8667,"img":"img/L4/walk/p054_20_04.jpg"}]},{"kind":"look","head":"한계 두 줄을 하나씩","boxes":[{"x":0.52,"y":0.225,"w":0.08,"h":0.05,"say":"상자 제목이 한계예요.","c":[0.46,0.195,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p054_21_01.jpg"},{"x":0.52,"y":0.29,"w":0.39,"h":0.08,"say":"분석이 없다. 샘플링 품질, **편향(Bias)**과 **분산(Variance)**을 다루지 않는다예요.","c":[0.5005,0.274,0.429,0.112],"r":6.8095,"img":"img/L4/walk/p054_21_02.jpg"},{"x":0.52,"y":0.39,"w":0.33,"h":0.05,"say":"성능이 군집화 알고리즘에 크게 좌우된다예요.","c":[0.5035,0.36,0.363,0.11],"r":5.8667,"img":"img/L4/walk/p054_21_03.jpg"}]},{"kind":"points","head":"기여 세 줄을 풀어 읽어요","items":["이웃 확장이 없다. 줄어든다가 아니라 없다예요. 배치 크기가 그냥 군집 크기예요.","메모리가 알뜰하다. 올릴 노드 수를 미리 알 수 있어 GPU 메모리를 딱 맞게 잡아요.","손대지 않은 GNN을 쓴다. 데이터를 자르는 일만 하고 모델 코드는 평범한 **GCN**이에요.","세 번째가 교수님이 말한 직관적이고 간단하다의 실체예요."]},{"kind":"points","head":"한계 두 줄을 풀어 읽어요","items":["분석이 없다. 이렇게 잘라도 원래 결과와 비슷하다는 수학적 보장이 없어요.","**레이어 단위 샘플링(Layer-wise Sampling)**은 각 층 출력이 원본과 비슷함을 보장했죠.","군집화 알고리즘에 좌우된다. 잘 자르면 잃는 엣지가 적고 못 자르면 많이 잃어요.","성능의 절반이 GNN이 아니라 **메티스(METIS)**에 달려 있는 셈이에요."]},{"kind":"compare","head":"세 방식을 이 슬라이드 기준으로","cols":["항목","**GraphSAGE**","FastGCN, ASGCN","**Cluster-GCN**"],"rows":[["이웃 확장","줄지만 남음","층마다 고정","없음"],["이론적 보장","없음","있음","없음"],["모델 코드","집계기를 고침","샘플링 분포를 설계","손대지 않음"],["성능을 좌우하는 것","뽑는 개수 $S$","제안 분포의 품질","군집화 알고리즘"]]},{"kind":"steps","head":"이웃 확장이 없다를 숫자로 확인해요","steps":["평균 차수 10, 군집 크기 500 이라고 해요.","층 1개면 **GraphSAGE**가 $S = 5$ 로 5개, **Cluster-GCN**은 500 이에요.","층 2개면 25 대 500, 층 3개면 125 대 500 이에요.","층 4개면 625 대 500 으로 뒤집혀요.","GraphSAGE 열은 층마다 5배씩 커지고 Cluster-GCN 열은 층수와 상관없이 고정이에요."],"answer":"게다가 Cluster-GCN 의 500 은 노드 하나가 아니라 500개 노드 전부의 손실을 얻는 대가예요.","given":"층수를 바꿔 가며 배치에 올라가는 노드 수를 비교해요."},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 **Cluster-GCN**을 이렇게 기억하라고 했어요.","되게 러프하고 조금 난폭한 방식으로 문제를 해결하는 알고리즘인데 작동은 잘한다고요.","난폭하다는 것이 한계이고 작동을 잘한다는 것이 기여예요."]}],"pass3":[{"kind":"english","head":"기여를 쓰는 문장","en":"Cluster-GCN removes neighborhood expansion because nodes outside the sampled subgraph are never touched, and it works with any off-the-shelf GNN.","ko":"Cluster-GCN은 뽑힌 부분 그래프 밖 노드를 아예 건드리지 않아 이웃 확장을 완전히 없애고, 기성 GNN을 그대로 쓸 수 있다.","tip":"off-the-shelf GNN 이라는 표현을 그대로 외워 두세요."},{"kind":"english","head":"한계를 쓰는 문장","en":"However, it gives no analysis of sampling quality, bias or variance, and its accuracy depends heavily on the clustering algorithm.","ko":"다만 샘플링 품질, 편향, 분산에 대한 분석이 없고 정확도가 군집화 알고리즘에 크게 좌우된다.","tip":"State the contributions and limitations of Cluster-GCN 이 나오면 두 문장을 이어 쓰면 돼요."},{"kind":"warn","head":"표현을 오해하지 마세요","items":["이웃 확장이 없다를 이웃을 안 본다로 읽으면 안 돼요. 군집 안 이웃은 전부 봐요.","메모리 알뜰과 파라미터가 적다는 다른 말이에요. 가중치 개수는 그대로예요.","줄어드는 건 중간 계산 결과를 담는 메모리예요."]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.2456,0.0757],"c":[0.0008,0.0019,0.2701,0.1077],"r":4.4585,"img":"img/L4/walk/p054_h.jpg"},"parts":[{"b":[0.065,0.19,0.425,0.41],"c":[0.0437,0.1695,0.4675,0.451],"r":1.8428,"img":"img/L4/walk/p054_11_01.jpg","say":"왼쪽 회색 상자가 기여예요. 불릿 세 개가 있어요."},{"b":[0.505,0.19,0.435,0.41],"c":[0.4833,0.1695,0.4785,0.451],"r":1.8862,"img":"img/L4/walk/p054_11_02.jpg","say":"오른쪽 회색 상자가 한계예요. 불릿 두 개가 있어요."}]}},{"p":55,"title":"CiteSeer 실험: 20% 를 지워도 그대로","terms":["CiteSeer","Cluster-GCN","Community","Homophily","Scale-free Graph","METIS","Message Passing","Mini-batch"],"pass1":[{"kind":"say","lines":["그렇게 잘라도 괜찮냐는 물음에 대한 실험 답이에요.","**사이트시어(CiteSeer)**를 100 조각으로 나누면 엣지의 약 20% 가 사라져요.","그런데 정확도는 72.0 에서 71.5 로 0.5 밖에 안 떨어져요.","반면 아무렇게나 나누면 46.1 로 무너져요."]},{"kind":"analogy","head":"책을 나누는 두 가지 방법","scene":"두꺼운 문제집을 100 권으로 나눠 들고 다니기로 했어요. 단원 경계를 따라 자르면 한 권에 같은 단원이 모여 공부가 잘돼요. 마구 섞어 나누면 한 권에 온갖 단원이 한 문제씩 들어가 흐름이 끊겨요.","map":[["단원 경계를 따라 자르기","**메티스(METIS)** 로 하는 그래프 분할"],["문제를 마구 섞어 자르기","무작위 분할"],["끊긴 흐름","엣지가 거의 남지 않아 사라진 **메시지 패싱(Message Passing)**"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"compare","head":"**사이트시어(CiteSeer)** 노드 분류 정확도","cols":["조각 수","무작위 분할","그래프 분할"],"rows":[["1 (분할 없음)","72.0","72.0"],["100 개 분할","46.1","71.5 (엣지 약 20% 제거)"]]},{"kind":"steps","head":"표에서 두 가지를 계산해요","steps":["그래프 분할의 손실은 $72.0 - 71.5 = 0.5$ 포인트예요.","무작위 분할의 손실은 $72.0 - 46.1 = 25.9$ 포인트예요.","몇 배 차이인가 보면 $25.9 / 0.5$ 로 약 52 배예요.","같은 100 조각인데 어떻게 나누느냐가 이만큼 차이를 내요.","**사이트시어(CiteSeer)**는 6개 분류라 찍기만 해도 약 17% 는 맞아요."],"answer":"46.1 은 72.0 에서 배운 것의 절반쯤을 날린 값이에요. 그래프 구조에서 얻던 성능이 통째로 사라진 거예요.","given":"표의 네 칸을 그대로 씁니다."},{"kind":"figure","head":"같은 100 조각이라도 어디를 자르냐가 전부","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"240\" y=\"24\" font-size=\"16\" text-anchor=\"middle\">CiteSeer 노드 분류 정확도<\/text>\n<line class=\"e\" x1=\"60\" y1=\"210\" x2=\"440\" y2=\"210\"/>\n<rect class=\"box\" x=\"90\" y=\"66\" width=\"70\" height=\"144\" rx=\"4\"/>\n<text class=\"tb\" x=\"125\" y=\"58\" font-size=\"16\" text-anchor=\"middle\">72.0<\/text>\n<text class=\"tm\" x=\"125\" y=\"232\" font-size=\"14\" text-anchor=\"middle\">분할 없음<\/text>\n<rect class=\"box2 b1\" x=\"205\" y=\"67\" width=\"70\" height=\"143\" rx=\"4\"/>\n<text class=\"tb b1\" x=\"240\" y=\"59\" font-size=\"16\" text-anchor=\"middle\">71.5<\/text>\n<text class=\"tm b1\" x=\"240\" y=\"232\" font-size=\"14\" text-anchor=\"middle\">그래프 분할<\/text>\n<text class=\"tm b1\" x=\"240\" y=\"252\" font-size=\"14\" text-anchor=\"middle\">100 조각<\/text>\n<rect class=\"box b2\" x=\"320\" y=\"118\" width=\"70\" height=\"92\" rx=\"4\"/>\n<text class=\"tb b2\" x=\"355\" y=\"110\" font-size=\"16\" text-anchor=\"middle\">46.1<\/text>\n<text class=\"tm b2\" x=\"355\" y=\"232\" font-size=\"14\" text-anchor=\"middle\">무작위 분할<\/text>\n<text class=\"tm b2\" x=\"355\" y=\"252\" font-size=\"14\" text-anchor=\"middle\">100 조각<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"44\" font-size=\"16\" text-anchor=\"middle\">엣지 약 20% 를 지워도 0.5 포인트만 내려요<\/text>\n<\/svg>","caption":"군집 경계를 따라 자르면 거의 안 떨어지고 무작위로 자르면 무너져요.","builds":3},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 이 실험을 이렇게 설명했어요.","분할을 하고 나니 엣지들이 엄청 없어질 줄 알았는데 거의 없어지지 않더라고요.","정보 소실이 많지 않아서 어지간한 데이터셋에서는 잘 작동하는 방식이라고 했어요.","실세계 그래프가 **스케일 프리 그래프(Scale-free Graph)**이기 때문이라고 다시 짚었어요."]},{"kind":"mining","src":"마이닝 5강 Community Detection","lines":["**사이트시어(CiteSeer)**는 노드 3312개, 엣지 4732개짜리 인용 네트워크예요.","노드가 논문이고 엣지가 인용 관계예요. Cora, PubMed 와 함께 기본 벤치마크예요.","같은 분야 논문끼리 서로 인용하는 경향이 강해서 **동질성(Homophily)**이 잘 성립해요.","그래서 **Cluster-GCN**이 잘 통해요."]}],"pass3":[{"kind":"english","head":"실험 결과를 쓰는 문장","en":"On CiteSeer with 100 partitions, graph partitioning removes about 20 percent of the edges but the accuracy only drops from 72.0 to 71.5.","ko":"CiteSeer를 100 분할하면 그래프 분할은 엣지의 약 20% 를 지우지만 정확도는 72.0 에서 71.5 로만 떨어지고 무작위 분할은 46.1 로 떨어진다.","tip":"뒤에 cutting along community boundaries loses very little information 을 붙이면 좋아요."},{"kind":"check","q":"**사이트시어(CiteSeer)**를 100 조각으로 무작위 분할했을 때 정확도는?","choices":["72.0","71.5","46.1","17.0"],"a":2,"why":"무작위로 나누면 조각 안에 엣지가 거의 안 남아 46.1 로 무너져요."},{"kind":"warn","head":"표를 읽을 때 조심할 점","items":["표의 숫자는 정확도이지 엣지 비율이 아니에요. 엣지 비율은 괄호 안의 약 20% 하나뿐이에요.","20% 제거해도 괜찮다를 아무 엣지나 20% 지워도 괜찮다로 읽으면 안 돼요.","**커뮤니티(Community)** 경계에 있는 20% 라서 괜찮은 거예요."]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4061,0.0757],"c":[0,0.0019,0.4467,0.1077],"r":7.3736,"img":"img/L4/walk/p055_h.jpg"},"parts":[{"b":[0.04,0.15,0.6,0.055],"c":[0.01,0.1108,0.66,0.1333],"r":8.8022,"img":"img/L4/walk/p055_20_01.jpg","say":"앞 세 줄은 p.52 와 같은 문장이에요."},{"b":[0.04,0.36,0.85,0.11],"c":[0,0.3205,0.935,0.1889],"r":8.7995,"img":"img/L4/walk/p055_20_02.jpg","say":"네 번째 줄이 새로워요. 엣지를 20% 지워도 **GCN** 모델의 정확도는 거의 그대로다예요."},{"b":[0.11,0.605,0.53,0.185],"c":[0.0835,0.589,0.583,0.217],"r":4.7762,"img":"img/L4/walk/p055_20_03.jpg","say":"아래 표예요. 세로는 몇 조각으로 나눴는지, 가로는 어떻게 나눴는지예요."},{"b":[0.62,0.55,0.26,0.38],"c":[0.607,0.531,0.286,0.418],"r":1.2164,"img":"img/L4/walk/p055_20_04.jpg","say":"오른쪽 그림은 p.52 와 같은 군집 그림이에요."}]}},{"p":56,"title":"문제: 한 군집 안에서 레이블이 치우친다","terms":["Cluster-GCN","SGD","Homophily","Community","Mini-batch","Bias","Embedding Utilization"],"pass1":[{"kind":"say","lines":["이번에는 나쁜 소식이에요.","군집은 비슷한 노드를 모아 놓은 곳이라 레이블도 비슷한 것끼리 모여요.","그래서 배치 하나의 정답 분포가 원본과 달라져요.","이것이 편향된 **확률적 경사하강(SGD)**으로 이어져요."]},{"kind":"analogy","head":"하루에 한 과목만 공부하기","scene":"민지가 월요일에 수학만 여덟 시간, 화요일에 영어만 여덟 시간 공부했어요. 화요일 저녁이 되니 월요일에 본 수학이 흐릿해졌어요. 매일 골고루 두 시간씩 공부한 친구는 두 과목 다 안정적으로 기억해요. 배치도 똑같아요.","map":[["하루에 한 과목만","한 군집만 담긴 **미니 배치(Mini-batch)**"],["흐릿해진 수학","반대쪽으로 밀려난 가중치"],["골고루 섞어 공부","여러 군집을 섞은 배치"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"왜 이런 일이 생기나요","items":["이건 사고가 아니라 필연이에요. 세 문장으로 이어져요.","하나, GNN의 근본 가정은 **동질성(Homophily)**, 인접한 노드는 비슷하다예요.","둘, 군집화는 인접한 노드를 한 덩어리로 모으는 일이에요.","셋, 따라서 군집 하나에는 레이블이 같은 노드가 모이게 돼요."]},{"kind":"points","head":"편향된 **확률적 경사하강(SGD)**이 왜 나쁜가요","items":["SGD 는 배치 하나가 전체를 대충 닮았을 것이라는 전제 위에서 움직여요.","배치가 한쪽으로 쏠리면 그 전제가 깨져요.","빨강만 든 배치로 갱신하면 다 빨강이라고 답하면 되겠구나 쪽으로 밀려요.","결과는 갈지자로 왔다 갔다 하면서 잘 수렴하지 않는 학습이에요."]},{"kind":"steps","head":"레이블 비율을 직접 세어요","steps":["노드 12개에 빨강 4개, 주황 4개, 파랑 4개로 고르게 있다고 해요.","원본의 빨강 비율은 $4/12$ 로 약 33% 예요.","군집 G1 이 빨강 3, 주황 1, 파랑 0 이면 배치 안 빨강 비율이 $3/4 = 75\\%$ 예요.","군집 G2 가 빨강 0, 주황 3, 파랑 1 이면 빨강 비율이 $0/4 = 0\\%$ 예요.","G1 과 G2 를 합치면 빨강 3, 주황 4, 파랑 1 로 비율이 $3/8$ 로 약 38% 예요."],"answer":"혼자면 75% 와 0% 로 튀는데 합치면 33% 에 가까운 38% 가 돼요. 이것이 다음 슬라이드의 답이에요.","given":"노드 12개를 군집 3개로 나눈 예를 씁니다."},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 커뮤니티 안에서는 레이블이 대부분 비슷할 것이라고 했어요.","어차피 다 비슷하니 그 정보만 있으면 되지 않냐고 생각할 수 있지만요.","항상 모두 같지는 않다는 것이 문제라고 했어요.","일부 다른 노드를 학습할 때는 정보를 골고루 봐야 하는데 그러지 못해요."]}],"pass3":[{"kind":"english","head":"치우친 레이블을 쓰는 문장","en":"Because clustering groups similar nodes together, the label distribution inside one cluster differs from that of the whole dataset, which makes each SGD step biased.","ko":"군집화는 비슷한 노드를 모으므로 한 군집 안의 레이블 분포가 전체와 달라지고, 그 결과 SGD의 각 갱신이 편향된다.","tip":"makes each SGD step biased 가 결론 조각이에요."},{"kind":"check","q":"**Cluster-GCN**에서 레이블이 치우치는 근본 원인은 무엇인가요?","choices":["레이블이 원래 불균형해서","군집화가 비슷한 노드를 모으기 때문에","층이 너무 깊어서","엣지가 너무 많아서"],"a":1,"why":"**동질성(Homophily)** 덕분에 이웃이 비슷하고, 군집화는 이웃을 모으니 필연이에요."},{"kind":"warn","head":"두 문제를 섞지 마세요","items":["치우친 레이블은 배치 안의 문제예요. 데이터 전체가 불균형하다는 뜻이 아니에요.","엣지가 사라지는 문제는 정보 손실, 이 문제는 학습 안정성이에요.","한계를 두 개 쓰라고 하면 둘 다 쓰면 좋아요."]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4061,0.0757],"c":[0,0.0019,0.4467,0.1077],"r":7.3736,"img":"img/L4/walk/p056_h.jpg"},"parts":[{"b":[0.05,0.15,0.32,0.05],"c":[0.034,0.12,0.352,0.11],"r":5.6889,"img":"img/L4/walk/p056_20_01.jpg","say":"맨 위가 문제, 치우친 레이블 분포예요. 치우친이 빨간 글씨예요."},{"b":[0.09,0.22,0.38,0.05],"c":[0.071,0.19,0.418,0.11],"r":6.7556,"img":"img/L4/walk/p056_20_02.jpg","say":"레이블이 비슷한 노드끼리 한 군집에 모인다예요."},{"b":[0.09,0.29,0.52,0.05],"c":[0.064,0.2572,0.572,0.1156],"r":8.7966,"img":"img/L4/walk/p056_20_03.jpg","say":"그래서 한 군집 안 레이블 분포가 원본 데이터와 다를 수 있다예요."},{"b":[0.09,0.355,0.26,0.05],"c":[0.077,0.325,0.286,0.11],"r":4.6222,"img":"img/L4/walk/p056_20_04.jpg","say":"이것이 편향된 SGD로 이어진다예요."},{"b":[0.38,0.49,0.25,0.37],"c":[0.3675,0.4715,0.275,0.407],"r":1.2012,"img":"img/L4/walk/p056_20_05.jpg","say":"아래 그림에서 무리마다 한 색이 압도적이에요. 색이 곧 레이블이에요."}]}},{"p":57,"title":"여러 군집을 묶으면 두 가지가 풀린다","terms":["Cluster-GCN","Induced Subgraph","Mini-batch","Community","SGD","Subgraph"],"pass1":[{"kind":"say","lines":["해법은 아주 간단해요. 한 개 대신 여러 개를 뽑으면 돼요.","군집 여러 개를 무작위로 골라 한 **미니 배치(Mini-batch)**로 묶어요.","그러면 배치 안 레이블 분포가 고르게 되고,","골라진 군집들 사이의 엣지도 되살아나요."]},{"kind":"analogy","head":"도시락에 반찬 두 칸을 담기","scene":"도시락 한 칸에 한 가지 반찬만 담으면 오늘은 계란만, 내일은 김치만 먹게 돼요. 두 칸에 나눠 담으면 하루에 두 가지를 먹게 되어 훨씬 고르죠. 게다가 두 반찬이 붙어 있어서 같이 먹는 맛도 생겨요.","map":[["도시락 한 칸","군집 하나짜리 배치"],["두 칸에 나눠 담기","군집 $q$ 개를 묶은 배치"],["같이 먹는 맛","되살아나는 군집 사이 엣지"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"왜 두 가지가 한꺼번에 풀리나요","items":["첫째, 서로 다른 성향의 군집이 섞이면서 레이블 비율이 평균으로 돌아가요.","둘째, 배치 노드를 다 합친 뒤에 **유도 부분 그래프(Induced Subgraph)**를 만들기 때문이에요.","유도 부분 그래프는 고른 노드끼리의 엣지를 전부 가져온다고 했죠.","그래서 두 군집의 노드가 다 배치에 있으면 그 사이 엣지가 자동으로 따라와요."]},{"kind":"points","head":"예쁜 지점이 하나 있어요","items":["엣지를 되살리려고 따로 한 일이 아무것도 없어요.","노드를 더 넣었을 뿐인데 엣지가 공짜로 따라왔어요.","고를 여지가 없다는 유도 부분 그래프의 성질이 여기서는 도움이 됐어요.","같은 성질이 한 번은 단점, 한 번은 장점으로 작동해요."]},{"kind":"steps","head":"$q$ 를 키우면 얼마나 되살아나나요","steps":["군집이 4개면 군집 쌍은 모두 $\\binom{4}{2} = 6$ 쌍이에요.","$q$ 개를 뽑으면 그중 $\\binom{q}{2}$ 쌍이 배치 안에 함께 들어와요.","$q = 1$ 이면 0 쌍이라 $0/6 = 0\\%$ 예요. 기본 **Cluster-GCN**이에요.","$q = 2$ 면 1 쌍이라 $1/6$ 으로 약 17%, $q = 3$ 이면 3 쌍이라 50% 예요.","$q = 4$ 면 6 쌍이라 100% 인데 그건 그냥 풀배치라 메모리가 터져요."],"answer":"$q$ 는 메모리와 정보량 사이의 조절 손잡이예요. 두 배 키우면 메모리도 두 배지만 되살아나는 쌍은 더 빨리 늘어요.","given":"군집 4개 중 매 배치마다 $q$ 개를 뽑아요."},{"kind":"figure","head":"군집 두 개를 합치면 레이블도 엣지도 돌아온다","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"118\" y=\"24\" font-size=\"16\" text-anchor=\"middle\">군집 하나만 배치로<\/text>\n<line class=\"e\" x1=\"70\" y1=\"70\" x2=\"110\" y2=\"70\"/>\n<line class=\"e\" x1=\"70\" y1=\"70\" x2=\"90\" y2=\"106\"/>\n<line class=\"e\" x1=\"110\" y1=\"70\" x2=\"90\" y2=\"106\"/>\n<circle class=\"n2\" cx=\"70\" cy=\"70\" r=\"13\"/>\n<circle class=\"n2\" cx=\"110\" cy=\"70\" r=\"13\"/>\n<circle class=\"n2\" cx=\"90\" cy=\"106\" r=\"13\"/>\n<text class=\"tm\" x=\"90\" y=\"142\" font-size=\"14\" text-anchor=\"middle\">G1 은 빨강만 가득<\/text>\n<circle class=\"n3\" cx=\"170\" cy=\"70\" r=\"13\"/>\n<circle class=\"n3\" cx=\"205\" cy=\"106\" r=\"13\"/>\n<text class=\"tm\" x=\"190\" y=\"142\" font-size=\"14\" text-anchor=\"middle\">G2 는 안 씀<\/text>\n<text class=\"tb b1\" x=\"118\" y=\"176\" font-size=\"16\" text-anchor=\"middle\">레이블이 한쪽으로 쏠려요<\/text>\n<line class=\"e\" x1=\"240\" y1=\"36\" x2=\"240\" y2=\"200\"/>\n<text class=\"tb\" x=\"362\" y=\"24\" font-size=\"16\" text-anchor=\"middle\">군집 두 개를 합쳐 배치로<\/text>\n<line class=\"e\" x1=\"300\" y1=\"70\" x2=\"340\" y2=\"70\"/>\n<line class=\"e\" x1=\"300\" y1=\"70\" x2=\"320\" y2=\"106\"/>\n<line class=\"e\" x1=\"340\" y1=\"70\" x2=\"320\" y2=\"106\"/>\n<line class=\"e\" x1=\"400\" y1=\"70\" x2=\"435\" y2=\"106\"/>\n<line class=\"e2 b2\" x1=\"340\" y1=\"70\" x2=\"400\" y2=\"70\"/>\n<circle class=\"n2\" cx=\"300\" cy=\"70\" r=\"13\"/>\n<circle class=\"n2\" cx=\"340\" cy=\"70\" r=\"13\"/>\n<circle class=\"n2\" cx=\"320\" cy=\"106\" r=\"13\"/>\n<circle class=\"n3 b2\" cx=\"400\" cy=\"70\" r=\"13\"/>\n<circle class=\"n3 b2\" cx=\"435\" cy=\"106\" r=\"13\"/>\n<text class=\"tb b2\" x=\"370\" y=\"52\" font-size=\"16\" text-anchor=\"middle\">되살아난 엣지<\/text>\n<text class=\"tm b2\" x=\"362\" y=\"142\" font-size=\"14\" text-anchor=\"middle\">빨강과 초록이 섞여요<\/text>\n<text class=\"tb b2\" x=\"362\" y=\"176\" font-size=\"16\" text-anchor=\"middle\">레이블도 고르고 엣지도 돌아와요<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"232\" font-size=\"16\" text-anchor=\"middle\">노드를 더 넣었을 뿐인데 엣지가 따라왔어요<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"256\" font-size=\"14\" text-anchor=\"middle\">유도 부분 그래프의 성질 덕분이에요<\/text>\n<\/svg>","caption":"노드 집합을 합친 뒤 유도 부분 그래프를 만들기 때문에 그 사이 엣지가 따라와요.","builds":3}],"pass3":[{"kind":"english","head":"해법을 쓰는 문장","en":"Cluster-GCN randomly selects q clusters and merges them into one batch, which balances the label distribution and recovers the between-cluster edges.","ko":"Cluster-GCN은 군집 $q$ 개를 무작위로 골라 한 배치로 합치는데, 그러면 레이블 분포가 고르게 되고 군집 사이 엣지도 되살아난다.","tip":"How does Cluster-GCN mitigate the imbalanced label problem 이라는 문제의 답이에요."},{"kind":"warn","head":"되살아나는 범위를 정확히","items":["되살아나는 것은 뽑힌 군집들 사이 엣지뿐이에요. 뽑히지 않은 군집으로 가는 엣지는 여전히 끊겨요.","무작위로 고른다가 중요해요. 매번 같은 조합이면 레이블 균형 효과가 없어요.","에폭마다 다시 섞어요. 격자 그림의 Epoch 1 과 Epoch T 색 배치가 다른 이유예요."]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4061,0.0757],"c":[0,0.0019,0.4467,0.1077],"r":7.3736,"img":"img/L4/walk/p057_h.jpg"},"parts":[{"b":[0.05,0.145,0.15,0.05],"c":[0.025,0.115,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p057_20_01.jpg","say":"첫 줄이 여러 군집 쓰기예요."},{"b":[0.08,0.22,0.55,0.05],"c":[0.0525,0.1839,0.605,0.1222],"r":8.8016,"img":"img/L4/walk/p057_20_02.jpg","say":"군집 여러 개를 무작위로 골라 한 묶음으로 삼는 방법이 제안됐다예요."},{"b":[0.05,0.29,0.14,0.05],"c":[0.02,0.26,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p057_20_03.jpg","say":"그 아래가 장점 두 가지예요."},{"b":[0.08,0.36,0.36,0.1],"c":[0.062,0.344,0.396,0.132],"r":5.3333,"img":"img/L4/walk/p057_20_04.jpg","say":"한 묶음 안 레이블 분포가 고르게 되고, 군집 사이에 사라진 엣지를 일부 되살려요."},{"b":[0.03,0.58,0.43,0.25],"c":[0.0085,0.564,0.473,0.282],"r":2.9819,"img":"img/L4/walk/p057_20_05.jpg","say":"왼쪽 격자에서 Epoch T 를 보세요. 같은 색 칸이 대각선 밖에도 나타나요."},{"b":[0.5,0.5,0.49,0.24],"c":[0.461,0.484,0.539,0.272],"r":3.5229,"img":"img/L4/walk/p057_20_06.jpg","say":"오른쪽에서 두 덩어리를 끌어오면 그 사이 파란 선이 그대로 살아 있어요."}]}},{"p":58,"title":"Cluster-GCN 알고리즘: 한 배치 만드는 순서","terms":["Cluster-GCN","METIS","Induced Subgraph","Mini-batch","SGD","Subgraph"],"pass1":[{"kind":"say","lines":["알고리즘을 세 덩어리로 나눠 읽어요.","하나, 노드 군집화는 학습 전에 **메티스(METIS)**로 딱 한 번이에요.","둘, 무작위로 $q$ 개 군집 뽑기와 셋, 학습하고 최적화는 반복마다예요.","배치의 엣지 집합에는 그룹 사이 엣지도 들어가요."]},{"kind":"analogy","head":"여행 준비의 한 번과 매번","scene":"여행을 가기 전에 지도를 구역별로 한 번 나눠 두었어요. 이 일은 딱 한 번만 하면 돼요. 그다음부터 하루하루는 구역 두 개를 골라 그날 돌아다니고, 돌아와서 기록을 정리해요. 이 일은 매일 반복해요.","map":[["지도를 구역별로 한 번 나누기","**메티스(METIS)** 군집화, 반복문 밖"],["구역 두 개 고르기","무작위로 $q$ 개 군집 뽑기"],["돌아다니고 기록 정리","손실과 기울기로 가중치 고치기"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"알고리즘 상자를 줄 번호로 읽어요","items":["1번, **메티스(METIS)**로 그래프 노드를 $c$ 개 군집으로 나눠요.","2번, 반복문을 시작해요. 3번, $q$ 개 군집을 비복원으로 무작위로 골라요.","4번, 뽑힌 노드와 그 사이 링크로 부분 그래프를 만들어요.","5번과 6번, 부분 그래프 위의 손실로 기울기를 구하고 Adam 으로 가중치를 고쳐요."]},{"kind":"formula","head":"배치의 엣지 집합","tex":"E_{aggr} = \\{(u, v) \\mid u, v \\in V_{aggr}\\}","parts":[{"sym":"V_{aggr}","say":"브이 애그리게이트라고 읽어요. 뽑힌 군집들의 노드를 전부 합친 집합이에요."},{"sym":"E_{aggr}","say":"이 애그리게이트라고 읽어요. 그 안의 노드끼리 이어진 엣지 전부예요."},{"sym":"\\mid","say":"세로 막대는 이러이러한 조건을 만족하는 이라는 뜻이에요."},{"sym":"\\cup","say":"합집합 기호예요. 여러 집합을 하나로 합쳐요."}],"whole":"양쪽 끝이 모두 배치 안에 있는 엣지를 전부 모은 것이에요. 조건에 같은 군집일 것이 없어서 군집 사이 엣지도 들어와요."},{"kind":"compare","head":"어디가 한 번이고 어디가 반복인가","cols":["덩어리","줄","언제","하는 일"],"rows":[["노드 군집화","1","학습 전 딱 한 번","**메티스(METIS)**로 $c$ 조각"],["무작위 $q$ 개 군집","3, 4","배치마다","뽑고 합쳐 부분 그래프"],["학습과 최적화","5, 6","배치마다","손실, 기울기, Adam"]]},{"kind":"steps","head":"반복 한 번을 따라가요","steps":["군집이 4개, 매 배치에 $q = 2$ 개를 뽑는다고 해요. 각 군집은 노드 3개예요.","$V_1$ 은 A, B, C 이고 $V_2$ 는 D, E, F 예요.","3번 줄에서 $V_1$ 과 $V_2$ 를 뽑았다고 해요.","4번 줄에서 노드를 합치면 A, B, C, D, E, F 여섯 개예요.","엣지는 군집 안 여섯 개에 더해 C-D 와 B-E 도 들어와요."],"answer":"p.53 에서 지웠던 C-D 와 B-E 가 여기서는 살아 있어요. $q = 1$ 이었다면 지워졌겠죠.","given":"노드 12개를 군집 4개로 나눈 예를 씁니다."},{"kind":"warn","head":"놓치기 쉬운 네 가지","items":["비복원으로라는 말을 놓치지 마세요. 같은 군집을 한 배치에 두 번 넣지 않아요.","1번 줄은 반복문 밖이에요. 학습 내내 딱 한 번만 돌아요.","Adam 은 **확률적 경사하강(SGD)**을 개선한 최적화 방법 이름이에요."]}],"pass3":[{"kind":"check","q":"**메티스(METIS)** 군집화는 언제 실행되나요?","choices":["배치마다","에폭마다","학습 전에 딱 한 번","학습이 끝난 뒤"],"a":2,"why":"반복문 밖에 있어요. 느린 작업이지만 한 번만 하니 전체 시간에 거의 영향이 없어요."},{"kind":"warn","head":"p.53 과 달라 보이는 점","items":["p.53 의 조건 $G_u = G_i$ 는 $q = 1$ 인 기본형을 말하는 거예요.","$q > 1$ 이면 같은 군집이 아니라 같은 배치 안으로 읽으면 돼요.","시험에서는 문제에 주어진 군집 표시를 그대로 따르면 돼요."]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.2908,0.0757],"c":[0,0.0019,0.3198,0.1077],"r":5.2789,"img":"img/L4/walk/p058_h.jpg"},"parts":[{"b":[0.02,0.21,0.14,0.05],"c":[0,0.18,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p058_20_01.jpg","say":"맨 위 굵은 제목이 미니 배치 학습이에요."},{"b":[0.04,0.275,0.42,0.13],"c":[0.019,0.259,0.462,0.162],"r":5.07,"img":"img/L4/walk/p058_20_02.jpg","say":"주황 줄이에요. 미니 배치마다 무작위로 $q$ 개 노드 그룹을 뽑아요."},{"b":[0.04,0.42,0.36,0.13],"c":[0.022,0.404,0.396,0.162],"r":4.3457,"img":"img/L4/walk/p058_20_03.jpg","say":"초록 줄이에요. 뽑힌 노드 그룹의 노드를 전부 모아 합집합을 만들어요."},{"b":[0.04,0.56,0.42,0.17],"c":[0.019,0.544,0.462,0.202],"r":4.066,"img":"img/L4/walk/p058_20_04.jpg","say":"노란 줄이에요. 그 노드 집합의 **유도 부분 그래프(Induced Subgraph)**를 뽑아요."},{"b":[0.07,0.75,0.3,0.05],"c":[0.055,0.72,0.33,0.11],"r":5.3333,"img":"img/L4/walk/p058_20_05.jpg","say":"빨간 줄이에요. 엣지 집합에 그룹 사이 엣지도 들어간다는 느낌표 문장이에요."},{"b":[0.62,0.3,0.37,0.43],"c":[0.593,0.2785,0.407,0.473],"r":1.5297,"img":"img/L4/walk/p058_20_06.jpg","say":"오른쪽이 논문의 알고리즘 상자예요. 줄마다 번호가 있어요."}]}},{"p":59,"title":"GraphSAINT가 보는 문제: 이웃 폭발","terms":["GraphSAINT","Neighborhood Explosion","Recursive Neighborhood Expansion","Degree","Receptive Field","Cluster-GCN","GCN","Hub Node"],"pass1":[{"kind":"say","lines":["여기부터 4주차의 마지막 모델 **GraphSAINT**예요.","**Cluster-GCN**이 군집으로 자르자였다면 GraphSAINT는 확률로 뽑자예요.","GraphSAINT가 지목하는 문제는 하나, **이웃 폭발(Neighborhood Explosion)**이에요.","층수가 고정돼 있어도 **차수(Degree)**가 높으면 봐야 할 이웃이 확 늘어요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 하나씩","boxes":[{"x":0.03,"y":0.145,"w":0.66,"h":0.06,"say":"이웃 폭발이라는 말이 따옴표와 기울임으로 강조돼 있어요.","c":[0,0.1017,0.726,0.1467],"r":8.798,"img":"img/L4/walk/p059_20_01.jpg"},{"x":0.03,"y":0.27,"w":0.9,"h":0.1,"say":"층이 많을수록 봐야 할 이웃이 많아진다는 건 직관적이에요. 층 수는 고정돼 있는데도요.","c":[0,0.22,0.99,0.2],"r":8.8,"img":"img/L4/walk/p059_20_02.jpg"},{"x":0.03,"y":0.4,"w":0.53,"h":0.055,"say":"평균 **차수(Degree)**가 높을수록 봐야 할 이웃이 더 많아져요.","c":[0.0035,0.3686,0.583,0.1178],"r":8.7983,"img":"img/L4/walk/p059_20_03.jpg"}]},{"kind":"points","head":"층 수는 고정돼 있는데도가 무슨 뜻인가요","items":["층 수를 2개나 3개로 고정해 두어도 계산 그래프는 얼마든지 커질 수 있다는 뜻이에요.","보통 신경망은 층수를 정하면 **수용 영역(Receptive Field)** 크기가 딱 정해져요.","GNN은 층수를 정해도 수용 영역이 그래프 모양에 따라 달라져요.","계산 그래프의 깊이는 같은데 폭이 제각각이라는 이야기예요."]},{"kind":"steps","head":"차수만 바꿔 가며 세어 봐요","steps":["층수를 3 으로 고정하고 평균 **차수(Degree)** $d$ 만 바꿔요.","계산 그래프 노드 수는 대략 $1 + d + d^2 + d^3$ 이에요.","$d = 2$ 면 1홉 2, 2홉 4, 3홉 8 로 합계 15 예요.","$d = 5$ 면 5, 25, 125 로 합계 156 이에요.","$d = 10$ 이면 10, 100, 1000 으로 합계 1111 이고 $d = 50$ 이면 12만 개가 넘어요."],"answer":"층은 3개로 똑같은데 차수 때문에 15 에서 12만으로 늘어요. 층수가 아니라 차수가 폭발을 만들어요.","given":"층수 $K = 3$ 고정, 평균 차수 $d$ 만 바꿉니다."},{"kind":"figure","head":"층은 고정인데 폭이 늘어난다","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"240\" y=\"24\" font-size=\"16\" text-anchor=\"middle\">층은 3개로 고정인데 폭이 늘어나요<\/text>\n<line class=\"e b1\" x1=\"120\" y1=\"140\" x2=\"120\" y2=\"92\"/>\n<line class=\"e b1\" x1=\"120\" y1=\"140\" x2=\"78\" y2=\"164\"/>\n<line class=\"e b1\" x1=\"120\" y1=\"140\" x2=\"162\" y2=\"164\"/>\n<line class=\"e b2\" x1=\"120\" y1=\"92\" x2=\"88\" y2=\"56\"/>\n<line class=\"e b2\" x1=\"120\" y1=\"92\" x2=\"152\" y2=\"56\"/>\n<line class=\"e b2\" x1=\"78\" y1=\"164\" x2=\"42\" y2=\"140\"/>\n<line class=\"e b2\" x1=\"78\" y1=\"164\" x2=\"52\" y2=\"200\"/>\n<line class=\"e b2\" x1=\"162\" y1=\"164\" x2=\"188\" y2=\"200\"/>\n<line class=\"e b2\" x1=\"162\" y1=\"164\" x2=\"198\" y2=\"140\"/>\n<circle class=\"n2\" cx=\"120\" cy=\"140\" r=\"14\"/>\n<circle class=\"n b1\" cx=\"120\" cy=\"92\" r=\"11\"/>\n<circle class=\"n b1\" cx=\"78\" cy=\"164\" r=\"11\"/>\n<circle class=\"n b1\" cx=\"162\" cy=\"164\" r=\"11\"/>\n<circle class=\"n3 b2\" cx=\"88\" cy=\"56\" r=\"9\"/>\n<circle class=\"n3 b2\" cx=\"152\" cy=\"56\" r=\"9\"/>\n<circle class=\"n3 b2\" cx=\"42\" cy=\"140\" r=\"9\"/>\n<circle class=\"n3 b2\" cx=\"52\" cy=\"200\" r=\"9\"/>\n<circle class=\"n3 b2\" cx=\"188\" cy=\"200\" r=\"9\"/>\n<circle class=\"n3 b2\" cx=\"198\" cy=\"140\" r=\"9\"/>\n<text class=\"tm\" x=\"120\" y=\"238\" font-size=\"14\" text-anchor=\"middle\">가운데 빨강이 대상 노드<\/text>\n<text class=\"tb\" x=\"352\" y=\"58\" font-size=\"16\" text-anchor=\"middle\">층 3개로 고정<\/text>\n<rect class=\"box b1\" x=\"262\" y=\"76\" width=\"180\" height=\"34\" rx=\"6\"/>\n<text class=\"t b1\" x=\"352\" y=\"99\" font-size=\"15\" text-anchor=\"middle\">1홉 3개<\/text>\n<rect class=\"box b2\" x=\"262\" y=\"114\" width=\"180\" height=\"34\" rx=\"6\"/>\n<text class=\"t b2\" x=\"352\" y=\"137\" font-size=\"15\" text-anchor=\"middle\">2홉 6개<\/text>\n<rect class=\"box2 b3\" x=\"262\" y=\"152\" width=\"180\" height=\"34\" rx=\"6\"/>\n<text class=\"t b3\" x=\"352\" y=\"175\" font-size=\"15\" text-anchor=\"middle\">3홉 11개<\/text>\n<text class=\"tb b3\" x=\"352\" y=\"218\" font-size=\"16\" text-anchor=\"middle\">차수가 10 이면 1000 개가 돼요<\/text>\n<text class=\"tm b3\" x=\"352\" y=\"240\" font-size=\"14\" text-anchor=\"middle\">층수가 아니라 차수가 폭발을 만들어요<\/text>\n<\/svg>","caption":"바깥으로 갈수록 노드가 3, 6, 11 로 확 늘어요. 그림의 개수는 예시 값이에요.","builds":3},{"kind":"mining","src":"마이닝 3강 Centrality","lines":["**차수(Degree)**는 노드에 붙어 있는 엣지의 개수예요.","평균 차수는 엣지가 $m$ 개, 노드가 $n$ 개인 무방향 그래프에서 $2m/n$ 이에요.","엣지 하나가 양쪽 노드의 차수를 1 씩 올리니 전체 차수 합이 $2m$ 이거든요.","이 값 하나만 알아도 계산 그래프가 얼마나 커질지 짐작할 수 있어요."]},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 확장성 문제의 원인을 한 문장으로 정리했어요.","이웃의 수가 고정돼 있지 않다는 것이라고요.","이웃이 없을 수도, 수십만 수백만일 수도 있다는 것이 문제라고 했어요.","그래서 **수용 영역(Receptive Field)**을 예상할 수 없으니 메모리도 병렬 연산도 어려워요."]}],"pass3":[{"kind":"english","head":"이웃 폭발을 쓰는 문장","en":"Neighbour explosion means that the number of nodes required to update one target node grows exponentially with the number of layers.","ko":"이웃 폭발은 대상 노드 하나를 갱신하는 데 필요한 노드 수가 층수에 따라 지수적으로 늘어난다는 뜻이다.","tip":"roughly d to the power K for average degree d 를 덧붙이면 더 좋아요."},{"kind":"warn","head":"같은 것의 다른 이름","items":["**이웃 폭발(Neighborhood Explosion)**은 GraphSAINT 논문이 쓰는 말이에요.","같은 현상을 **Cluster-GCN**은 **재귀적 이웃 확장(Recursive Neighborhood Expansion)**이라 불러요.","그림의 노드 개수 3, 6, 11 은 그림을 그리기 위한 예시 값이에요."]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.9032,0.3668],"c":[0,0,0.9935,0.4035],"r":4.3773,"img":"img/L4/walk/p059_h.jpg"},"parts":[{"b":[0.34,0.48,0.26,0.42],"c":[0.327,0.459,0.286,0.462],"r":1.1005,"img":"img/L4/walk/p059_11_01.jpg","say":"가운데 빨강이 대상 노드예요. 주황이 1홉, 노랑이 2홉, 초록이 3홉이에요."},{"b":[0.03,0.4,0.53,0.055],"c":[0.0035,0.3686,0.583,0.1178],"r":8.7983,"img":"img/L4/walk/p059_11_02.jpg","say":"평균 차수가 높을수록 봐야 할 이웃이 더 많아진다고 적혀 있어요."}]}},{"p":60,"title":"부분 그래프 샘플러 세 가지","terms":["GraphSAINT","Node Sampler","Edge Sampler","Random Walk Sampler","Random Walk","Degree","Subgraph","GraphSAGE","Node-wise Sampling"],"pass1":[{"kind":"say","lines":["**GraphSAINT**는 군집화를 하지 않아요.","**부분 그래프(Subgraph)**를 바로 뽑는 샘플러를 쓰는데 세 종류예요.","**노드 샘플러(Node Sampler)**, **엣지 샘플러(Edge Sampler)**, **랜덤워크 샘플러(Random Walk Sampler)**예요.","셋 중 하나를 고르는 것이지 같이 쓰는 게 아니에요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"슬라이드 글자 두 줄","boxes":[{"x":0.03,"y":0.155,"w":0.68,"h":0.055,"say":"부분 그래프 샘플러로 미니 배치 학습용 부분 그래프를 바로 뽑는다예요.","c":[0,0.1069,0.748,0.1511],"r":8.8006,"img":"img/L4/walk/p060_20_01.jpg"},{"x":0.03,"y":0.28,"w":0.16,"h":0.055,"say":"그 아래가 샘플러 구성이에요. 상자 세 개가 이어져요.","c":[0.01,0.2525,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p060_20_02.jpg"}]},{"kind":"formula","head":"**엣지 샘플러(Edge Sampler)**의 확률","tex":"p_{u,v} \\propto \\frac{1}{d_u} + \\frac{1}{d_v}","parts":[{"sym":"p_{u,v}","say":"피 유 브이라고 읽어요. 엣지 $(u, v)$ 가 뽑힐 확률이에요."},{"sym":"\\propto","say":"비례 기호예요. 값 자체가 아니라 비율만 정한다는 뜻이에요."},{"sym":"d_u","say":"디 유라고 읽어요. 노드 $u$ 의 **차수(Degree)**, 즉 이웃 수예요."},{"sym":"1/d_u","say":"차수의 역수예요. 차수가 크면 작아져요."}],"whole":"양쪽 노드의 차수가 작을수록 이 엣지를 더 자주 뽑는다는 뜻이에요. 약한 연결을 우선 챙겨요."},{"kind":"formula","head":"**랜덤워크 샘플러(Random Walk Sampler)**의 확률","tex":"p_{u,v} \\propto B_{u,v} + B_{v,u}","parts":[{"sym":"B_{u,v}","say":"비 유 브이라고 읽어요. $L$ 홉 **랜덤워크(Random Walk)**가 $u$ 에서 시작해 $v$ 에서 끝날 확률이에요."},{"sym":"B_{v,u}","say":"반대 방향의 같은 확률이에요. 무방향이라 양쪽을 다 더해요."},{"sym":"L","say":"엘이라고 읽어요. 랜덤워크의 걸음 수예요."}],"whole":"걸어서 이어질 수 있는 엣지일수록 자주 뽑는다는 뜻이에요."},{"kind":"steps","head":"엣지 확률을 직접 계산해요","steps":["엣지 (a, b) 는 양쪽 차수가 2, 2 라 $0.5 + 0.5 = 1.00$ 이에요.","엣지 (c, d) 는 2, 4 라 $0.5 + 0.25 = 0.75$ 예요.","엣지 (e, f) 는 5, 5 라 $0.2 + 0.2 = 0.40$ 이에요.","엣지 (g, h) 는 10, 10 이라 $0.1 + 0.1 = 0.20$ 이에요.","합이 2.35 이니 각각을 합으로 나누면 0.43, 0.32, 0.17, 0.09 예요."],"answer":"차수가 2 와 2 인 약한 엣지는 43%, 차수가 10 과 10 인 허브 사이 엣지는 9% 로 약 5배 차이예요.","given":"엣지 네 개가 있고 양쪽 노드의 차수가 주어졌어요."},{"kind":"mining","src":"마이닝 10강 Random Walk-based GRL","lines":["**랜덤워크(Random Walk)**는 이웃 하나를 무작위로 골라 이동하기를 반복한 노드 순서열이에요.","DeepWalk 가 이것으로 임베딩을 만들었죠.","10강은 랜덤워크의 장점을 표현력과 효율 두 가지로 들었어요.","GraphSAINT 에서도 걸어간 길이 곧 이어진 부분 그래프라 조각이 끊기지 않아요."]},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 세 샘플러를 이렇게 정리했어요.","노드 샘플링은 그냥 균등하게 뽑고, 엣지 샘플링은 양쪽 노드의 차수에 따라 가중치를 준다고요.","랜덤워크 샘플링은 엣지 하나를 뽑고 끝나는 게 아니라 다음 엣지로 계속 따라가는 것이라고요.","그리고 못 박았어요. 셋을 같이 쓰는 게 아니라 셋 중 하나를 고르는 것이라고요."]}],"pass3":[{"kind":"exam","src":"2025 가을 중간 6번 (a) (3점)","q":"How does GraphSAINT's sampling strategy differ from node-wise or edge-wise sampling methods like GraphSAGE?","qko":"**GraphSAINT**의 샘플링 전략이 GraphSAGE 같은 노드 단위, 엣지 단위 방법과 어떻게 다른지 서술하세요.","solve":["먼저 무엇을 뽑는지를 대비시켜요. GraphSAGE 는 개별 노드나 엣지를 뽑아요.","GraphSAINT 는 미니 배치마다 **부분 그래프(Subgraph)**를 통째로 뽑아요.","그래서 구조와 이웃 정보를 더 많이 지킬 수 있어요.","그러면서도 학습은 여전히 효율적이에요."],"answer":"GraphSAINT samples entire subgraphs for each mini-batch instead of individual nodes or edges, preserving more structural information."},{"kind":"warn","head":"이름 때문에 헷갈리는 점","items":["**노드 샘플러(Node Sampler)**와 **노드 단위 샘플링(Node-wise Sampling)**은 다른 말이에요.","노드 샘플러는 그래프 전체에서 노드를 뽑아 부분 그래프를 만드는 것이에요.","노드 단위 샘플링은 대상 노드마다 그 이웃을 뽑는 것이에요."]},{"kind":"check","q":"**엣지 샘플러(Edge Sampler)**는 어떤 엣지를 더 자주 뽑나요?","choices":["양쪽 차수가 큰 엣지","양쪽 차수가 작은 엣지","무작위로 똑같이","가장 긴 엣지"],"a":1,"why":"확률이 차수의 역수 합에 비례해요. 역수라서 차수가 작을수록 커요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.7058,0.3207],"c":[0,0.0018,0.7764,0.3528],"r":3.9123,"img":"img/L4/walk/p060_h.jpg"},"parts":[{"b":[0.045,0.37,0.295,0.54],"c":[0.0302,0.343,0.3245,0.594],"r":0.9712,"img":"img/L4/walk/p060_11_01.jpg","say":"왼쪽이 **노드 샘플러(Node Sampler)**예요. 노드를 균등하게 뽑아요."},{"b":[0.37,0.37,0.25,0.54],"c":[0.3575,0.343,0.275,0.594],"r":0.823,"img":"img/L4/walk/p060_11_02.jpg","say":"가운데가 **엣지 샘플러(Edge Sampler)**예요. 빨간 선이 뽑힌 엣지예요."},{"b":[0.655,0.37,0.295,0.54],"c":[0.6402,0.343,0.3245,0.594],"r":0.9712,"img":"img/L4/walk/p060_11_03.jpg","say":"오른쪽이 **랜덤워크 샘플러(Random Walk Sampler)**예요. 1, 2, 3 이 걸어간 순서예요."}]}},{"p":61,"title":"작은 조각 위에 온전한 GNN을 세운다","terms":["GraphSAINT","I.I.D.","Bias","Hub Node","Scale-free Graph","Normalization","Subgraph","Cluster-GCN","Random Walk Sampler"],"pass1":[{"kind":"say","lines":["뽑은 **부분 그래프(Subgraph)** 위에서는 평범한 GNN을 통째로 돌려요.","손댈 것이 없어요. 이미 작으니까요.","다만 이 샘플러는 **독립 동일 분포(I.I.D.)**가 아니라서 인기 있는 노드가 더 자주 뽑혀요.","그래서 뽑히는 빈도로 **정규화(Normalization)**를 해 줘야 해요."]},{"kind":"analogy","head":"반 대표만 자꾸 인터뷰하기","scene":"기자가 아무 교실에 들어가 이야기를 듣기로 했어요. 어느 교실에 가든 반 대표는 늘 앞에 있어 매번 인터뷰하게 돼요. 뒤에 앉은 친구는 어쩌다 한 번 걸려요. 그대로 쓰면 반 대표 이야기만 남아요.","map":[["늘 걸리는 반 대표","**허브 노드(Hub Node)**"],["어쩌다 걸리는 친구","차수가 낮은 리프 노드"],["반 대표 이야기가 된 기사","샘플링이 만든 **편향(Bias)**"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"온전한 GNN과 **독립 동일 분포(I.I.D.)**가 무슨 뜻인가요","items":["온전한 GNN은 샘플링을 신경 쓰지 않는 보통 GNN이라는 뜻이에요.","부분 그래프 안에서는 이웃을 골라내지 않고 다 봐요. 이미 작으니까요.","I.I.D. 는 표본끼리 서로 영향을 주지 않고 모두 같은 규칙으로 뽑힌다는 뜻이에요.","주사위를 100 번 굴리면 각 결과가 I.I.D. 예요."]},{"kind":"points","head":"왜 I.I.D. 가 아닌가요","items":["독립이 아니에요. **랜덤워크 샘플러(Random Walk Sampler)**가 $u$ 를 밟으면 다음은 $u$ 의 이웃이에요.","앞에 뽑힌 것이 뒤에 뽑힐 것을 정해요.","동일 분포도 아니에요. 엣지가 많은 인기 노드는 어떤 방식으로도 걸려들 확률이 높아요.","그래서 모델이 인기 노드에 대해서만 잘하는 쪽으로 기울어요. 이것이 **편향(Bias)**이에요."]},{"kind":"steps","head":"인기 노드가 얼마나 자주 뽑히는지 세어요","steps":["노드 5개짜리 그래프에서 허브 H 의 차수가 4 이고 리프 L1 부터 L4 의 차수가 1 이에요.","엣지는 H-L1, H-L2, H-L3, H-L4 네 개예요.","엣지 하나를 뽑으면 그 양 끝 노드가 부분 그래프에 들어와요.","어느 엣지를 뽑든 H 는 무조건 들어와요. 확률 $4/4 = 1.0$ 이에요.","리프는 4번 중 1번만 들어와요. 확률 $1/4 = 0.25$ 예요."],"answer":"H 는 리프보다 4배 자주 학습돼요. 다음 슬라이드에서 이 확률로 손실을 나눠 균형을 되찾아요.","given":"**엣지 샘플러(Edge Sampler)**로 허브 하나와 리프 넷을 뽑아요."},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 실세계 그래프가 **스케일 프리 그래프(Scale-free Graph)**라고 여러 번 말했어요.","차수가 낮은 노드가 대부분이고 차수가 높은 노드는 거의 없다고요.","그 소수의 **허브 노드(Hub Node)** 주위로 리프들이 붙어 커뮤니티를 이룬다고 했어요.","인플루언서가 더 자주 뽑힌다는 말은 정확히 그 허브 이야기예요."]}],"pass3":[{"kind":"exam","src":"2025 가을 중간 6번 (b) (7점)","q":"Calculate the output representations of nodes A, B, C, D and E at layer k = 1, where the MEAN is taken over neighbours u with G_u = G_i.","qko":"뽑힌 부분 그래프 $G_1$ 이 A, B, C, D, E 이고 F 는 밖이에요. 엣지는 A-B, A-C, B-D, C-D, D-E 예요. 처음 값은 차례로 0.1, 0.3, 0.3, 0.4, 0.1 이에요.","solve":["뽑힌 부분 그래프 안 이웃만 평균해요. A 의 이웃은 B, C 예요.","$h_{N(A)} = \\mathrm{MEAN}(0.3, 0.3) = 0.3$ 이에요.","B 의 이웃은 A, D 라 $\\mathrm{MEAN}(0.1, 0.4) = 0.25$, C 도 같은 이웃이라 0.25 예요.","D 의 이웃은 B, C, E 라 $\\mathrm{MEAN}(0.3, 0.3, 0.1)$ 로 소수 둘째 자리 반올림해 0.23 이에요.","E 의 이웃은 D 하나라 $\\mathrm{MEAN}(0.4) = 0.4$ 예요.","자기 값을 앞에 이어 붙이고 렐루를 씌우면 끝이에요. 전부 양수예요."],"answer":"$h_A = [0.1, 0.3]$, $h_B = [0.3, 0.25]$, $h_C = [0.3, 0.25]$, $h_D = [0.4, 0.23]$, $h_E = [0.1, 0.4]$"},{"kind":"warn","head":"계산에서 조심할 점","items":["E 처럼 이웃이 하나뿐이면 그 값 자체가 평균이에요. 나누기 1 이에요.","뽑힌 부분 그래프 밖 노드 F 는 분자에서도 분모에서도 빠져요.","**Cluster-GCN**과 식이 완전히 같아요. 군집이 부분 그래프로 바뀌었을 뿐이에요."]},{"kind":"english","head":"왜 정규화가 필요한지 쓰는 문장","en":"Subgraph sampling is not an I.I.D. sampler because high degree nodes are far more likely to be included in a sampled subgraph.","ko":"부분 그래프 샘플링은 차수가 높은 노드가 훨씬 자주 포함되므로 I.I.D. 샘플러가 아니다.","tip":"not an I.I.D. sampler 라는 표현을 그대로 쓰세요."}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4131,0.0757],"c":[0,0.0019,0.4544,0.1077],"r":7.5007,"img":"img/L4/walk/p061_h.jpg"},"parts":[{"b":[0.03,0.145,0.48,0.05],"c":[0.006,0.115,0.528,0.11],"r":8.5333,"img":"img/L4/walk/p061_20_01.jpg","say":"작은 부분 그래프를 뽑고 그 위에 온전한 GNN을 세운다예요."},{"b":[0.03,0.215,0.22,0.05],"c":[0.018,0.185,0.244,0.11],"r":3.9434,"img":"img/L4/walk/p061_20_02.jpg","say":"이웃 크기가 일정하다예요."},{"b":[0.03,0.28,0.28,0.05],"c":[0.016,0.25,0.308,0.11],"r":4.9778,"img":"img/L4/walk/p061_20_03.jpg","say":"**독립 동일 분포(I.I.D.)** 데이터 샘플러가 아니다예요."},{"b":[0.03,0.345,0.58,0.11],"c":[0.001,0.329,0.638,0.142],"r":7.9875,"img":"img/L4/walk/p061_20_04.jpg","say":"왜냐는 물음의 답이에요. 인기 있는 사용자, 즉 인플루언서 같은 노드가 더 자주 뽑혀요."},{"b":[0.03,0.475,0.58,0.11],"c":[0.001,0.459,0.638,0.142],"r":7.9875,"img":"img/L4/walk/p061_20_05.jpg","say":"어떻게라는 물음의 답이에요. 엣지와 노드가 뽑히는 빈도로 집계와 손실을 정규화해요."},{"b":[0.21,0.6,0.59,0.28],"c":[0.1805,0.584,0.649,0.312],"r":3.698,"img":"img/L4/walk/p061_20_06.jpg","say":"그림 왼쪽이 뽑힌 부분 그래프, 오른쪽이 그 위에 세 층을 쌓은 보통 GCN이에요."}]}},{"p":62,"title":"편향 없애기: 뽑히는 빈도로 나눈다","terms":["GraphSAINT","Normalization","Bias","Mini-batch","Hub Node","Cluster-GCN","Variance"],"pass1":[{"kind":"say","lines":["**정규화(Normalization)**는 두 곳에 들어가요.","**미니 배치(Mini-batch)** 손실은 노드가 뽑힐 확률로 나눠요.","이웃 집계는 엣지가 뽑힐 확률로 만든 계수로 나눠요.","자주 뽑히는 것은 작게, 드물게 뽑히는 것은 크게 쳐 주는 거예요."]},{"kind":"analogy","head":"자주 오는 손님과 드문 손님","scene":"가게 주인이 손님 의견을 모아요. 매일 오는 단골은 한 달에 서른 번 말하고, 일 년에 한 번 오는 손님은 한 번 말해요. 들은 횟수 그대로 반영하면 가게는 단골 취향으로만 바뀌어요. 그래서 주인은 드문 손님의 한마디를 크게 새겨듣기로 했어요.","map":[["매일 오는 단골","자주 뽑히는 **허브 노드(Hub Node)**"],["일 년에 한 번 오는 손님","드물게 뽑히는 리프 노드"],["크게 새겨듣기","확률로 나누는 **정규화(Normalization)**"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"formula","head":"손실 정규화","tex":"\\mathcal{L}_{\\text{batch}} = \\sum_{v \\in G_s} L_v / \\lambda_v, \\qquad \\lambda_v = |V| \\, p_v","parts":[{"sym":"\\mathcal{L}_{\\text{batch}}","say":"엘 배치라고 읽어요. 이번 미니 배치의 손실이에요."},{"sym":"\\sum_{v \\in G_s}","say":"뽑힌 부분 그래프 안의 모든 노드에 대해 더하라는 뜻이에요."},{"sym":"L_v","say":"엘 브이라고 읽어요. 노드 $v$ 하나의 손실이에요."},{"sym":"p_v","say":"피 브이라고 읽어요. 노드 $v$ 가 뽑힐 확률이에요."},{"sym":"\\lambda_v","say":"람다 브이라고 읽어요. 정규화 계수 $|V| p_v$ 예요."},{"sym":"|V|","say":"브이의 크기, 즉 전체 노드 개수예요."}],"whole":"배치 안 각 노드의 손실을 그 노드가 뽑힐 빈도로 나눈 것의 합이에요."},{"kind":"points","head":"$\\lambda_v$ 가 왜 이런 모양인가요","items":["모든 노드가 공평하게 뽑히면 $p_v = 1/|V|$ 이고 그러면 $\\lambda_v = 1$ 이에요.","공평할 때는 아무것도 하지 않는다는 뜻이에요.","자주 뽑히는 노드는 $p_v$ 가 커서 $\\lambda_v$ 가 1 보다 크고 손실이 작아져요.","드문 노드는 $\\lambda_v$ 가 1 보다 작아서 손실이 커져요."]},{"kind":"formula","head":"집계 정규화","tex":"a(u, v) = p_{u,v} / p_v","parts":[{"sym":"a(u, v)","say":"에이 오브 유 브이라고 읽어요. 엣지 $(u, v)$ 의 정규화 계수예요."},{"sym":"p_{u,v}","say":"엣지 $(u, v)$ 가 뽑힐 확률이에요."},{"sym":"p_v","say":"도착 노드 $v$ 가 뽑힐 확률이에요."}],"whole":"엣지 확률을 도착 노드 확률로 나눈 값이에요. 이 계수로 메시지를 나눠서 더해요."},{"kind":"steps","head":"허브 그래프로 실제로 보정해요","steps":["노드는 H, L1, L2, L3, L4 로 전체 노드 수가 5 예요.","H 는 $p_v = 1.00$ 이라 $\\lambda_v = 5 \\times 1.00 = 5.00$ 이에요.","리프는 $p_v = 0.25$ 라 $\\lambda_v = 5 \\times 0.25 = 1.25$ 예요.","원래 손실이 둘 다 2.0 이라면 H 는 $2.0 / 5.00 = 0.40$ 이 돼요.","리프는 $2.0 / 1.25 = 1.60$ 이 돼요."],"answer":"정확히 4배 뒤집혔어요. H 는 4배 자주 뽑히니 한 번의 무게를 4분의 1 로 줄인 거예요.","given":"p.61 에서 구한 확률을 그대로 씁니다."},{"kind":"figure","head":"빈도로 나누면 무게가 뒤집힌다","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"240\" y=\"24\" font-size=\"16\" text-anchor=\"middle\">뽑히는 빈도로 손실을 나눠요<\/text>\n<text class=\"tm\" x=\"88\" y=\"56\" font-size=\"14\" text-anchor=\"middle\">노드<\/text>\n<text class=\"tm\" x=\"196\" y=\"56\" font-size=\"14\" text-anchor=\"middle\">뽑힐 확률<\/text>\n<text class=\"tm\" x=\"306\" y=\"56\" font-size=\"14\" text-anchor=\"middle\">원래 손실<\/text>\n<text class=\"tm\" x=\"414\" y=\"56\" font-size=\"14\" text-anchor=\"middle\">보정 후<\/text>\n<rect class=\"box2 b1\" x=\"30\" y=\"66\" width=\"420\" height=\"44\" rx=\"6\"/>\n<text class=\"tb b1\" x=\"88\" y=\"94\" font-size=\"16\" text-anchor=\"middle\">허브 H<\/text>\n<text class=\"t b1\" x=\"196\" y=\"94\" font-size=\"15\" text-anchor=\"middle\">1.00<\/text>\n<text class=\"t b1\" x=\"306\" y=\"94\" font-size=\"15\" text-anchor=\"middle\">2.0<\/text>\n<text class=\"tb b1\" x=\"414\" y=\"94\" font-size=\"16\" text-anchor=\"middle\">0.40<\/text>\n<rect class=\"box b2\" x=\"30\" y=\"118\" width=\"420\" height=\"44\" rx=\"6\"/>\n<text class=\"tb b2\" x=\"88\" y=\"146\" font-size=\"16\" text-anchor=\"middle\">리프 L1<\/text>\n<text class=\"t b2\" x=\"196\" y=\"146\" font-size=\"15\" text-anchor=\"middle\">0.25<\/text>\n<text class=\"t b2\" x=\"306\" y=\"146\" font-size=\"15\" text-anchor=\"middle\">2.0<\/text>\n<text class=\"tb b2\" x=\"414\" y=\"146\" font-size=\"16\" text-anchor=\"middle\">1.60<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"196\" font-size=\"14\" text-anchor=\"middle\">자주 뽑히는 허브는 한 번의 무게를 4분의 1 로<\/text>\n<text class=\"tm b3\" x=\"240\" y=\"220\" font-size=\"14\" text-anchor=\"middle\">드물게 뽑히는 리프는 4배로 크게<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"250\" font-size=\"16\" text-anchor=\"middle\">길게 보면 모두 같은 무게로 배워요<\/text>\n<\/svg>","caption":"자주 뽑히는 허브의 한 번은 가볍게, 드문 리프의 한 번은 무겁게 쳐요.","builds":3},{"kind":"points","head":"왜 편향이 없어진다고 말할 수 있나요","items":["확률 $p$ 로 뽑히는 것을 $1/p$ 배 해 주면 반복했을 때의 평균이 원래 값과 같아져요.","손실 2.0 인 노드가 확률 0.25 로 뽑히면 100번 중 25번쯤 나타나 기여가 50 이에요.","확률 1.0 인 노드는 100번 나타나 기여가 200 이에요. 4배 차이죠.","보정 후에는 $25 \\times 1.6 = 40$ 과 $100 \\times 0.4 = 40$ 으로 똑같아져요."]}],"pass3":[{"kind":"english","head":"두 정규화를 쓰는 문장","en":"GraphSAINT removes the sampling bias with two normalizers: the mini batch loss is divided by a node normalizer, and the message on each edge is divided by an edge normalizer.","ko":"GraphSAINT는 두 개의 정규화로 샘플링 편향을 없앤다. 미니 배치 손실은 노드 계수로 나누고, 엣지 위의 메시지는 엣지 계수로 나눈다.","tip":"두 식의 대상이 손실과 집계로 다르다는 점을 꼭 밝히세요."},{"kind":"check","q":"자주 뽑히는 노드의 손실은 어떻게 되나요?","choices":["더 크게 친다","더 작게 친다","그대로 둔다","0으로 만든다"],"a":1,"why":"큰 $\\lambda_v$ 로 나누니 작아져요. 드문 노드는 반대로 커져요."},{"kind":"warn","head":"여기서 실수하기 쉬워요","items":["나누는 것이지 곱하는 것이 아니에요. 자주 뽑히는 쪽을 줄여야 하니까요.","두 정규화의 대상이 달라요. 하나는 손실에, 하나는 집계에 써요. 섞이면 안 돼요.","확률은 정확히 구하기 어려워서 실제로는 샘플링을 여러 번 돌려 세어서 추정해요."]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4131,0.0757],"c":[0,0.0019,0.4544,0.1077],"r":7.5007,"img":"img/L4/walk/p062_h.jpg"},"parts":[{"b":[0.05,0.13,0.35,0.05],"c":[0.0325,0.1,0.385,0.11],"r":6.2222,"img":"img/L4/walk/p062_20_01.jpg","say":"맨 위가 샘플러가 만든 **편향(Bias)**을 어떻게 없앨까예요."},{"b":[0.08,0.195,0.45,0.05],"c":[0.0575,0.165,0.495,0.11],"r":8.0,"img":"img/L4/walk/p062_20_02.jpg","say":"노드마다 뽑힐 확률로 미니 배치 손실을 정규화한다예요."},{"b":[0.32,0.28,0.3,0.1],"c":[0.305,0.264,0.33,0.132],"r":4.4444,"img":"img/L4/walk/p062_20_03.jpg","say":"가운데 식이 그 손실 정규화예요."},{"b":[0.65,0.25,0.29,0.18],"c":[0.6355,0.234,0.319,0.212],"r":2.6751,"img":"img/L4/walk/p062_20_04.jpg","say":"오른쪽 둥근 상자에 기호 설명이 있어요. 노드 확률과 엣지 확률이에요."},{"b":[0.08,0.445,0.44,0.05],"c":[0.058,0.415,0.484,0.11],"r":7.8222,"img":"img/L4/walk/p062_20_05.jpg","say":"엣지마다 뽑힐 확률로 이웃 집계를 정규화한다예요."},{"b":[0.44,0.51,0.16,0.05],"c":[0.42,0.48,0.2,0.11],"r":3.2323,"img":"img/L4/walk/p062_20_06.jpg","say":"그 아래 식이 집계 정규화 계수예요."}]}},{"p":63,"title":"연결성 지키기와 분산 감소","terms":["GraphSAINT","Variance","Bias","Degree","Edge Sampler","Random Walk Sampler","Random Walk","Normalization"],"pass1":[{"kind":"say","lines":["또 다른 문제는 연결성을 지키는 것이에요.","부분 그래프가 조각조각 끊기면 학습이 흔들려요. 이것을 **분산(Variance)**이 크다고 해요.","해법은 중요한 이웃, 즉 약한 연결을 더 자주 뽑는 것이에요.","그것을 여러 층으로 확장한 것이 **랜덤워크 샘플러(Random Walk Sampler)**예요."]},{"kind":"analogy","head":"외줄 다리와 여러 갈래 길","scene":"섬으로 가는 길이 하나뿐인 마을이 있어요. 그 다리가 끊기면 마을은 완전히 고립돼요. 반대로 길이 백 개나 있는 큰 도시는 길 하나가 막혀도 아무 문제가 없어요. 그래서 다리를 점검할 때는 외줄 다리부터 챙겨야 해요.","map":[["외줄 다리","**차수(Degree)**가 낮은 노드에 붙은 엣지"],["백 개의 길","허브에 붙은 수많은 엣지"],["외줄 다리부터 챙기기","차수의 역수에 비례해 엣지를 뽑기"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"formula","head":"분산을 최소로 하는 엣지 확률","tex":"p_{u,v} \\propto \\frac{1}{d_u} + \\frac{1}{d_v}","parts":[{"sym":"d_u","say":"노드 $u$ 의 **차수(Degree)**예요. 그 노드가 가진 엣지 개수예요."},{"sym":"1/d_u","say":"차수의 역수예요. 차수가 작으면 큰 값, 크면 작은 값이에요."},{"sym":"+","say":"양쪽 사정을 모두 본다는 뜻이에요. 한쪽이라도 외로우면 챙겨요."},{"sym":"\\propto","say":"비례 기호예요. 전부 더해 1 이 되게 나눠야 진짜 확률이에요."}],"whole":"양쪽 끝이 외로울수록 이 엣지를 자주 뽑는다는 뜻이에요. p.60 의 **엣지 샘플러(Edge Sampler)** 공식이 여기서 나왔어요."},{"kind":"points","head":"**분산(Variance)** 감소가 무슨 뜻인가요","items":["분산은 뽑을 때마다 결과가 얼마나 들쭉날쭉한가예요.","운이 나빠 리프 노드가 고립된 채 뽑히면 그 배치의 학습 결과가 엉뚱해져요.","약한 엣지를 우선 챙기면 부분 그래프가 매번 비슷하게 잘 연결된 모양이 돼요.","그래서 결과가 덜 흔들려요."]},{"kind":"steps","head":"엣지 하나의 소중함을 비율로 재요","steps":["차수 1 인 리프에게 엣지 하나는 $1/1 = 1.00$, 즉 정보의 전부예요.","차수 4 인 보통 노드에게는 $1/4 = 0.25$ 예요.","차수 100 인 허브에게는 $1/100 = 0.01$ 이에요.","엣지 (리프, 보통) 은 $1.00 + 0.25 = 1.25$, (보통, 인기) 는 $0.25 + 0.05 = 0.30$ 이에요.","(허브, 허브) 는 $0.01 + 0.01 = 0.02$ 예요. 합이 1.57 이에요."],"answer":"확률로 바꾸면 각각 약 0.80, 0.19, 0.01 이에요. 리프가 고립되는 일을 막는 설계예요.","given":"차수가 1, 4, 20, 100 인 노드들이 있어요."},{"kind":"points","head":"랜덤워크 샘플러가 왜 다층 판인가요","items":["**엣지 샘플러(Edge Sampler)**는 엣지 하나씩 따로 뽑아서 조각이 끊길 수 있어요.","끊기면 1홉 이웃은 있는데 2홉 이웃이 없어서 층을 2개 이상 쌓을 수가 없어요.","**랜덤워크(Random Walk)**는 $u$ 에서 $v$ 로, 다시 $w$ 로 이어서 걸어요.","$L$ 걸음이면 $L$ 홉짜리 길이 통째로 뽑혀서 $L$ 층 GNN에 딱 맞아요."]},{"kind":"figure","head":"따로 뽑으면 끊기고 걸어서 뽑으면 이어진다","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\">\n<text class=\"tb\" x=\"118\" y=\"24\" font-size=\"16\" text-anchor=\"middle\">엣지를 따로따로 뽑으면<\/text>\n<line class=\"e2\" x1=\"50\" y1=\"80\" x2=\"96\" y2=\"80\"/>\n<line class=\"e2\" x1=\"150\" y1=\"140\" x2=\"196\" y2=\"140\"/>\n<circle class=\"n\" cx=\"50\" cy=\"80\" r=\"12\"/>\n<circle class=\"n\" cx=\"96\" cy=\"80\" r=\"12\"/>\n<circle class=\"n\" cx=\"150\" cy=\"140\" r=\"12\"/>\n<circle class=\"n\" cx=\"196\" cy=\"140\" r=\"12\"/>\n<text class=\"tm b1\" x=\"118\" y=\"182\" font-size=\"14\" text-anchor=\"middle\">조각이 서로 떨어져 있어요<\/text>\n<text class=\"tb b1\" x=\"118\" y=\"210\" font-size=\"16\" text-anchor=\"middle\">2층을 쌓을 수 없어요<\/text>\n<line class=\"e\" x1=\"240\" y1=\"36\" x2=\"240\" y2=\"228\"/>\n<text class=\"tb\" x=\"362\" y=\"24\" font-size=\"16\" text-anchor=\"middle\">걸어 다니며 뽑으면<\/text>\n<line class=\"e2 b2\" x1=\"292\" y1=\"80\" x2=\"340\" y2=\"110\"/>\n<line class=\"e2 b2\" x1=\"340\" y1=\"110\" x2=\"392\" y2=\"92\"/>\n<line class=\"e2 b2\" x1=\"392\" y1=\"92\" x2=\"434\" y2=\"140\"/>\n<circle class=\"n2 b2\" cx=\"292\" cy=\"80\" r=\"12\"/>\n<circle class=\"n2 b2\" cx=\"340\" cy=\"110\" r=\"12\"/>\n<circle class=\"n2 b2\" cx=\"392\" cy=\"92\" r=\"12\"/>\n<circle class=\"n2 b2\" cx=\"434\" cy=\"140\" r=\"12\"/>\n<text class=\"tl b2\" x=\"292\" y=\"85\" font-size=\"14\" text-anchor=\"middle\">1<\/text>\n<text class=\"tl b2\" x=\"340\" y=\"115\" font-size=\"14\" text-anchor=\"middle\">2<\/text>\n<text class=\"tl b2\" x=\"392\" y=\"97\" font-size=\"14\" text-anchor=\"middle\">3<\/text>\n<text class=\"tl b2\" x=\"434\" y=\"145\" font-size=\"14\" text-anchor=\"middle\">4<\/text>\n<text class=\"tm b2\" x=\"362\" y=\"182\" font-size=\"14\" text-anchor=\"middle\">걸어간 길이 곧 이어진 조각이에요<\/text>\n<text class=\"tb b2\" x=\"362\" y=\"210\" font-size=\"16\" text-anchor=\"middle\">L 걸음이면 L 층에 딱 맞아요<\/text>\n<text class=\"tb b3\" x=\"240\" y=\"254\" font-size=\"16\" text-anchor=\"middle\">랜덤워크 샘플러는 엣지 샘플링의 다층 판이에요<\/text>\n<\/svg>","caption":"걸어간 길이 곧 이어진 부분 그래프예요. 그래서 층을 쌓을 수 있어요.","builds":3},{"kind":"mining","src":"마이닝 10강 Random Walk-based GRL","lines":["10강 뒷부분에서 div2vec 이라는 모델을 배웠어요.","DeepWalk 와 node2vec 이 차수 높은 노드를 과도하게 밟는 문제를 지적했죠.","그리고 차수에 반비례하게 뽑자고 제안했어요.","GraphSAINT 의 차수 역수 공식과 정확히 같은 발상이에요."]}],"pass3":[{"kind":"english","head":"분산 감소를 쓰는 문장","en":"To reduce variance, GraphSAINT samples an edge with probability proportional to the sum of the inverse degrees of its two endpoints.","ko":"분산을 줄이기 위해 GraphSAINT는 차수의 역수 합에 비례하는 확률로 엣지를 뽑는데, 그래야 끊기기 쉬운 저차수 노드에 붙은 엣지가 더 자주 뽑힌다.","tip":"which are more likely to be disconnected 를 덧붙이면 이유까지 담겨요."},{"kind":"english","head":"랜덤워크 샘플러를 쓰는 문장","en":"The random walk sampler is the multi-layer extension of edge sampling, since a walk of length L gives a connected subgraph for an L layer GNN.","ko":"랜덤워크 샘플러는 엣지 샘플링의 다층 확장인데, 길이 $L$ 의 워크가 $L$ 층 GNN에 알맞은 연결된 부분 그래프를 만들어 주기 때문이다.","tip":"multi-layer extension 이라는 표현이 핵심이에요."},{"kind":"warn","head":"두 단어를 섞지 마세요","items":["p.62 는 **편향(Bias)**, p.63 은 **분산(Variance)** 이에요.","편향은 평균적으로 틀린 쪽으로 기운다, 분산은 뽑을 때마다 결과가 들쭉날쭉하다예요.","차수의 역수를 거꾸로 외우는 실수가 많아요. 차수가 작을수록 확률이 커요."]}],"pass4":[],"walk":{"head":{"b":[0.0131,0.0179,0.4131,0.0757],"c":[0,0.0019,0.4544,0.1077],"r":7.5007,"img":"img/L4/walk/p063_h.jpg"},"parts":[{"b":[0.04,0.135,0.46,0.055],"c":[0.017,0.1075,0.506,0.11],"r":8.1778,"img":"img/L4/walk/p063_20_01.jpg","say":"또 다른 문제, 연결성을 지켜야 한다에서 **분산(Variance)** 감소로 이어져요."},{"b":[0.04,0.205,0.52,0.18],"c":[0.014,0.189,0.572,0.212],"r":4.7966,"img":"img/L4/walk/p063_20_02.jpg","say":"어떻게라는 물음에 두 가지 답이 있어요. 중요한 이웃을 더 자주, 그리고 독립 엣지 샘플링이에요."},{"b":[0.41,0.4,0.15,0.09],"c":[0.385,0.384,0.2,0.122],"r":2.9144,"img":"img/L4/walk/p063_20_03.jpg","say":"가운데 식이 분산 최소화를 위한 최적 엣지 확률이에요."},{"b":[0.18,0.52,0.38,0.16],"c":[0.161,0.504,0.418,0.192],"r":3.8704,"img":"img/L4/walk/p063_20_04.jpg","say":"왼쪽 그림은 이웃이 많은 $u$ 와 $v$, 오른쪽은 이웃이 거의 없는 $u$ 와 $v$ 예요."},{"b":[0.57,0.55,0.18,0.11],"c":[0.558,0.534,0.204,0.142],"r":2.554,"img":"img/L4/walk/p063_20_05.jpg","say":"굵은 선은 더 자주 뽑고 가는 선은 덜 뽑는다고 적혀 있어요."},{"b":[0.04,0.69,0.52,0.19],"c":[0.014,0.674,0.572,0.222],"r":4.5806,"img":"img/L4/walk/p063_20_06.jpg","say":"확장 항목이에요. 무작위 엣지 샘플링의 다층 판이 랜덤워크 샘플러예요."}]}},{"p":64,"title":"예제 코드: GraphSAINTRandomWalkSampler","terms":["GraphSAINT","Random Walk Sampler","Random Walk","Normalization","Subgraph","Mini-batch","Degree","Cluster-GCN"],"pass1":[{"kind":"say","lines":["PyTorch Geometric 에는 **GraphSAINT**의 랜덤워크 샘플러가 이미 들어 있어요.","도구 하나를 만들면 부분 그래프를 뽑아 미니 배치로 내주는 일까지 알아서 해 줘요.","슬라이드 아래 파란 띠에 하는 일이 적혀 있어요.","**랜덤워크(Random Walk)**로 노드를 뽑아 부분 그래프를 만들고 미니 배치로 학습한다예요."]},{"kind":"look","walked":1}],"pass2":[{"kind":"look","head":"코드 상자를 두 덩어리로","boxes":[{"x":0.05,"y":0.235,"w":0.57,"h":0.15,"say":"위 다섯 줄은 필요한 도구를 불러오는 줄이에요.","c":[0.0215,0.219,0.627,0.182],"r":6.1245,"img":"img/L4/walk/p064_20_01.jpg"},{"x":0.05,"y":0.475,"w":0.57,"h":0.16,"say":"아래는 샘플러 도구를 하나 만드는 줄이에요. 괄호 안이 설정값이에요.","c":[0.0215,0.459,0.627,0.192],"r":5.8056,"img":"img/L4/walk/p064_20_02.jpg"}]},{"kind":"compare","head":"샘플러에 준 설정값","cols":["인자","값","뜻"],"rows":[["data","그래프 객체","샘플링할 원래 그래프"],["batch_size","6000","한 배치에서 랜덤워크를 몇 개 출발시킬지"],["walk_length","2","워크 한 번에 몇 걸음 걸을지"],["num_steps","5","한 에폭에 배치를 몇 번 내줄지"],["sample_coverage","100","정규화 계수를 추정하려고 미리 몇 번 샘플링할지"],["num_workers","4","샘플링을 몇 개의 프로세스로 동시에 할지"]]},{"kind":"steps","head":"한 에폭에 몇 개 노드를 볼까요","steps":["워크 한 번이 밟는 노드는 출발 1 더하기 2걸음이라 최대 3개예요.","배치 하나의 워크 수는 6000개예요.","그래서 배치 하나의 노드 수는 $6000 \\times 3$ 으로 최대 18000개예요.","한 에폭의 배치 수는 5개예요.","한 에폭에 처리하는 노드는 $5 \\times 18000$ 으로 최대 90000개예요."],"answer":"Flickr 의 노드가 약 9만 개이니 한 에폭에 그래프를 대략 한 바퀴 도는 셈이에요.","given":"슬라이드에 적힌 설정값을 그대로 씁니다."},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 이 코드를 직접 돌려 보라고 했어요.","**GraphSAINT**는 세 가지 방법으로 샘플링을 하는데 셋 중 하나를 고르는 것이고요.","이 도구는 그중 **랜덤워크 샘플러(Random Walk Sampler)**가 구현된 것이라고 설명했어요.","그리고 PyG 의 NeighborSampler 에도 홉 개수 옵션이 있다고 덧붙였어요."]}],"pass3":[{"kind":"check","q":"`walk_length=2` 는 슬라이드의 무엇에 해당하나요?","choices":["배치 크기","걸음 수 $L$","군집 개수","층의 폭"],"a":1,"why":"2걸음이면 2홉까지 이어진 부분 그래프가 나와서 2층 GNN에 딱 맞아요."}],"pass4":[{"kind":"code","head":"슬라이드에 적힌 코드 그대로","file":"L4 슬라이드 p.64","code":"from torch_geometric.datasets import Flickr\nfrom torch_geometric.loader import GraphSAINTRandomWalkSampler\nfrom torch_geometric.nn import GraphConv\nfrom torch_geometric.typing import WITH_TORCH_SPARSE\nfrom torch_geometric.utils import degree\n\nloader = GraphSAINTRandomWalkSampler(data, batch_size=6000, walk_length=2,\n                                     num_steps=5, sample_coverage=100,\n                                     save_dir=dataset.processed_dir,\n                                     num_workers=4)","lines":[{"from":1,"to":1,"say":"Flickr 데이터셋을 가져와요. 노드가 사진이고 노드가 약 9만 개인 큰 그래프예요."},{"from":2,"to":2,"say":"오늘의 주인공이에요. loader 라는 폴더 이름처럼 데이터를 배치로 잘라 내주는 도구예요."},{"from":3,"to":3,"say":"GNN 층이에요. 부분 그래프 위에서 돌릴 평범한 GNN 층이에요."},{"from":4,"to":4,"say":"torch_sparse 라이브러리가 설치돼 있는지 알려 주는 표시값이에요."},{"from":5,"to":5,"say":"**차수(Degree)**를 구하는 함수예요. p.63 의 차수 역수 계산에 필요한 그 차수예요."},{"from":6,"to":7,"say":"빈 줄 뒤가 샘플러 도구를 만드는 줄이에요. 원래 그래프 data 와 배치 크기 6000 을 줘요."},{"from":8,"to":8,"say":"한 에폭에 배치를 5번 내주고, 정규화 계수 추정을 위해 미리 100번 샘플링해요."},{"from":9,"to":10,"say":"추정한 계수를 저장할 폴더와 샘플링에 쓸 프로세스 수를 정해요."}],"link":"3번 줄의 평범한 GNN 층이 p.61 의 온전한 GNN을 그대로 세운다에 해당해요."},{"kind":"pyterm","name":"불러오기(from 과 import)","say":["파이썬은 남이 만든 도구를 가져다 써요. 그때 쓰는 것이 import 예요.","from 뒤에는 도구가 들어 있는 상자 이름, import 뒤에는 꺼낼 도구 이름을 적어요.","한 번 꺼내 두면 그 뒤로는 이름만 불러 쓰면 돼요."],"example":"from torch_geometric.utils import degree\nprint(degree)"},{"kind":"pyterm","name":"키워드 인자(keyword argument)","say":["함수에 값을 줄 때 이름을 붙여 주는 방식이에요. 이름=값 모양이에요.","순서를 외우지 않아도 되고, 코드를 읽을 때 무슨 값인지 바로 보여요.","슬라이드 코드의 batch_size=6000 이 바로 이 모양이에요."],"example":"def hello(name, times=1):\n    print(name * times)\n\nhello(name=\"안녕\", times=3)","out":"안녕안녕안녕"},{"kind":"warn","head":"코드에서 헷갈리기 쉬운 점","items":["batch_size=6000 은 노드 6000개가 아니라 워크 출발점 6000개예요.","sample_coverage 를 0 으로 두면 **정규화(Normalization)**를 하지 않아요. 켜 두는 게 맞아요.","4주차에는 실습 노트북이 없어요. 이 코드는 슬라이드에 적힌 그대로예요."]}],"walk":{"head":{"b":[0.0131,0.0179,0.3051,0.0757],"c":[0,0.0019,0.3356,0.1077],"r":5.5397,"img":"img/L4/walk/p064_h.jpg"},"parts":[{"b":[0.035,0.175,0.93,0.515],"c":[0.0,0.1492,1,0.5665],"r":3.1382,"img":"img/L4/walk/p064_11_01.jpg","say":"위 검은 상자가 코드예요. 윗부분은 불러오기, 아랫부분은 도구 만들기예요."},{"b":[0.04,0.755,0.88,0.11],"c":[0,0.7122,0.968,0.1956],"r":8.798,"img":"img/L4/walk/p064_11_02.jpg","say":"아래 파란 띠가 이 코드가 하는 일을 한 줄로 적은 것이에요."}]}},{"p":65,"title":"4주차 마무리와 다음 주 예고","terms":["Scalability","Node-wise Sampling","Layer-wise Sampling","Graph-wise Sampling","Cluster-GCN","GraphSAINT","GraphSAGE","Receptive Field","Normalization","Subgraph"],"pass1":[{"kind":"say","lines":["마지막 쪽은 Q&A 슬라이드예요.","**확장성(Scalability)** 문제의 원인은 하나, 이웃 수가 고정돼 있지 않다는 것이에요.","해법은 셋, 노드 단위, 레이어 단위, 그래프 단위예요.","실무에서 가장 손쉽고 폭넓게 쓰이는 것은 k홉 부분 그래프 샘플링이에요."]},{"kind":"compare","head":"4주차를 한 표로","cols":["항목","**노드 단위 샘플링(Node-wise Sampling)**","**레이어 단위 샘플링(Layer-wise Sampling)**","**그래프 단위 샘플링(Graph-wise Sampling)**"],"rows":[["대표 모델","**GraphSAGE**, VR-GCN","FastGCN, ASGCN","**Cluster-GCN**, **GraphSAINT**"],["무엇마다 정하나","대상 노드마다","층마다","반복마다"],["뽑는 것","이웃 $S$ 명","층에서 쓸 엣지들","**부분 그래프(Subgraph)** 하나"],["장점","구현이 간편","품질을 이론적으로 보장","직관적이고 간단"],["단점","품질 보장 어려움","복잡해서 잘 안 쓰임","이론이 없고 레이블이 치우침"]]}],"pass2":[{"kind":"compare","head":"**Cluster-GCN**과 **GraphSAINT** 한 줄 비교","cols":["항목","**Cluster-GCN**","**GraphSAINT**"],"rows":[["조각 만드는 법","**메티스(METIS)**로 미리 군집화","배치마다 그때그때 샘플링"],["편향 처리","안 함, 한계로 적혀 있음","확률로 **정규화(Normalization)**"],["조각 종류","군집, 즉 커뮤니티","노드, 엣지, 랜덤워크 중 하나"],["계산식","같은 군집 이웃만 평균","같은 부분 그래프 이웃만 평균"]]},{"kind":"prof","when":"4주차 화요일 수업","lines":["교수님은 마지막 정리에서 이렇게 묶었어요.","가장 손쉽고 폭넓게 쓰이는 것은 대상 노드 중심의 k홉 부분 그래프 샘플링이라고요.","어차피 k층 너머는 보지 않으니 거의 정보 소실이 없다고 했어요.","좋은 해법은 한 가지 문제만 푸는 경우가 드물고 여러 문제의 트레이드오프를 함께 본다고요."]},{"kind":"points","head":"다음 주 예고","items":["5주차는 깊은 GNN과 과평활이에요.","층을 깊이 쌓으면 왜 모든 노드가 비슷해지는지를 배워요.","그리고 건너뛰기 연결과 잔차 연결이 왜 필요한지를 배워요.","3주차의 부분 그래프 가방 이야기도 여기와 엮인다고 했어요."]},{"kind":"recap","items":["**확장성(Scalability)** 문제의 원인은 이웃 수가 고정돼 있지 않다는 것 하나예요.","**수용 영역(Receptive Field)**을 예상할 수 없으니 메모리도 병렬 연산도 어려워요.","**Cluster-GCN**은 군집으로 미리 자르고, **GraphSAINT**는 확률로 그때그때 뽑아요.","오늘의 용어는 Graph-wise Sampling, Cluster-GCN, GraphSAINT, METIS 예요."]}],"pass3":[{"kind":"exam","src":"2024 가을 중간 4번 (10점)","q":"Calculate the output representations of node A, B, C, D, E at layer k = 1 for the GraphSAINT model, where the MEAN is taken over neighbours u with G_u = G_i.","qko":"**GraphSAINT** 문제예요. 부분 그래프 안 엣지는 A-B, A-C, B-D, C-D, D-E 예요. 처음 값은 차례로 0.1, 0.4, 0.2, 0.2, 0.1 이에요.","solve":["A 의 이웃은 B, C 라 $\\mathrm{MEAN}(0.4, 0.2) = 0.3$ 이에요.","B 의 이웃은 A, D 라 $\\mathrm{MEAN}(0.1, 0.2) = 0.15$ 예요.","C 의 이웃도 A, D 라 $\\mathrm{MEAN}(0.1, 0.2) = 0.15$ 예요.","D 의 이웃은 B, C, E 라 $\\mathrm{MEAN}(0.4, 0.2, 0.1)$ 로 반올림해 0.23 이에요.","E 의 이웃은 D 하나라 $\\mathrm{MEAN}(0.2) = 0.2$ 예요.","자기 값을 앞에 붙이고 렐루를 씌워요."],"answer":"$h_A = [0.1, 0.3]$, $h_B = [0.4, 0.15]$, $h_C = [0.2, 0.15]$, $h_D = [0.2, 0.23]$, $h_E = [0.1, 0.2]$"},{"kind":"warn","head":"시험 모양을 한 번에 기억하세요","items":["4주차 세 모델은 전부 계산 1 더하기 서술 1 한 세트로 나와요.","문제에 군집이나 부분 그래프 표시가 있으면 조건이 붙은 쪽이에요.","표시가 없으면 **GraphSAGE** 문제이고 이웃을 전부 평균해요."]},{"kind":"check","q":"문제지에 군집 $G_1$, $G_2$ 표시가 있으면 어떤 모델의 계산인가요?","choices":["**GraphSAGE**","**Cluster-GCN** 또는 **GraphSAINT**","GCN","FastGCN"],"a":1,"why":"조건 $G_u = G_i$ 가 붙는 쪽이에요. 군집 밖 이웃은 분모에서도 빠져요."}],"pass4":[]}]};
